window.STUDY_CONF={"storage": "slow-reader:lingxiu:v1", "book": "靈修生活", "noPages": true, "glossary": {"靈修": "每天安靜在神面前禱告、讀經、親近神的操練。", "靈交": "作者用語：人的靈與神相交，不只是說話，也包括安靜和感受。", "悟性": "理解和思考的能力。用悟性禱告，就是有條理、清楚地表達的禱告。", "準繩": "量度的標準。作者討論怎樣判斷靈修好不好。", "肉體、魂、靈": "作者把人分三個層面：身體感官、感情意志思想、與神接觸的部分。", "內室": "主耶穌說禱告要進內室、關上門；指安靜、不受打擾的地方。", "主禱文": "主耶穌教門徒的禱告（馬太福音六章），作者視為禱告的「樣子」。", "讀經": "閱讀聖經。作者介紹靈交式、精讀、多讀、研讀、撮讀、背讀等方法。", "解經": "解釋經文的意思。作者強調按正意、按上下文和作者原意去解。", "活祭": "羅馬書十二章的比喻：把自己整個人獻給神，為主而活。", "神的旨意": "神想人怎樣行。作者認為主要從聖經真理的原則去明白。", "呼召": "神呼喚人去作某件事，這裏特別指全時間傳道。", "撒但": "聖經中與神為敵、欺騙和控告人的那惡者。", "世俗": "與神為敵、使人離開神的世界價值和風氣。", "聖靈充滿": "作者理解為被真理充滿：明白真理、遵行真理，而不在乎特別現象。", "方言": "聖經記載的說別國話的恩賜。作者對今天的方言運動持保留和批評立場。", "靈恩派": "強調方言、神蹟等聖靈恩賜的教會運動。這是作者的批評對象之一，本站不作評斷。"}};
window.BOOK_LESSONS=[{"title":"為甚麼寫這本書？","short":"先聽作者的心意","terms":["靈修"],"cards":[{"label":"先抓住一個重點","title":"很多信徒不懂得怎樣靈修","lines":["作者聽到很多人問：為甚麼禱告幾分鐘便沒話說？為甚麼總不能專心？","他發現連傳道人也常被這些問題困住。","所以他想寫一本專門回答這些實際問題的書。"],"takeaway":"這本書是為「想靈修卻不知怎樣做」的人寫的。"},{"label":"把意思拆開","title":"書從課堂而來","lines":["作者在 1976 年於神學院教「靈修生活」一科。","他用半年整理、教了十八小時，然後寫成這本書。","他說自己不是最有資格的人，但因為需要逼切，就擔起這工作。"],"takeaway":"內容是從教學和經驗整理出來的。"},{"label":"讀之前想一想","title":"帶着自己的問題來讀","lines":["序言列出很多問題：時間、地方、讀經方法、情緒低落、聖靈充滿等。","你可以先圈出最貼近自己的一兩個。","讀到相關章節時，再停下來想想。"],"takeaway":"帶着一個問題讀，會讀得更專心。"}],"quiz":{"question":"作者寫這本書的主要原因是甚麼？","options":["很多信徒不懂怎樣靈修，卻少有書專門回答","為了寫一本學術研究","為了介紹教會歷史"],"answer":0,"hint":"回想序言開頭列出的一連串問題。","explanation":"作者見到很多人有靈修的實際困難，所以寫書回應。"},"key":"pre","id":1,"no":"序言","bookTitle":"序言","part":1,"partName":"入門","partTitle":"第一站　入門","idx":1,"original":[{"label":"序言","text":"所有教會，所有基督徒都知道靈修生活的重要，但卻有許多不知道靈修生活如何重要，重要的程度是怎樣。更嚴重的是一般信徒都不懂得如何靈修。他們不斷的發問—為甚麼我的禱告只能維持幾分鐘便沒有話說了？為甚麼我總不能集中思想去靈修？為甚麼我在靈修之中總摸不到神？我抽不出時間，也沒有適合的地方來靈修怎樣辦？我怎能進入靈界享受甜蜜的靈修生活？究竟怎樣讀經才能明白其中教訓真理？"},{"label":"序言","text":"怎樣才算是有亮光的讀經？讀經的方法有那幾種？最標準的靈修生活是怎樣的？我情緒低落之時怎樣進行靈修？我的靈性跌倒了，但我沒有力量起來靈修怎麼辦？靈修的內容是甚麼？我怎能在靈修之時明白神的旨意或特的指示？何謂被聖靈充滿？說方言是甚麼？"},{"label":"序言","text":"—可是很少人能回答這些問題，甚至不少傳道人自己也是被這一類的問題困住，不敢告訴别人，當然也不能幫助别人，結果整個教會落在幽谷之中，工作無力，全無增長，且有退縮現象，因為生命上出了毛病，怎能「長大成人，滿有基督長成的身量」呢？"},{"label":"序言","text":"奇怪的是，這個問題既然如此嚴重，如此逼切需要解決，但中文屬靈書籍中竟沒有一本是特為這一類問題寫的，如果有，也只是間接的，稍微提及一點點，帶不出甚麼幫助的。"},{"label":"序言","text":"即使是英文屬靈書～我沒有辦法作一個全面性的調查～，也沒有聽見任何人介紹過有關這一方面的，記得有一次有機會與英國•F^.11昀！ra.nk：Fntwistle交通，我問他為何他們出版的書多注重學術理性方面，而靈性方面的書好像很少注重？"},{"label":"序言","text":"他回答說，他們也看見這一方面的不平衡，只是十分難找到適合的人選來寫這一方面的書，例如最近他們想要出版一些有關生社方面的書，就一直找不到適合的人來寫。"},{"label":"序言","text":"我個人認為這是一個嚴重的問題，基督教缺了這一環就糟透了。適逢去年～一九七六年～海外神學院請我教授「靈修生活」一科，我花了半年的時間去整理思考，教了十八個小時的課，得到的反應結果相當良好。雖然到目前為止我不能說我是最有資格寫這本書的人，但既然沒有人寫，為了逼切的需要，我這不是最有資格的人也不能不担起這個重任了。\n\n但願神親自賜福給這一本書，使所有閱讀的人都深深的感受到聖靈的感動，靈命得到復興，榮耀歸給神。\n\n吳主光一九七七年十月"}]},{"short":"靈修為何重要？怎樣才算好？","terms":["靈修","準繩"],"cards":[{"label":"先抓住一個重點","title":"靈修比學識和工作更重要","lines":["作者從主耶穌在曠野勝過試探說起。","那次得勝，不是靠學識或工作，而是靠屬靈的力量。","所以他提醒：工作沒有果效時，先檢查自己的靈修。"],"takeaway":"屬靈的力量，從靈修而來。"},{"label":"把意思拆開","title":"不要用錯誤的尺來量靈修","lines":["作者說：靈修好壞，不能單看時間長短。","也不是看早起遲起、有沒有禁食，或情緒是否激動。","不過他也提醒，不以時間為標準，不等於可以馬虎。"],"takeaway":"時間、感受不是最終標準。"},{"label":"用生活例子想一想","title":"像晨運：看的是健康","lines":["晨運好不好，要看身體是否健康，不是看跑了多久。","同樣，靈修好不好，要看生活是否活出主的樣式。","例如：能否勝過試探、行真理、帶出基督的香氣。"],"takeaway":"正確的準繩是生活的「表現」。"}],"quiz":{"question":"作者認為怎樣判斷靈修生活的好壞？","options":["看生活中是否活出主的樣式","看每次靈修有多長時間","看靈修時情緒有多激動"],"answer":0,"hint":"想想晨運的例子：看的是結果。","explanation":"作者說靈修的目的在於親近主、活出主，所以看生活表現。"},"key":"ch1","id":2,"no":"第一章","title":"正常的靈修生活","bookTitle":"正常的靈修生活","part":1,"partName":"入門","partTitle":"第一站　入門","idx":2,"original":[{"label":"第一章","text":"我們的主耶穌基督在出來正式公開傳道之前，他先在曠野受魔鬼的試探四十晝夜。結果那一場大戰爭的勝利是百分之一百屬於主的。這次得勝的關係重大，因為以後所有的工作都以這個為基礎，尤其在趕鬼和保守自己一無瑕無疵一，使自己可以為全人類「一-次獻上成為永遠的贖罪祭—的救贖工作上更為重要。可是，我們要問，主這一次的得渗是在工作上呢？是在學識上呢？還是在靈修上呢？大家都知道這次的得勝完全是在靈修上。\n\n可見靈修在屬靈的爭戰上比學識重要，也比工作重要。"},{"label":"第一章 · 靈修生活不可忽視","text":"靈修生活不可忽視\n\n可嘆，今天不少傳道人或教會的領袖們，一旦發現自己的工作沒有成果，教會沒有增長，神沒有重用自己的時候，便立即想到—一這可能是工作沒有「方法」，可能是自己的「學識一不夠；於是想盡千方百計，到外國去拿一個學位回來，去進修心理學，考古學、哲學，語文：：～我不是說這些沒有用～，至於自己的靈修生活，就是一團糟的，模黑亂撞的，枯乾無味的，也沒有想到要去改。"},{"label":"第一章 · 靈修生活不可忽視","text":"曇最悲慘的，今天連許多神學院也不重視靈修，就是聖經本身也少研究了。神學生接受四年的神學教育，往往連聖經也沒有讀完一遍就出來傳道，四年的時間，多半花在學術的研究，即使間中有聖經科，教授的方針多半是教導學生們的所謂「客觀」的態度來皏究，其實是教導他們「站出來」—不要站在聖經裏面—去看看聖經是否可信。"},{"label":"第一章 · 靈修生活不可忽視","text":"「站出來」的教導使學生們根本沒有機會去「親身體會」-其中的真理亮光；「看看聖經是否可信」的態度間接將「懷疑」種植在學生們的心靈裏。\n\n當然在護教的研究立場上我們還可以用這個態度，但不可能每一次讀聖經，讀每一段聖經都用這態度的。神學家們假想的信仰敵人太多了，多到一個地步，以致他們認為需要用全部或大部份的神學教育去應付。其實敵人並不是那麼多的，用盡各種方法証明聖經是可信，這在靈程上只是最基本最膚淺的第一步。"},{"label":"第一章 · 靈修生活不可忽視","text":"一個神學博士，如果他的研究全部都是集中在這一點上，即是說，他在明聖經是可信的道理上有很大的心得，他的靈性程度還只不過是在最基本最膚淺的地步上。他的博士學位一點也不能顯示他的靈性有甚麼豐盛。今天的神學教育若不返回靈性的操練上札根，特别是在靈修的生活上操練札根，神學教育是注定叫這末世普遍的教會大大傾向不信和不冷不熱，被主吐出的危機裏的。"},{"label":"第一章 · 靈修生活不可忽視","text":"傳道人發現自己的工作不成功，為何不先檢討一下自己的靈性光景？為何不先在讀經和新社方面多下功夫？為何不先改善一下自己與神的關係？反而先想到方法學術那一邊去呢？無他，只因為靈修生活，屬靈能力這一類的東西是沒有博士學位的。而且學術理性的東西「易得難失」，所以被認為比較實際有把握。不是嗎！只要看一本書，立刻就可以得到其中的學問了，多容易？而且若非患上失憶症，一生也不會失去所得的學問。"},{"label":"第一章 · 靈修生活不可忽視","text":"但靈性能力的東西就不同了，這一類的東西是「難得易失」的：煮完一本「新社出來的能力」之後，我們知道，仍未得著新神出來的能力，或者操練多少年之後才得到多少，可是如果我們一旦驕傲犯罪，這能力就立刻失去了，所以這些難得易失的靈性東西，在一些沒有深度又不肯付代價的基督徒或傳道人來說，是抽象的，是不實際的，甚至有些信仰根基不大妥當的人看來，更是不存在的。"},{"label":"第一章 · 靈修生活不可忽視","text":"當歐美在第十八九世紀掀起理性主義，懷疑主義，唯物主義，無神主義，進化論，理想主義等思想的時候，教會遭受到重大的打擊，於是新神學派，不信派就抬頭，聖經被批判到體無完膚，甚至神學家宣佈「神死了」。在這種情形之下，神怎樣挽救祂自己的教會呢？神豈是興起學術的研究，方法的改善，去抵擋這些洪潮呢？"},{"label":"第一章 · 靈修生活不可忽視","text":"不，神在歐洲興起了「敬虔運動」，在英國興起了衞斯理移眾的「復興運動」，在美國興起了「靈性大甦醒運動」來挽救教會，抵擋不信的主義入侵。\n\n因為神知道，人的不信，其主要因素不是在理性問題，而是在靈性問題。對付理性問題是治標，唯有解決靈性問題是治本。我不是說理性沒有用，我乃是說靈性在先，理性在後。可是今天多少傳道人將這次序顛倒了。"},{"label":"第一章 · 靈修生活不可忽視","text":"看近日各教會都有一教會增長」研究熱，但仔細調查一下，大多數教會的傳道人是希望尋找一些「方法」去使教會人數增加，奉獻增加，聚會地方擴大，他們很少想到自己的靈性問題，全教會的靈性問題，應該怎樣增長。"},{"label":"第一章 · 靈修生活不可忽視","text":"如果有人提醒他們要注意靈性的增長，他們就認為這一點連小孩子都知道了，不用再提，要緊的是有何「特别的方法一没有。他們認為連小孩子都知道，其實他自己就是不知道。最少他不知道教會單在人數經濟上增長，這只是一個普通機構的增長。教會不是機構，教會是神的家，誰說「家」是機構？"},{"label":"第一章 · 靈修生活不可忽視","text":"家的增長需要「生命」，需要「溫暖」，需要與家長—父神—保持極和諧的關係，這些不是方法可以辦到的，只有美好的靈性生活才能辦到。"},{"label":"第一章 · 靈修生活的操練與目的","text":"靈修生活的操練與目的\n\n當然，要教會增長，要有個人屬靈的能力，要破客大大使用是靈性的問題，不是學術方法的問題。靈性的份量要經過操練才能得到，不能一朝一夕立刻得到，但我們決不應該因為難得到這些，就懶得去操練。隋性是靈性長進一個大障碍。看主耶穌出來傳道之前，在曠野受試探的大得勝也不是一朝一夕的。按他禁食四十晝夜的記錄來看。"},{"label":"第一章 · 靈修生活的操練與目的","text":"他一定操練了許多才達到這個地步，最少是從他年幼懂事有第一次靈修以來，一直操練到三十歲出來工作的時候。初時也許他只能禁食禱告一天半天，後來禁食十天八天，到三十歲受魔鬼試探之前，他已經操練到登峯造極的地步，能專心新芒禁食四十天之久。當然不是禁食本身有甚麼果效，這只是表明專心新芒到了-個挑步，沒有空去吃，顧不得吃，不想吃，為的是免得打斷了這個重要的禱告。"},{"label":"第一章 · 靈修生活的操練與目的","text":"所以，我在這裏指出的不是「禁食」的記錄，而是藉主耶穌禁食四十晝夜禱告的記錄，指出主耶穌的靈修生活，和得勝仇瑞的能力，都不是一朝一夕得到的，必須經過長時間的操練。如果不是這樣的話，我們要反問，為何主耶穌到三十歲才出來傳道呢？為何他不像戴德生=漾十八歲就到中國來傳道呢？那豈不是有更長的特間可以行更多的神蹟奇事嗎？所帶出來的影響力不也是更多嗎？不！"},{"label":"第一章 · 靈修生活的操練與目的","text":"戴德生所面對的工作不比主耶穌的重要，戴德生可以操練十八年(如果從出生就操練的話)就能承担他的工作，但主耶穌要操練三十年才能承担救世工作，當然主耶穌的神性是不需要操練的，但他的人性仍要操練，像他一出世就要操練講話走路等～我們不相信主耶穌出生以後立刻會講話會走路等～，因為他凡事都必須與我們相同。"},{"label":"第一章 · 靈修生活的操練與目的","text":"所以主耶穌的禁食與禱告生活也一定與我們相同—1需要操練。我們今天要認識神的兒子，得以「長大成人，滿有基督長成的身量」，就不能不學像主一樣操練自己。如果我們相信「操練身體，益處還少，唯獨歡度，贍事都有益處，因有今生和來生的應許，」(提前四8)這一節聖經，我們為何不相信「操練學問，操練方法，操練幹的益處還少，唯獨操練靈修生活，比其他的都重要」呢？"},{"label":"第一章 · 靈修生活的操練與目的","text":"在每天的靈修上，我們都操練早睡早起，操練思想集中，操練運用屬靈的智慧和悟性，操練讀經的亮光發掘，操練進入靈界的靈交，操練行道的生活，操練與神同行，操練喜樂，操練身體情緒的控制，操練熟習聽聖靈的聲音，操練抵擋試探，操練明白神的旨意：：總之，我們的靈修生活就是操練，「靈修」顧名思義是「靈的修練」。"},{"label":"第一章 · 靈修生活的操練與目的","text":"所以初學靈修的未能達到理想，這是必然的，因仿缺乏操練。許多運動家天天練習，小心飲食，恆心不懈，這樣他才能保持身體健康在最好的狀態下，在比賽之時才能得勝。就是許多老人家，因為要得到身體健康的緣故，也天天早起，到郊外或山上去晨運，結果他們的操練也得到預期的效果。基督徒為靈性的健康，過得勝的生活，豈能不作靈修的操練呢？"},{"label":"第一章 · 靈修生活的操練與目的","text":"初期的操練一定是悶的，是辛苦的，是花時間的，是好像很慢才見效的，這種情形在操練身體上豈不也是一樣嗎？有人說:不能勝過早晨的一刻，不能勝過那張床，怎能勝過一整天，勝過複雜的環境呢？這句話是鬱的。基督徒啊！主的工人們啊！每天一期點的得勝，積起來就是屬靈的能力了。"},{"label":"第一章 · 靈修生活的操練與目的","text":"别人可以為自己的肉體，為世界物質，賞賜而操練身體，我們怎麼不能為自己的靈性，為教會屬神的羣羊，為永存的賞賜，仿禮自己，而更恆心的作靈修的操練呢？况且，靈修生活並不是沈閃的，也不是辛苦的，難受的，像身體的操練一樣。問題只在你操練自己的時候，心中想像的目的是甚麼。晨運的人坊何勝過早起，勝過時間，勝過崎嶇山路，不感到搖手搖身是悶的動作？因為他們心中的思想，不是集中在時間，動作，路途等事物上，而是集中在健康和清新空氣的享受上。"},{"label":"第一章 · 靈修生活的操練與目的","text":"運動家也是一樣，他們並不集思在肉體的辛苦，時間的消耗等事物上，乃在比賽時的獎賞上。同樣的，我們靈修的感受也隨着我們的思想集中點，即我們靈修的目的而轉變。記得年輕之時，在夏令會中，導師問我們每一個組員為何要靈修。如果我不靈修我那一天會磁鉀子的，會眼眉跳的:會有意外的。」有一個組員這你的靈修目的不對」導師清楚而直接的指出說:「因為靈修不是用來關那，類員化吉的。"},{"label":"第一章 · 靈修生活的操練與目的","text":"有一天神要你撞釘子，遭意外時，你豈不放棄你的靈修生活嗎？」「我感到如果我不靈修，我就不是基督徒？」另一個提出他的答案說。「你的也不對」導師說:「靈修不是做基督徒的規條，不靈修就有自咎感，於是靈修就單被自咎感所驅使，必然是痛苦的，是不能持久的。何况這會變成功德主義:-我之所以得救，我之所以配稱為基督徒，因為我有靈修。"},{"label":"第一章 · 靈修生活的操練與目的","text":"』不，配不配稱為基督徒不在這裏，只在是否真正相信主重生得救。」「一我靈修才會知道神給我那一天的指引是甚麼？」又一個獻出他的答案。「這也不對，」導師又說:「因為靈修不是上台下，不是問卦。當然神會引帶我們每一天的路程，但這不應是最主要的目的。」「我有靈修的習慣會使我更熟聖經，更有禱告的能力。」這個組員想這答案會是最好的了。"},{"label":"第一章 · 靈修生活的操練與目的","text":"但導師仍說:「這只是靈修的好處，不是最終的目的。」「那麼，最終的目的是甚麼？」大家一同問。一靈修最終的目的是主自己，禱告是為親䓅舖，向他表示出自己的愛，感謝和讚美；讀經是為認議守，知道滿的計愛令讀聖經要像讀情信一般，一面讀一面想到自己的愛人，於是讀的時候就被愛所吸引，心中所充滿的，沒有别的，只有對方。"},{"label":"第一章 · 靈修生活的操練與目的","text":"靈修若能這樣，就必甜蜜，就是享受，就必沒有時間長不耐煩的感覺，就必會恆心，就必滿足主自己，主也在這時候滿足我自己，這才是最正確的靈修目的。」是的，這是最正確的靈修目的，可是當時導師没有告訴我們要達到那目的是需要操練，以致我個人在一時間不能進到他所說的心境中，就心灰了，壟且以為這丛是抽象的，是理論上的，是永不能達到的。"},{"label":"第一章 · 靈修生活的操練與目的","text":"其實不然，只不過我缺乏操練。有時偶然間我們會感到靈修很甜蜜，但不久又消失了，不能持久，因為我們還未學會完全控制自己。至於我們應該怎樣操練的問題，這要放在下一章才再詳細研究了。目前我們還需花許多時間去思根的，還是最理想的靈修生活應該是怎樣的問題。這一點，我們不能不以主耶穌為最高"},{"label":"第一章 · 注意「正常」與「超常」","text":"注意「正常」與「超常」\n\n或許有人想，主耶穌不錯是我們靈修最高最理想的榜樣，可是祂的榜樣太高了，有誰可以放下正常的生活去作幾十天的靈修呢？不，我們的意思並不是要學主耶穌長久禁食，或作幾十天的靈修。"},{"label":"第一章 · 注意「正常」與「超常」","text":"要知道主耶穌平常也不是這樣禁食禱告的。這不過是仿閉一個超常的爭戰，才有這超常的禁食禱告。我們一定要分清楚「正常」與「超常」。正常來說，主耶穌也像你我一樣有日間忙碌的工作，有吃有喝，有宴會，有旅行，有講道，有休息。"},{"label":"第一章 · 注意「正常」與「超常」","text":"至於靈修生活也是一樣，祂只能早晚抽一段不長不短的時間來禱告，不然，祂就沒有時間睡了，祂十分懂得分配時間，祂知道何時應該退到山上禱告，何時應該睡覺休息，何時應該放下工作來吃飯，這是祂正常的生常。"},{"label":"第一章 · 注意「正常」與「超常」","text":"但一旦有超常的事情臨到的時候，祂就要整夜禱告到天亮了。例如主在客西馬尼為上十字架接受可怕的刑罰，好使我們得免神的忿怒，而通宵禱告。又例如揀選十二位門徒之前作整夜禱告等。所以，我們學主的榜樣也要注意正常時期與超常時期的分別。在正常的時期，有正常的靈修生活，但遇到超常的事，即不平常的事臨到的時候，我們還得學主禁食禱告，整夜禱告，甚至作幾天的禱告。"},{"label":"第一章 · 注意「正常」與「超常」","text":"有了正常與超常的分别，我們就應該知鑑别自己靈修生活的標準是甚麼了。因為超常的標準是視乎那臨到自己的超常事件的性質和重大程度是怎樣，然後才定得出自己這一次的禱告是否須要禁食，若須要，那麼要多久等等。可惜，許多基督徒將主耶穌和一些神偉大的僕人們的超常標準當作自己正常的標準，於是就害倒自己了。"},{"label":"第一章 · 注意「正常」與「超常」","text":"因為發現自己不能達到那一個標準，就以為自己的靈修不好，或以為自己付的代價不夠，於是就拚命去求，去「付代價」，去强逼自己，鞭策自己，務求達到那一個「理想」的，但不知道是「超常」的目標，結果有的弄到自己灰心，有的懷疑神，有的神經表焉，有的在某種情形之下還破豬靈利用，甚至被鬼附。都因為他們把超常的當作正常的。"},{"label":"第一章 · 錯誤的準繩","text":"錯誤的準繩\n\n為此，我要指出，正常靈修好壞的判斷不能以下面的幾點為標準:1不能以時間長短為標準:我說這句話不是為那些局情的人說的，不要以為不按時間長短為標準，於是就馬虎了事，每次只用三兩分鐘靈修就算了。不，我們雖然不以時間的長短為標準，但也必須有個標準的。\n\n下文我們將會指出心常靈修的標準是甚麼，我相信任何屈情的人，若照着那些標準去行，他根本不能再懶惰了。"},{"label":"第一章 · 錯誤的準繩","text":"我說不以時間長短為標準的意思是指一些人，他們的心目中以為越長時間就越好，其實這種觀念卻隱隱特銜的藏有「功德」的想法在內也有修道主義的思想在內，即使他們的禱告好到好像在黑門山上看見異象一般，主耶穌還是不同意一搭棚一以便可以長期居住在山上，過那種所謂一一甜蜜」的生活，反過來，主耶穌指出祂必須下山到耶路撒冷去完成才華的工作。"},{"label":"第一章 · 錯誤的準繩","text":"而且聖經評論彼得搭棚的要求為一他不知道自己所說的是甚麼」。真的，心目中認為越長時一間靈修越好的人，真不知道這未必是主所喜悅的。灬不能以早起為標準:我這樣說也不能不先警告一些貪睡的人，恐怕他們看見我這樣說就放心繼續睡下去了。"},{"label":"第一章 · 錯誤的準繩","text":"不，如果他們真的明白靈修的意義，他們是絕不應貪睡遲起的，我說不以早起為標準，只因為有一些熱心過份的基督徒，他們聽了某某神僕人的見証，知道他們每天早上四時鍾，或五點鐘就起來靈修。於是就以為神大用他們就是因為他們早起。卻沒有想到最主要的還是他們禱告的心，他們的生活，他們的順服等。"},{"label":"第一章 · 錯誤的準繩","text":"由於這種錯誤的心理，許多基督徒鮑嗎自己越早起越好，結果弄至自己睡眠不足，日間不夠精神做事，於是就容易失敗，常發脾氣，甚至連自己所寶貴的靈修時間也不能集中精禮，總是想東想西，或半睡半醒的禱告，讀聖經也全無得着。"},{"label":"第一章 · 錯誤的準繩","text":"在這種情形之下不斷自責，也有因此鮑嵌自己更早起的，以為對付撒但總要與牠相反就對了，可憐最後弄至神經表下，也有精神崩潰的。或問，為甚麼那一本書說某某神的僕人可以這樣呢？唉呀！你為何不問那位神的僕人每晚幾圖狂睡呢？仿何不弄清楚他有沒有午睡呢？坑何不研究一下他的環境與健康背景是怎樣呢？為何不問神給他這種恩賜，但有沒有給你呢？為何不問他的年紀多大呢？"},{"label":"第一章 · 錯誤的準繩","text":"我們知道老人可以少睡一點，但年輕人，尤其是睡得不好的人，若減少睡眠的時間，會危害他的健康的，我有一個朋友，他一躺下就立刻睡得甜甜的，甚至他從來很少作夢的，所以他每天睡五小時就足夠了，但我每次躺下去，非到一小時以外不能入睡，而且入睡了還像想東西，想東西又像入睡似的，而且很容易醒，有時自己的鼻鼾聲吵醒自己。"},{"label":"第一章 · 錯誤的準繩","text":"記得在神學院讀書期間，我在二樓睡，花園金魚池的金魚翻身，我也會破吵醒的，所以我非驗在床上最少八小時不起來，不是我不能起，乃是我知道，我若太早起，那一整天都會頭重重的，做起工作來最少慢一倍，靈修也沒法集中思想。所以，各位讀者，不要盲目的以早起為標準，嚴格來說，以為越早起越好的人，其實也是有點修道主義，甚至有黑苦修主義的思想在內。3不能以禁食坊標準:禁食的意義在前交已經稍微提過了，在這裏我要作進一步的指出。"},{"label":"第一章 · 錯誤的準繩","text":"靈修的好壇仍不能以禁食坊標準，禁食的意義只不過是坊趨常的事專心稿告，以致不能抽空去吃，也不想吃，所以才禁食，但在正常的靈修生活中是無須禁食的。加果我們以為仿了要得到更好的靈修生活，於是就決定每陽一天禁食一餐或每週禁食一天，或進行其他方式禁食的話，那就流於形式化了。有人說，吃能了東西，血液會集中到胃副，於是腦副便出現輕徵貨血的狀態，這種狀態很容易中人入睡的。"},{"label":"第一章 · 錯誤的準繩","text":"正加一般人說，吃飽便睡覺，原因就是這個了。反過來說。饑飲的時候，血液都跪到腦部去，於是頭腦就靈活清醒；這種說法也很有理由。但如果仿此而高學標食的重要性的話，我要指出，其重要的所在仍不在禁食本身，乃在頭腦靈活清醒上。我們找不到理由證明神喜歡人無繩無故的禁食，以為神看見自己已經沒有吃東西這麼久了，袍就會答應祠告或賜下更甜蜜的奎告感受，這是芝唐怪誕的。"},{"label":"第一章 · 錯誤的準繩","text":"法利賽人常常禁食，天主和教徒常常禁食，回殺徒常常禁食，基督徒真是堂塵莫及，這就證明禪喜歡他們多過基督徒嗎？當然不會的，所以靈修的好壞是不能以禁食狀態來到斷的。：4.不能以强烈的情緒為標準:關於情緒這一點，我以後還會再加詳細討論的。但我以為，在判斷靈修的好壞的原則上，我不能不先稍微的指出一下。"},{"label":"第一章 · 錯誤的準繩","text":"今天實在太多人追求情緒不是追求主，另一方面也有許多人反對情縱，以為人只像一部機器，要絕對理性化，不應受情緒作用影響，視情穎仿魔鬼的工具。\n\n兩個極端都是錯的。我們因愛主而靈修，如果是頁「仿」，那裏有可能沒有「情」的呢？真愛必有真情，我們說靈修是「甜蜜」的，與主靈交就是一種，是十分「快樂」的，這些說法都是情緒上的感受。這是正常的，只有那些早測心理學，但又對心理學一知半解的人才會拒絕靈修時的情緒。但我在此要强調指出的，不是靈修不要情緒，而是不以之為標準。"},{"label":"第一章 · 錯誤的準繩","text":"許多基督徒在夏令會中得到復興，痛哭流淚稿告；或是某一次他們在靈修低沉的情说；因着聖靈的光照感動，第一次突破長久以來況閣的靈修生活，感到靈修的甜蜜，於是就十分寶貴這樣的經驗了。可是，他們發現，時間慢慢過去，這種「甜蜜」的感受不能維持下去，小像以往的甜蜜，就斷定自己的靈修生活走下坡，懷疑主不同在，或自己付代價不夠。"},{"label":"第一章 · 錯誤的準繩","text":"於是出盡各種方法相全要得回那種感受，詞翊的走向偏激的路途上去絲譯番羅箋變成神秘主義者。其實，他們只在意識上追求主，但在潛意識上是追求情緒，這是錯誤的。要知道，我們人類的結構原本就是這樣:任何情緒感受都會被時間冲淡的。如果我們悲傷的感受是一直維持不變的話，那太痛苦了，一切安慰成了徒然，連主的救恩也無效了。"},{"label":"第一章 · 錯誤的準繩","text":"如果我們喜樂的高潮是一直維持下去不變的話，那也太難受了，我們一定會精祝月潢的。所以，某一次的靈修甜蜜感受漸漸消失，這是正常的，因為不是每一次靈修都像那第一次靈修一樣，有從低沉的光景中突破的感受，也不是每一次都有那第一次認罪痛哭的需要，所以自然的，以後的靈修禱告就有情緒減退的現象了。"},{"label":"第一章 · 錯誤的準繩","text":"其實，只要我們沒有犯罪，沒有離開主，沒有消滅聖靈的感動，我們是仍然在主的愛中的，情緒不能作仿天斷的根據。以後我繼續論及靈修的理想狀態之時，也會指出有甜蜜的感受的，但讀者不可以那一點為吸-引你靈修的主要因素，要緊緊記在心中的，是以主耶穌為吸引你靈修的主要因素，有了主就有甜蜜，但有了甜蜜未必有主，而且，倘若有了主而感受不到甜蜜，那也是不要緊的，要緊的是內心的平安。"},{"label":"第一章 · 錯誤的準繩","text":"若要有正常的甜蜜也可以，但必須要進深認識主。每深一層的認識主，自然會產生又一次的「新感受」，但新感受潤尊淡下來的現象是正常的。如果我們能每一次靈修都有深一層的認識主，我們就能每一次都有新感受，這樣我們也就能常常感受到甜蜜了。但我們仍不能忘記，希望維持甜蜜的靈修本身是不夠正確的，只有希望維持更深的認識主才是正確的"},{"label":"第一章 · 正確的準繩","text":"正確的準繩\n\n判斷靈修生活的好壞標準不憑時間長短，不憑早起遲起，不憑禁食進食，不馮繞用烈情緒；那麼要憑甚麼原則來判定呢？要解答這問題，我們先要注意晨運的人，他們晨運的情况是好是壞憑甚麼判定呢？是憑時間嗎？是憑早起嗎？是憑情緒嗎？是憑動作嗎？是憑興趣嗎？不！是憑他們是否達到目的，就是身體健康。怎麼知道他們身體健康呢？是要看他們在日常生活中有沒有精神活力一表現」。"},{"label":"第一章 · 正確的準繩","text":"再看那些運動員，他們練習狀態的好壞，是憑甚麼判斷呢？是憑時間嗎？是憑早起嗎？是憑進食節食嗎？是窟與趣嗎？不！是憑他們是否達到目的。就是比賽之時勝過别人的「表現」。同樣的，靈修生活的好壞，是色淮包麼判定呢？不是憑靈修之時的現象，乃是憑是否達到靈修的目的。我們已經稍微說過，靈修最終的目的是坊主自己，希望藉靈修可以更深的認議宛，更深的愛他。"},{"label":"第一章 · 正確的準繩","text":"可是，我們怎知自己更深的認議宛，更深的肪補呢？是要看我們是否活出祂的樣式，帶出祂的香氣，遵行祂的旨意，像祂勝過試探種種的「表現」。因為主耶穌說:「憑他們的果子就可以認出他們來」(太七20～。又說:「有了我的命令又守的，這人就是愛我的，愛我的必蒙我父愛他，我也要愛他，並且要向他顯頭。」"},{"label":"第一章 · 正確的準繩","text":"(約十四刀)還有保羅說:「認議禮的兒子，得以長大成人，滿有基督長成的身量，使我們不再作小孩子，中了人的詭計和欺騙的法術:::(這種表現也就是像主勝過試探的表現～。"},{"label":"第一章 · 正確的準繩","text":"—一弗四1314一如果有人說，他的靈修很好，但他的生活不能流露出基督的香氣，不能勝過試探，不能行真理，反而常常軟弱跌倒，每當試探來的時候，發現自己沒有力去抵擋，你想他的靈修好嗎？不！"},{"label":"第一章 · 正確的準繩","text":"無論他在靈修中感受到多甜蜜，用了多少時間，出了多少力量對付自，也是等於零‧反之，如果他的靈修沒有甚麼特别的感受等，但他的生猜有力，像主，行真理，他的靈修仍是好的(不過，在正常的情形來說，生活有沒有力的表現，往往與靈修的時間，早起，禁食，感受等等有間接的關係，但記得那只是在「正常」的情形卡；而且兩者的關係也只是「間接」的～。"},{"label":"第一章 · 正確的準繩","text":"所以，真正準確衡量靈修好壞的標準是生活和工作的「表現」。我這樣說是提醒主內的弟兄姊妹，不要步往修道主義，神秘主義，偏激主義去。基督教不是思想上的宗教，不是形式上的宗教，而是與實際生命和生活有直接關係的宗教。"},{"label":"第一章 · 正確的準繩","text":"信仰沒有實際生活的流露是虛假的，信心沒有行為是死的，說愛主比這一切更深而不牧養餵養主的羊也是不實際的，跟隨主而不背起十字架是不真心的，盡心愛主而不加上盡力愛主是騙人的，有感而不動是不算為有感動的。"},{"label":"第一章 · 正確的準繩","text":"所以，我們不要追求靈修的感受(有感受是好的，但那不是我們追求的目標～，或其他現象，緊要的是追求主自己，追求活出主自己。"}]},{"short":"專心靈修，從準備開始","terms":["內室"],"cards":[{"label":"先抓住一個重點","title":"第一關：專心","lines":["很多人靈修時雜念很多，想東想西。","作者說，要先找出雜念從哪裏來。","例如看太多電視、小說，或心裏貪愛某些東西。"],"takeaway":"對付雜念，要從源頭入手。"},{"label":"把意思拆開","title":"身、心、靈都要準備","lines":["早睡早起：清早安靜，處處都可以是「內室」。","把一天最好的時間獻給主，並建立有規律的習慣。","起床後先收拾床鋪、梳洗、做幾分鐘早操，讓睡意過去。"],"takeaway":"好的作息，幫助好的靈修。"},{"label":"用生活例子想一想","title":"沒有地方？早一點起來","lines":["一家幾口住在小房間，很難安靜。","作者建議：在家人還睡的時候起來靈修。","你也可以想想：自己一天中哪段時間最清醒、最安靜？"],"takeaway":"先安排時間和地方，再開始靈修。"}],"quiz":{"question":"作者為甚麼建議起床後先收拾、梳洗、做早操？","options":["讓睡意過去，頭腦清醒地靈修","因為這是教會的規定","為了節省靈修時間"],"answer":0,"hint":"作者提到心臟、血液和腦部的變化。","explanation":"他說這些小步驟讓人清醒，禱告更容易專心。"},"key":"ch3","id":3,"no":"第三章","title":"靈修前的準備","bookTitle":"靈修前的準備","part":1,"partName":"入門","partTitle":"第一站　入門","idx":3,"original":[{"label":"第三章","text":"許多人都有這個經驗，就是要有好的靈修，第一關要衝過的是[專心」‧不知怎的，每次靈修總是雜念多多，想東想西，結果使自己花了許多無謂時間，靈修一點得着也沒有，為甚麼？仔細分析來說，不能專心有以下的幾個原因"},{"label":"第三章 · 為甚麼不能專心","text":"為甚麼不能專心\n\n1因為靈修前太多接觸雜念的來源；請你仔細想一想，每一次攪擾你靈修不能專心的雜念是甚麼？查看這些雜念的來源是甚麼？你會發現，可能你看小說或看電視太多了，以致小說電視的圖片再一次在你靈修時出現，尤其是一些命你印象深刻的圖片，諺加打鬥，色情等類的圖片最容易在靈修時出現的。所以，你要對付這些來源，不看這一類的電視和書報。如果雜念來源是因為你貪愛世物，諸如百貨公司的衣服用品等，你也要對付。"},{"label":"第三章 · 為甚麼不能專心","text":"要有好的靈修，我們必須是要付代價。任何「偶像」都不能取代主耶穌的位置。即使是一些正常的事物，如果它攪擾我們的靈修，中斷我們與主的關係，我們就要割棄。讓我擧兩個例子來解釋：得一位弟兄在靈修禱告時不專心，以致他將「天父」的稱呼，潮潮塗塗的稱作「師醒」。他立刻發現自己的錯，於是認罪說:「天父呀！"},{"label":"第三章 · 為甚麼不能專心","text":"請你原諒我，我一定是看武夾小說太多了，想不到在靈修時不知不覺的稱你為師傅，真對不起，我知道我這一次又」寬鬼一掌-了。\n\n-一掌’那又是武俠小說的口脗！天父啊！赦免圾免，我員訪死::」他發現他一直無法擺脫武俠小說的雜念，直至他對付了這種嗜還有一位傳道人，他十分喜愛種花，本來種花是一種正當而健康的嗜好，但因為他太愛種花了，以致花成了他的偶像。每天起來，第一件事就是去看看那些花，做點修剪澆水的工作，然後回到房間去靈修，可是一閉上眼睛就看到花，-打開聖經就看到花。"},{"label":"第三章 · 為甚麼不能專心","text":"他無法專心靈修，聖靈感動他不要愛花過於愛主，他可以愛花，只是不可以愛花多過靈修親近主。但他不肯順服，有一天他醒來又去看花，誰知小鳥飛來把花吃光了。他知道是神的管教，不能不順服下來，專心靈修了。2因為精神不夠:日間忙碌，到了晚上帶着筋疲力盡的身體靈修，常會不能專心，因為精神不夠，睡眠不足，太早起來靈修也會不能專心。"},{"label":"第三章 · 為甚麼不能專心","text":"如果是因為前者，那就要減輕日間的工作，如果不能減輕三最低限度也不要將靈修時間放重在晚下方應該放重在早正。晚上的靈修禱告應是屬於檢討性的，代禱性的。早上的靈修應是屬於親近主，敬拜主，是靈交性的。如果晚上太疫做，早上一早醒來又睡眠不足，無法專心，那就非減少日間工作不可了。"},{"label":"第三章 · 為甚麼不能專心","text":"對於一些一向不習慣早上靈修，突然轉變過來，熱心愛主，決定每天淸早起來靈修的人，我要提醒他，初期不夠精神，不能專心，是意料中事，因為未成習慣。"},{"label":"第三章 · 為甚麼不能專心","text":"應該勉勵自己不可灰心，繼續努力。但對於一些過度熱心，誤以為越早越好的人，我也要提醒他，這樣做會影響自己不夠精神，甚至影響身體健康。在身體健康越壞，越逼自己更早起來，又越不夠精神集中思想的情况下，結果你的靈修生活就會越糟，我勸這樣的人不如先睡足才靈修。為何我們要視睡眠為「惡物」呢？這是神設計的，是必需的，只有貪睡才是惡物。"},{"label":"第三章 · 為甚麼不能專心","text":"我常常淸楚地發現，每當我有了足夠的睡眠後，我的靈修是更專心，3因為沒有想到自己是來到主的面前:有一個人常常禱告不專心。後來他探取一個新方法，把一張椅子放在前面，離遠一點：同椅子跪下禱告，這樣他就能專心了，為甚麼？他說因為這樣會幫助他容易想到神丛在目己面前，一想到神在面前，就不敢不專心了。當然，這個方法是幼稚一點，但它的意思卻是正確的。"},{"label":"第三章 · 為甚麼不能專心","text":"許多時候我們把靈修當作一個發洩我們內心寃屈的機窗或當為一種宗教習慣工完全沒有想到自己來到了稱公面前，_所以不專心禱告。\n\n當你去見一位重要人物，如總統，總經理，校長之類的人物，你面對着他，你會糊亂講話嗎？不！你會提高自己的精神，小心每一句講出來的話。同樣，只要我們相信我們在靈修時候是來到神的寶座前，我們必會看見那二十四位長老都放下富是售伏敬拜，四活物畫夜不住的說「聖哉！聖哉！聖哉！一在這種嚴肅偉大的場面裏，誰敢不專心呢？"},{"label":"第三章 · 為甚麼不能專心","text":"4因為邪靈在要批:許多有趕鬼經驗的神的僕人告訴我們，不少基督徒在接觸過邪術，靈媒，交鬼，異教儀式，占卜，巫醫等神所不喜悅的而又是危險的事物之後，他的靈修就好像有了隔膜，不能專心，讀經無亮光，而且不能集中思想，有時甚至聽道也不能專心，好像對一切屬神的事物工作都沒有興趣，或提不起勁似的，如果是這樣，他需要徹底認罪，並且在入禧中竭力奉主耶穌的名吩咐邪靈離開，"},{"label":"第三章 · 為甚麼不能專心","text":"有時雖然我們沒有交鬼，但攪擾我們的雜念若是一些屬於汚穢罪惡的雜念，為安全起見，我們也可以奉主耶穌基督的名趕走這種意念，主耶穌基督的名是我們每一個基督徒隨時可以應用的最具威力的權柄。我們應該習慣使用這寶貝的名。除以上四種主要原因之外，當然還有環境嘈雜，心事掛慮，時間不夠等等因素，我不打算在這裏討論，我會在以下談到靈修的程序時，連帶解決這些問題。"},{"label":"第三章 · 身心靈的準備","text":"身心靈的準備\n\n要達到專心靈修，進到神面前的靈修，我們還需要有一些準備工夫。\n\n-一早睡早起:我發現今天許多基督徒的靈性不好，其中一個主要因素是因為太遲才睡，太晏才起床，大衞那一次跌倒犯罪，與拔士巴行淫，謀殺她的丈夫，以致後來遭遇禍患痛苦，完全是因為他睡到「太陽平西」的時候才起來，意思是說，他把夜當日，日當夜，生活倒了。這樣的生活，無疑就是大衞靈性最低潮的生活，不用說他的靈修不是停止了，就是隨便馬虎了事。"},{"label":"第三章 · 身心靈的準備","text":"為甚麼早睡早起對靈性有好處？這很容易明白的，試想在一天之中罪惡最活躍的時間是甚麼呢？豈不是在夜間嗎？電視節目多，而且多是「兒童不宜觀看」的那一類。百貨公司，電影院，歡樂場所，賭博地方等五花八門的試探引誘都是在夜間開放的，清早起來，一切娛樂場所，百貨公司，電視等等都靜止了，都仍在「熟睡」中。試問一個基督徒習慣夜生活，他接觸罪惡的機會豈不是多嗎？"},{"label":"第三章 · 身心靈的準備","text":"～當然，為職業為學業而運睡的不算在內～：反之，如果他是習慣草睡草起的話”他在罪惡最活躍之時熟睡学；與罪隔絕了，用不理睬的態度去對付罪，這是最好的方法。第二天一早醒來，精神煥發，這時所有罪惡的場合都靜止了，他根本沒有機會去接觸罪，反而，他可以利用這段時間去靈修，親近主，何等美好？"},{"label":"第三章 · 身心靈的準備","text":"許多人嘆息沒有安靜的地方靈修，尤其是這個寸金尺土的香港，許多人家只住一個房間，他們沒有客廳，更談不上新禧房。\n\n一家幾口擠在一個房內，那裏可以安靜靈修？不！問題是在乎你是否早起早睡。當全家人都仍在熟睡的時候，你起來靈修，這時豈不是處處都是「內室」，都是安靜的地方嗎？神要求我們奉獻給祂的，是「無殘無疾」的，県一頭生」的，是最好的。攻打迦南地之時，第一座城的金銀要歸給耶和華，田間的土產，初熟的要獻給耶和華。長子要歸耶相華。"},{"label":"第三章 · 身心靈的準備","text":"同樣的，一天最好的時間要獻給主。最好的時間是那一段呢？在任職夜班護士工作的基督徒來說，可能最好的時間是旁晚，但一般來說，無疑最好的時間是在淸早。我在上一章裏說最好的靈修不能以時間長短為準？也不能以越早越好為準，那一種說法是為一些過度熱心而沒有智慧的基督徒說的。但為一般基督徒，我强調的指出，應該盡草起床。有人說，不能勝過早上第一段時間，怎能勝過整天的時間呢1？"},{"label":"第三章 · 身心靈的準備","text":"F的工。或問，以甚麼為「盡早」的標準呢？如果我們要睡入小時才夠的話。盡早起床的意思不是只睡四五小時就起來，那是普通人吃不消的。也不是睡足入小時才起來，那是没有性取心的¥“應該要以八小時減一黑，即七小時半左右為準o福樣一來可以勉勵自己進取，發掘自己的潛力(因為我們定一些事物的標準，常常過於遷就自己，於是就定得太寬～，二來也不會影响自己的精神健康。"},{"label":"第三章 · 身心靈的準備","text":"基督徒應該要有規律的生活，不可放縱，不可生活無度。規定自己每天甚麼時候起來，就要甚麼時候起來，規定自己每天多少時間靈修就要用多少時間靈修。不能今天是這樣，明天又是那樣。無規律的生活是不穩與跌倒的前奏曲。有人反對規律的生活，認為這樣會使靈修「習慣化」。我要反問，即使習慣化又有甚麼不好？如果是一個好習慣的話，為甚塵我們要反對它呢？"},{"label":"第三章 · 身心靈的準備","text":"今天的青年人反對傳統習慣反到一狂亂」的地步，連有價值的傳統，有好修養的習慣都反對，結果反對到一個地步，自己也不知道在反甚麼？我肯定的說，如果我們的靈修真的因習慣化而無味，那濃～是比沒有靈修好。"},{"label":"第三章 · 身心靈的準備","text":"但無味豈是因為習慣化呢？為何不想想毛病在那裏而設法改善呢？所以，我勸勉每一個中徒•！該養成有規律的靈修生活習慣，有了這個好習慣之後，「惰性」就被勝過了，靈性也穩定成熟了。Z第一件事:有一些人認為要將最好的獻給誦立所以每呈醒來第一件事應該是靈修，不應先做其他的事。"},{"label":"第三章 · 身心靈的準備","text":"可是，許多人照這個勸告去做，一早醒來立刻轉身跪下禱告反而覺得精神不能集中，靈修進行得不好，因為睡意還未完全過去。其實我們要將最好的獻給神是對的，但清早起來第一段時間未必是最好的。"},{"label":"第三章 · 身心靈的準備","text":"最好的時間應是精神煥發，思想集中，睡意全消的時間，所以清早起來第一件事要做的，不是靈修禱告，乃是收拾床鋪，穿着整齊，尤其要穿上鞋襪，這樣做的目的:第一是不讓自己的惰性有機會發作，以致自己再上床睡覺。"},{"label":"第三章 · 身心靈的準備","text":"收捨床鋪，穿鞋穿衣就是破釜況自的意思。這是經驗之談，尤其是初學習靈修的人，更應留意這一點。第二個目的是養成整齊雅觀的習慣，這一點雖然對靈修沒有直接的關係，但我以為一個靈修好的人，決不能是一個衣履不整，床被狠藉的人。在小事上不齊整，在大事上焉能有條理，間接影响他的靈性也不會有恆心和忠心。無論如何，神是不喜歡人糊亂，乃喜歡人按規矩次序生活的。"},{"label":"第三章 · 身心靈的準備","text":"第三個目的是讓自己的睡意漸漸過去，為了要使自己的睡意完全過去，醒來的第二件事還不要立刻靈修，乃要一，•第二件事:梳洗和做早操。梳洗是必須隨着衣履整齊的，不過在天冷時洗一個冷水面也有提神的作用。至於做早操，這也是重要的，我說重要，不全是因為操練身體使之健康。要知道，當我們睡在床上之時，我們的心臟跳動得不吃力，血液從最低的背脊抽到最高的鼻頂也不超過一尺高的壓力。"},{"label":"第三章 · 身心靈的準備","text":"但當我們從床上起來，站在地上時，心臟立刻要很吃力的把脚底的血液抽到腦部去，由一尺的壓力轉變仿五六尺高的壓力，這一個立刻的轉變，對一個身體健壯的人來說，當然問題不大，但對一個文弱的人來說，他的心臟就難以應付這樣大的轉變，於是，當我們一早醒來時，如果立卅靈修禱告，就會有腦部輕微貧血和半缺氧的狀態出現，這就是睡意未消的現象，懾情的人以為自己是睡眠不足，其實不是，只是睡意未消吧了。"},{"label":"第三章 · 身心靈的準備","text":"這時，如果我們收拾床被，穿衣梳洗，睡意已為消退。再加上做幾分鐘的早操，使心臟跳動得快一點，使血液循環加速，把足夠的氧氣帶到腦部去，這在生理衞生上稱為「帶氧連動；不但對身體健康十分有幫助，許多老人每天行「晨運」的意思就在此，而且更能使自己在靈修之時精神煥發，思想集中，睡意全消。"},{"label":"第三章 · 身心靈的準備","text":"我以為許多人因為忽略這一點，結果使自己在靈修時花了許多無謂的時間，又自怨自恨，怪責自己不專心，又不明白為何會這樣，弄到心灰意冷。\n\n誰知問題不過是忽略這小小的常識。所以我以為，做早操的習慣雖然不是人人都有，但最低限度是每個人應有的。"}]},{"short":"一次靈修可以怎樣進行","terms":["靈交","悟性"],"cards":[{"label":"先抓住一個重點","title":"靈修有一個簡單的次序","lines":["作者建議：恭敬跪下、唱詩、用靈禱告、用悟性禱告、讀經。","準備好身心，反而節省因分心而浪費的時間。","這是他自己的經驗，不是唯一的方法。"],"takeaway":"有次序，比較容易進入安靜。"},{"label":"把意思拆開","title":"用靈和用悟性禱告","lines":["用靈禱告：安靜敬拜，像孩子在父親懷裏，不必說很多話。","用悟性禱告：有條理地為事情和別人代求，可以先列出來。","作者也提醒：用靈禱告不等於一定要說方言。"],"takeaway":"安靜相交 + 清楚代求。"},{"label":"把意思拆開","title":"靈交式讀經","lines":["禱告後不急着說「阿們」，把讀經也包括在禱告中。","讀經是神向我們說話；禱告是我們回應神。","一邊讀、一邊回應，讀完才結束禱告。"],"takeaway":"真正的靈修是一種安息和享受。"}],"quiz":{"question":"作者說的「靈交式讀經」是甚麼意思？","options":["把讀經放在禱告裏，一邊讀一邊回應神","盡量快速讀完很多章","只讀別人寫的靈修書"],"answer":0,"hint":"作者說讀經是神說話，禱告是人回應。","explanation":"他建議讀完經才說「奉主名求，阿們」，讓讀經和禱告連在一起。"},"key":"ch4","id":4,"no":"第四章","title":"靈修的程序","bookTitle":"靈修的程序","part":1,"partName":"入門","partTitle":"第一站　入門","idx":4,"original":[{"label":"第四章","text":"我們用了十分八分鐘的時間來作上述的準備工夫，這是不會影響靈修不夠時間的。而且，有了好的精神狀態，我們禱告才會容易更專心，結果反而省回許多在禱告中因不能專心而損失的時間。"},{"label":"第四章","text":"我有一個朋友，他有一天告訴我，他跪在地上禱告了六個小時，但其中最少有五個半小時的時間花在控制自己要專心的掙扎上，他發現自己跪下不久，思想就不其然的跑到老遠的地方去，等到發覺這種現象之後，立刻把自己的思想一捉一回來，但不到一分鐘又跑去了，如是者捉來捉去，雖然禱告六小時，但一點效果也沒有，內心不斷的自責，［後來我勸他如果再遇到這種情形，不妨先去睡一會兒，醒來做點體操等，使自己有足夠的精神再來禱告，就不會這樣了。"},{"label":"第四章","text":"果然他依照這方法去準備一下，情形完全改孌，可以專心禱告了。能專心禱告半小時，勝過不專心禱告幾小時。但是，是否有了好的精神狀態，就可以立刻進到最好的靈修境界呢？不！我們要使自己進入靈界的狀態裏，還需要有以下的程序一"},{"label":"第四章 · 恭敬跪下","text":"恭敬跪下\n\n千萬不要躺着靈修，那不單是容易入睡，同時也是不歡虛的姿態，許多人認為「有了敬虔外貌，卻背了敬虔的實意一是錯的，卻不想到，有茹虛的實意也必須要有敬虔的外貌。"},{"label":"第四章 · 恭敬跪下","text":"坐着靈修也不是好的姿態，除非有特殊理由不能跪下，我以為如果怕跑下或燥號下，或認為無需太緊張要跪下，這種種心理都是妨礙我們有好的靈修的「礁石」，這一點點代價不付，焉能得到靈裏的復興。~2"},{"label":"第四章 · 唱一些詩歌","text":"唱一些詩歌\n\n我覺得許多基督徒忽略靈修時唱詩的重要性。他們以為唱詩只是聚會時才需要的，全想不到需慾！受公型修時也是十分需要的，因為有許多聖詩是特别為靈修而寫的。"},{"label":"第四章 · 唱一些詩歌","text":"我們各人家中應有聖經，但也應有聖詩。聖經給我們帶來真理，聖詩給我們帶來喜樂安慰，藉着詩人的靈修心得，我們可以得到許多寶貴的提醒與鼓勵。而且，我强調靈修時應該唱一些詩歌，最大的目的還不是這個，最大的目的是詩歌可以引導我們的思想斬漸進入靈界樂境。"},{"label":"第四章 · 唱一些詩歌","text":"當我們唱詩的時候，我們的思想自然集中起來，隨着詩詞的意景轉動，慢慢的忘記自己在地上，好像飛到神的面前，進到主的懷抱，進到靈界聽見隱密的言語，有人說，唱詩不但要「唱出」詩歌的意思，還要「唱入」詩歌的宣垃，這句話就是我所指的意思。例如我們唱～請讀者不要單閱讀，要試試用心唱～：1.主耶穌啊！想起了你，心中便覺甜蜜。"},{"label":"第四章 · 唱一些詩歌","text":"卫不得今天就被提，與你同在一起。(副歌～啊你是園中的鳳仙花，你是沙崙的玫瑰花，你是谷中的百合花，使我不能捨下。2.世上沒有一個聲音，把你恩典唱盡；世上也沒有一顆心，受完你的愛情。3.雖然有時流淚傷心，情感不能自禁，可是想起你的同情，憂愁化為高興。4.你愛多塵轉長深高，沒有人能知曉，“蒙愛的人只能說道，哦你的愛奇妙！-看！"},{"label":"第四章 · 唱一些詩歌","text":"這首詩的瑟增多美，它把我們帶上天，又帶我們進到雅歌所描述的花園裏那就是帶我們進入靈界。真正用心唱這首詩的人，必然會漸漸忘記自己在地上，想到自己飛到天上似的，類似這樣的詩歌還有許多許多，讓我兩舉幾首作為例證:(天主聖歌第三三四首是賈玉銘前輩精心作品1.我今靜默主前，仰瞻恩主聖顏，默默無聲，以靈交談，陳明我心所願；衷懷傾吐，一無隱瞞，我心主心，相合無間。"},{"label":"第四章 · 唱一些詩歌","text":"～細心唱，細心想，照着這詩意靈修，多美妙，多甜蜜的境界，再唱第二節：～2.我今靜默主前，猶如父子會面，依慕慈懷，見主笑臉，心靈活潑自然。\n\n無憂無懼，大得寵眷，從豐滿中，得了豐滿。(讀者！你想想，靈修時跪在神面前，如同投入祂的懷抱裏，看見祂對你笑，你會有何等的感受？—一定好像第三節的感受一樣：～3.我今靜默主前，信心如同眼見，萬事交託，望主成全，脫去一切重担。無上快慰，無上平安，心靈恬憩，悲喜交感。(「無上快慰、平安、恬憩:::」誰說這樣的靈修是苦悶，是重担？"},{"label":"第四章 · 唱一些詩歌","text":"～4我今靜默主前，等候主旨顯現？無聲有聲，不言而言，心意倍覺誠虔。靈界秘事，親耳聽見，箇中滋味，何能言生？(「無聲有聲，不宣血言而言」這正是靈交的禱告，是首己的心靈已經進到靈界的狀態，心中有說不出來的嘆息，感受到聖靈在自己內心用二靈一去補足自己的禱告。我說用圳菩告，意思是內心充滿聖靈的感動，想要講出來，但不知從何說起，也不曉得怎樣表達。"},{"label":"第四章 · 唱一些詩歌","text":"只能「心靈相通」，像一對在戀愛中的情人，你眼望我眼，我眼望你眼，自自然然的用眼神去傳遞了自己的心聲似的，當我們進到靈界的狀態時，情形也差不多是這樣。～～再唱一首頌主聖歌第三三七首～1.耶穌，我正安息安息，在你無限歡樂中，我已尋得你大恩愛，得知你慈心。你吸引我注目望你，你的柔美滿我靈，你又用你「改變」權能，使我得完全。\n\n耶穌，我正安息安息，在你無限歡樂中；我已尋得你大恩愛，得知你慈心。"},{"label":"第四章 · 唱一些詩歌","text":"2.哦主你仁慈何廣大，比海更深更廣大。一哦主你恩愛何奇妙，竟全賜我身！一主啊我今安息你內，確知你恩典何豐！確知你的應許可信，更知全屬我。3.哦主我要單純靠你，我要專一仰望你，你那純潔不變的愛，滿足了我心！滿足了極深的渴慕，滿足了每一要求，更以祝福圍繞我身，你真的是一愛。4.無論在我工作安息，你永遠以臉照我，我安息在你笑容中，黑陰盡消散。"},{"label":"第四章 · 唱一些詩歌","text":"今天父面上的光輝，父神榮耀的照耀，保守我永信靠安息，以恩充滿我。•再來唱一首更普遍的，青年聖歌第一合訂本第七十三首:1.獨步徘徊在花園裏，玫瑰花，尚有晶瑩朝露，忽有溫柔聲，傳入我耳中，乃是神子主耶穌。"},{"label":"第四章 · 唱一些詩歌","text":"祂與我同行又與我共話，對我說我單屬於祂；與主在園中心靈真快樂，前無人經歷過。2.我主慈聲何等甜蜜，小雀鳥停歌屏息傾聽，主使我聽見，天上美妙至，趾我心快樂甦醒。唉！還有許多很好的靈修詩歌，差不多每本聖詩都有許多首，只可惜基督徒唱詩太注重音調，不注重詩詞意景。其實，作詩的人是因為受詩詞意景的感動才配上音調的。"},{"label":"第四章 · 唱一些詩歌","text":"更可惜的是基督徒只在教會聚會時才唱詩，在家中，在靈修時很少有習慣唱詩的，結果生活失去許多喜樂，靈修失去許多感動。，3用加神告:唱詩是靈修的一部份。唱詩的目的是利用作詩的人的靈交經驗引導我們思想集中，從而學會自己也漸漸進入靈的境界中，去用靈來禱告。用靈來禱告不一定是用「方言一禱告，我不贊成人追求方言，這一點我們將會在以後的篇幅中詳細討論。"},{"label":"第四章 · 唱一些詩歌","text":"不過，我在此不能不先指出，靈恩派的人以為他們用方言禱告才算是用靈來禱告，這一點是武斷的，是偏激的，是狹窄的，甚至許多時候會引人走向錯誤途徑的。因為他們叫人追求超自然的感受，不是追求主，結果有不少人弄至那靈附身。不錯聖經說用方言下灬濤告就是用靈來禱告～林前十四14～，但誰說只有用方言禱告才是用靈禱告:主耶穌一生未講過方言，難道祀從來就沒有用過靈禱告？或問，然則怎樣的禱告是用靈來禱告呢？"},{"label":"第四章 · 唱一些詩歌","text":"用靈禱告的意思就是在禱告中，自己的靈進入了靈界，或者說是自己的思想集中在主身上，集中在靈界裏，以致忘記了自己是在地上，這時，心靈間得到很多很大的感受，這此天焦六中有情緒上的感受，但我早已說過情緒上的感受是不準確的，這只是一種「副作用」，真正在靈裏禱告的感受是「真理」，不是情緒，意思是說，心靈間感受到主有極豐盛的啟示，祂將祂的美麗，榮耀，慈愛，溫柔，豐盛，"},{"label":"第四章 · 唱一些詩歌","text":"聖潔，威嚴，信實，應許，高貴，能力::等啟示給我，不是說我不認議先這一切的美好，乃是說我二深訂唱」真」的認議袖，「更深」有無限的深度，「上真」也有無限的深度，當我用靈來禱告時，我的靈所感受到的深度是難形容的，是不能用言語表達的，我只能說祂十分美麗，但怎樣美麗我無法述說，無法用理性的句語表達出來叫人能在悟性上有所領受。"},{"label":"第四章 · 唱一些詩歌","text":"正如我在上文介紹賈玉銘牧師所寫那首詩歌之時所指出的:「點黑無聲，以靈交談」，「無聲有聲，不言而言，心靈倍覺誠虔，靈界秘事，親耳聽見，箇中滋味，何能言宣？」保羅也說:「我們本不曉得當怎樣禱告，只是聖靈親自用一說不出來的歎息替我們禱告。」說不出來的禱告就是用靈來禱告的狀態。"},{"label":"第四章 · 唱一些詩歌","text":"或許我用較實在的講法:有時我喜歡伏在丰前，構想自己是雅歌中的一童女定投在「長人」主耶穌的胸懷，祂環抱我，摸我的頭髮，我對他說:「主啊！你全然美麗」，我好像聽見祂對我說:「你單屬於我我於是「安靜默言不的」，將頭更傾向祂，去感受他的愛，在我的思想中，我有許多感受湧出來:「我感受到像我這樣-個罪人祂還會愛我:::像祂這樣美麗的主竟然會看中我::今後，我與禹:::補與我:::何等美好的前景，我們在新耶路撒冷裏結合，要永遠同住:::啊！祂釘痕的手好像摸我的面，我好像感受到：：：主啊！"},{"label":"第四章 · 唱一些詩歌","text":"我更深深的愛你。」這樣斷斷續續的，難以形容的禱告就是用靈來禱告，因為我雖然間中有幾句話可以用言語表達出來，但當我默言無聲之時，只有我的靈才能感受到更深的層面，是我不能用言語表達的。"},{"label":"第四章 · 唱一些詩歌","text":"再說一對戀愛中的男女，他們相會時，豈是講個不停的呢？如果是講個不停的主那二定是有問題了，或者是在對罵，不！在戀愛中的男女也是千言萬語盡在「不言中」的，我們與主的關係，正是這樣有時我喜歡構想自己是一隻小羊，好牧人耶穌尋找我，把我抱起，替我纏裹傷口，領我歸回羊轉，補那無微不至的愛與關懷，祂的牧養看顧，祂的捨身保護，使我想得「入神一，想得入神在靈交中就是用靈禱告了。"},{"label":"第四章 · 唱一些詩歌","text":"有時我喜歡構想自己是一個小寶寶，天父抱起來吻一下，然後放在懷裏，放在膝上，祂不要求我向祂講一大套話，祂只要求我向祂說一聲「啊爸父！」我在祂的懷裏就以愛以靈與祂有了無限的相通，這就是用靈來禱告。聽說有一個很會禱告的人，一天有一位著名的佈道家來探訪他要求與他一同稿告。"},{"label":"第四章 · 唱一些詩歌","text":"於是二人跪下，那位佈道家先開聲禱告，當然他也是神的僕人，他的葵告一定是不錯的，一定是感人的。但當這位佈道家情詞逼切的禱告完了，理應輪到這位很會禱告的基督徒濤告了，可是等了許久，還不見他開聲禱告，這位佈道家有點不耐煩，於是掙開眼看看他是否已經入睡了。"},{"label":"第四章 · 唱一些詩歌","text":"但看他樣子又不像入睡，反而像在禱告的甜蜜中，於是双耐心等了許久，等得真難以忍受了，突然聽見這位很會禱告的基督徒開聲了，他柔聲的說:「父阿！\n\n一只一句，又靜下來了，可是這位佈道家後來對人說，他感到自己慚愧得流下淚來，因為他自己的禱告只像對神遠遠站着演講，而這位很會禱告的基督徒吼J但他卻像投入天父的懷抱，很親蜜，很滿足天父心意的禱告。比外，我常喜歡在靈修之中敬拜神，主耶穌說：一神是個靈，所以拜祂的必須用心靈誠實拜祂。」"},{"label":"第四章 · 唱一些詩歌","text":"在禱告中用心靈來拜祂，就是用靈來禱告本斯在敬拜秒時，我會思想到n+啟示錄第四冖五章所形容天上那大敬拜的情形:全能的父神高高坐在寶座上，周圍有虹，有閃電，聲音，雷轟從寶座中發出，二十四位長老都放下他們的冠冕俯伏敬拜，四活物晝夜不住的說:「聖哉！"},{"label":"第四章 · 唱一些詩歌","text":"聖哉！聖哉！主神是昔在今在以後永在的全能者。L又有千千萬萬的天使大聲說：刁會被殺的羔羊，是配得榮耀，豐富，智慧，能力，尊貴，榮耀，頌讚的。」於是天上，地上，地底下，淮海裏，和天地間一切所有被造之物都說:一但願頌讚，奪貴，榮耀，權勢，都歸給坐寶座的和羔羊，直到永永遠遠。」"},{"label":"第四章 · 唱一些詩歌","text":"我雖然依照聖經能形容出這一切，但我的靈在敬拜時所感受到的，卻是好像來到那「員實的場合」，無法形容其中的奧秘，我會化身在那大敬拜聚會當中，有時我會化身在天地之間，想到諸天正在述說神的榮耀，穹蒼正在傳揚祂的手段，而我就不其然的從心裏向神說:一神啊！我也將榮耀，頌讚，感謝歸給你::」。"},{"label":"第四章 · 唱一些詩歌","text":"我想到野地裏的百合花，雖然無人欣賞，但它們依然每天放香吐艷，天空中的小鳥，雖然很少人留意，但它們仍然每天歌唱，為甚麼呢！它們一定在歸榮耀繪禾，於是我提醒我這身為神兒女的，也應當每天清早敬拜榮耀祂。"},{"label":"第四章 · 唱一些詩歌","text":"有時我的注意力集中在神的無所不在，我會想到天地之大，我會感燼宙的充滿何等奇妙，是我能感受而不能形容的，有時我想到神的無所不知，我就會追溯到亙古之時，祂如何的揀選我，為我預備救恩，我會感數禮崗偉大，是超過我所想象的偉大，因為誰能想得透自互古至永遠和其中神一切的作為呢？"},{"label":"第四章 · 唱一些詩歌","text":"有時我想到祂的公義，祂的信實，他的慈愛，祂的能力，祂的聖潔，祂的豐盛，祂的美麗，祂的尊貴::我每思想一點，我都能進入靈界，用靈來敬拜，用靈來禱告，心中越來越與神合一，越來越被神的豐盛充滿。"},{"label":"第四章 · 唱一些詩歌","text":"讀者你如果看明白我所寫的，你是只在悟性上領會，但如果你照着我所寫的去禱告。禱告到一個地步，你發現我所寫的真是「皮毛」，不能表達萬分之一，那時你就是進入了用靈來禱告的光景了。去年，我有機會到台灣，在一個全省地方教會同工退修會裏講道，我欣然看見大會的手冊列出每天靈修時的思想中心，全避都是主耶穌的名字，規定每天思想幾個名字，讓我把這些名字列出來給各位思想。"},{"label":"第四章 · 唱一些詩歌","text":"乓二說請才人首字主到源知息慧務具安條水條天編三完扶創安代天元主族詩泉先安智溫寶平中活隘根長君良喜蔭愛門光首樹者者子的的的的所的利給的的的燈的子司者的的的的的的的的的的放泊生後當縣活多起內之熱人典的人兒你判載忘不丰和就油一放上館尹生用馬命自念恩命貼的，"},{"label":"第四章 · 唱一些詩歌","text":"配遺所所所引可負有人前全疚鐘末絕奧永避慈以生超顧賜生體神大審不不無無無吸不同自使的者者者的者者者師祭者者者者者的者的者的友者疊命羊堂理路士石盛領漆救炒養高治華罪大尊助勝喝新終義漣先豐引聖振奇餵至醫教睛至至幫得賞更成&榮首朋牧堡生羔吩真道謀煥日日日日日日日日日日日日日日日日日日日日日日日日日日日日日日1234567890DnzgabbUBDZZ人名品只要我們在禱告中思想進入到其中的豐盛，甚至有難以形容的感受，那時，我們的禱告就是用靈來禱告了一—4"},{"label":"第四章 · 用悟性禱告","text":"用悟性禱告\n\n用靈禱告完了，我們可以再用悟性禱告，我自己喜歡早上用靈來禱告敬拜，晚上用悟性禱告代求，或問甚麼是用悟性禱告呢？用悟性禱告就是用理性可以領悟的，表達得清清楚楚的，有條有理的禱告。"},{"label":"第四章 · 用悟性禱告","text":"例如以色列人十個探子報惡訊，使全會眾向神人摩西發怨言，大大惹耶和華發怒要滅絕他們的時候，摩西為百姓禱告求神赦免他們說:「埃及人必聽見這事，因為你要施展大能，將這百姓從他們中間領上來:::.如今你若把這百姓殺了，如殺一人，那些聽見你名聲的列邦必議論說，耶和華因為不能把這百姓領進他向他們起誓應許之地，所以在曠野把他們殺了。"},{"label":"第四章 · 用悟性禱告","text":"現在求主大顯能力，照你所說過的話說:耶和華不輕易發怒，並有豐盛的慈愛，赦免罪孽和過犯，萬不以有罪的為無罪，必追討他的罪，自父及子，直到三四代。求你照你的大慈愛圾多這百姓的罪孽，好像你從埃及到如今常圾見他們一樣。」(民十四0)摩西的禱告很聰明，他曉得以神的性情，應許，榮炮坊求圾金的根據，理由很充足。請注意，這種用理性淸楚有條有理的禱告，容易表達出來叫人領悟的禱告，就是用悟性來禱告。"},{"label":"第四章 · 用悟性禱告","text":"不過我們用靈來禱告必須在先，用悟性禱告必須在後，例如主耶穌教訓我們禱告～刁主千交」，以後再詳論其中的內容～，是三個「願」在先，三個「求」在後，三個願就是一願人都會你的名為聖，願你的國降臨，願你的則悶行在地上，如同行在天上」。如果我們仔細的思想一下其中的內容，我們會發現，這三個願就是敬拜，就是關心屬天的事，所以也就是用靈來禱告。"},{"label":"第四章 · 用悟性禱告","text":"三個求是「我們日用的飲食，今日賜給我們。免我們的債，如同我們免了人的債。不叫我們遇見試探，救我們脫離兇惡」。分析其中內容，全部都是屬於地上的事，是日常生活的事，是容易了解的事，所以這三求就是用悟性來禱告。"},{"label":"第四章 · 用悟性禱告","text":"屬靈的，屬神的在先，屬地的，屬人的在後，這是理所當然的。用悟性來禱告旣然是可以領悟的，是容易表達的，我贊成在我們靈修之前先把這所要禱告的事項列出來。當然隨即想到的也可以禱告，但有計劃的代禱懇求是更好的。我不是說要把每一句話都寫出來，然後用背誦的方式禱告。"},{"label":"第四章 · 用悟性禱告","text":"我乃是說，要將禱告事項點列出來，這樣會比較全面一些和仔細一些，尤其是傳道人，代禱的事實在太多了，可以分開一星期每天為不同的範圍禱告，除非有非常充足的時間，例如每天有三四小時代禱，否則實在不能關心到每一件事。"},{"label":"第四章 · 用悟性禱告","text":"看保羅的代禱，他常為各教會代禱，各教會的同工領袖也常被他記念，有些軟弱的肢體，有些教會的紛爭，有些病人，有些關於傳福理的工作。有些是關於受逼迫的信徒::這一切都經常壓在他的心中，當我們讀他的書信的開頭和結尾，尤其是羅馬書第十六章之類的部份，我們會驚奇，他怎可能會有這許多時間，會這麼仔細，關心到這許多人，這許多事？"},{"label":"第四章 · 用悟性禱告","text":"我深信他一定是有計劃的，一定是有一個自定的禱告日曆之類的時間表的。無論如何，他不會毫無準備的，到神告時想到甚麼就為甚麼代禱。因為這樣必不週全。所以我贊成用悟性禱告最好有一個計劃或程序寫下來，依着一件一件的禱告，教會領袖為自己的羊羣代禱更應這樣，依着會友名單每天為幾個代禱，直到全教會每一個弟兄姊妹都能關心到為止。用悟性禱告的內容雖然是包羅萬有的，但主耶穌教訓我們不要為衣食等事禱告。"},{"label":"第四章 · 用悟性禱告","text":"因為我們所需用的東西，我們的天父是知道的，主禱文裏為一我們日用的飲食」而求，也只是為「今日」的需要吧了。明天沒有東西吃也不可求，事實上背誦主禱文的人「今天」沒有飲食是非常少的。如果有，天父也必定照顧我們一切所需用的。主教訓我們不可為吃甚麼穿甚麼求，因訪冗要訓練我們的信心，禱告没有信心是没有作用的，如果我們求神而不信神，我們的祈求就不是祈求，而是埋怨。"},{"label":"第四章 · 靈交式讀經法","text":"靈交式讀經法\n\n用悟性禱告完了，不要說「奉主耶穌基督名求，啊們」，要把這句話押後至讀完聖經之後才說。我的意思說，把讀經包括在禱告裏面，一邊讀，一邊禱告，到讀完經之後，亦即是禱告完了，於是這時候說「奉主耶穌基督的名求，啊們」，這樣就洽當了。把讀經包括在禱告裏面，這種讀法可以稱為靈交式的讀法。因為我們禱告，是我們向神講話；我們讀經，是神向我們講話。"},{"label":"第四章 · 靈交式讀經法","text":"當我們以這種態度去讀的時候，我們就是在與神靈交。因此，這種讀法要運用感情、思敬虔去攜際經文的靈配各訓，讀得很慢，心靈間像在安靜細聽主的馨香一般，每得到一點教訓亮光，立刻用禱告向神回應，像交談一般。這種讀法，滋味無窮。當然讀聖經不能單用靈交的讀法；］這會太慢；也會不夠間。我們還有許多種讀經法，但這個要留待以後的篇章才再討論。然而，學習靈交式的讀法是非常重要的。"},{"label":"第四章 · 靈交式讀經法","text":"這種讀法能叫人看聖經為「直接從神口中講出來的話」，不是看為一本學術書去研究批判，對我們的敬虔操練，和吸收生命之道方面，尤有奇效。"},{"label":"第四章 · 結語","text":"結語\n\n這種靈修方法是一種安息、一種享受、是靈裏的享受。所以如果有人在靈修時感到苦悶、疲乏、重担，他的靈修已經走錯了方向，渭環變成不是靈修了。真正的靈修是像以賽亞書四十章二十九至三十一節所形容的「疲乏的，祂賜能力，軟弱的，祂加力量。"},{"label":"第四章 · 結語","text":"就是少年人也要疲乏困慌，強壯的也必全然跌倒。但那等候耶和華的～經常進行正常靈修的～，必從新得力，他們必如鷹展翅上騰，他們奔跑卻不困倦，行走卻不疲乏。」我們要特别注更「加鷹展翅上騰一這句話。刁上騰」表示勝過地心吸力，在靈修之中，上騰表示勝過屬地的一切引誘。諸如世事的牽掛，物質的享受，食物的需要，貪睡的舒適等等。禱告到忘記自己在地上，周圍環境一切事物都忘記了。"},{"label":"第四章 · 結語","text":"一鷹展翅」是不需要用盡力的，所以是不疲乏的，看鷹展翅，只需要伸開，揚幾下，就可以隨着氣流很自然很舒適的上騰，而且，鷹停留在天空很長的時間也不疲倦，因為牠飛在空中旣然不需要用力，也就等於休息。同樣，這樣的靈修也是不會疲乏，不會因時間長而不耐煩的。"},{"label":"第四章 · 結語","text":"「鷹上騰」是飛得最高的，同樣，真正的靈修也使人的靈像飛到神的寶座前，飛到三重天上天，與神親近。不但如此，長久進行這種靈修，還會使人得力，使公靈性高超，使人勝過試探。"}]},{"short":"靈修以外：與神同行","terms":["靈修"],"cards":[{"label":"先抓住一個重點","title":"靈修完了，主仍與你同行","lines":["作者提醒：不要以為靈修完就可以「過自己的生活」。","這樣會把信仰和生活分開。","他鼓勵人整天都記得主在身旁，隨時與祂交談。"],"takeaway":"主不只在靈修那半小時。"},{"label":"把意思拆開","title":"幾種輔助","lines":["與神約會：在平日之外，特別抽一段較長的時間親近神。","靈修輔讀物：初信者可用，但慢慢要學會自己與神相交。","靈修測表：記錄自己的情況，看看靈性是上升還是下滑。"],"takeaway":"工具是幫助，不是代替。"},{"label":"讀之前想一想","title":"教會也要重視靈修","lines":["作者認為，教會只重人數和經濟增長是不足夠的。","領袖應把靈修生活推廣到全教會。","原書這一章有測表；掃描後只餘欄目，原文卡已標明。"],"takeaway":"先有質的增長，才有真正的增長。"}],"quiz":{"question":"作者對靈修輔讀物有甚麼看法？","options":["可以用，但要漸漸學會自己與神相交","完全不應該使用","比讀聖經更重要"],"answer":0,"hint":"作者說成熟的基督徒最終要怎樣？","explanation":"他說要摸出輔讀物的路線原則，然後漸漸擺脫依賴。"},"key":"ch5","id":5,"no":"第五章","title":"靈修的輔助","bookTitle":"靈修的輔助","part":2,"partName":"紮根","partTitle":"第二站　紮根","idx":1,"original":[{"label":"第五章","text":"我們經已詳細的談論過靈修的內容方法，但是還有幾蛙與靈修有關十分重要的，無的我們無法在上幾章提及，所以我們必須再用這一章的篇幅作為一個補充。"},{"label":"第五章 · 與神同行","text":"與神同行\n\n最重要的一點是靈修完之後，不要告訴自己:現在我可以開始過自己的生活了。這種思想很危險，它不但把信仰與生活分開，而且在心理上把主耶穌留在「新稿室」裏，不要祂跟着自己去上班辦工，或上學，或在一天的生活裏管轄自己。主耶撈變成他每天靈修時的主，不是每時每刻隨事隨在的主。"},{"label":"第五章 · 與神同行","text":"所以千萬要緊記，靈修完了，起來的時候要告訴自己，主在我心裏，在我旁邊，我要與祂同行共話，我要與祂一同生活。實在的說，每早晨的靈修是特别與主親近的時間，但在日間一切生活裏，我還是不斷的與宙親近，只不个迴還小是特别的親近，而是生活在一起的親近。"},{"label":"第五章 · 與神同行","text":"我從前不明白何謂「不住的禱告」，一個人怎可能一天二十四小時不停的禱告呢？後來我看了只.英所寫的「主教導我們禱告」一書，作者指出，不住的禱告，不是一天到晚不停的禱告，而是一天到晚不停的將自己的靈向神的寶座開放，好像扭開了一架無線電對講機，校準了接收的波長，甚麼時候那一邊的對講機有訊號發射過來，這邊的對講機立刻收到，於是我們可以立刻回答過去。"},{"label":"第五章 · 與神同行","text":"同樣的，我們的靈全時間的向神的寶座開放，甚麼時候神有感動，有啟示，有提醒，有責備有話語傳到我們的心靈裏，我們立刻知道，我們就可立刻用禱告回應神。例如，我走路的時候，看見路上有許多人起著上班辦工，如果我的靈是向神開放的話，我可能收到從神而來的感動「世人可以仿世事忙，你為何不可以為屬靈的事忙？你辦屬靈的事不像辦屬世的事那樣認真了。"},{"label":"第五章 · 與神同行","text":"」我收到這樣的感動，於是我立刻可以在走路的當中，用禱告在心靈間回答神～不必閉上眼睛，也不必用長的句語或「奉主耶穌名求阿們」之類的話，只簡簡單單的回答一兩句就可以了～說:「主啊！是的，多謝你提醒，我應該更認真的事奉你」。這樣隨走路，隨做事，隨生活，時有這樣的心靈與故六談，就是把靈修放在生活裏。只可借，我們白天晚上都可能遇到許多事，但總是想不起要這樣的與神交談。"},{"label":"第五章 · 與神同行","text":"菲律賓有一位女執事，每天帶着自己十歲大的女兒上學去，她自己便去教小學，有一天她和女兒一同上學時，半途遇見亠個賊，把她身上的錢包搶去，轉身便溜入橫巷裹不見影踪，當時這位女執事嚇了一跳，一時間不知如何是好，忽然發現自己的小女兒在旁邊低頭合着雙手新芒，她立刻醒悟過來了：為何不禱告？於是她在路上簡簡單單的禱告了幾句。"},{"label":"第五章 · 與神同行","text":"禱告完了，驀然看見一位弟兄走過，於是把這事告訴他，說:「錢失了不要緊，沒有鎖匙怎回家呢？」那弟兄知道那小偷住在附近，於是託人向他討回鎖匙。後來她回到教會作見證說:「我感到十分慚愧，我身為執事，遇了事還不曉得立玖糖告，我的小女兒反比我靈性好，她曉得立列藹告。」"},{"label":"第五章 · 與神同行","text":"是的，我們日間遇到許多事不曉得立贅稿告，要到晚禱時才想起要告訴神，這是因為我們的靈沒有全時間向神開放，只有靈修時才與神交談，靈修後就把神留在新福室裏，開始自己單獨生活了。"},{"label":"第五章 · 與神同行","text":"如果我們能隨時隨在與神交談，我們的靈性豈非更高超，我們豈非更容易勝過試探！我們豈非更像主？自從我有了這個認議之後，我立志向這個目標追求，我發現我這個人是十分健忘的，每天早上靈修的時候，我總提醒自己今天記得要將自己的靈向神開放，好讓我能接收到從神而來的感動，啟示或話語。"},{"label":"第五章 · 與神同行","text":"可是，到了晚上靈修禱告的時候，我只能到神的面前懺悔說:「神附『我今天叉忘了與你交談，我怎樣才能不斷的提醒自己要這樣做呢？」我盡我的力量去提醒自己，結果我也只能一天有四五次與神交談，我不能達到隨時隨在將自己的靈向神開放，我日間遇到許多的事，但每一次我總是先想到屬世的層面，屬人的方法等等，我不能事事都先想到神的層面，我總學不會事事先與神交談一下。"},{"label":"第五章 · 與神同行","text":"有一天，我要去講一堂道，題目是「與神同行」。在路上走路的時候，我再思想一下講章的內容，我想到與神同行必須同心、同方向、同步伐:::忽然間，我想到了一點新的亮光，也是最重要的關鍵—與神同行必須將神常擺在自己的右邊—這是大衞的經驗。大衞在詩篇十六篇七至八節說:「我將耶和華常擺在我的面前，因祂在我的右邊，我便不至搖動。"},{"label":"第五章 · 與神同行","text":"因此我的心歡喜，我的靈快樂，我的肉身也要安然居住。」於是我在路上一面行，一面與神交談，在我的心靈裏，我以耶和華在我的右蕩，與我同行共話。我正式的體會到，與神同行的具體經驗是這樣的，以往我無法將自己的靈全時間向神開放，是因為我在心理上仍然以為神是在天上。"},{"label":"第五章 · 與神同行","text":"但現在我將神擺在我右，我用信心去接妥這事實，於是我就能更多的與神同行共話，好像真有一位「隱形」的朋友在我身邊常常伴着我一樣。我以這種「靈交放在日常生活中一為我個人追求的目標，我知道，我還要操練，再加操練，才能達到最理想的境界。目前我雖然還在操練中，但神旣然教導我這方法，我深深的願意更多主內肢體都一同走這與神同行的路。"},{"label":"第五章 · 與神同行","text":"仁：.山帶神約食\"除了每天靈修和與神同行之外，我近來還深深的感到有一個需要，在一年之中，抽兩三次假日到郊外安靜的地方，與神有一個特别的約會"},{"label":"第五章 · 與神約會","text":"與神約會\n\n是甚麼？為甚麼這是一個「特别一的約會？為甚麼我們需要這種約會？我從前對這名稱是一無所知的。有一次，我們的教會推行了一個「獨立追求運動」。目的是鼓勵弟兄姊妹在聚會以外還抽時間出來追求屬靈的長進。其中包括了讀屬靈書籍，靈修，個人生活見證等等。在這運動中，我們安排了一個特别的見證聚會，請了四位全香港知名熱心追求事奉主的基督徒回來，講述他們自己獨立追求的經驗。"},{"label":"第五章 · 與神約會","text":"其中有一位說，他無論怎樣忙，在一年之中總有一兩次抽一個星期或三幾天到郊外去「與禾改會」。這不是度假，旅行，享受一下郊野風味。與神約會只單單為讀經，新祝，檢討自己的靈性和全家的靈性生活。這個見證打入我和全教會弟兄姊妹的心，自此，我的內心就常常想到這一個需要。"},{"label":"第五章 · 與神約會","text":"我感到這種與神約會是需要的，因為每天的靈修實在時間有限，又因日間工作太忙的原故，就是與神同行共話也不夠深入，這些只能在「量」上增加我與神的靈交，但在質」上，我仍感到有不足夠的現象。工作忙是一個問題，「心忙」卻是更重要的問題。「忙」的生活，使我們的精神，身體，靈性都出現了「「透交」的現象。\n\n我們的身體需要休息，我們的精神需要休息，同樣我們的靈也需要在主裏享受真正的休息。"},{"label":"第五章 · 與神約會","text":"神為以色列人安排了每七日就有一日「安息」，每七年就有一年「安息」，每七個七年就多加一年「安息」，一年之中還安排了七個節期，也是坊從以色列人「安息」，這些安息不單為身體在工作方面有休息的機會，同時也在精神靈性方面有安息的機會，以色列人在安息日親近神，在節期中檢討自己的生活，有認罪，有感恩，有敬拜，有學習律法，這是神的安排設計。"},{"label":"第五章 · 與神約會","text":"並且神特别一賜福」給這些安息的機會～創二3～。我們基督徒雖然不必再守安息日，安息年和節期，但身體，精神，靈性的安息仍是需要的，將這安息的原則應用到我們的靈修生活上，我覺得一年之中有一兩次抽假期去與神約會，不論對我們的身體，精神，靈性都有大幫助。"},{"label":"第五章 · 與神約會","text":"在與神約會之中，我們可以有充足的時間透透微微的研究完一卷聖經，我們也可以透透微微的檢討一下自己的性格和靈性狀態，從而作出一個有效的改善計劃，我們還可以無牽無掛的，盡情盡意的與神有一段甜蜜的靈交，更深入的思想主的美麗，豐盛，榮耀，權能:::也讓自己更進入祂的豐盛。"},{"label":"第五章 · 與神約會","text":"這是何等美好的一件事，夏命會和各式各樣的退修會原本就是為這個目標而設，可是許多參加夏令會和退修會的弟兄姊妹並沒有對準這個目標去參加，而許多夏令會退修會也沒有對準這個目標去進行，結果許多夏令會退修會並不能使人「安息」，反而使人「忙亂」。"},{"label":"第五章 · 與神約會","text":"我以為尤其是在教會中作領袖的，在夏令會中作職員的，他們必定忙個不了，所以十分需要個人單獨與故御會，事實上，許多神偉大的僕人是在這種特別與神約會中得到大復興。"},{"label":"第五章 · 靈修輔讀物","text":"靈修輔讀物\n\n初得救的基督徒尤其感到靈修的困難，在禱告方面，不曉得怎樣思想主自己，不懂得靈交是甚麼。在讀經方面不明白聖經的意思，感到無從入手，在這種困惑乏味的狀態下，許多人就放棄了他的靈修生活。"},{"label":"第五章 · 靈修輔讀物","text":"於是有經驗的人就感到有需要將一些神偉大僕人的靈修思想感受寫下來，可以給初入門的基督徒作一個引導，這一類的靈修書在中英文書籍中也不少，值得介紹的有—1.擧世知名的「荒漠甘泉一。台灣蔣介石總統一生最愛讀，認為最得幫助的書有四本:聖經、荒漠甘泉、三民主義、唐詩三百首。這四本書也是蔣總統的陪葬品。自從這消息一宣告出來之後，全台灣甚至世界各地都大量銷售荒漠甘泉。"},{"label":"第五章 · 靈修輔讀物","text":"各非宗教書店也有出售。事實上這是一本好書，還有「新荒漠甘泉L。2「遠溪清流」是一本啓發人思想的靈修好書。3「黑門山路」適合青年人用。4「嗎哪」，英文本名一y［Jtn10StITor•H—是一本相當深入的書。"},{"label":"第五章 · 靈修輔讀物","text":"6「谷中清泉7.效法基督」是一本古書，英文本名品Imitatic）1Chris」，注重對付自我，9「靈修日新」幫助讀經的有：10「每日讀經釋義」尤其適合初信者。11.清晨靜思主話」是一本只有啓發性問題的輔讀物。12.乛靈修日課」有解釋的輔讀物。"},{"label":"第五章 · 靈修輔讀物","text":"13.一聖光日引」全部以聖經節按不同主題編成。艹「ea］zchleSm3—適合大專程度的青年用，也是一本只有啓發性問題的輔讀物。中文本是「研經日課」。以上的靈修輔讀書籍各有各不同的特點，但目的都是為幫助初入門的基督徒在靈修時有正確的思想。可是我們不能一生靠這些輔讀物過活，太過依重輔讀物的基督徒學不會自己讀經解經，學不會與主進一步的靈交。"},{"label":"第五章 · 靈修輔讀物","text":"我們都可以有靈修輔讀物，但我們要學會漸漸的摸出靈修輔讀物裏面的思想路線和原則，從而泗泗擺脫輔讀物的輔導，進而自己單獨的與神靈交，這才算為一個成熟的基督徒。"},{"label":"第五章 · 靈修測表","text":"靈修測表\n\n如果我們喜歡看看自己的靈修和靈性進度的情形，從而研究出進展慢和進展快的原因的話，設計一些靈修測量表來觀察自己也是好的些測量玥還有提醒的功效，當自己的靈修和靈性走下坡時，圖表的曲線向下走，就會提醒自己檢討悔改，也會幫助自己找出其中的原因來。"},{"label":"第五章 · 靈修測表","text":"測量表的種類有許多，也可以自己設計一些特别適合自己用的。在此，我建議以下幾種測量表給讀者:（例一）讀經與禱告比較表\n\n（原書此處為「靈修測表」表格，掃描後只餘欄目：讀經、祈禱、最理想、得力、享受、正常、習慣性、沉悶、懷疑、日、期（例二）祈禱的情緒，進入靈界深度，"},{"label":"第五章 · 靈修測表","text":"與自潔程度比較表、情緒、激動、興奮、感動、安息、普通、煩悶、討厭、日期、進入靈界深度、合、見主、愛主、相通、普通、地上、黑暗、日期、自潔程度、像主、一切為主、無愧於主、無虧艮心、普通、汚穢、不敢禱告、日期（例三）靈修情況，與神同行情況，"},{"label":"第五章 · 靈修測表","text":"勝試探能力比較表、靈修情况、最理想、親近主、有感動、有興趣、普通、馬虎了事、討厭、日期、與神同行情況、完全合一、峙刻與神交談、有感觸時禱告、遇大事會禱告、普通、怕見神、離開神、日期、勝試探能力、被聖靈充滿、控制靈、控制魂、控制肉體、普通、不能自制、放縱情慾）"},{"label":"第五章 · 推廣靈修","text":"推廣靈修\n\n如果你是教會的領導人，或團契的負責人，你還應有一個責任，就是將靈修生活推廣至全教會。一個教會如果不注重靈修生活，不單直接影响會友的靈性變下，工作無力，而且也會漸漸變質，因為在屬靈的層面沒有人去攔阻撒但做破壞工作。所以，教會要增長，必須先重視質的增長。沒有好的質，也必沒有增長的力。可惜今天許多教會只注重經濟增長，人數增長，禮堂擴大，在靈性生命上的增長反而忽略了。\n\n或問，究竟有何方法使全教會都重視靈修生活呢？"},{"label":"第五章 · 推廣靈修","text":"以下的方法可能是很基要但常被人忽略的：一在申請受浸時查閱靈修生活—在我所牧養的竹會要，見想要申請受浸的人，必須先填寫一份表格，這份表格當然包括申請人的姓名地址年歲等，但這表格更重要的是要他填報自己的聚會情况；例如經常參加那些聚會，在聚會中有受感動沒.有，最得幫助是那一個聚會等；信仰情况：例如會否有過懷疑，信心、愛心、對神、對人、對事奉的長進或退步情況等。"},{"label":"第五章 · 推廣靈修","text":"其中我們特别重視的是他的靈修情況，他必須寫明有否每日讀經悶祝，新禧的時間長短，讀經的章數多少，現在讀經讀到何處，開始每日靈修的習慣至今多久，每次靈修的感受如何，有否靈修輔讀物，有否每次謝飯等等。我發現許多人拿了表格回家填寫的時候，如果他沒有靈修，或靈修的情況很差，他根本就不敢交回表格。直到他勉勵自己有好的靈修生活才再申請受漫。"},{"label":"第五章 · 推廣靈修","text":"雖然靈修生活不好不一定是等於不得救。但最低限度我們可以從他的靈修生活看到他的露命是否健全，或者根本沒有屬靈的生命。一個真有屬靈生命的人，他不可能對一切屬靈的事物都沒有興趣的，再者，讓申請受漫的人明白靈修生活的重要性是何等重要，這是最基本不過的。"},{"label":"第五章 · 推廣靈修","text":"任何一個基督徒，最肯接受勸告的時候就是他申請受漫的時候，此時不勉勵他有好的靈修生活，日後勸他就難了。如果我們要求每一個受漫加入教會的人都必須有靈修生活的話，那麼，自然全教會的弟兄媽妹就個個都有靈修生活了。2在議道時經常強調靈修生活—我發覺每一個人都有天生的情性，受漫之時有好的靈修生活，未必等於以後都會有好的靈修生活，惰性會趾人的靈修停頓或轉弱的。"},{"label":"第五章 · 推廣靈修","text":"所以我們身坊教會領導人的，應該常常加以提醒，提本一次不夠，十次八次也是不夠，要經常接需要接情形或輕或重的提醒，重的可以講一堂以靈修仿題的道，輕的可以在鹿道時指出—「如果你沒有靈修生活，你可能不會明自我今天所講的道，因訪我所講的會牽涉許多聖經歷史教訓背景在內，我沒有時間詳細講解那些背垃，不然就不夠時間講道:所以有靈修的人，就是有經常讀聖經的人，"},{"label":"第五章 · 推廣靈修","text":"他不但因為知道那些聖經背景而能明白我所講的道，而且往往因仿聽一篇講道，秘發他同時明白他平常讀經時所不明白的，於是他所得到的不單是一堂道，而是幾堂道。可見靈修的重要。」這樣的一段話可以經常重複提及，直到全教會都重視靈修為止，我發現一個勸勉要重複許多許多次才能打進全會衆的心靈裏的。"},{"label":"第五章 · 推廣靈修","text":"，3由教會全體長老執事同工帶出影響力—我以坊傳道人在帶領長執同工會議之時，第一段時間應該先交通一下長執同工本身的靈修和靈性問題，這不一定是指責靈性不好的長執同工，～但有時也可能需要按份量輕重加以溫和的指責的～大可以請自以為靈修好的長執同工講一些自己的感受心得，尤其是與領導教會的崗位有關的心得。"},{"label":"第五章 · 推廣靈修","text":"經常這樣强調靈修，長執會議才會屬靈，討論才會有準確方針路線，靈修和靈性不好的長執自然會不敢亂發言或不敢强橫控制教會。不過，最重要的還是加强推動全體長執作全教會弟兄姊妹靈修和靈性的榜樣:傳道人應在講道時强調這一點，鼓勵弟兄姊妹有靈性或靈修上困難的向各長老執事請教。"},{"label":"第五章 · 推廣靈修","text":"如果長老執事沒有好靈修的，他們就必原形畢露，從而趕緊追上，如果長老執事有好的靈修生活的話，他們一同協助影響全體弟兄姊妹，那麼影響的範圍就闊得多了。"},{"label":"第五章 · 推廣靈修","text":"我們要推廣到全教會的弟兄姊妹都深深有一個感覺「「沒有靈修生活是最丟臉，最不敢告訴人的事[這樣才算進入成功的第一步。以後教會選立任何一個長老，執事或同工，都會很自然的按候選人的靈修靈性為標準，不會按他的勢力，才幹，家勢，名譽為標準，教會就長進得健全了。"},{"label":"第五章 · 推廣靈修","text":"4舉行一些以靈修旋重的特別聚會當-個教會落在整體的靈修靈性低沉的情形齊時，就必須使用特殊而強烈的補救辦法了，我發覺許多教會只會照傳統每年開一兩次佈道大會，開一兩次培靈大會就以為可以復興教會了，誰知往往這些聚會不能對症下藥，例如靈修不好，單是一兩次培靈議道是不夠和的，必須加上其他的特別聚會，諺如清最集體靈修聚會，讓弟兄姊妹實際學習怎樣露修，有些衝會每週都有這樣的聚會，有的每天都有，為何世人可以每天集體行晨運，我們不可每天集體靈修？"},{"label":"第五章 · 推廣靈修","text":"還有靈修見證大會，靈修書籍介紹聚會，代售或謙價出售新富跪吾，推行小組新稿，新太網，讀經團契，聖經問答比賽，全日研太會，兒外靜修會等等。\n\n這些聚會的學行，都是需要特別設計，目的為針對教會的真正需要。但要註居，這些聚會不能與旅行，遊戲，或任何輕鬆的活動混為一談，要達到理想靈修的目的絕不是輕鬆的事，反之，可能是痛哭，悔改，認罪，對付自我，器書面對神的事。所以推行這些特別聚會，從策劃，宣傳，籌備到實踐，都需要好好的思想稿告，因為仇珊魔鬼必不會輕易記過，我們要履「備戰」的態度來推行才對。"},{"label":"第五章 · 推廣靈修","text":"當然，推廣全教會靈修還有別的方法，但我以信只要我們持定這個日標，一心要推廣，一心要親近神，終有一天，總有一個有效的方法，我們會達到討祝喜悅的階段的。"}]},{"short":"照這個樣子禱告","terms":["主禱文"],"cards":[{"label":"先抓住一個重點","title":"主禱文是禱告的「樣子」","lines":["作者指出，主耶穌說「要照這個樣子禱告」。","重點不是背誦，而是學習它的結構、次序和內容。","我們本不懂得怎樣禱告，主禱文就是榜樣。"],"takeaway":"學的是模式，不只是字句。"},{"label":"把意思拆開","title":"全面性的禱告","lines":["先稱神為「我們在天上的父」：這是親密的靈交。","然後關心神的名、神的國、神的旨意。","再求日用的飲食、赦免、脫離兇惡：而且是為「今日」。"],"takeaway":"先神後人，先屬靈後屬地。"},{"label":"再看一個細節","title":"最後一句的出處","lines":["作者提到，「國度、權柄、榮耀…」一句在聖經小字註明有古卷沒有。","所以他討論結構時沒有包括這一句。","這是作者的經文看法，讀者可再參考其他資料。"],"takeaway":"留意聖經小字的註明。"}],"quiz":{"question":"作者認為主耶穌教主禱文，最主要想門徒怎樣做？","options":["學習它的結構和次序來禱告","每天背誦很多次","只在聚會時一起唸"],"answer":0,"hint":"留意「照這個樣子」幾個字。","explanation":"作者說主耶穌注重的是禱告的樣子：結構、次序、內容。"},"key":"ch6","id":6,"no":"第六章","title":"「主禱文」","bookTitle":"「主禱文」","part":2,"partName":"紮根","partTitle":"第二站　紮根","idx":2,"original":[{"label":"第六章","text":"保羅在羅馬書第八章二十六節說:「我們本不曉得當怎樣禱告，只是聖靈親自用說不出來的歎息替我們禱告::因為聖靈照病故的則妃引聖徒祈求之保羅所說的「我們5•不但包括他自己，甚至連全人類都包括在內，因為全人類沒有一個人能「照著神的旨瑟」新求，所以聖靈來為我們祈求。但聖靈替我們新禧是用「說不出來的歎息」，這個對於•我們來說，我們永遠學不會的，因仿修明白。"},{"label":"第六章","text":"我們能明白，又可以學會作最好的禱告，就只有主耶穌教我們學的禱告文了，因為主耶穌一定明白神的旨总，又一定照神的旨意來教我們禱告無穎。所以下I）取好，最理想，最曰合神心意的禱告就是我們通常稱為「圭芒女」的祠告了。"},{"label":"第六章","text":"在此我要再一次指出，靈恩派的人士以為用方言禱告才是用靈禱告，才是更屬靈更合神心意的禱告，這是錯的，我們不否認在聖經時代用方言禱告就是用靈禱告，正如我在前一章已經說過，禱告中進入靈界，感受到難以用言語表達出來的禱告也就是用靈來濤告。"},{"label":"第六章","text":"而且聖經並沒有說用方言禱告就是更屬靈更合神心意的禱告，反之，能效法主入交那樣方式的禱告才是最好最合神心意的禱告。主往交裏沒有方言，主耶穌一生也沒有教導人用方言禱告，祂自己也從未試過用方言禱告可見我們不一定要追求用方言芒告我們應該追求的，是主篇女那樣的禱告。"},{"label":"第六章","text":"可惜，今天我們看見很少人明白主芒女的禱告何以是最好最合神心意的禱告，大家只會背誦，而且甚少在背誦的時候心中思想其中的意思的。\n\n我們指責天主教和别的宗教有「念經」的習慣，理由是他們用重複話來禱告，違反主耶穌的教訓，因為人用重複話來禱告時，心中的思想不可能襲所說的話相同，於是這就等於「用咀唇敬拜神，心卻遠離神」了。其實，背誦主社交的人，豈不也是這樣嗎？"},{"label":"第六章","text":"我不是反對背主禧文，我乃是反對背主褚女而口是心非的態度，背主祝交就等於背聖經，所以我不能反對人背聖經，但背主社交而口是心非者常以為這就是一種最好的禱告，那就錯了。"},{"label":"第六章","text":"如果我們仔細讀聖經，我們會發現主耶穌當時根本就不是教導門徒背祂所教的禱告詞，我們有許多很强烈的理由支持這一點看法，現在讓我們一面提出這些理由，一面思想一下主稿女的內容為甚麼是最好，最合神心意的禱告。「進你的内室。"},{"label":"第六章","text":"日日6刚上門已細讀馬太福音第六章主耶穌論禱告的那一段經文，我們會發現，在主說出「主稿女」(第九節)之前，祂先教導門徒禱告的態度(第五至八節)，不要愛站十字路口或會堂～公關的地方)稿告，這是假冒為善的人所作的。"},{"label":"第六章","text":"禱告的時候要「進入內室，關上門。「～私人的地方一禱告在暗中的父。這樣請問，跟着主所教的「主彷婦」是為公禱的？還是為私濤的？我相信沒有人會說是為公禱的。那麼，為甚麼今天背主社交的人只在聚會公禱時背，不在私禱中背？而且我也從沒有聽見過有牧師說他自己常在私禱中背主祝女，或在講台上勸勉人在私禱中背主乎妳，可見這是與主耶穌原本的意思相反了。"},{"label":"第六章","text":"主耶穌的意思是說，圭太交最適宜在暗中個人與天父靈交時用的。最好最合神心意，的禱告應該是以一暗中的父」焦祝告的對象，不應該以「故意叫人看見」為目標。換言“之，主耶穌所教的禱告文，其實就是每天個人靈修的禱告文，個人靈修的新稿與公禱有一個很大的分别，公禱時是為聚會，仿別人或代表别人禱告，靈修時是為自己與神的關係禱告。"},{"label":"第六章","text":"公禱不能有固定的形式，因為每次聚會，每次所注重的都不同，但私禱可以有較仿點定的模式，因為每天靈修所面臨的事，大致上都是差不多的。如果我們用這個角度去看「主禱交」，我們就發現，主隔女只適合於私蘭，不適合於公禱。或許有人指出’“主千克第一句就是「我們」，那不是「公禱一嗎？不！當時主耶穌用「我們」二字，思坊生教導全體門徒，不是教導一個門徒"},{"label":"第六章 · 「你們要照這個樣子禱告」","text":"「你們要照這個樣子禱告」\n\n主耶穌開始教導門徒的時候，請注意祂不是說:「你們禱告，要這.樣說」我們的中文聖經翻譯得不是最準確，其實英文聖經與原文聖經都是說Lfter11Slanner.YO1pr•準確的譯法應是「你們要照這個樣子芒告\"當然主耶穌的意思不是要門徒背誦，如果是背育，補一定清楚說明，主耶穌所注重的是「主祝婦」的樣学；亦即是主袖交的結構，次序，內容等等。\n\n請看主芒婦的結構層次:1稱呼:「我們在天上的父」"},{"label":"第六章 · 「你們要照這個樣子禱告」","text":"2三願望：（a）一願人都尊你的名為聖一—1先敬拜（b一願你的國降臨一1—關心神的國（c一願你的旨意行在地上，如同行在天上。」神的旨意就是神的義，3三祈求：（a）一我們日用的飲食，今日賜給我們。一—為自己所需（b一免我們的債，如同我們免了人的債。一—為與别人的關係（c一不叫我們遇見試探，救我們脫離兇惡。"},{"label":"第六章 · 「你們要照這個樣子禱告」","text":"一為與魔鬼的關係在先的「三願望」是關心神的國和神的義，這正是主耶穌所教訓的，「你們要先求他的國和祂的義，這些東西(日用飮食等東西)都要加給你們了」(太六@)。三個願望稍後再詳細研究。跟着在後的三祈求都是關心自己的一切:自己所需，自己與人的關係，自己與魔鬼的關係，主將為自己所需的祈求放在三個祈求中的第一個，表明祂十分愛我們，關心我們所需用的一切。"},{"label":"第六章 · 「你們要照這個樣子禱告」","text":"可是請注意，主耶穌只准我們签“今日」所需的祈求，不准我們為「明天」所需的求，因為祂在同一章的後半部指出:「不要為明天憂慮，因為明天自有明天的憂慮，一天的難處一天當就夠了。」只要我們先求神的國和神的義，這些東西都要一加」給我們了，「加」字的意思是不用求，天父自動會按時賜下的。所以主禱文裏指明日用的飲食，只求神「今日一賜給我們。"},{"label":"第六章 · 「你們要照這個樣子禱告」","text":"換言之，如巢我們今白已經有了所需用的飲食，就可以在福告中減去這一句，或將這一句履坊感恩的禱告。可是，遙看見許多基督徒，不但今日有飲食，明日也有，有的甚至一生的飲食也不成問題了，他仍背這句話，最可笑的就是晚上聚會完了，聚會的主席習慣請大家背了主社交才散會，其實他們那一天三餐已經吃過了，怎好瑟思再向神求「今日」的飲食呢？"},{"label":"第六章 · 「你們要照這個樣子禱告」","text":"仿此，我不敢背主篇女，別人背，我盡量用心去附和，但背到這一句，我不能附和，我只在心中感謝神已將一切所需的竟給我。\n\n我深信，主耶穌這樣的教導，分明是要我們反省感因的。三新求的第二求是為自己與別人的關係，主耶穌藉此提醒我們要愛別人，要原諒別人。不過請注瑟，真正用心靈去思想這句話的人，必定發現主耶穌將這句話的次序倒轉了。和說:「殉我們的債，如同我們匈了人的債」，瑟思是說:「天父求你肯夠我們的罪。你看伯也赦殉了別人的罪了，人我怎樣赦免別人的罪，求你也照樣(即「如同」)圾更我的罪。"},{"label":"第六章 · 「你們要照這個樣子禱告」","text":"」我不敢背這一句，因為如果天父員的照我航見別人的樣子圾匈我的話，我的罪還在，我自問，許多時候我雖然肯原諒別人，但我原諒得不夠徹底，我的腦子裏總是留下得罪我的人的陰影。"},{"label":"第六章 · 「你們要照這個樣子禱告」","text":"如果下一次他再得罪我的話，他以前一切的罪過又再一次出現在我的面前，可見我並沒有完完全全的赦免他，像天父赦匈我一樣，如果天父照我圾免別人的樣子散匈我，我想我所有罪的陰影必定仍在天父的眼前，那我就活不了，所以，我每一次想到這一句神告女，我心中總是說:「天父，我知道我應該這樣求，但我不敢，求酥照你的應許先瘋匈我的罪〞好讓我可以學習照你赦免我的樣子去散匈別人公签西三13～因為主耶穌說你先毅匈那欠你一千萬兩銀子的僕人，然後你才要求那僕人赦免別人十両銀子。」"},{"label":"第六章 · 「你們要照這個樣子禱告」","text":"可是主耶穌在講完「主竺女」之後，跟着立刻加强指出:「你們饒恕人的過犯，你們的天父也必饒恕你們的過犯，你們不饒恕人的過犯，你們的天父也必不饒恕你們的過犯。"},{"label":"第六章 · 「你們要照這個樣子禱告」","text":"」主這樣說是「理所當然」的次序，但祂用大恩大愛改變了這個次序。所以我們先得到天父的赦免，主耶穌是先為我們捨命，然後，我們才照主的大愛去愛人並散見人，如果我們先得到主的愛，主的赦免，我們還在禱告中不肯去圾金人，我們要担的罪是何等的大呢？三祈求的最後一個求是為自己與撒但魔鬼的關係。"},{"label":"第六章 · 「你們要照這個樣子禱告」","text":"主將這一個放在最後，表示撒但的權勢極小，只要我們保守自己在主的愛裏，我們就可以勝過牠，-不叫我們遇見試探」是我們不要去接觸撒但，「救我們脫離兇惡」是撒但來接觸我們時，我們要避開牠。"},{"label":"第六章 · 「你們要照這個樣子禱告」","text":"可是這得勝的關鍵全在乎我們順服神的帶領才能「不遇見試探」，信靠禮的能力才能得I～救脫離兇惡一品既以這個新求使我們反省前面兩個祈求立買我們明天沒有東西吃的時候‘一\"我們要留心撒但會趁這機會來試探我們。當别人欠我們的一債一的時候，我們要小心那、惡者(註疙聖經的小字～會來唆擺我們不要赦免别人。^r像這樣完全，合神心意的新禧千構正是主耶穌教導我們要學習的「樣子」。"},{"label":"第六章 · 古卷無最後一句","text":"古卷無最後一句\n\n-或許有人會問，仿甚麼我論及主禱文的結構時，不提及「因為國度，權柄，榮耀，全是你的，直到永遠阿門」這一句？是的，因為這一句話根本不是出自主耶穌所說的，請看中文聖經馬太福音六章十三節最後的小字，那裏豈不是註明「有古卷無因為至阿們等字」嗎？原來這一句話只出現在第入世紀的。：od.eX8RUS：COODo二ogoo二本古卷裏。"},{"label":"第六章 · 古卷無最後一句","text":"其他古卷完全沒有這一句，我們知道天主教早在主後五九年時已經成形，並且背放新社交的習慣也漸漸流行，他們把這段經文改為背誦用的新禧妳，所以加上這最後一句，到後來第入世紀抄聖經的人以為這句話旣已流行了，不妨加進聖經裏去，到第十六十七世紀宗教改革的時候，基督教認為背新福不合真理，所以把天主教所有的新社交都廢棄了，唯有這一個主芒女大家以為旣然是主耶穌所教導的，就可以存留下來。"},{"label":"第六章 · 古卷無最後一句","text":"那時，他們還未發現這個主稿女的最後一句是後人加上去的，一直到近代研究古卷的學者才發現。事實上看經文本身，如果我們把這最後一句減去了，上下交放通順一貫。再者，路加福音也有記載主彷女，但路加所記的就沒有這最後一句了。如果主耶穌教人禱告是要人背的話，怎麼連路加也背漏了一句呢？不，路加壟沒有背漏一句，路加所記的是聖靈所默示的，最準確無誤的。"},{"label":"第六章 · 古卷無最後一句","text":"因此，我們清楚的看見，主耶穌並沒有教導門徒這最後一句。那麼，主禱文沒有了這最後的一句，還能成為一個完整的禱告交嗎？自然不能了。因為主並沒有教訓人去背，只教訓人照這個一樣子」去禱告吧了。再退一萬步來說，如果我以上的解釋全部是錯誤的話，請問，為甚麼我們並沒有看見聖經記載以後門徒們有背這主芒女？為甚麼使徒行傳和所有新約書信也沒有提及？"},{"label":"第六章 · 古卷無最後一句","text":"再參考初期教會的歷史，為甚麼也沒有發現古時的教會有背主往交的習慣？一個鐵一般的事實，主宇交根本不是用來背的。\n\n旨全面性的造”再者，如果我們仔細的思想一下主禱文的內容，我們會發現主教導我們的禱告，不是一個禱告，而是許多種不同的禱告合在一起的禱告，亦即是"},{"label":"第六章 · 全面性的禱告","text":"全面性的禱告\n\n，這個全面性的禱告不可能一口氣背出來的，請看1靈交的禱告—「我們在天上的父」。舊約所有的聖徒從沒有一個敢稱禮仿父的。整部舊約的聖經只能找到幾位偉天的先知！"},{"label":"第六章 · 全面性的禱告","text":"質經有過幾次用比喻方式來稱祝仿父八十三16，六十四8’申三十二6，代上二上LU•耶三17等～。他們每次想到神，卻是想到和的威嚴、神聖、可畏、高高在上，只—-有大祭司一年一次帶着牛羊的血戰戰兢兢的進入至聖所親近神。如今主耶穌教導門徒新禧說「我們在天上的父」，門徒聽見這句話豈不是十分十分的感到希奇嗎？"},{"label":"第六章 · 全面性的禱告","text":"主升天之前又再對門徒强調這一點說:「和發要升上去見我的父，也是你們的父」(約二十19～。可見，主耶穌賜給我們這作兒女的位份是勝過舊約所有先知祭司的位份。"},{"label":"第六章 · 全面性的禱告","text":"我不贊成基督徒新芒之時常說一神啊」，因為這樣說好像與神有一個距離，除非是認罪悔改信主之時才適合稱神為神。不然，我們應常稱神為「天父一才對。主耶穌一生禱告都稱禮必父，只有在十字架上担當我們的罪的時候，才說：一神啊！神啊！為甚廢離棄我」。保羅新神也是說「我在父面前屈膝一～弗三14～。"},{"label":"第六章 · 全面性的禱告","text":"當我們站在兒女的立場上，不是站在罪人的立場上裙告，我們的禱告就親切得多了二好’刈像蒙慈愛的兒女一樣一～弗五1～的來到神面前，父親把兒女抱到自己的懷裏，這樣的禱告，正如我在上一章所說的，是一種靈交的禱告，是甜美的，是蒙福的，是親切的。"},{"label":"第六章 · 全面性的禱告","text":"2敬拜的禱告一酯人都拿你的名仿吾」。我們可以說前三願望的禱告是用靈來禱告，後三個祈求的禱告是用悟性來禱告。用悟性的禱告即是理性可以領悟得來的禱告，這方面我們已經在上文交代清楚了，用靈來禱告即是自己的靈感受到靈的境界，感受到神自己一切的豐盛，以致無法用可以理解的言語來表達，只能「疙會」而不可以-言傳」。"},{"label":"第六章 · 全面性的禱告","text":"這樣，為甚麼我說前三願望的禱告是屬於用靈來禱告呢？現在讓我們一-來思首先我們想一想「願人都尊你的名為聖」這一句。假如我們將自己放入這句話的更卉裏的話，我們會看見以賽亞先知所看見的聖潔的主，以致撒拉弗也因神的榮光而用翅膀遮臉遮腿，並且晝夜不住的說:「聖哉！聖哉！聖哉！"},{"label":"第六章 · 全面性的禱告","text":"一以賽亞先知只能形容撒拉弗的反應，他無法形容神的聖潔到底聖潔到怎樣的程度，我們讀那段經文的時候，對神的聖潔只可意會而不可描述，我們由撒拉弗的反應，以賽亞先知立刻說自己「禮謊」的反應，我們可以想像得到神是何等的聖潔，當然我還會想到啟示錄第四第五章所形容的天上大敬拜，四活物也畫夜不住的說「聖哉！"},{"label":"第六章 · 全面性的禱告","text":"聖哉！聖哉！一我們會看見二十四位長老俯伏敬拜，千萬天使唱新歌的情景。還有，我們也可以想像神降臨在西乃山上，以致山頂冒煙心，有雷轟IN密雲宜角聲，火焰，神親自大聲說：一凡摸這山的都要把他治死」，以色列人怕得魂不附體，這一切都反映神的威嚴聖潔。"},{"label":"第六章 · 全面性的禱告","text":"但當我們真的在禱告中自己的靈進入到這種境界時，我們所體會的必定遠超過我們所能在這裏表達的，何况，我們還可以坦然無懼的進到這位聖潔的父面前，那種感受豈是我們可以形容得來的？我們會不其然的說:「父啊！你是聖潔的，我也要聖潔，但願所有人類都尊你的名為聖！」"},{"label":"第六章 · 全面性的禱告","text":"一說到願所有人類都為聖—時，我們又會想到全人類敬拜神的場面何等的偉大，試把這個意境變成圖畫來想一想，那豈是我們所能形容的？所以我稱這種禱告為用靈來禱告，同時也是敬拜的禱告，耶穌說:「神是個靈，所以拜祂的必需用-心靈』和誠實拜祂一，用「心靈」來敬拜，就是用靈來禱告。"},{"label":"第六章 · 全面性的禱告","text":"可惜，今天背主稿女的人甚少學會敬拜的禱告，甚少學會用靈來禱告，他們以仿祠告就只是「求」，一天到晚求神賜這個賜那個給自己，全不想到主教訓我們要敬拜在先，敬拜不是為己，而是為神，是將榮耀頌讚歸給神，但願背主禧婦的人認真考慮這一點：先敬拜神，將榮耀歸給祂，這樣你的祈求就蒙悅納了。\n\n3爭戰的禱告—「願你的國降臨」。"},{"label":"第六章 · 全面性的禱告","text":"想到神的國降臨，我們就想到神的計劃成功，神征服了世界，敗壞了仇敵魔鬼，主耶穌駕着天上的雲降臨，地上萬族都要因祂哀哭，主的榮光充滿全地，有千萬聖者隨若袍，於是主統治世界，平定天下，撒但被所繳:::這一切的情形絕不是背一句話的時間可以意會，必須花上半小時以上，用最敏銳的靈才能意會，當我們意會到這一切的時候，我們說:「願你的國降臨」，我們的心意即是說:「父神，"},{"label":"第六章 · 全面性的禱告","text":"但願你早日打敗並摺鄉仇敵魔鬼，使你的國可以早日降臨，至於我，我個人準備好了，我十分願望你的國早日降臨，我也曉得，為了使天國早日降臨，我自己也必須加入這場與天空中屬靈氣的惡魔對抗的爭戰，搶回失落的羊。"},{"label":"第六章 · 全面性的禱告","text":"」於是我們站在與撒但敵對的地位，我們的心境好像當自己是一個天國的戰士，為天國而戰，這既然是一場屬靈的爭戰，所以這個禱告也就是用靈來禱告，可惜，許多背主樞女的人從來沒有試過爭戰的禱告，不為人的靈魂着急，不想到主的再來，不記得自己是天國的子民，他們的禱告只知為己，不知為神的國，這樣，背主祝交有何意義？"},{"label":"第六章 · 全面性的禱告","text":"4與神同行的禱告「願你的旨意行在地上，如同行在天上」，我說這是與神同行的禱告，因為阿伯拉罕與神同行～創十八16～，神將滅所多瑪俄摩拉二城的旨意告訴亞伯拉罕，雖然亞伯拉罕為羅得多次祈求，但亞伯拉罕也同意如果城相沒有足夠的義人的話，他也願禾減城的旨意成就在地上。"},{"label":"第六章 · 全面性的禱告","text":"以諾與神同行，神告訴他將會用洪水滅當時的世代～以諾的兒子瑪土撒拉即「死時洪水來臨」之意～，並告訴他未世時神帶着千萬的聖者從天降臨要施行審判。以諾也願神的旨意行在地上闲I！行◎此外還有挪亞與神同行也是這樣，他傳義道，警告當時世代的人要悔改，因此造方舟，也是表示他願神的旨意行在地上。"},{"label":"第六章 · 全面性的禱告","text":"至於如同行在天上的意思，是表示願望神的旨意成就在地上之後，天國就可以降臨在地上，那時神就統管全宇仙，祝的旨意就可以在地若天了。\n\n這一句把我們牽到千禧年國，牽到更遠的新天新地，我們若能禱告進入靈界，想到這句話的意境，我們就有說不出來的感受。因為誰能以現今的理性去完全理解新天新地的一切？但我們可以用圳來褲告，用靈去體會。這句話所帶來的一切豐盛，當我們能這樣思想禱告，我們就是與神同行了。與神同行的必須同心～摩三3～，旣能同心，就能了解神的旨意貝然也願神的旨音门行一上如同行在天上。"},{"label":"第六章 · 全面性的禱告","text":"能這樣願神的旨意行在地上如同行在天上，也就是表示自己也願意順服神的旨意。可是，許多背主稿閻的人，在背這話的時候，思想行為還在抗拒神的旨意呢？他們像是對主說:「主啊，我願你的旨意行在地上如同行在天上，只不過我不在地，也不在天，我在半天吊。所以我不能順服你的旨意，不能與你同行。」多可憐的禱告◎5感恩的禱告—「我們日用的飲食，今日賜給我們。"},{"label":"第六章 · 全面性的禱告","text":"」我在前文已經說過，這個濤告只為「今日」，所以，我深信主耶穌的意思是特要藉着這句禱告文來提醒那些已經在今天有飲食的人要感恩。這一點我不再詳細說了，但我要指出，許多背主薦交的人在背的時候並沒有感恩，這種忘恩的態度，怎能得客人喜悅？"},{"label":"第六章 · 全面性的禱告","text":"6認罪的禱告—「免我們的債，如同我們免了人的債一，這一句我們在前文也詳細討論過了，「債」這分明是指我們所犯的罪，我們求神免債，即求神赦罪。\n\n只是主耶穌提醒我們，赦罪的條件是我們也要赦人的罪。這是認罪的禱告，這一個稿告人人做過，但並不是人人都照這原則去認罪。-追求聖潔的禱告—一不叫我們遇見試探，救我們脫離兇惡。」這一句我們在前文也討論過了，但我再加以指出，在我們的禱告生活裏，應該時常小心抵擋那惡者。不與牠交往，這樣我們就能過得勝的生活，所以這樣的禱告應是追求聖潔的禱告。"},{"label":"第六章 · 全面性的禱告","text":"好，我們看過主社交原來裏面包括了七種不同的禱告，七種禱告項目(這樣，填問誰可以在短短的半分鐘的時間裏背了這主往女，而能完全的用心靈誠實表達出來呢？我深信世上没有一個人能這樣，每一次當別人背主芒交而我在旁邊用心靈去附和的時候，我總有一個感覺，巴不得他們背慢一點，好讓我的思想可以稍微跟得上。"},{"label":"第六章 · 全面性的禱告","text":"但是每次都令我失望，尤其是他們背的時候那種語氣神情，似乎趕着要結束，不局希的樣子，叫人真的難以同心。\n\n不過，我這一章所論的最主要不是指出背主禱文而沒有心的弊病，我最希望指出的是，在我們的靈修生活裏，應該以主芒女所帶給我們的結構內容原則為依歸，因為那是最會禱告的主，最能明白神心意的主所教導我們的。"}]},{"short":"讀經方法與解經原則","terms":["讀經","解經"],"cards":[{"label":"先抓住一個重點","title":"靈修讀經之外，還要多讀","lines":["靈交式讀經較慢，一天一章要三年半才讀完全本聖經。","所以作者建議在其他時間用別的方法讀。","例如：精讀、多讀、研讀、撮讀、背讀。"],"takeaway":"不同方法，各有用處。"},{"label":"把意思拆開","title":"讀經的步驟","lines":["先禱告，用敬虔的心開始。","先抓住經文的總意，再分析結構和各點真理。","最後一步最重要：把真理應用在生活上。"],"takeaway":"讀出來、讀進去、活出來。"},{"label":"把意思拆開","title":"解經的原則","lines":["聖經不是難明白的書，問題在於方法。","要留意譯本文字、時代背景，按字的第一個意思解。","也要按作者想表達的意思，以及聖靈的意思來明白。"],"takeaway":"按正意解經，不過份拆字。"}],"quiz":{"question":"作者說讀經最後、也最重要的一步是甚麼？","options":["把真理應用在生活中","背下每一節經文","找出最多不同的原文意思"],"answer":0,"hint":"作者說沒有這一步，一切都變成空中樓閣。","explanation":"他強調要默想、禱告、自我檢討，立志實行。"},"key":"ch7","id":7,"no":"第七章","title":"怎樣讀經","bookTitle":"怎樣讀經","part":2,"partName":"紮根","partTitle":"第二站　紮根","idx":3,"original":[{"label":"第七章","text":"我們在「靈修的程序」一章裏面已經稍微的談論過靈交式的讀經法，照那一個辦法讀經大約半小時以上才能讀完一章，因為花了許多時間在思想及禱告。如果我們一天只能讀一章聖經的話，那麼我們就要三年半的時間才能將全本聖經讀完一次，這個速度太漫了。一個基督徒非要將全本聖經讀完三四次以上不能對聖經有真正的了解2這樣說來，豈不要花上十二至十五年的時間才能做一個較為成熟的基督徒？"},{"label":"第七章","text":"况且，以三年半的速度看完全部聖經，事實上到再看第二次的時候，必會發現三年半之前所讀過的早已忘記得一乾二淨了。所以，我們在靈交式的讀經法以外，必須加上其他的讀經法，以補其不足之處，才能叫我們的靈性增長得健全。，门"},{"label":"第七章 · 各種讀經法","text":"各種讀經法\n\n談到必須加上其他的讀經法時，必會有人想到時間分配的問題．'靈交式的讀法已經用了半小時以上了，還加上其他的讀法，豈不要花上半天的時間去靈修？不，我們在靈修時用靈交式的讀法，但我們還可以用别的時間來進行其他的讀經法，現在讓我將各種讀經法並詳細的辦法介紹出來。"},{"label":"第七章 · 各種讀經法","text":"一精讀法:精讀法與靈交式的讀法大致上是一樣的，不過靈交式的讀法注重在讀到但感受時，用禱告去與入交談一下才再繼續下去，财像與神交談一樣；神藉聖經對我講話，我藉禱告回應神的話。但精讀法則注重讀之時細心思想，務求將聖經中的教訓亮光發掘出來，不輕易放過任何一個字，盡量構想自己處身於聖經所描述的情景裏面，感受作者所感受的一切感動，這就是精讀。"},{"label":"第七章 · 各種讀經法","text":"所以精讀可以與靈交式的讀法合併，也可以分開。我個人贊成早晨靈修時合併這兩種讀法來讀聖經。，2多讀法:為了補早晨讀經的不足，晚上靈修時還需要用「多讀法」來讀聖經，甚麼是多讀法？"},{"label":"第七章 · 各種讀經法","text":"多讀的意思是快讀，是不求基解，不重思考，只币熟記內容和篇章的讀法，是重量不重質的讀法，好像看報紙一般，盡量利用最短的時間去看最多的聖經，最理想是一晚看十章八章聖經，如果晚上不能抽空多讀，日間閒來利用讀報紙的時間去多讀聖經也可以。或者有人會感到奇怪，這樣的讀法也會有用嗎？"},{"label":"第七章 · 各種讀經法","text":"是的，單用這種方法讀經得益不多，但配合精讀一起用，即早晨精讀，晚上多讀，兩種讀法一同進行，效果就非常大了，單用精讀法會太慢，會失去全部聖經的一貫性，會不易產生亮光，會難以入門。"},{"label":"第七章 · 各種讀經法","text":"但有了多讀法配合之後，在精讀時就會想起多讀時所看過的經文。那節經文雖然在多讀時不明白，也沒有時間去思考，但現在想起來接駁在精讀時所思想的這一節經文上，立刻就產生亮光了。"},{"label":"第七章 · 各種讀經法","text":"例如在精讀約眾芒音第一$扒章時，看到「太初有道，道與神同在，道營\"這道太初與神同在岳處旦油西物是藉閉宙造的見被造的沒有一樣不是藉項補造的::我們會立刻想到創世記第一章所記載神的創造工作，照約翰福這裏所說的，「道「～即耶穌基督)一定在創世記第一章那裏出現過，但怎麼我們在讀創世記之時沒有看見有「道」出現？"},{"label":"第七章 · 各種讀經法","text":"然後我們忽然想通了，「道」這個字即從神口中說出來的話，怪不得創世記說:「神說『要有光』，就有了光」，「神說」這句話，一定就是表示從神那裏有子追一出來創造萬物了。"},{"label":"第七章 · 各種讀經法","text":"這樣，我們在精讀時常想到別的有關的經文才能產生亮光，如果我們單精讀而沒有多讀的話，我們就難以想到這節經文與另一卷書的那一節經文有關了，主耶穌受試探的時候，魔鬼利用聖經來試探祂說:「經上記着說：一，但主耶穌立刻回答:「經上記者說::.」，這個「又」字表明主耶穌十分熟悉聖經，祂想到這一節經文一定要與那一節經文配合起來解才能有正確的用處，可見主耶穌-定多讀聖經。"},{"label":"第七章 · 各種讀經法","text":"3研讀法:有一些經文特別需要研讀才能明白得透澈的，例如一些與當時的歷史背景，風俗習慣，原文含意等等有關的經文，如果我們不先得到這些資料；我們會容易解錯聖經的。"},{"label":"第七章 · 各種讀經法","text":"所以，我們在以上的讀經法之外，還需要加上這一個讀經法才能完善，這個讀經法與精讀法不同，精讀法只注重思想經文本身的意義、亮光、教訓。但研讀法卻轉到經文的背後，去看作者，歷史，風俗，原文等等問題。"},{"label":"第七章 · 各種讀經法","text":"我以為研讀法不需要天天進行，只需要在開始精讀每一卷書之前抽兩三小時去研讀就夠了，但我不贊成利用靈修的時間去研讀，靈修的時間是與神親近的時間，把研【法插進去會影響我們與神的靈交。"},{"label":"第七章 · 各種讀經法","text":"我們大可以每星期一次抽下午或别的時間去進行研讀，如果我們在精讀時發現有難明的地方是與背景等事物有關的，我們大可以先記下來，等到每星期-次研讀的時間才拿出來在研讀時，因為要查究歷史背景等資料，我們是不能缺少一些研經工具書的。"},{"label":"第七章 · 各種讀經法","text":"首先我們要有一本串珠聖經，它可以幫助我們找到别的有關的經文，串珠聖經在中文只有一種，但在英文卻有許多種，例如司可福聖經Scofiel［deference：F3ik）le，…遜聖經(上寢oBooeo0n～等。此外，我們還需要一本「經六縛彷」，宅可以幫助我們搜集全部聖經有關某一事物的經文供我們參考。類似的還有「聖經題鏡」，「經訓彙_編」等。"},{"label":"第七章 · 各種讀經法","text":"更加全面性的資料可以參考「聖經苦科全書」，「聖經備典二，一聖經手册一，英文這方面的書有許多許多，諸如「之@<世生品5全Op全0onaryThZdeTVan'ic；toria1C：VClo1）e（liaBethyf8一等書也是最基本的。"},{"label":"第七章 · 各種讀經法","text":"有關每卷書的作者背景等資料可以參考「新舊約導論」，「希伯來史精義」，「新約精義」，「兩約之間」等書，不過在參考這一類書之時，要小心有不信派的思想滲入，尤其是新舊約導論之類的書。此外，有價值的工具書還有許多許多，參考書的多寡要視乎我們研究的深度，需要，範圍等。但一般來說，上述的這些書是任何研究聖經的人都應該有的。"},{"label":"第七章 · 各種讀經法","text":"4撮讀法:許多有讀經心得的人都發現，要明白保羅書信，必須每次一口氣把一卷書讀完，這是真的，其中的關鍵是在於得到全書的中心思想和思路結構。所以我以為不可少的還有「撮讀法」，甚麼是撮讀法？撮讀法就是將全卷書撮要出它的大意來，從而找出它的中心思想，尋出它的思路，定出它的大綱結構，這一點是任何做研經工夫的人都必須做的。"},{"label":"第七章 · 各種讀經法","text":"首先，我們要一口氣將全卷書讀完一次，找出它的中心思想。第二次小心慢讀，也是二口氣讀完它，但目的不是要思想其中的亮光教訓，血是按中心思想的定向，慢慢找出每段的分段劃分線，段與段之間的關係轉變～亦即是所謂思路～。"},{"label":"第七章 · 各種讀經法","text":"然後在第三次讀的時候，就要把全書的分段大綱寫出來，如果自己不寫，也要跟一些著名的解經家所研究出來的大綱去讀，去跟踪他的思路最少兩次，務求將全書的骨幹熟記在心中，最好背出來，這一點對我們精讀有十分大的幫助，可以使我們不致斷章取義，並使我們的思想有條理，有系統，有準確方向，這樣所得的亮光就多而準確了。"},{"label":"第七章 · 各種讀經法","text":"我以為這種讀法可以放在研讀的時間內，如果時間不夠，也可以再抽出一天下午出來撮讀，但緊記要在精讀每一卷書之前做好撮讀的工夫。\n\n5背讀法:最後我們還需要有背讀法，這種讀法是放在精讀一卷書之後，我們在精讀時，必定得到許多亮光，其中有一些非常有幫助的經文可以抽出來背誦，最好是全章書背，我認識有一些熱心的基督徒將新約聖經一卷一卷的背，背誦使我們達到熟能生巧的階段，也使我們能將經文放進我們的「潛意識」裏面，日後遇到甚麼事情的時候，有關的經文就會自動浮現出來，幫助很大，對講道研經的幫助也很大。\n\n或問我們精讀之時要留意那一類經文拿出來背誦呢？"},{"label":"第七章 · 各種讀經法","text":"我們要特别留瑟禾的應許，屬靈事物的定義，強列的勸角安慰等類的經文，即是其中含有一個隱藏的等號的經文：許多經文告訴我們其塵事情就等於甚麼事情，怎樣做就會產生甚麼結果，有了甚麼跟着就會有甚麼等等，這一類經文一定是重要的，是定義式的，是含有不變真理的，是一些特别的啟示，是一些歷史事蹟的結論，所以拿出這些經文來背誦是最有益的，我建議將一些舊聖經拆開，"},{"label":"第七章 · 各種讀經法","text":"把所要背誦的那一卷書放在自己衣袋裏，閒時拿來讀讀，直到能背出來為目，加果我們生來是記憶力差的人，也可以拿來思想，每字每節的思想，思想得多了，就差不多可以背出來了。「惟喜愛耶和華的律法，晝夜思想，這人便為有福」(詩，六么～。"},{"label":"第七章 · 讀經的程序","text":"讀經的程序\n\n上先禱告，用敬虔的心開始:我們在「靈修的程序」那一章裏面已經說過，在靈修濤告完了，不要立刻說「奉主耶穌基督的名求，阿們」，乃要將這句話放在讀經之後才說，意思是將讀經包括在禱告之中，一邊讀一邊禱告，這是靈交式的讀法。"},{"label":"第七章 · 讀經的程序","text":"即使我們不是用靈交式的讀法，先禱告，預備好一個敬虔的心來讀，還是十分需要的，因為我們讀的不是一本普通的學術性的書，我們要讀的是神的話，如果用中國古時皇帝的諭旨來比喻：我們會比較明白，當欽差大臣帶誰旨宣報「聖旨到」時，任何女武百官都要下跪留心傾聽，無不以所宣讀的為皇帝親口說出來的命令。同樣，我們讀神的話豈不更要以敬虔的心來讀，好像親耳聽見神說話的聲音一般？"},{"label":"第七章 · 讀經的程序","text":"的時候，心中亦要單存學術研究的問題，諸如:「這個故事的背景是甚麼？」「這一點究竟與事實是否脗合？」「這個教訓怎樣可以編成講章？一等等，這些問題是好的，但不是最重要的。最重要又不可少的問題應該是:「神在這一段經文中向我說些甚麼？」「和伯可以藉這段經文認識主那一方面的美麗、品德、屬性？」全部思想集中在我與主的關係上，這樣的能虧誠能使自己的靈性得到真正的褲傘。"},{"label":"第七章 · 讀經的程序","text":"例如提摩太後書三章一至八節這一段論及末世危險的日子的經文，要面列出了十九件术世時常出現的罪！逗段經文我已經讀過幾十遍了，每一次讀的時候，我總是存着一個研究態度—「是的，這世代就是未世了，因為這裏許多的罪都在我們現在的社會裏出現。"},{"label":"第七章 · 讀經的程序","text":"」我會數數有多少種類的罪，我會想到報章的罪案新聞，我會研究每樣罪的性質影響等，但直到有一天我再讀這一段經文時，我問主要藉這段經文间我說甚麼？我可以認識主甚麼？"},{"label":"第七章 · 讀經的程序","text":"立刻我就發現，這十九件罪或重或輕我竟犯了一大半，甚至幾乎接近全部～請讀者試試用這態度來看看這一段經六)，秩立刻明白末世的危險就是我們基督徒沾染了這許多的罪也不自知，我立刻看到主再來的威嚴，和我在主面前的情層，豬一次我讀這一段經文，才是真正的得着這一段經文，才是接通到我的靈性的讀經，所以，用禱告向虛的心來開始讀經是最重要的。"},{"label":"第七章 · 讀經的程序","text":"亠2注意總意：禱告之後，讀第一遍還是需要注意基本的步驟，沒有基本的步驟，以後解釋就會困難，甚至出現錯誤。第一個基本的步驟是全神注意經文的總意是甚麼，務求明白其中的中心思想。如果這一個步驟做得好，讀完全卷書之後一定會清楚明白這全卷書在說些甚麼，每一章的總意是甚麼。"},{"label":"第七章 · 讀經的程序","text":"我發現有許多讀完全部聖經十次八次的人，還是說不出以弗所書和歌羅西書有甚麼分别，這兩卷書的重點或總意是甚麼，其他如四福音的重點分別，絢輸一二三書的重點分别，哥林多前後書的重點分别，提摩太前後書和提多書的重點分别等，都是分不清的，研究聖經不先做好這一點，深入的工夫一定做不好，讀者如果想要在這一方面得到一些參考書的幫助，我以為最好最值得介紹的是「聖經研究」那一套研經課程的書了。\n\n3注意分段:明白了全書或全章的總意之後，進一步要找出其中的結構分段。"},{"label":"第七章 · 讀經的程序","text":"這一個步驟與上一個步驟的意義差不多，只不過是比較仔細深入分析每一節經文在結構上的關係，從而加以系統化，從總意分出大分段，再從大分段分出小分段然後分出小圖等，這即是尋索出其中的思路，做好這一步工夫可以使自己在解經時不會出現斷章取義的毛4注意真理歸納:上一步注意分段是注意經文的系統結構，是順序的，是跟着思路來分析的，但現在進一步要注意的是真理歸納，"},{"label":"第七章 · 讀經的程序","text":"意思是留心第一章第二段可能和第三章第一段在某一方面的真理上會出現關連的現象，這種關連現象未必是根據系統結構的，未必是前後文的關連，可能是跳過一兩章的關連，有時是許多點出自許多不同地方的關連。"},{"label":"第七章 · 讀經的程序","text":"我們把一卷書有關某一方面真理的許多點歸納起來，串連起來，就是這一步所要做的工夫，例如，讀腓立比書讀到溶會貫通的人，一現腓立比書裏面散佈着許多有關一喜樂一的經文，保羅在寫腓立比書時真的存有這些關於喜樂的真理，只是他沒有將這個真理有系統地，放在一段裏表達出來，聖靈認為把這個員理散佈在全書之中能帶出更奇妙的效果，所以保羅就寫成我們現今聖經裏的腓立比書。"},{"label":"第七章 · 讀經的程序","text":"像這樣分散的，似乎是隱藏的真理，在每一卷書裏都有許多許多，有的點數多關係大，容易被人發掘出來，有的點數少，關係小，就不容易被人發現出來，我們旣然熟讀了全書的結構分析，應該對這一步不會感到太困難的。"},{"label":"第七章 · 讀經的程序","text":"_5注意-個真理的本意:我們無論研究經文直接表達出來的真理(即可以分段分析的，作者接著結構寫出來的真理「—參見上述第3點～，或研究分散在各段中歸納出來的真理(即其關連系統隱藏在經文裏，作者没有按結構寫出來的真理—參上述第4點)我們的注意力不是只集中在其中的結構關連就算了，我們還要進一步注意每一黑山理的本身，"},{"label":"第七章 · 讀經的程序","text":"以上文所提及的腓立比書中的喜樂真理為例:我們發現一4，18，25，26；917，18，28，29；三1，14，18；四1’4，5，10，可以歸納起來，成為保羅論喜樂的完整真理，有了這個發現十分寶貴，但不要停留在這裏，應該還要再進一步緊握着以上所列出來的每一點，仔細加以思想，不放過每一個字，每一個背景，務求找出保羅心底裏有關喜樂的詳細資料和感受，擧一個簡單的例:四章四節說:「你們要靠主常常喜樂，我再說，你們要喜樂。"},{"label":"第七章 · 讀經的程序","text":"」保羅的語氣似乎非常着緊，而且十分强調「要」字，好像喜樂與不喜樂是在乎我們要與不要，可是，我們世人慣常按情緒的變化而斷定自己喜樂不喜樂，當我們情尿僑落，心中煩燥之時，我們怎能「要」自己喜樂就能立刻喜樂呢？我們都想喜樂，但要不來，因為我們煩悶低落的情緒無法立刻轉過來。"},{"label":"第七章 · 讀經的程序","text":"是的，情緒是不能立刻轉過來，是不能受即時的控制，但喜樂的根據是可以立刻轉過來的，我們不喜樂往往是因為看重了自己和世物的損失等等，但當我們把這個看法轉過來看主，我們就能「靠主」喜樂了，正如保羅被人評論攻擊，又坐監受苦，但他說:和0靠主大大的喜樂」分明保羅的喜樂是不憑環境，不憑情緒，乃憑主自己，他那樣苦還可以靠主大大喜樂，我們豈不也可以靠主喜樂嗎？不要着眼於情緒損失，要着眼看主，這樣，「要」喜樂就可以要得來了。"},{"label":"第七章 · 讀經的程序","text":"這種讀經法是「讀進」聖經的真理去，好像自己進到作者的心境中，上一個步驟的讀經法是「讀出」聖經的真理來，就是把聖經中的真理結構分析出來，我們不要停在「讀出一的境界，我們務要進入「讀進」的境界，這樣，我們的讀經就能「深、0注意真理的教訓應用:我們明白了聖經的真理之後，最後一步是最重要的，沒有這一步，一切都變成空中樓閣，這就是將真理應用出來，將其中的教訓發揮出來，"},{"label":"第七章 · 讀經的程序","text":"讀聖經的時候，讀到真理亮光，要立刻默想，禱告，自我檢討，提醒自己立志實行，甚至試試找出一些故事或生活實例去配合或去發揮解釋所得到的真理，例如我明白了可以「靠主立刻喜樂」，我就立刻默禱，想想自己現在是否喜樂，不喜樂是為甚麼原因，喜樂又是為甚麼原因，我能否學會「靠主」立刻喜樂，靠是怎樣靠::是的，我要學保羅不看環境，視線單堂才「標竿一，脚不斷的「直跑」，心中不斷的想那公義的冠冕」，就是「主」要給我的，我深信，如果我能這樣行，我一定可以像保羅一樣「常常喜樂」，而且「大大的喜樂」。"},{"label":"第七章 · 讀經的程序","text":"當然，這一個步驟也就是我在論及第一步驟之時所說的，心中常存一個問題：一神要藉這段經文向我說甚麼？我可以藉這段經文認識主甚麼？」但那第一個步驟是校準讀經的目標，而這最後的一個步驟卻是達成那個目標，將所得到的真理亮"},{"label":"第七章 · 解經的原則","text":"解經的原則\n\n讀者至此可能感到上述方法談何容易，聖經是一本最深奧的書，一本最偉大的著作，所以要明白聖經，讀通聖經，並不是簡單的一回事。\n\n可是，如果聖經果真是這樣難明白的，請問讀者，為甚麼保羅說提摩太從小就明白聖經呢～提後三15～？為甚麼連提摩太的外祖母羅以這麼大年紀的老婆婆也可以明白～提徬5，而且還教導提摩太的母親友尼無明白，最後又教導提摩太明白？這樣看來，聖經豈不是男女老幼都能明白？可見，聖經絕不是像一般人所以為非常難明的一本書。"},{"label":"第七章 · 解經的原則","text":"按聖經被稱為神的啟示這句話而言，「所示」在英'€Xe，意恿是揭開讓人看個明白。聖靈知道神的事極其奧秘難明，所以祂特别將神的奧秘藉聖經啟明出來，目的是讓人明白，例如保羅寫哥林多前後書給哥林多教會的弟兄姊妹，你想當他們看到這兩封信的時侯，他們明白不明白呢？"},{"label":"第七章 · 解經的原則","text":"當然明白，而且是一看就明白，因為是寫信他們的，保羅寫的時候已經就他們能明白的程度而寫，試問有誰寫一封信給别人，而不叫人明白他們寫的呢？同樣帖撒羅尼凶癥會的弟兄姊妹接到保羅寫給他們的信，他們也一看就明白，加拉太，以弗所，歌羅西以及所有聖經的受書人都是這樣。"},{"label":"第七章 · 解經的原則","text":"聖靈特別感動聖經作者把神的奧秘寫成書信，歷史，詩歌，傳記，預言等，目的是人容易明白，只要讀聖經的人心中有神的靈，自然就不難明白屬神的事～林前二10—12～。反之，神學家將聖經裏面的真理抽出來，用人的智慧重新編寫，變成「系統神學」，那就使人難以明白了，我們看見許多小孩子也明白聖經，但我們卻看見許多傳道人也不明白系統神學。"},{"label":"第七章 · 解經的原則","text":"所以，我們應當知道，聖經裏面的真理的確是奧秘的，但經過聖靈的啟示，甩詩歌，故事，書信，歷史，傳記，預言等體裁寫出來之後，就變成容易明白了。至於一般基督徒之所以感到不明白，大致上有以下的原因:1不靠聖靈:如上文所指出，只要我們心中有神的靈，我們不難明白神的事。可是許多人根本沒有神的靈，或者有一些雖然有神的靈但卻不肯靠神的靈。"},{"label":"第七章 · 解經的原則","text":"他們每次讀經的時候都以一種學術研究的態度來讀，以聖經為一本古書，一本學術書，一本需要重新批判的書。讀時不但沒有信心，反而站在懷疑或者對立的立場來批判，這樣的人焉想從神那裏得甚。如果我們真的靠聖靈來讀，我們一定以禱告歡度的態度來開始，讀時像聽見神親自講話的聲音一般。"},{"label":"第七章 · 解經的原則","text":"每一句都用信心接受，這樣我們必定感到容易明白的。灬2心理作用:一般人拿起聖經來讀的時候，第一個觀念就認仿襄是一本最深奧的書，最偉大的書，所以也一定是最難明白的書，最難解釋的書。於是因為有了這樣的心理，讀的時候遇到了一點點難處也就容易原諒自己不去研究、思想，或懶於找尋答案，因為以為答案一定難以找到，甚至是找不到的。"},{"label":"第七章 · 解經的原則","text":"這種心理攔阻人很大，其實這種心理是出於人的惰性和不肯付代價追求的心，我們在上文已經說過，神已經將祂奧秘的事啓明出來了，既然啓明出來，就一定是可以明白的，而且一定是不難明白的，問題是我們有沒有正確的途徑去解釋和研究。所以，我們讀經之時先求神給我們能明白，我們就應相信我們可以明白，不要被這種心理困擾。，譯本文字:如果說聖經實在有難明的因素，那其中的一個因素就是譯本文字未能暢順表達原文的含意和句法。"},{"label":"第七章 · 解經的原則","text":"聖經在原文～即希伯來文和希臘文～讀起來十分暢順，字句的含意也表達千分清楚完美，因為聖靈感動作者寫書的時候”已經把最完美的意義，用最好的句法表達出來，例如詩篇在原文多是押副的，而且帶有美麗的詩歌體裁。可是譯成中英文之後，押融和詩歌體裁的美就完全失去了。在含意方面，原文在文法，性別，時式，語氣，關係等方面都表達得清楚，可是譯成中英文之後，這些特黑也就灘少了。"},{"label":"第七章 · 解經的原則","text":"所以，現今我們讀中婦聖經時有不晶順或不明白的現象出現。本來要解決這一個困難，我們非要熟讀原文不可，但感謝寅，禮感動許多原文學者替我們做了許多工夫，使我們得到許多更能明白原文含意的參考書和譯本，只要我們參考和比較這些譯本，原文準確的意思就不難得到。"},{"label":"第七章 · 解經的原則","text":"值得參考的中文聖經譯本有「聖經新譯本」，「聖經意譯本+當代福百」，「呂振中譯本」，「新舊庫譯本」等。英文聖經的譯本比較多，值得參考的有多已世邱0co所o乙o所we全op全〉選才王后Bogo二.刀2oocgd計Co經6號二0之o二上ooOO一己和和三oo朮歷等等。有4時代背景:還有一個一般人感到實在的而本來沒有的困難，吉是時代背景的困難。"},{"label":"第七章 · 解經的原則","text":"我說這是本來沒有的困難，因為在當時第一受書人的立場來說，他們是完全了解那書的'時代背景的，所以他們讀起來的時候，就不會感到有這一類的困難。可是對於我們現今的人來說，當時的風俗習慣，文化背景，度量衡制，歷史政治，寫書原因，作者性格等「等我們都不能直接從聖經裏面看出來，於是在解釋方面就容易出錯了。"},{"label":"第七章 · 解經的原則","text":"擧一個例說，我：聽過有好幾位傳道人講解林前四章九節「因為我們成了一台戲，給世人和天使觀看」這一句經文，他們都是站在現今電影明星的立場來解，說做戲子的收入雖不錯，但我們所演•\"的喜劇或悲劇，都是假的，都是暫時的，真的生活要到天上的家鄉水有，正加演戲的真正的生活要到後台才表現出來。"},{"label":"第七章 · 解經的原則","text":"這種解法說來動聽，但殊不知完全錯誤，因為一成了一台戲」在當時的社會來說是成了「鬥獸場中的殉難者」。羅馬人殘酷成性，常把俘虜和犯人放進門蟬場中互相搏鬥或與野獸搏鬥，以供自己作為娛樂。故此，保羅指的是使徒被世人輕看，視為低賤的人。所以，我們要準確解釋聖經，一定要照當時的時代背景來解，這一類的參考書也不少，讀者不難找到。"},{"label":"第七章 · 解經的原則","text":"一②懶於研經:最實在的解經困難還有一點，就是聖經的句語太簡短，不像現今的小說記述一個故事那麼詳盡生動。是的，聖經因為是在古時寫成的，古時的紙張和書寫工具都十分昂貴和不便，所以所有古書都是以簡述法來書寫，正如我們中國的古文也是以簡述法來書寫一樣，一句古文往往包含了許多意思在內。聖經的語句也是這樣。而且，倘若聖經的寫法是像現今的小說那麼詳細的話，聖經就會厚得不實際，不能人手一冊等。"},{"label":"第七章 · 解經的原則","text":"不過奇妙的是，雖然聖經的寫法是那麼簡化，但所有重要和有價值的資料都全部包含在聖經的文字裏面，只要我們留心找這些資料，我們自然可以詳細明白聖經，好像我們詳細明白一部小說一樣。換言，我們可以利用聖經的一切資料將之再寫成詳細如小說，生動如小說的書。能這樣將其中一切隱藏的資料找出來就是已經將聖經解釋得明白了。"},{"label":"第七章 · 解經的原則","text":"可是，一般人讀聖經的時候，總是愛用快讀的方法，不求思考，不求甚解，甚至用得過且過的態度，勉强讀完一章聖經，只為應付做基督徒要靈修的責任就算了，這樣怎能明白聖經呢？結果在這種基督徒來說，聖經之所以難解並不因為聖經本身深奧難明，而是因為他們的惰性使他們難明吧了。"},{"label":"第七章 · 解經的原則","text":"或問，聖經如果容易解得明白，那麼解經的原則是甚麼？怎樣才算是按「正意一解經呢？這個問題的一部份答案已經包括在上述五點之中了。現在我再將這幾點連同其他幾點列出來，好讓讀者有一個完整的參考。"},{"label":"第七章 · 解經的原則","text":"正意的解經就是1）按聖經本身的意義解:不要存一個先入為主的觀念去解，意思是說，不要自己先有一個思想，然後去找聖經的經文來支持自己的思想，好像戴了一副有色眼鏡，看每一樣東西都是有色的。"},{"label":"第七章 · 解經的原則","text":"換言之，聖經本身的意思並沒有注意，反而强將聖經的意思曲解來遷就自己的意思，這就是錯解聖經。真正按正意來解經者，必須放下自己先入為主的思恕，讓聖經向我自己說出它自己要說的話。為了不要影响它說話，我們每一次讀聖經之時，甚至連上一次讀這一段經文時所得的亮光解釋都要放下，因為上一次得到的讀經心得未必絕對準確。"},{"label":"第七章 · 解經的原則","text":"如果我們每次讀經都是照上一次的心得方向繼續解下去，我們會可能一生都押爭不了第一次的錯誤，而第一次的錯誤都是在自己初信靈性知識最膚淺的狀態中作出來的，將自己一生的思想建基在初信，靈性知識最膚淺的狀態中，這豈不是最危險和最是毒的嗎？"},{"label":"第七章 · 解經的原則","text":"所以，我們每一次讀經，都應當以「第一次讀」的心境來讀，即以完全沒有成見，沒有任何先入為主的觀念來讀，讓聖經說它本身要說的話，這就是按正意解經了。"},{"label":"第七章 · 解經的原則","text":"人2）按當時受書人的立場背景來解:這一點我們在上文已經解釋過了。任何不按當時的立場背兽解的意思都是錯誤的，例如新約羅馬書至提多書是特為外邦基督徒而寫的，所以解釋的時候要按外邦人的立場來解；希伯來書至啓示錄是特坊狠太基督徒而寫的。所以解釋的時候應該以猶太人的立場而解。"},{"label":"第七章 · 解經的原則","text":"當然兩者之中間中有例外的，因為在外邦人的教會中也間中有猶太人，在猶太人的基督徒之中也間中會牽涉到外邦人。\n\n但兩者絕大部份的重圖歷是明顯分開的。如果忽略了這一個分别，就不是按正意解釋了。（3）按上下文全書一貫的意思解:正如我在前文一讀經的程序」那一段裏面所說的，讀經的時候一定要找出全書的總意及結構分段的所在，因為這樣才能在解經之時將經文裏面的道理整個抽出，不至斷章取義。"},{"label":"第七章 · 解經的原則","text":"但有時一個道理所牽涉的範圍不單是一小段，可能會牽涉整卷書，甚至整部聖經，所以所謂按聖經一貫的意思來解，就是按全本聖經的意思來解。\n\n例如采鬼試探耶穌時引用詩篇九十一篇十一至十二節，勸耶穌從殿頂跳下來說:「主要為你只附奧的使者用手托着你，免得你的脚碰在石頭上。」可是主耶穌知道這一節聖經不能單獨解，必須連在申命記六章十六節一起解，才不會斷章取義。於是他立刻引那一節聖經回答說:「經上又記着說:不可試探主你的故。」這個双字十分重要，它表明了聖經的一貫性，和解釋的原則，所以按正意解就是按全本聖經的一貫竟思解。"},{"label":"第七章 · 解經的原則","text":"0接女字本身所表達出來的第一個意思解:解經的人常醞調每字每劃都是神的啓示，都不能改變，因此解經要按經妳婦字本身的意義來解，不能單按精義或靈意解，這個意見是對的，新神學派的解經法就是不按字義只按精義解，他們認為聖經裏面所記載的神蹟是不可信的，但其精義卻是好的。"},{"label":"第七章 · 解經的原則","text":"可是另一方面，福音派或基要派的解經家卻有一些太過注重字義的解經，他們研究聖經原文的解釋，說那一個字在原文有幾個意思，於是在解經的時候就按該字的各個不同的意思來解，解出許多道理來，甚至有些意思只是字眼有，不是該字應用時所有的，這樣過份將一個原文的字來分析，結果生出許多不是出於聖經作者原意的意思來。"},{"label":"第七章 · 解經的原則","text":"因為作者在寫書的時候，首沒有應用那一個字的各個不同的意義，也不一定註凍每一個字的字眼所含的意義，他也不會祈望讀者去研究那些字的各個含意和字眼才能明白佈所寫的。"},{"label":"第七章 · 解經的原則","text":"任何作者在應用一些文字來寫作的時候系他发應用那些文字所表達出來的「第一個意思」，這樣，當然讀者在解釋他的文章時，也應該按照文章所應用的文字所表達的第一個意思來解，太過强調原文的解釋有時反而不是按正意解，我個人認為，我們的中文聖經已經將原文所表達出來的第一個意思百分之九十以上翻譯出來了。"},{"label":"第七章 · 解經的原則","text":"讀中文聖經的人不應該常存一個懷疑的心，以為中文聖經不準確、若是這樣，我們中國人豈能信主得救？又例如鑑別那靈時，我們照絢輸壹書四草一至二節的話質問邪靈，豈不是無贅？貼不要按原文的字句來質問才有效？不，神也悅納我們的中文聖經，只不過當中文聖經未能將原文妳字所表達出來的第一個意思完全翻譯出來時，我們才需要按原文解經，不然，按中文解經已經夠了。"},{"label":"第七章 · 解經的原則","text":"（5）按作者想要表達的意思解:許多時候，先了解作者的生平，靈性，性格，背景等，能了解作者的用心，文字所表達的只是道理，但作者的心境，感受，往往是隱藏在文字背後的。如果我們不將作者的心境感受配合在文字的道理上，我們所骨折的便會肯淺，不生動。反之，配合了就生出許多亮光來。"},{"label":"第七章 · 解經的原則","text":"這一點在當時的受書人來說是毫無問題的，因為他們十分了解作者的一切，但在我們來說，因為隔了二千多年以上的時間，我們就感到與作者的感受有了脫節或隔膜，為此我們必須先研究作者的生平背景，寫書原因等，才能按作者的意思來解，才能按正意解。"},{"label":"第七章 · 解經的原則","text":"0接亞靈的意思解:聖靈是聖經的真正作者，許多時候聖經作者講一句話，連他自己也不完全明白，因為他不知道聖靈為何感動他這樣說話，例如大衞寫詩篇第二十二篇第一節時說:「我的神，我的神，為甚麼離棄我？」他只是就他的感受，來詰問禮仿何離棄他。"},{"label":"第七章 · 解經的原則","text":"他知眾感動他要寫這句話，但我們現今的人明白，原來他所講的，不知不覺的預言了主耶穌在十字架上所受的苦，主耶穌在十字架上說：一神啊，為甚麼離棄我」就是應用大衞這句話。"},{"label":"第七章 · 解經的原則","text":"所以，如果單按作者個人的意思來解，這句話是表示他個人的痛苦，但如果按聖靈的意思來解，這句話就多了一個意思，就寔預言主耶炙擔當我們的罪，在十字架上磁神離棄之時所受的痛苦，所以按聖靈的意思來解經，就是深一層的解經，但這樣的解經非要我們用信心和數上的態度來跟隨聖靈的引導不可，正如詩人所說:「求你開我的眼睛，使我看出你律法中的奇妙一～詩一一九18～°"}]},{"short":"與神合一，控制肉體、魂、靈","terms":["肉體、魂、靈","靈交"],"cards":[{"label":"先抓住一個重點","title":"靈修的目標是活出主","lines":["作者再看主耶穌受試探，找出最理想的境界。","第一是與聖靈合一：被聖靈引導。","第二是與父神合一：生命、思想和靈都與神一致。"],"takeaway":"理想的靈修，是與神合一。"},{"label":"把意思拆開","title":"三次試探，三個層面","lines":["石頭變食物：試探肉體的需要，學習控制肉體。","從殿頂跳下：試探人的感覺和驕傲，學習控制魂。","拜魔鬼得萬國：試探敬拜的對象，學習控制靈。"],"takeaway":"肉體、魂、靈都要順服神。"},{"label":"用生活例子想一想","title":"這一章為何放在「進深」？","lines":["這章較多神學概念，例如靈、魂、體的分別。","先有靈修的習慣，再讀這章會更容易明白。","讀時可以問：我最容易在哪一個層面失守？"],"takeaway":"先有習慣，再看目標。"}],"quiz":{"question":"作者從主耶穌三次受試探，帶出哪三方面的操練？","options":["控制肉體、控制魂、控制靈","讀書、工作、休息","早起、唱詩、讀經"],"answer":0,"hint":"看這一章的三個小標題。","explanation":"作者把三次試探對應人的三個層面。"},"key":"ch2","id":8,"no":"第二章","title":"最理想的境界","bookTitle":"最理想的境界","part":3,"partName":"進深","partTitle":"第三站　進深","idx":1,"original":[{"label":"第二章","text":"我們在上文已經說過，判斷靈修生活的好壞不憑靈修時的感受現象，乃憑實際上活出主自己多少來決定，因為我們靈修的目的是要更多親近主，從而更深的認議袍，更深可是，我們當怎樣行才算活出主？到達了那一個境界才算最理想呢？要明白這一點我們不能不再看看主耶穌在曠野受魔鬼試探四十天的表現了。盼望我們先認議袍靈修到達何種境界，以致我們活出祂的樣式，我們就能進入最理想的靈修境界。"},{"label":"第二章","text":"..（一與聖靈合-當我們翻開馬太福音第四章記載主耶穌受魔鬼試探那一段經文的時候，第一句話吸引我們注意的，就是:「當時，耶穌被聖靈引到曠野。」如果我們再看路加福音第四章記載主受試探的那段經妳，我們又發現最後的一句是:「耶穌滿有聖靈的能力回到加利利。」這使我們清楚的看到，主耶穌的靈修是已經達到的境界。"},{"label":"第二章 · 與聖靈合一","text":"與聖靈合一\n\n甚麼是靈修？顧名思義靈修就是「靈」的修煉。肉體的五官感覺全部是為接觸物質的層面。魂是支配我們感情意志思想的層面，靈是支配我們與神接觸，即通往靈界的層面。可是，我們人類犯了罪，與神的生命隔絕了，我們忘記神，接觸不到神，因為我們的心眼瞎了，我們的靈昏迷了，麻木了。正如詩篇二十三篇所說:「耶和華是我的牧者：：祂使我的靈魂甦醒。"},{"label":"第二章 · 與聖靈合一","text":"」反過來說，從前沒有耶和華作我的牧者時，我的憲魂是昏迷的，失去知覺的，最低限度對罪惡的敏感性是越來越麻木的，對神的事情更加捉摸不到的。父正如絢輸壹書第五章二十節所說:「全世界都臥在那惡者手下。一臥一字表明全人類的靈都受魔鬼控制，倒下來，昏迷了。所以全人類都失去靈的功效，不能與神相通。圣不得人們不信神，因為不能通到神那裏。"},{"label":"第二章 · 與聖靈合一","text":"但感謝主，自從聖靈重生了我們，使我們的靈甦醒，有了豐盛生命的力量之後，我們第一個靈的感覺，就是對罪的敏感性大了。我們為罪痛哭，我們憎恨罪惡，努力對付罪過聖潔的生活。"},{"label":"第二章 · 與聖靈合一","text":"當我們的罪洗淨了，生活漸漸成聖了，我們的靈也就越來越對屬天的，屬靈的事有了越來越强烈的反應，我們藉信心似乎看見了，正如希伯來書十一章十三節說:「這些人都是存着信心:::從遠處望見:::一個更美的家鄉，就是在天上的。"},{"label":"第二章 · 與聖靈合一","text":"」並且在我們屬靈的追求上，我們甚至也可以泗沁的看見主自己。當然，我說看見，不是指肉眼，而是指靈眼。靈眼的看見，一是在乎信心—信神臨在的信心大到一個地步，可以說簡直就是看見祂的顯現。另-方面我們的靈眼能看見卻是在乎聖靈的能力和引導，祂開我們的心眼，祂引導我們的思想和信心，祂也叫神向我們顯現。"},{"label":"第二章 · 與聖靈合一","text":"信心在我們信主得救時就有了，不過很狂形，很幼稚，所以信心需要操練才能長大，才能更深的「看見」屬靈的事，對神的信心是出自我們的靈，所以信心的操練也就是我們靈的修練•靈的修練是全面性的，信心心的修練只是嚼於靈的修練的一部份。"},{"label":"第二章 · 與聖靈合一","text":"例如愛心，敬虔、感恩之心，對屬靈事物的滲透力(林前三但是靈修不單是我們自己的修練，我們還需要聖靈來引導，來指教，加力，啟示，一直以致充滿，這樣才能進行真正的靈修。如果單靠我們自己的修練，那是修道主義，苦修主義。"},{"label":"第二章 · 與聖靈合一","text":"而且單靠我們自己的努力修練，沒有聖靈的引導，加力，啟示等，我們仍不能通到神那裏，更談不上參透神的心意，因為屬靈人必須有神的靈才能參透神的事(林前二1112～。所以我們靈修是怎樣「修」怎樣「練」呢？我再說不是「自修」，而是一靈修，是靠聖靈來修練。或者說，是修練自己去與聖靈合一。"},{"label":"第二章 · 與聖靈合一","text":"我們在上文說過，靈修好壞的標準是看他的生活表現能否像主，能否勝過試探，能否有屬靈的能力。現在我們再看主耶穌怎樣勝過魔鬼的試探？\n\n祂的能力從何而來？注意，聖經說，祂勝試探第一個秘訣是隨從「聖靈引祂到曠野一，祂得能力也是「滿有聖靈的能力」。所以我們可以很明確的說，主耶穌的靈修生活的境界就是自己的靈與聖靈完全合一的境界。如果我們要在生活上活出主，要在試探上得勝，要得着能力，要進入最理想的靈修境界，我們就必須修練自己的靈與聖靈合一。"},{"label":"第二章 · 與聖靈合一","text":"我們太過習慣物質界的生活了，我們也太看重肉體的感受了，以致我們雖然重本了，有了新生命，也有聖靈居住在我們裏面，我們也不習慣與聖靈和諧相處。\n\n我們常常使補擔憂，常做祂不喜歡我們做的事，常不理會祂的感動甚至警告，最低限度我們把一天的時間劃分給物質的身體太多，劃分給聖靈的時間太少。我們自然習慣聽世界的聲音，不習慣聽聖靈的聲音，這是我們每一個人的光景。因此，我們需要靈修，需要訓練自己多聽聖靈的聲音，從而跟從祂的引導，從而勝過試探，從而得屬靈的能力。"},{"label":"第二章 · 與聖靈合一","text":"當我們進行靈修禱告的時候，我們通常是閉上眼睛的～張開眼睛也可以，閉上眼睛之後，我們就好像來到一個屬靈的境界，但是四處都是黑漆漆的(因仿閉上眼睛)，我們看不見那條路通往神那裏去，更談不上靈修的甜蜜和更深認識主。這時候，我們需要聖靈在這漆黑的心境中加以乛引導」。"},{"label":"第二章 · 與聖靈合一","text":"我們自己也運用「信心」去跟從，當「信心」與「引導」能完全合一之時，也就是我們能完全與聖靈合一了，於是聖靈告訴我們已經來到了神的寶座前，到了「靈界」，我們信，這信已經完全與聖靈的引導合一了，所以這信就立刻使我們忘記，或不注意到閉上眼睛那種「黑暗，反而因聖靈所「告訴」我們的，我們便好像真的見到「靈界」，見到「主坐在寶座上口。"},{"label":"第二章 · 與聖靈合一","text":"我再說，這「見到一丕是肉眼的，是屬心眼的。但這見到的卻是真實的。我們不是說，聖靈引導我們在閉上眼睛之後所見到的是心理上的，是想出來的，是虛構的。不！藉信心和聖靈的能力，我們真的來到神的面前，來到靈界。我們需要信，要有與聖靈的引導完全合一的信，我們就能真的來到這個境界了。"},{"label":"第二章 · 與聖靈合一","text":"但我知道不是每一個人都能有與聖靈的引導完全合一的信心，所以我們需要修練，例如先自潔，因為非聖潔就沒有人能見主，然後集中思想，摒除雜念與疑心，安靜等候，在等候中有時可以唱一些靈修詩歌，使自己專心。"},{"label":"第二章 · 與聖靈合一","text":"藉詩歌的幫助，叫自己的思想集中在主身上。有時等候得久了，還需要禁食，免得分心，有時要練習放下一切的掛慮憂愁。有時要訓練自己勝過疲倦～但太疲倦者可以去睡覺休息一會再來禱告，聖靈所說的沒有半點意思暗示主耶穌四十晝夜禁食，同時也四十晝夜不睡覺。"},{"label":"第二章 · 與聖靈合一","text":"但在這一切的操練上，最重要的是信心的操練，和留心聽聖靈引導的聲音的操練，等到我們操練到習慣信，習慣聽，又能習慣行之時，我們就已經進到最理想的境界了。_與父神入口一我們再看主耶穌受試探的故事，請注疙，仿何魔鬼三次試探耶穌都用一個「若」字呢？前兩次魔鬼說:「你若是神的兒子」。最後一次說:「你若俯伏拜我」。"},{"label":"第二章 · 與聖靈合一","text":"這很明顯的，魔鬼的意思是要耶穌懷疑自己不是神的兒子，要耶穌與神分開，轉去「拜一祂。拜的意思是靈的投靠，降服。總括來說，三個試探都是想要破壞主耶穌與業褲的合。因為魔鬼知道，主耶穌得能力，是從與神與聖靈合一而得來的只要拆散了冗們的合一，就可以逐個擊破了。這是多麼陰險，多麼毒辣的詭計。現在我們又看主耶穌怎樣對付祂呢？主耶穌三次都是用「經上記閉說」的話來回轂雷經上記着的話，就是父神的話。\n\n主耶穌不用自己的話來還擊，卻要用父神的話還擊，表明祂完完全全的"},{"label":"第二章 · 與父神合一","text":"與父神合一\n\n。看祂第一次的回擊指出:「人活着：：乃是靠神口裏所出的一切話。」—._是生命的合一，第二次的回擊指：一不可試探主你的神一—.1這是思想上的合一。第三次的回擊指出:「當拜主你的神一—這是靈的合一。我們還相信，丰耶穌少這些話來回擊魔鬼，是聖靈智慧和謀略的靈～賽十一2引導宙的。"},{"label":"第二章 · 與父神合一","text":"所以這也是與聖靈合一，聖父聖子聖靈三位合一的力量是大得不可想象的，像魔鬼這一種受造之物焉能敵擋得住。即使在數學上，我們也曉得三個打一個是必勝的，但三位一體的神若分開了，根本就不用攻擊，神也自己分解至肢離破碎而減世了。"},{"label":"第二章 · 與父神合一","text":"像原子粒一般，一旦將其中盟，質字，中子分開了，就產生大爆炸，毀滅了。自古至今，撒但不知想盡千方百計，藉着各種異端邪說滲入教會，在信徒的信念裏分解三位一體的神，總是叫人認為耶穌只是人不是神，或只是神不是人，或聖靈沒有位格，或三位三體，或一位一體，:::。因為撒但知道，我們基督徒如果與這位三位一體的神合一了，那麼我們任何一個人都可以勝過祂了。"},{"label":"第二章 · 與父神合一","text":"話說回來，靈修的修練，不單是與聖靈合一的修練，同時也是與神合一的修練—即在神的話語上修練自己，今天基督教太多人企圖只在與聖靈合一的方面修練自己，但卻沒有在與神合一—」與神的話合一—方面操練自己，千果他們不但不能與聖靈合一，反而與邪靈合一，因為聖靈與神的話語是分不開的，聖靈稱為真理的靈，除去了真理，那靈就不是聖靈，將神的話與聖靈分開，這豈不也是等於將三位一體分開？宮豐不也是撒但的老套詭計。"},{"label":"第二章 · 與父神合一","text":"再者，聖靈用甚麼引導我們呢？是用神的話，聖靈沒有了引導我們的工具，我們還是得不到祂的引導。在閉上眼睛那「漆黑」航境界中，邪靈跑來，伸手牽着我們走，我們還以為是聖靈自己，這是今天不少信徒所遇到的危機。我們不能缺少神的話，所以最理想的靈修是不能缺少用心靈來讀經的。我們所操練的還是信心與神的話完全合一。等到我們的信心與神的話完全合一時，那時就是我們”與神完全合一之時了。"},{"label":"第二章 · 與父神合一","text":"我們與神完全合一的境界，就是靈修最高境界。我們不是說:靈修分開兩部份第-部份是禱告，在禱告中我們要與聖靈合一；第一部份是讀經，在讀經之中我們要與神的話合一。不！這也是錯的。我要指出的是:在禱告之時，我們用信心與聖靈的引導合一，聖靈引遵的工具是神的話，所以在祝告之時也同時與神的話合一。即在禱告之時同時與聖靈和神合一普分開的。"},{"label":"第二章 · 與父神合一","text":"另一方简”在讀經之時，我們也要用信心與神的話和聖靈的引導合一。我的意思是在讀經之前要禱告，在讀經之中邊讀邊禱告，在讀經之後還要禱告，用禱告包着整個讀經的過程。好讓聖靈的引導與神的話同時在我們的信心裏產生功效。當我們用信心來讀神的話語時，我們應該感受到的不是「讀芒釉供呈的—1一讀」只能聽見自己的聲香。我們乃是「聽」見神直接向我們講話「—好像聽見神自己的聲音。"},{"label":"第二章 · 與父神合一","text":"以色列人在西乃山下聽見神講話的聲音，沒有一個不茹同，不接受的。但當神的話寫了下來，以後以色列人誦讀的時候就再沒有那種感受了。原因是他們沒有信心。如果我們能完全相信聖經是神的話，即信到一個地步感受到聖經是直接由神親自「講」出來的話，那麼我們的靈性就能容易與神合一了。可惜我們只在瑟議上信，不在靈裏信。"},{"label":"第二章 · 與父神合一","text":"我們不在靈裏信，是因為我們沒有用禱告的心去讀，好讓聖靈能引道我們信禮的話信得深，深到我們的靈裏。可嘆！今天太多基督徒以聖經為一本學術性的書去研究批判，甚至許多傳道人也是這樣，許多神學院也是這樣。"},{"label":"第二章 · 與父神合一","text":"有人說，許多祝學院，而是一神學的」院，這話是十分對的。還有一點，我們不是說只在靈修的禱告讀經之中與神和聖靈合一，靈修完了，我們也就可以離開合一的境界了。看主耶穌在四十晝夜禁食禱告之前後都有聖靈充滿，有聖靈的能力，神的話以後也不離祂的口，我們就知道主耶穌是沒有半刻不與神合一的。同樣的，當我們靈修完了，我們千萬不要在心理上告訴自己:-我現在開始過自己的生活了。"},{"label":"第二章 · 與父神合一","text":"」不！我們的生活不屬自己，乃是為主而活。我再說，靈修好壞的判斷準繩是甚麼？不是靈修「之時」的現象，乃是靈修「之後」的生活表現。你能否活出基督的樣式呢？或問，我們怎能這樣活出基督呢？首先，如果你的靈修真的是與神與聖靈合一的話，你就能了。因為這樣的靈修會使你得力去活出基督。第二是你在日間生活之時，仍要在心靈間不斷的禱告，不斷的思想和應用神的話。"},{"label":"第二章 · 與父神合一","text":"「不住禱告」的意思不是二十四小時不停的禱告，而是二十四小時將你的靈不間斷的向天、向神、向聖經開放，好讓甚麼時候你感受到聖靈的感動，神的啟示，你可以立刻隨時隨地的用心靈向禮稿告。如果我們與神與聖靈的合一是完全的話，我們感受聖靈的感動和神的啓示也越多。這樣，我們就能與神同行，與神共話，每一天，每一刻不停的被聖靈充滿，帶出基督的香氣了。名"},{"label":"第二章 · 控制肉體","text":"控制肉體\n\n我們再來思想主耶穌怎樣勝過第一次的試探。魔鬼以善意姿態對祂說:「你可以吩付石頭變成食物。\n\n意思是說:「你已經四十天没有吃東西了。何必這樣折磨自己呢？你大可以吃點東西再靈修，要小心心自己身體呀！我不是勸你吃不可吃的東西，其實你若是神的兒子，你喜歡吃甚麼就可以憂甚麼了，何等方便？-覽鬼的話聽來有理，但為甚麼主耶穌不肯吃呢？有人說工因為牠是魔鬼，見魔鬼說「是」的，我們就說「不」就對了。"},{"label":"第二章 · 控制肉體","text":"我認為這個答案不夠準確，因為許多時候魔鬼會化作光明的天使，會變成我們家中的親人，摯友，甚至主內的兄弟姊妹。\n\n那麼當魔鬼藉你的父母來勸你吃的時候：您豈知道那是出於魔鬼的呢？你豈可以對父母說:「你們是魔鬼，所以我不吃」呢？不！我們對抗魔鬼最根本的方法是先要藉著員理看穿牠的詭計來，使牠無所遁形，然後才對付牠。"},{"label":"第二章 · 控制肉體","text":"看主耶穌怎樣回答牠，主說:「人活着不是單靠食物，乃是靠神口要所出的一切話。」我們知道一食物」是供養肉體的，而神的話是供養「靈性」的。所以主耶穌的意說：二隴鬼，你勸我吃這不是你的好意。你的意思是要我看重一肉體，但人活著不是單靠肉體。"},{"label":"第二章 · 控制肉體","text":"你知道我這時候禁食新菩，我得能力是在乎我藉禁食新祠使我的靈與父哩與聖靈作完全的合一，所以你勸我吃，目的是要我在着重肉體之時忽略一靈口，但我之所以活着就是靠=。"},{"label":"第二章 · 控制肉體","text":"你的說計好毒，我不上你的當。」是的，主耶穌會對門徒說:有一類鬼非要禱告禁食，不能將牠們趕出去。何况現在主耶穌所對付的是鬼王？豈不更™黑禁食嚼告四十晝夜才能對付牠嗎？但我要再一次的指出，禁食的意思並非是一種「功農一或「苦行修練」，而是因為專心禱告到了一個地步以致忘記去吃，或不顧得去吃，不想吃。意思是說，專心禱告到了一個地步，自己的「盤」完全控制了自己一肉體一的任何要求都不能影響「靈」。"},{"label":"第二章 · 控制肉體","text":"撒但未必叫你犯大罪才能打倒你的，牠只需要在你靈修的時候，勸你不要太熱心，或太工迷一～這是今天許多基督徒都接受的勸告～，也要注意自己的衣食住行，現實生、估2學業事業等，牠就足以佔有你，驅使你去犯更大的罪了。簡言之，撒但不外勸你看重「肉體」不要太看重「靈」。因為牠知道叫人活着的，而且永活的是「靈」。"},{"label":"第二章 · 控制肉體","text":"所以我灬n們要「靈修」，在靈修的修練之中，我們要控制肉體，當我們能完全的控制肉體之時，也就是我們的靈修生活進到理想的境界之時。_胚謂完全控制肉體，不是單指禁食說的。同時也是指屬於肉體的一切活動，要求或.傾向說的。例如性慾，脾氣，暴怒，貪婪，邪情:::等。"},{"label":"第二章 · 控制肉體","text":"當魔鬼要來試探主耶穌的時候，秀要在主的身上找一個弱點來進攻，可是，主耶穌已經完全控制自己的肉體了，在他身上找不到性慾，脾氣等弱點，唯一可能的弱點就是主的「食人懲」，因仿補已經四一天沒有吃甚麼了，所以撒但才以「吃」的問題來試探祂如果你說你有很好的靈修，但靈修完了，起來過日常生活的時候，你不能勝過自己的脾氣，性慾等等，你的靈修仍是失敗的。"},{"label":"第二章 · 控制肉體","text":"不能控制肉體，叫肉體隨着自己的靈來生活’h生大這就等於肉體與靈出現矛盾或對敵的現象，這現象强化了，就是分裂。靈魂與肉體完全分開就是死，靈魂與肉體分裂也就使我們開始感受到死的痛苦滋味。啊！弟兄，你若在靈修之時勝不過惰性，勝不過貪睡的肉體要求，耐不佳時間的衝力，你怎能勝過日間悠長的一天，和五花入門的試探呢？求主幫助我們攻克己身，叫身服我們，像保羅一樣。"},{"label":"第二章 · 控制肉體","text":"保羅之所以靈修到有「三層天」的經歷，又能說自己「活着就是基督」，是因為他能完全的控制自己的身體，他控制自己的身體甚至可以叫它多受勞苦逼迫，補滿基督患難的欠缺。當撒但將一根刺加在他的肉體之上的時候，主耶穌沒有把它除去，因為主知道這根刺反而成為他更完全控制自己肉體的操練。他一生不貪錢，也沒有想到結婚的問題，結果他不論生死都能叫基督在他身上照常顯大。啊！多叫人羨慕的屬靈生活。但這一切都是他操練自己，控制肉體的結果。"},{"label":"第二章 · 控制魂","text":"控制魂\n\n魔鬼第二次的試探，是勸主耶穌從殿頂上跳下來，理由県：一因為經上說，主要為你吩咐祂的使者用手托住你，免得你的脚碰在石頭上」。問題在這裏，為何魔鬼勸主耶穌從殿頂上跳下來？而不勸祂從更高的山崖上跳下來呢？原來站在高山上與站在殿頂上的感受不同。"},{"label":"第二章 · 控制魂","text":"站在高山上沒有人看見，但站在殿頂上就人人都看見。因為當時的聖殿天天有許多人出入，而且這些人都是為敬拜神而來的，如果這些人看見耶穌站在殿頂上，就是至聖所上面的地方，也是一般人認為神榮光降臨的地方，他們一定會用敬畏和景仰的目光注視祂。何况當耶穌跳下來的時候，竟然有天使出現用手托閉奧，大家一定以祂為從天而降的真神，立刻跪拜不停了。"},{"label":"第二章 · 控制魂","text":"撒但就是用這種感受為餌去引誘耶穌。第一次用食物引誘不成功，因為主耶穌控刻了自己的肉體，但這一次用「感受」去引誘耶穌，是針對冗的魂，魂比肉體更難控制，何况撒但還以神的話來掩飾呢！可是主耶穌也不上當，因為祂也能夠完全的控制自己的魂。於是祂也引用神的話指出工不前試探主你的入」。"},{"label":"第二章 · 控制魂","text":"意思是說，一革「感受」若不是神主動賜的，我不勉强神賜給我。這種勉強禮去按我自己的意思去行事的行動就是試探神。站在殿頂上代表在宗教上的高位。萬人景仰的名譽是許多傳湆人天天想要得到能。尤其是經歷到「天使出現」，而且竟然「用手托住自己的北」，那真是了不起的「屬靈」經歷了。「天使出現」代表超自然的現象。”用手托住自己的閃」代表安全的保証，啊！今世代的基督徒千萬要注意。"},{"label":"第二章 · 控制魂","text":"今大許多所謂靈恩運動，不過是一種追求「感受」的運動。他們强調「感受」過於真理。認為有某些感受的就是被聖靈充滿，不曉得聖靈是稱為真理的聖靈。正如保羅在帖撒羅尼迦後書第二章所指出的，末世「有不法的人來，是照撒但的運動，行各樣異能神蹟，和一切虛假的奇事。並且在那些況洽的人身下，行各樣出於不养的詻計。"},{"label":"第二章 · 控制魂","text":"因為他們示領受仿員理的心’使他們得救，故此，禮就給他們二個\"生發錯誤的心，叫他們信從虛謊，使一切不信真理，倒喜愛不義的人，都破定罪。\n\n」請~1H注意，員理是鑑別真偽的憑據，不是異能神蹟的「感受」。看今天許多强調靈恩的人，高藥方言，見異象、神醫、預言、奇事等等，認為這些感受是聖靈充滿的証據，甚至有些下認為是得救的証據。最低限度認為這是靈性「突破」或升高的現象。何等錯謬！～至於聖靈充滿”，方言，神蹟等問題，我們在本書的附篇裏會更詳細的討論～。"},{"label":"第二章 · 控制魂","text":"他們當中有不少証實是被邪靈附着的，但其餘的人還是繼續追求這些超自然的感受，首且引「求餅不會給你們石頭」這類經文來作安全保証，其實撒但豈不也引經文向耶穌保証有天使托攻祂的脚J嗎？他們中了撒但的詭計，歸根究底都是因為這等基督徒落在屬魂的生活裏，追求「感受」不是追求主，他們的靈修未能達到控制魂的階段。"},{"label":"第二章 · 控制魂","text":"我們靈修親近主，可能有很甜蜜的感受，但這不應該是我們追求的目的，我們的目的是主。所以，當我因為身體不適，或不夠精神，或其他種種問題使我不能保持那種甜密的感受時，我不應懷疑主不與我同在，或覺得自己落在靈性的幽谷之中。"},{"label":"第二章 · 控制魂","text":"除非自己細心禱告的時候，發現自己有罪行，有主所不喜歡的事物存在，那我應立刻自潔，離開罪。但倘若自己已經自潔了，双沒有做主所不喜歡的事，而且如今靈修研芒是一心親近主的，怎有可能主不理睬我，離開我呢？聖經清楚的告訴我們，只要我們常在主裏面，主就必定常在我們裏面一約十五4～。我没有犯罪，又行主所喜歡我行的，我自然就是在主裏面了(約9心。"},{"label":"第二章 · 控制魂","text":"我旣清楚我是在主裏面，我就是没有任何一感受」，我知道我還是在主裏面。因我深信聖經的真理！三的話—1是不變的。我們的情緒感受可以隨身體健康，和環境際遇而變，但這不表示主變了，或自己不在主裏面了。成熟的基督徒不憑感受判斷自己的靈性光景，乃憑真理和信心來肥繩。"},{"label":"第二章 · 控制魂","text":"我們JN的靈修達到控制Anl境界時，就是任何魂的感受都不能左右自己信心與神合一之時，這種境界就是最理想的境界。\n\n或問到了這实Y當然到了這種境界之時我們可能會有興奮，喜樂、甜蜜等感受。但這也不是常有的，因為情緒天然是受時間沖淡的，所以當這些感受渭渭淡下來的時候，我並不着急，因為我深信我仍在主裏面，或問，當我的感受漸漸淡下來，又不因此着急，又深信自己是在主裏面之時，有何感受？我可以肯定的說，這時的感受就是平安、寢靜或安息。可是，加果我在某種因素之下，信心稍微搖動了，我會失去這種平安或安息的感受也未可料。"},{"label":"第二章 · 控制魂","text":"但主的同在和我在主裏面仍是鐵一般的事實。例如有一個人回到自己的房間，撒但攻擊他，他心中忽然.有一個馨香對他說:「你這麼大胆，一個人住二間這麼大的房間？」他一聽見這個聲音，心中立玖惡卍起來，好像感受到四週鬼影幢幢似的，失去了平安和寧靜的感受。於是他立玖稿告求神快快救他，不然鬼出現就不得了。可是他越禱告，就越懼怕，越沒有平安。"},{"label":"第二章 · 控制魂","text":"最後他心裏起了一個意念—「我是神的兒子，沒有理由神不理我的」。他一這樣想，立刻所有恐怖的氣氛就消失了，心中也回復平靜了。為甚麼呢？因為他剛才雖然禱告，但他的禱告是失去信心的禱告。失去了信心就影響他內心的平靜。但當他想到自己是神的兒女，他沒有懷疑這一點，也想不出神會不理他的理由來，於是信心堅定，撒但欺騙的手段就立刻失敗了，他的內心也回復平安了。"},{"label":"第二章 · 控制魂","text":"請問，當這個人內心感受到惡栩之時，是否表示他不在主裏面，主也不在他裏面呢？不！主仍在他裏面，他仍在主裏面，只不過信心軟弱，於是情緒感受就變動了。所以，感受是不能用來判斷自己屬靈的光景的。容我再說，你若說自己的靈修很好，而在日常生活之中，發現自己勝不過驕傲，虛榮，情繕等感受，你的靈修仍不是真正好。因為你仍不能實際地控制自己的現。在靈修時學會控制自己的魂，在日常生活之中才能有員正得有的表現，才能流露出主的香氣。"},{"label":"第二章 · 控制靈","text":"控制靈\n\n魔詢第三次試探耶穌說:「你若偽伏拜我，我就把這一切(世上的萬國與萬國的榮華)都賜給你。\n\n」憑語氣，我們看見魔鬼在前兩次的態度，是友善的態度。用慈客的面孔來撞飾物的姆計。但兩次都被主耶穌看透了，於是魔鬼原形畢露9所以，第三次載控的語氣完全沒有搓飾:「你若售供拜我)我就把這一切都賜給你，意思是說:「不錯，我確是魔鬼，剛放磁你看穿了，現在我也不必再掩飾，不如我們直接底网的談多吧，你來無非想要從我手裏礁回世上的萬國。"},{"label":"第二章 · 控制靈","text":"好！我送答你，條件只要你以供拜我。其實我們何必一定要站個你死我活呢？你也知道這樣門下去，你終必喪身於十字架的！好吧！現在你拜我，拜我::快拜我::」魔鬼棄露出稚的本來面目，秀一定用盡牠的魔力去踢耶穌屈服下來拜牠。"},{"label":"第二章 · 控制靈","text":"我的意思是說，這次牠不但用盡全世界—牠全部所有的—來引誘耶穌，旣然牠的本來面目也被看穿了，牠就毫無禁忌的也用盡牠一切超自然的魔力去逼耶穌的靈「—耶穌最深入的部份，最致命的部份—「屈服下來拜牠。因為「拜」是用[靈」夫拜的。這是最大的威逼利誘，所以這個試探也是最利害的試探。啊！主耶穌得勝的能力何等的大。"},{"label":"第二章 · 控制靈","text":"祂沒有上當，試想，冗既放下天上的榮華，甘心降卑來救我們，祂又怎會為地上的榮華而失節呢？基督徒們！你們若看重主要賜給我們在天上的豐盛，就必不會為地上的一點點而離開主了。"},{"label":"第二章 · 控制靈","text":"或問，我們怎能訓練自己看重天上的產業而看輕地上的財寶呢？怎能勝過這一類的試探呢？這是「靈力」的問題了。看主耶穌不肯屈膝下拜，不但因為祂看不上世上的榮華，更是因仿冗控制自己的需的力量，遠遠大過魔鬼逼冗號下的魔力。曾有一個基督徒到廟宇去遊覽，在廟中看見許多面目角狐的偶像，突然他感受到有一種莫名的靈界的力量，逼他向偶像跪下。"},{"label":"第二章 · 控制靈","text":"他不肯，但那種神秘的力量越來越大，逼使他屈服下來。最後，他大喊:「耶穌呀！救我。」他忽然恢復力量，拔足狂奔跑出廟宇外面。主耶穌的名勝過邪靈的力。我們深信，在魔鬼勸耶穌下拜之時，牠一定會用盡牠的魔力去逼耶穌屈服，但主有更大的自制力，就是祂的靈力，魔鬼是毫無辦法的，因為主耶穌控制着自己的靈，與神與聖靈合而為一。"},{"label":"第二章 · 控制靈","text":"不但如此，耶穌除引用聖經指出「當拜主你的神，單要事奉祂之外」，還用自己的話說:「撒但，退去吧！」在整個試探的過程裏，主耶穌一直都是用聖經的話來回擊，但只有這一句話是出於策自己的。這一句話帶有莫大的能力，撒但—抵揣者—結果抵擋不住，氨去了。仿甚麼主耶穌可以用自己的話斥退撒但呢？補還沒有在十字架上藉才死敗壇掌死權衝采鬼！"},{"label":"第二章 · 控制靈","text":"是的，主耶穌能用自己的話斥退魔鬼，因為冗的震魂體都受到控制，完完全全的與父神，與聖靈合而為一，所以發出莫大的能力來。\n\n我們靈修是否真的「靈」修？我想有一些基督徒是坊聖經知識而「自修」，更有一些為宗教規條而「苦修」，還有一些以半睡半醒的態度去進行「零修」。‧誰是真正的靈修」呢？只有用「靈」去敬拜親近瑣—祝是個「靈」—方是靈修，而且靈與靈藉信心的接觸，進而靠主耶穌基督的恩典與寅合一。到了我們員正能修練自己，培到與神合一的時候，我們的屬靈能力就勝過撒但任何的引誘和魔力了。"},{"label":"第二章 · 控制靈","text":"有四十多年趕鬼經驗，輔導過二萬多個被污鬼壓制的人的高科爾(至元GO由師，筆了「鬼附與精神病」(種籽出版祉出版)一書。在這書裏面，他指出屬靈人的靈力或靈性程度，是可以從他對搞淫鬼的情形看出來的。他說，有一些褲污鬼壓制的人在接觸-個有靈力的傳道人時，他們會感到頭痛或其他不適的病徵，但如果接觸一個虛有其表的傳道人，他們就毫無不適的感覺。"},{"label":"第二章 · 控制靈","text":"他建議，最好開一個大會，招聚所有的傳道人來，然後吩咐一個有這種感受的被鬼壓製的人在這些傳道人面前走過，就可以分辯出施是神的僕人，誰不是禮的僕人了。當然這種建議是不可能的，但其中的道理是對的，今天多少為主工作的人缺乏屬靈的能力，因為他們的靈修生活出了問題。儘管他有神學博士的學位，有甚麼主教監督的名銜，他不與主聯合為一，他就毫無力量對抗撒但。"},{"label":"第二章 · 控制靈","text":"我們屬靈的工作是一種爭戰的工作。只不過我們不是與屬血氣爭戰，是與天空中屬靈氣的惡魔爭戰(弗六12一。代們的兵器是「屬靈」的兵器。\n\n我們的力量自然也是「屬靈」的力量，絕不是靠我們肉體的，理，屬世的力量。但要有這種力量，非要我們在靈修時，真的控制自己的靈完全的與神合一不可。怎樣才算是在靈修時控制自己的靈與入合一？在靈修時，我們不要坊「胡食」這一類「外邦人所求的」事禱告(太六32～，即使是為教會聖工，為别人的靈魂，為自己的事奉等禱告也不要放在最先和最重的位置上。"},{"label":"第二章 · 控制靈","text":"最先和最重要的禱告是敬拜，感謝，讚美，獻上榮耀，尊貴，能力，權勢等給神的禱告。這就是-靈交」式的禱告(稍後詳談細論)。當我們藉着這樣的靈交想到神一切的豐盛榮耀之時，我們的信心不是單以為這一切都是真的，而是進一步靠主耶穌基督以為這一切都是「我父親」的，而我是祂的兒女，所以我有格承受祂這一切的豐盛。想到祂的榮耀是何等豐盛，我不其然獻上讚美，但想到我可以靠主耶穌基督承受祂的豐盛，我立刻獻上感謝。"},{"label":"第二章 · 控制靈","text":"想到祂的權能，我不其然敬拜祂，但想到祂用祂的權能蔭庇我的時候，我立刻投靠祂。請注意，當我為「承受一祂的豐盛而獻上感謝，叉仿冗的權能蔭庇而立刻一投靠一祂的時候，我是不知不覺的與祂聯合了。多認議科，更多信靠祂，這是我們靈修時候所要特别注重「修練」的，這種修練也就是控制自己的靈與神合一的靈修了。"},{"label":"第二章 · 控制靈","text":"這是最理想的靈修境界，我寫出這些話不是說我已經完全了，試問世上除了主耶穌基督之外，誰可以達到完全全全的控制自己的靈體魂與神與聖靈合一呢？雖然如此，我感謝神，第一是因仿冗藉耶穌基督的榜樣帶給我們這個進到理想靈修境界的原則，使我們可以照着行。\n\n第二是因為甚麼時候我跌倒了，我還可以靠着主耶穌的恩典，隨時隨地的起來，再一次的親近神，與祂合一。"}]},{"short":"識破撒但的欺騙、離間、攻擊","terms":["撒但","世俗"],"cards":[{"label":"先抓住一個重點","title":"許多信徒失敗，是因為被騙","lines":["作者說，神的兒女在神的愛中本可得勝。","但撒但最擅長說謊，使人失去信心。","例如利用情緒低落、懷疑，或犯罪後的自責。"],"takeaway":"信心是勝過那惡者的關鍵。"},{"label":"把意思拆開","title":"欺騙、離間、攻擊","lines":["欺騙：讓人以為情緒低落就是神離開了，或罪洗淨後仍有痕跡。","離間：用世俗污穢和驕傲自恃，使人與神疏遠。","攻擊：用苦難疾病，但信心知道一切都在神的准許中。"],"takeaway":"認清三種手段，就不容易中計。"},{"label":"用生活例子想一想","title":"馬丁路德的故事","lines":["作者引述：撒但拿出記滿馬丁路德罪狀的書。","他寫上：「祂兒子耶穌的血也洗淨我們一切的罪。」","這說明：悔改後，要相信罪已被赦免，再站起來。"],"takeaway":"不要被過去的罪困住。"}],"quiz":{"question":"作者說，悔改後仍覺得「污蹟洗不去」，應該怎樣看？","options":["這是撒但的欺騙，要相信主的血已洗淨","要不斷折磨自己來贖罪","從此不再事奉"],"answer":0,"hint":"想想馬丁路德寫了甚麼。","explanation":"作者鼓勵信徒憑信心拒絕這控告，恢復親近主。"},"key":"ap3","id":9,"no":"附篇三","title":"勝過那惡者的信心","bookTitle":"勝過那惡者的信心","part":3,"partName":"進深","partTitle":"第三站　進深","idx":2,"original":[{"label":"附篇三","text":"我們因着信靠耶穌基督，就得以稱為神的兒女。神用愛兒女的愛包團著我們，保護我們，只要我們不犯罪，不離開祂，我們就能在祂的愛中過蒙福得勝的生活，撒但的能力盡管有多大，也不能損害我們分毫。這種生活，這樣的福氣，多寶貴、多甜密、多快可是！我們發現許多基督徒仍然不快樂，仍然失敗，仍然跌倒不能起來，仍然無法得着自由，天天過着做撒但刀柱的生活，為甚麼呢？是主的能力不夠嗎？"},{"label":"附篇三","text":"是我們信了耶穌還未得救嗎？不！這完全是因為我們的信心弱。聖經說:「因仿贍從神生的，就勝過世界，使我們勝了世界的就是我們的信心，勝過世界的是誰呢？不是那信耶穌是神兒子的麼？」(約壹五45)撒但知道使我們勝過牠的，就是我們的信心，因為我們藉着信，將我們接尊到神的大能薩席之中，撒但就無所施其技了。所以牠二直想盡千方百計也要解除我們能信，只要能叫我們不信，牠就可以為所欲為了。\n\n但是，牠可用甚麼方法叫我們不信呢？我發現撒但有三個辦法"},{"label":"附篇三 · 撒但的欺騙","text":"撒但的欺騙\n\n撒但最本事的技能就是說謊，自古至今，從沒有一個人未祕物騙過的，只有主耶穌基督不上牠的當，在那次四十晝夜的禁食新禧中，用神的話語拆穿牠的詭計一參看第二章)。然而，撒但今天慣用甚麼欺騙手段呢？上情緒上的感覺:通常我們遇到天氣悶熱，或睡眠不足，或身體不適，或嘈雜環境，或工作多而無意義等等時，我們會產生情緒低潮。"},{"label":"附篇三 · 撒但的欺騙","text":"情緒本來是一種情感上的乛感覺」，情緒低潮就是情感上的感覺不靈敏，或對本來能引起我們喜怒哀樂的事物不能產生應有的反應。這時候，可能我們最軟弱備受撒但攻擊的地方就是我們的感覺了。於是撒但就進前來，用牠那欺騙人的口脗對我們說:「你現在是否覺得沒有喜樂？你的靈修是否覺得失去神的同在？你是否覺得工作失去能力？你是否覺得::覺得：：覺得：。"},{"label":"附篇三 · 撒但的欺騙","text":"厂許多喜愛追求感覺的基督徒就受不住這一連串的「提醒一，讓我淸楚在這裏指出，靈恩派和一些過份强調靈裏感覺的基督徒多是在這一方面中了撒但的欺騙的。"},{"label":"附篇三 · 撒但的欺騙","text":"他們「覺得」自己裏面不妥，於是就恐懼憂愁起來，拚命尋找一些方法來恢復這樣的感覺，結果他們就以激動、混亂、大叫、新奇、刺激，指責等聚會方式來滿足自己，因為這樣的聚會最能叫人有所感覺。感覺受欺騙只是其中的禍害，最慘的是邪靈趁機而入，叫人真正經歷超自然的感覺，於是就不能自拔了。我在第一章已經說過，情緒感覺不是壞東西，我們不可能沒有感覺的。"},{"label":"附篇三 · 撒但的欺騙","text":"但我們要指出，情縱感覺不是「準確」的東西，不可能單用來衡量自己屬靈的光景的。真正準確不變可以用來衡量的是真理。我的意思是說:當我感覺得沒有喜樂，覺得神不同在，覺得工疟無力等時，如果我明白是有一個直接的原因，例如因為我犯了罪，我貪愛世界等，我就知道這感覺是對的，是真的因為是真理的聖靈指出我有罪之時產生的。"},{"label":"附篇三 · 撒但的欺騙","text":"但如果我的感覺沒有直接明白的原因，即不是真理的聖靈在我內心用真理啟示我，使我們因此而產生正常的感覺，那麼，這種感覺是不可靠的，可能是情緒低落所引致的，也可能是撒但政擊所怪。如果我有一個莫名的感覺，但因為我要查出這莫名的感覺的原因，於找到了一個實在的原因。我也不應該以這個原因為一定準確的原因。"},{"label":"附篇三 · 撒但的欺騙","text":"因仿正常來說，是先有原因後有感覺，莫名的感覺就是沒有原因在先，後來找出來的原因未必就是真正產生這種感覺的原因。\n\n例如，一個人感到神不與他同在，他不明白是甚麼原因，但他十分難過焦急，逼自己去找出其中的原因，後來他找到了一個，原來前幾天會經對一個傳道人無禮。請注意，這一個原因未必就是使他感到神不同在的所謂「隱藏」的原因。固然對傳道人無禮是錯的，但這樣逼自己去找原因，總或多或少會找着一點的，試問有誰的生活是最完全的？不如說，神不同在的感覺是一種錯覺，是撒但的攻擊欺騙。"},{"label":"附篇三 · 撒但的欺騙","text":"但如果聖靈指出，因為那一次對傳道人無禮，於是就以為傳道人所作的工自己也可以做到有餘，因為自己比傳道人本事，這樣騙例起來，所以工作事奉感到無力，感到神不同工不同在。這樣有直接關係的原因才是正確的原因。不然，不要受魔鬼的欺騙。情穎既然是易變的，不準確的，我們就不要以情穎仿標準。夏令會不一定是你以往曾經歷過的那種激動，痛哭，喜樂的情形才算是復興的，有得着的。"},{"label":"附篇三 · 撒但的欺騙","text":"因為第一次的經歷多是情穎渡動得最利害的經歷，以後雖然神的靈照樣動工，神的恩典照樣多，情緒感受不一定像上一次那麼大，因為情緒是隨時間淡下來的。"},{"label":"附篇三 · 撒但的欺騙","text":"考試成績好，一聽到十分歡喜，但時間久了，這喜樂也淡下來了，但首不表示成績也慢慢差了，祝用時間冲淡人的情緒，是叫有痛苦的人不會長久受痛苦的折磨，叫有喜樂的人不會長久滿足在地上的喜樂，等到有一天，我們的主回來，我們的身體改變成焦榮耀的身體時，我們就能哭那新天新地的新生活中，經歷得起長久不冲淡的喜樂了。所以在情穎低潮時(即使在平常生猹中v要小心撒但欺騙你的感覺。"},{"label":"附篇三 · 撒但的欺騙","text":"有真實原因的感覺我們才重視，我們不要理會它。纖使自己感到懼怕，無力，孤單，痛苦，絕望，我們仍不要動搖，我們可以對撒但說:我信神看顧我，我信神的愛不變，我信我仍在神的愛中，我信，總之我堅定相信，因坊伯現今這些可怕的感覺都是沒有原因的，不論這些感覺是出自生理，心理，或撒但的攻擊也好，我信神必能便我勝過。這樣藉信心海過撒但的欺騙，我自己不知經歷過多少次，古今也有不知多少基督徒經歷過。\n\n但可惜，不曉得這樣藉信心抵擋仇敵魔鬼的人，今天仍是多着"},{"label":"附篇三 · 不正常的懷疑","text":"不正常的懷疑\n\n多年以前會經有一段時期我犯罪，軟弱，跌倒，離開神，沒有靈修，然後有一天，我突然懷疑起來:「我想可能沒有神吧！」我拚命抓許多理由來支持自己的想法。越想越覺得自己想得對，於是我的生活越來越不像樣，因為想到旣然沒有神，誰來管我呢？"},{"label":"附篇三 · 不正常的懷疑","text":"可是我覺得還有一種力量管着我，當時我不知道是甚麼力量(現在知道是聖靈的力量，禮首沒有因為我懷疑就離開我～，只覺得內心因犯罪而痛苦，感到虛空，自疚，不安。一天，當我返回自己的房間時，感到需要祈禱認罪，但又不信有祝，必情十分矛盾。最後終於跪下禱告說：一神啊！倘若有你存在，求你告訴我。」立刻，我聽見右耳邊有聲音說:「你為何犯罪？」"},{"label":"附篇三 · 不正常的懷疑","text":"我回答說:「我不想犯罪的，但有一種外來的力量迫使我去犯罪，使我不由自主！」聖靈感動我說:「你以為逼你去犯罪的力量是甚麼，豆而十X．一我說:「是魔鬼！-當我一說出是魔鬼的時候，我立刻明白過來了。"},{"label":"附篇三 · 不正常的懷疑","text":"為甚麼我只信有魔鬼而不信有神？兩者都是屬於靈界的！我單懷恬祝的存在是何等是推？我向神認罪，悔改改，立志以後永不再懷恬策。於是有大喜樂充滿我的內心。自從那一次之後，我檢討自己為何會懷疑起來，就得到很寶貴的結論，使我能立志至死篤信為我們信心創始成終的主。"},{"label":"附篇三 · 不正常的懷疑","text":"現在我把所得的分享給各位：la）不合邏輯的懷疑:我們知道正常的，合科學的懷疑，是在深入研究之時，發現有錯誤或不通的地方，雖然參考過許多書籍，請教過許多有深入研究的人，亦無法解決，這樣才能下初步的判斷—可能這裏有錯。"},{"label":"附篇三 · 不正常的懷疑","text":"雖是這樣，遇有相反意見的人，仍樂瑟聽，務求審慎鑑定，以免出錯。可是，像我那一次的懷疑，既沒有深入研究，也沒有參考書籍，更沒有請教屬靈的長者；反而犯罪，停止靈修，無緣無故的懷疑起來。"},{"label":"附篇三 · 不正常的懷疑","text":"雖然後來也抓到一些理由來支持自己的懷疑，但那分明是事後鑫強想出來的，決不是使自己產生懷疑，不是出自魔鬼的欺bb）不平衡的懷疑:再說以公正態度去懷疑一件事，必須把正面反面的理由都拿來衡量，看是反方的理由强，還是正方的理由强，然後才能下一個初步的判斷，倘若單看正方，或單看反方就下判斷，這樣的結論是不平衡的，不公正的。今天，許多基督徒只在一小點道理上想不通，就立刻表示懷疑，表示不信。"},{"label":"附篇三 · 不正常的懷疑","text":"其實那一小點的想不通，能否因此就否定整個神學信仰呢？何况那一小點的想不通，有極高的可能性是自己愚拙，認議瞄淺。我們應當注意正方的埋由比反方的理由重得多，任何地上的法官，遇到這樣的案件，總會判正方勝訴的。例如支持我們的信仰不倒的理由有—兩千多年以來千萬基督徒的見証並他們的研究心得:以色列果然照聖經的預言應騐復國，有不少科學家是信耶穌。"},{"label":"附篇三 · 不正常的懷疑","text":"聖經仍是世上最多人看，最受尊重，譯本最多，銷售總數最多的書，聖經的事蹟得到考古學的多方証明，基督教的信仰改變了歷史，改變了許多罪人，普遍影响了現今世界，今天許多禱告仍帶來神蹟；今天最先進的國家仍是以基督教信仰立國的國家:::這許多正方的理由，使我們的信仰穩如泰山。如果有人因為一加圖想不通而懷疑，我可以肯定，他的懷疑必定是出於魔鬼的。"},{"label":"附篇三 · 不正常的懷疑","text":"（c）絕路的懷疑:一次主耶穌講論自己的肉是可吃的，自己的血是可喝的一71～。猶太人最怕吃血，何况吃人血呢？所以他們不明白主所說的，壟且討厭這種講法。雖然主解釋祂所講的話是指着靈，指着生命說的，但他們仍然不肯相信。於是他們都離開主，不再跟隨祂了。耶穌問十二個門徒說:你們也要去麼？從這個問題看，我們知追十二個門徒當時也不明白仿甚麼主的肉和血是可吃的，他們也是一樣受到床擾。"},{"label":"附篇三 · 不正常的懷疑","text":"但西門彼得想了一想，就對主說:「主啊！你有永生之道，我們還歸從誰呢！」這是一個何等有智慧的答覆！意思是說:「那問題我們雖然也想不通，但這不是最重要的問題，最重要的問題是你有永生之道，倘若我們也跟衆人一樣退去，那必短是死路一H..條，但跟隨你，我們有永生，這是我們想通的，所以我們還是決定跟隨你。」"},{"label":"附篇三 · 不正常的懷疑","text":"是的，我們之所以信耶穌，是因為我們認定我們無法解決罪和死的問題，世上也没有人能解決，如今這位為我們的罪死，又復活過來的主耶穌，祂說祂能赦我們的罪，救我們免死，反得永生，祂正是我們所需要的救主，這一點是我們確知的。"},{"label":"附篇三 · 不正常的懷疑","text":"這樣，雖然在督教的許多道理中，有一點我暫時想不通，我豈可以因為這一點而放棄永生的主呢？退一萬步說，縱使連主有永生之道也是假的，即是說，跟隨主也是死路一條，這樣，不論退去也死，跟主也死，旣然都是一樣，為何急着要退去，不仔細看清楚才下決定呢？無論怎麼說也好，因為一點想不通而退去的人，是被魔鬼欺騙了。"},{"label":"附篇三 · 不正常的懷疑","text":"要知道，自古至今，雖有千萬人起來提出許多所謂証據，企圖推翻基督教的信仰，但從來沒有一個人能提出半點證據，証明主沒有永生之道！綜合以上的種種懷疑，我們可以認定，這全部是魔鬼慣用欺騙人的手段。要勝過這樣的懷疑，也是需要堅定的信心。真信心的根基不是自己頭腦，因為自己頭腦有限，頭腦有許多想不通的東西。"},{"label":"附篇三 · 不正常的懷疑","text":"真信心的根基是主自己，因為主是我們信心的對象，所以在情在理，信心應當以主為根基。主從來未有過失信的紀錄，主從來沒有半點對我們不好，主從來沒有半點不可信任的壞事做過出來，這樣，主就是可信的。\n\n撒但自古至今都是說謊的，只有牠才是不可信的"},{"label":"附篇三 · 潔淨後的痕蹟","text":"潔淨後的痕蹟\n\n撒但還有一種極利害，害死千萬信徒的欺騙手段，就是當你犯了罪，又真心到神面前悔改之後，牠就告訴你:「你犯了這樣污算的罪，雖然神赦免你，當然你不致滅亡，但你想你有了這樣的紀錄，你怎能起來事奉主？你已失去了屬靈的能力，你的汚蹟是洗不去的，你以後怎可以還厚着面皮去靈修，去親近神？你應該繼續自責，你要折磨自己以作贖罪。"},{"label":"附篇三 · 潔淨後的痕蹟","text":":::」這樣的話聽起來有情有理，而且牠的姿態是何等公義神聖，叫聽見的人常誤以為是聖靈的聲音，於是就有許多基督徒受了牠的欺騙，從此不敢事奉，也認定自己已經失去屬靈的能力，不配親近神，一生自責，自己折磨自己。有許多受不了這種精神壓力，甚至精神崩潰，或神經衰弱。所以有一個精神病院的統計說，基督徒患精神神病的機會比常人高。"},{"label":"附篇三 · 潔淨後的痕蹟","text":"因為普通人做了壞事的自疚感不大，但基督徒嫩有了最高的標準，又常常面對聖潔的神，再加上內裏新生命的排斥罪惡性情，這樣便叫他們常常感受到罪的困擾，自疚感也大得多。撒但趁此機會，加重他們自疚感，直到他們受不住，神經崩潰為止。其實，我們犯了罪雖然應當自責，難過，但我們認罪之後卻應該立刻相信主的赦免是徹底的，是不留痕蹟的。"},{"label":"附篇三 · 潔淨後的痕蹟","text":"聖經說我們必潔白如雪。我們在主的眼看來仍是可愛沒有瑕疵的。像哥林多教會的信徒那樣腐敗，保羅仍指出他們是「聖徒」，「在主耶穌基督顯現的日子無可責餓。厂+-刖。“一像曠野中的以色列人那樣犯罪，但神的靈感動巴蘭先知時仍說:「神未見雅各中有罪孽，也未見以色列中有奸惡。"},{"label":"附篇三 · 潔淨後的痕蹟","text":"～民二十三21～當然希伯來書的作者說:「所以我們只管坦然無懼的，來到施恩的寶座前，為要得憐恤，蒙恩惠，作隨時，他正是在指出，主耶穌「並非不能體恤我們的軟弱一因為主「也會凡事受過試探，與我們一樣，只是祂沒有犯過罪』來四蕊所以，今天的基督徒若能用堅定不移的信心對撒但說:「你不要欺騙我，我雖然犯了罪，但主的血已經洗淨，再沒有痕蹟，再沒有紀錄。"},{"label":"附篇三 · 潔淨後的痕蹟","text":"我仍然恢復我屬靈的能力，恢復親近主的資格，我靠主恩，主的血，仍要站起來事奉主。一在堅定不移的信心面前，撒但就無所施其技了。據說馬丁路德未改革之前，在天主教中當禮甫之職，常為自己的罪感到痛苦自責，他發現越要藉功德來贖罪，越發覺自己有時不盡的罪。後來他明白聖經因信稱義的道理，起來玫革教會，一天晚上，他看見魔鬼挾着三本厚厚的書進到他的書房來，說要帶他下地獄去。"},{"label":"附篇三 · 潔淨後的痕蹟","text":"馬丁路德質問牠憑甚麼權柄，根據甚麼，魔鬼說:「我就是掌死權的魔鬼，你看你犯了許多的罪，我都記錄在這三本書裏了，根據這許多的罪，你要受我的繳繳了。"},{"label":"附篇三 · 潔淨後的痕蹟","text":"」馬丁路德接過三本書來看，裏外都寫滿了自己一生所犯的罪，連思想上的罪牠都記錄下來了，但馬丁路德不慌不忙的拿起一支筆來，在書上寫了一句話：一祂兒子耶穌的血也洗淨我們一切的罪。一一約壹一7～魔鬼立刻搶回那三本書，發現裏面全部空白，所有的罪案都沒有了。"},{"label":"附篇三 · 潔淨後的痕蹟","text":"是的，我們要相信主的血有完全的功效，主的愛有完全的恩典，主的能力有完全的得勝，我們要信，堅定不移的相信，撒但的欺騙就失敗了。"},{"label":"附篇三 · 撒但的離間","text":"撒但的離間\n\n撒但知道我們得能力是因為我們常在神的愛中，神旣愛我們，又幫助我們，撒但就毫無辦法害我們了。牠可以用盡各種的方法來欺騙我們，目的是叫我們失去信心我們就得不着能力去抵擋牠，牠就可以為所欲為了。倘若我們藉堅定不移的信心，不受牠的欺騙，通常牠會進而探取更直接手段—就是離間。用罪來離間我們與神的關係。"},{"label":"附篇三 · 撒但的離間","text":"無論用欺騙的手段也好，用離間的手段也好，牠的目的總是要我們與神隔開。只要我們與神隔開，牠就可以為所欲為。然而牠用甚麼罪，甚麼方法來離間我們與神的關係呢？"},{"label":"附篇三 · 世俗污穢","text":"世俗污穢\n\n以色列人在曠野期間，摩押人和米甸人因為懼怕以色列人，但又自問沒有能力攻打他們，於是召了巴蘭先知來，想要藉着先知的咒詛來攻擊以色列人，誰知神不准巴蘭先知品論，反而祝福以色列人，摩押人和米甸人自然生氣，打發巴蘭先知空手回本地去。"},{"label":"附篇三 · 世俗污穢","text":"貪財的巴蘭先知回去之後越想越不甘心，分明有機會得到摩押人和米甸人許多金銀財寶，但耶和華神卻不讓他得到，而且他也深知耶和華神愛護以色列人，他是無法加害與他們的。可是，後來他竟然想出一個借刀殺人的毒計來，獻給摩押人和米甸人，換取他所要貪得的金銀財寶。這毒計就是請米甸人派一些婦女到以色列人的營幕外面跳舞，引誘以色列人與她們行淫和拜偶像。"},{"label":"附篇三 · 世俗污穢","text":"巴蘭先知知道，只要以色列人行淫和拜偶像，摩押人和米甸人不用攻擊以色列人，神也會親白擊殺以色列人的，因為耶和華是一位聖潔和鼠政的神。果然，這毒計順利成功，神因為以色列人行淫和拜偶像的緣故，-日之間就用盛疫擊殺了二萬四千以色列人。當然，後來神也没有放過巴蘭先知，神吩咐摩西提拿他，把他殺了。這件事告訴我們，撒但有一個非常利害的毒計，那就是巴蘭的毒計。"},{"label":"附篇三 · 世俗污穢","text":"不錯，神愛我們，神維護我們，但是撒但也知道，只要我們沾染了世俗污笑，禮就自動的與我們隔開，甚至會鞭打管教我們。我想巴蘭想出這一條毒計害以色列人，但他想不到撒但竟也用這條毒計來害死他。"},{"label":"附篇三 · 世俗污穢","text":"撒但的離間和借刀殺人的手段真是高明，且L，世俗襪的毒素也真是可類似以上例子的歷史事實，真是多得很，諸如參孫，大衞，所羅門等，都是被神重用的僕人，但都是因為沾染世俗污航而跨食得很利害的，或許有人以為，基督徒很少犯巴蘭，參孫，大衞，所羅門等人所犯的罪的。"},{"label":"附篇三 · 世俗污穢","text":"對！但是基督徒不一定犯大罪才算是沾染世俗汚，請看以掃，希伯來書的作者指出，他貪戀一碗紅豆湯就是貪戀世俗了(來十二16～，結果失去長子的名份，失去神選民的地位，從亞伯拉罕所得的應許福氣中墮落了。一碗紅豆湯是一件小事，但失去選民地位和應許是大事。基督徒也可能因為貪戀圖圖世俗污穢，就引來非常大的惡果。因為雅各書說:「豈不知與世俗為友的，就是與神為瑞慶？」"},{"label":"附篇三 · 世俗污穢","text":"(雅四4～與世俗做做朋友，在一般基督徒看來是一件小事，誰知它的惡果是使我墜落到與神為敵的地位—即受神攻擊的地位。\n\n或問，世俗澆算是甚麼？就是約壹書起二章十五至十七節所說的世界和世界上的事，因為原文聖經一世俗「與刊品含二字是相同的。聖經說:「不要愛世界和世界上的事，人若愛世界，愛父的心就不在他裏面了。因為凡世界上的事，就像肉體的情慾，眼目的情人答，首今生的驕傲，都不是從父來的，乃是從世界來的。這世界和其上的情慾都要過去，惟獨遵行神旨意的，是永遠常存的。」"},{"label":"附篇三 · 世俗污穢","text":"肉體的情慾就是一切肉體的需求，而使我們失去愛父神的心的，即離間我們與父的關係。同樣，眼目的情慾就是一切你想要看但它會離間你與父神的關係的，今生的驕傲就是一切你認為足以自豪而不能帶進永世，反而離間你與神的關係的。"},{"label":"附篇三 · 世俗污穢","text":"擧例來說:分别善惡樹的果子在夏娃看來認為「好作食物」，這就是肉體的情慾；那果子能「悅人的眼目」，這就是眼目的情慾；那果子又能使人「有智慧」，這就是今生的驕傲。"},{"label":"附篇三 · 世俗污穢","text":"又例如:魔鬼在試探耶穌時，叫耶穌吩咐石頭成食物，牠就是以肉體的情慾來試揉寅；將萬國和萬國的榮華給耶穌看，就是以眼目的情慾來試探祂；帶耶穌到殿頂上，叫耶穌在眾目瞼瞪之下跳下去，以博得萬人的景仰，這就是以今生的驕傲來試探祂。"},{"label":"附篇三 · 世俗污穢","text":"今生的矣例這一樣我們留待下一點再談，台裏我們再談談肉體的情慾一一旦被撒但控制了，又可稱仿「那情一，邪情是會上癮的，是污自的，是不正常的，是罪惡的。例如今天許多青年人喜愛穿異性服裝，男的愛長像女人的長髮，女的穿男的窄身褲，男的愛長女的指甲，女的愛像男的紋身。"},{"label":"附篇三 · 世俗污穢","text":"許多服裝，嗜好，動作，並不是為了「美」，也不是為了實際的「需要」，而只是為了一種莫名的，新潮的，標奇立異的「感受」。\n\n請註疙，這種怪的所謂感受，其實就是邪情了。拿男孩子的長髮來說，我們不必辯論頭髮多長才算標準。我們要指出一個奇徑的感受，就是頭髮荔珊長起來之時，心中障唔搬起一種戀慕，想要傾向女性化，想要吸引别人和自我吸引的感妥。"},{"label":"附篇三 · 世俗污穢","text":"等到頭髮長到實在不可以不剪短時，就發現這種感受牽制着他，叫他不捨得剪短，而且他不惜冒着朋友家人輕看他的損失，强詞奪理的為自己的長髮辯護，但他心中明明的聽見聖靈的聲音～如果他是一個基督徒的話～—「無論是甚麼別的事，趾弟兄跌倒的，一慨不作才好一～羅十四有&)；「見事我都可行，但不都有益處，凡事我都可行，但無論那一件，我總不受他的轄制一～林前六)；「你們的本性不也指示你們，男人若有長頭髮，便是他的羞辱麼？"},{"label":"附篇三 · 世俗污穢","text":"一～林前十一14～；一無論作甚麼，總要為榮耀神而行一～林前+冖1～。這一種抵擋聖吉馨理的感受，不是一邪情」是甚麼？邪情旣然是麗鬼控組的感情，要擺娩懂情的捆綁，就要先對付魔鬼本身。我發現，撒但無論用那一種世俗污航來引誘我們離開神也好，即使是金錢，名譽，地位，性慾，服裝，娛樂，食物，友誼等等，牠都經常加上一邪情」，藉以牢籠人的心。"},{"label":"附篇三 · 世俗污穢","text":"所以，當我們落在這一種試探時，我們大可以直接對撒但本身加以斥責說:「撒但，你退去，我知道你想要藉世俗污穩的邪情來離間我與神的關係，但我偏要站穩在神的愛中，我現在奉主耶穌基督的名，吩咐你離開我！」出於信心又靠着耶穌基督的名，撒但必要退去，邪情必要解開，引誘力就消失。雖然有時趕走了牠，稍後牠又會再來，但只要我們堅決的奉主的名趕牠，牠到底還是要退去的。"},{"label":"附篇三 · 世俗污穢","text":"有一點要注意，就是在奉主耶穌的名趕物時，心理上不要注視邪情或世俗的「可愛之處」或「來勢之兇猛」，因為這樣注視，無形之中等於承認牠與你仍有關係，所以，我們在趕牠時，心埋上的注意力要集中在主耶穌這一面，既然趕了牠，就連一眼也不要看牠，儘管牠再來的來勢多兇猛，因人為我不看牠，只看主，牠在主面前就變弱，甚至退去了。"},{"label":"附篇三 · 世俗污穢","text":"或問我們怎能不看牠，怎能只看主？這就是信心的問題了。抵擋魔鬼仇敵要有信心，只有信心能將我們連到主的豐盛和能力裏面，只有信心能叫我們勝過魔鬼任何試探攻擊◎撒但離間的手段不一定用世俗污稻的。我發現在這一個世代裏～可能在别的世代也是這樣)，撒但很喜歡用"},{"label":"附篇三 · 驕傲自恃","text":"驕傲自恃\n\n的手段來離間基督徒與神的關係，牠會對基督徒說:「你真聰明，你竟然發現基督教是可信的，其實你之所以有這樣的發現，完全是因為你會運用理性，因此，你今後要認定一件事，若通不過你的理性，不要接受相信。"},{"label":"附篇三 · 驕傲自恃","text":"」這樣的意見，青年基督徒，尤其是大學裏的基督徒，最喜歡接受。不錯，神賜給我們長好的理性，適當地運用理性可以辨出真偽。但適當地運用理性，往往會變成過份强調理性，以致讀神的話也用理性來批評，不運用信心去接受，反運用理性去懷疑。"},{"label":"附篇三 · 驕傲自恃","text":"這樣過份强調理性其實就是驕例，矣傲到一個地步，以為自己不但聰明過魔鬼，甚至也聰明過神，因為他以為可以憑自己的理性去判斷出魔鬼的話對，還是神的話對。換言之，他相信的不是神，也不是聖經，而是自己的理性。正如我在前文論懷疑時所指出的，這樣的理性本身已墜落到不合理的地步了。可是，今天不知多少基督徒是這樣，不知多少神學家是這樣，不知多少教會是這樣。他們因為高舉理性不知不覺高舉了自己，這樣矣伍自恃的態度使他們與神隔絕了。"},{"label":"附篇三 · 驕傲自恃","text":"既然與神隔絕，就更不認議禾，讀聖經更無亮光，判斷就更容易出錯，撒但見到這種情形，就更為所欲為，將一間一間神學院，-間一間教會，一個一個基督徒帶到不信派的圈子裏。這一點我在前文已經先後論及了，不過，在這裏我要指出，這也是撒但離間人與神的關係的一個最慣用的辦法。至於抵擋的途徑，還是要運用堅定不移的信心。"},{"label":"附篇三 · 驕傲自恃","text":"我們信神，並不全因為我們想通了，當然我們必要在基本的原則上想通才信，但最重要的，不是這個，最重要的是我們信心的根基在於神本身，不在我們的理性。"},{"label":"附篇三 · 驕傲自恃","text":"神可信，因為祂是神，因為祂從來沒有失信，因訪宙比我聰明，袍造我，完愛我，向我所懷的一婦疙念都是賜平安的意念。我只要在這些原則的問題上想通了，我就安心信祂了。我不需要每一件小事大事都想通才信，因為這樣根本沒有可能，若可能，我自己就是神了。"},{"label":"附篇三 · 驕傲自恃","text":"我想不通是自然的，因為我是人，要用人的腦袋去想通所有屬神的事情是不合邏輯的，因為我承認我是人，很眇小，我相信神是神，很偉大，所以我很容易就拒絕了撒但叫我驕傲自恃的離間詭計了。\n\n可見勝過撒但這樣的詭計的，也是信心。"},{"label":"附篇三 · 撒但的攻擊","text":"撒但的攻擊\n\n假如欺騙不來，離間不成，撒但往往就會用第三種方法，那就是直接的人身攻擊了。•彭（a）苦難疾殼:移伯記告訴我們，許多苦難疾病是撒但攻擊我們的工具，但信心卻叫我知道，任何苦難疾病都有神的准許在其中。基督徒的信心不應像拜偶像之人的信心，他們的信是在乎利害關係，我們的信是在乎愛與生命的關係。拜觀音的人沒有一個愛上觀音的，也沒有聽見觀音愛上一個人，為那人死。"},{"label":"附篇三 · 撒但的攻擊","text":"所以拜觀音的人，雖然載氛獻豬，但鷄和豬都是為自己肚腹的，而且獻鷄獻豬不外想要藉此不大有價值的東西，換取高價值的「出入平安」，「貨如輪轉一，乛金玉滿堂」等等。如果拜一段時期不靈騐，就轉去拜别的偶像，或關公，或任何土地汚鬼，不問牠的法力是否比觀音大，不問牠的品德是否比觀音高，只問牠是否肯聽自己的話，成就自己所想望的。"},{"label":"附篇三 · 撒但的攻擊","text":"照樣，如m仁果基督徒信神是因為利害關係，要求神聽我們的話，不是我們要聽神的話，這樣的信還不是真信。真信心是相信神能叫萬事都互相效力，咱我們愛神的人得盆處，而且不一定是地上的益處，最主要還是屬天的，屬靈的益處。我們可以窮，可以病，可以死，但我們並不因這些否定神是可信的，因為我們的外體可以毁壞，但我們的內心卻因信而一天新似一天。"},{"label":"附篇三 · 撒但的攻擊","text":"因我們信我們這至暫至輕的苦楚，要為我們成就極重無比永遠的榮耀。我們不是顧念所見的，因為所見的是暫時的，所不見的是永遠的。\n\n當我們落在苦難疾病中，我們要檢討一下自己的靈性生活，看看是否因為自己犯了罪，貪愛世界，才招至這樣的苦難疾病，如果真是這樣，這就是神的管教，我們要服在神的管教中，不可灰心，因為神旣然管教就自然表示祂十分愛我們，這一點希伯來書十二章有十分詳細的勸勉。"},{"label":"附篇三 · 撒但的攻擊","text":"如果檢討完了，發現苦難疾病的來臨，並不關係神的管教和自己的過犯，反而是在自己靈性好的狀態中來臨的，這一定就是出於撒但的攻擊。\n\n尤其是有一些傳道人經驗到，每當他們在講台上强烈針對撒但時，撒但就會或重或輕的對付他們的身體。不過無論重或輕都有神的准許在其中。有時也會因為教會興旺，或要承担重大的職任，或因為神將要重用他，撒但就來加以攻擊。神的准許是因為神也想要藉這樣的攻擊來試煉他。"},{"label":"附篇三 · 撒但的攻擊","text":"當我們檢討，斷定是撒但的攻擊之後，第一件要緊記的，是要穩定自己的情緒，不要讓自己灰心，不要生氣，不要抱恕，不要心懷不平，不要讓自己在情緒低落之時生出各樣的懷括與誤解，正如我在前論情緒之時所指出的。"},{"label":"附篇三 · 撒但的攻擊","text":"第二件緊要的事，是要留心撒但這樣的攻擊作用目標為何。了解牠針對的目標，我們可能會更修配得勝。如果牠攻擊你，是因為你承担重任，神要重用你，你就可以在接任那工作之時特别小心自己。如果牠攻擊你是因為想要破壞你的靈修生活的話，你就該越發重視改善你的靈修生活。如果牠攻擊你是因為你的工作會影响許多人的話，你就該為衆人儆醒。"},{"label":"附篇三 · 撒但的攻擊","text":"總而言之，我們不要氣餒，我們不要怕任何攻擊，即使撒但要在我們肉身上加一根永久不能除開的刺，像保羅所經歷的一樣，我們也要用信心堅持到底，與撒但對抗，對抗的態度認定了，勝利始終是屬於我們的。（b）邪靈附身:撒但最後一招直接攻擊的手法，就是附在人的身上。不過，牠絕對不能隨便出現，隨便附在基督徒的身上，這還是要通過神的准許才可以的。神有時准許撒但附在一些基督徒身上。"},{"label":"附篇三 · 撒但的攻擊","text":"為的是要那些基督徒在日後經歷過從自己身上出來的經驗，可以更加剛强，也能幫助别人，有的是為了讓别的基督徒可以因他更認識魔鬼的本來面目，從而更儆醒為主工作。"},{"label":"附篇三 · 撒但的攻擊","text":"但被附的人也要担當自己做錯事的代價，而且被鬼附有局部的和全身的分别，這也就是做錯事輕重和担當代價輕重的分别。通常來說，鬼附在一個人身上，必須通過幾個關:第一是犯罪，如果基督徒過聖潔的生活，撒但是無能為力的；第二是交鬼，如果基督徒不接受，不信靠任何儀式(基督教必行的儀式只有浸禮和擘餅紀念主兩個，其他的一切不是必要行的，即使是按手禮，也是可行可不行的，如果强調一定要行才能得到某種屬靈的恩賜或福氣，那就錯了)，包括任何拜祭，符咒，秘術，與秘術有關的動作，邪靈是無法施其技的。"},{"label":"附篇三 · 撒但的攻擊","text":"第三是意志投入，甚至有一些秘術叫人先將自己的思想「空白」，也是這個意思。事實上，在甘心情願去履行交鬼的儀式時，也就等於意志投入，因為人旣然信靠牠，自然在意志上投入於牠。"},{"label":"附篇三 · 撒但的攻擊","text":"如果那儀式叫人認識的靈越兇惡的話，在意志投入之後，附在那人身上的邪靈也就越兇惡，如果那儀式叫人認識的靈像光明天使一般的，附在人身上的那露就只能用光明天使的姿態來在人身上工作，叫人受騙，等到那人對牠的信任大一點之後，也就是在意志上不探取太嚴密預防之後，牠會再以比較兇惡一點的姿態來引誘他履行第二次的儀式，如果履行了，即還志節入了，也就等於他願意接納比較兇惡的勢力附在他身上，這樣，邪靈一步一步的由部以致全身，由似乎光明的天使以致兇惡黑暗魔鬼，附在那人身上。"},{"label":"附篇三 · 撒但的攻擊","text":"所以邪靈要附在人身上，意志是重要的一關，邪教為了人意志肯投入，有時先勸人吃迷幻藥，有時先藉一些神蹟奇事欺哄人，叫人信任，有時先叫人失眠，在極度彼億之下，意志會較易放鬆受騙，有時會利用激動的聚會氣氛，叫人不提防而作意志投入，總之，邪靈非先得到人的意志投入，或人對牠的信心，就不能作甚麼。"},{"label":"附篇三 · 撒但的攻擊","text":"為此，基督徒只要靠真理有堅定的信心，不履行任何交鬼的儀式，不將自己的意志隨便向一個靈投入，魔鬼就無所施其技了。\n\n但向聖靈，我們可以放心投入，不過聖靈稱仿頁理的聖靈，所以憑真理就可以認出地來。投入聖靈是無須靠按手或任何儀式的，只要我們悔改信耶穌，作一個重生的基督徒，聖靈就自然進入我們心中，但卻不是附在我們身上。總括來說，撒但無論用任何手段攻擊我們，只要我們堅定信靠主的心，就可以完全"}]},{"short":"從聖經原則明白神旨意","terms":["神的旨意","活祭"],"cards":[{"label":"先抓住一個重點","title":"神的旨意不是神秘莫測","lines":["作者用一個「求婚」的例子，說明很多人把神旨意弄得很神秘。","他認為神的旨意主要已在聖經真理中顯明。","明白之前，先要重生得救，並願意獻上自己作活祭。"],"takeaway":"先有對的生命和心志。"},{"label":"把意思拆開","title":"三個步驟","lines":["一、用屬靈智慧和悟性，看事情是否合乎聖經真理。","二、在真理範圍內仍有多個選擇，可以自己立志去行。","三、若行錯了，神會攔阻或用特別方法引導。"],"takeaway":"真理是原則，立志是自由。"},{"label":"用生活例子想一想","title":"升學選擇","lines":["作者舉例：去美國、英國、加拿大、留港，還是工作？","先在禱告中放下私見，願意為主而活。","然後按真理和實際情況作決定，不必等異象。"],"takeaway":"目的正確，手段也要合乎真理。"}],"quiz":{"question":"在聖經真理範圍內仍有幾個選擇時，作者怎樣建議？","options":["可以自己立志去行，神會在需要時攔阻","一定要等異夢或異象","選最困難的一個"],"answer":0,"hint":"看「立志行事」那一節。","explanation":"作者引用腓立比書，說神在人心裏運行，使人立志。"},"key":"ap1","id":10,"no":"附篇一","title":"如何明白神的旨意","bookTitle":"如何明白神的旨意","part":4,"partName":"專題","partTitle":"第四站　專題","idx":1,"original":[{"label":"附篇一","text":"基督徒常把神的旨意弄至神秘莫測。有一個弟兄追求一位姊妹，向她說:「我昨晚新褲清楚神的旨意要我向妳求婚，妳可否答應？」那位姊妹聽了之後十分憂愁，跑來找我訴苦，說:「我實在不願意嫁給他，但神的旨意又要我嫁給他，怎辦？」當然，我給她指出，她如果不喜歡那位弟兄，那就不是神的旨意，如果是神的旨意，神也必感動她愛上那位弟兄。"},{"label":"附篇一","text":"但這個例子表明了多多少少基督徒不曉得怎樣明白神的旨意，或許有一部份責任要歸咎一些傳道人在講台上講見証，或寫傳記的態度。他們往往不把怎樣淸楚知道是神的旨意的過程詳細說出，只草草的說:「那天晚上我禱告直到天亮，神就使我明白我應該這樣做了。」這樣的一句話叫聽的人想了半天也想不明白，究竟他們是在那天晚上突然聽到從天上來一個聲音告訴他們應該那樣做呢？"},{"label":"附篇一","text":"還是做了一個異夢得了超自然的啟示？又或者他們根據甚麼理由想通了？還是有一種不可言喻的感力在他們心中啟發他？像這樣的見証我們聽得多了，於是在一般基督徒中，總有一種神秘感「—神的旨瑟員難明白。"},{"label":"附篇一","text":"究竟神的旨意是否真的難尋難測？有人說，是的，保羅也清楚的說:「深賣！禮豐富的智慧和知識，祂的判斷何其難測，祂的縱跡何其難尋。～羅十一33～又有以賽亞書淸楚記着說:「耶和華說，我的意念非同你們的意念，我的道路非同你們的道路。天怎樣高過地，照樣我的道路高過你們的道路，我的意念高過你們的意念。」(賽五十五8—9～可見神的旨意確是高深莫測。"},{"label":"附篇一","text":"但我在這裏要指出，上述所引用的兩節經文不能用來證明神的旨意難明白，因為這兩節經文都是站在人的立場上說的，人憑人的智慧聰明，當然無法明白神的旨意。但要明白神的旨意，一定要站在神啟示的立場來想，我們身為神的兒女，神豈會不肯讓我們明白祂的旨意呢？當然肯，因為先既然要求祂的兒女行在宙旨瑟裏，宙一定肯啟示清楚明白，不然，移就無權追究我們不行祂旨意的責任了。"},{"label":"附篇一","text":"主耶穌清楚的說:「父啊！天地的主，我感謝你，因為你將這些事向聰明通達的人就藏起來，向嬰孩就顯出來，父阿！是的，因為你的美意本是如此一～太十一25—26～。對了，無論人何等聰明通達，神的旨意仍然是難尋的，但無論我們何等幼稚是搶，只要我們是神的兒女，神的嬰孩，這樣，神的旨意對我們來說，就容易明白了。或問，我們要怎樣才能變成嬰孩呢？要明百神的旨意應有何種步驟呢"},{"label":"附篇一 · 要重生得救","text":"要重生得救\n\n要變成一個嬰孩唯一的辦法是重生得救，即是從水和聖靈而生，從「水」生是指約翰悔改的洗禮，藉着悔改我們定了以往的我是死的，人的辦法是無能為力的，以往的生活是腐敗的，從「聖靈」生是指藉着信心接耶穌進入自己的心裏，繳眾說：一凡接待祂的，就是信祂名的人，祂就賜他們權柄作神的兒女。"},{"label":"附篇一 · 要重生得救","text":"～約一L～這樣，我們是神的兒女，我們是有神的靈的人，我們要明白神的事就沒有困難了，正如林前二章九至十二節說:「如經上所訊，”禮為肪袖的人所預備的，是眼睛未會看見，耳朶未聽見，人心未會想到的』(怪不得難明，但是～，只有神藉着聖靈向我們顯明了。因為聖靈參透萬事，就是神深奧的事也參透了(所以變得易明～。除了人裏頭的靈，誰知道人的事？多這樣，除了神的靈，也沒有人知道神的事。"},{"label":"附篇一 · 要重生得救","text":"我們所領受的(重生得救時領受的)，並不是世上的靈，乃是從神來的靈，叫我們能知道神開恩賜給我們的事。」真的，一個未重生得救的人根本上不希望明白神的旨意，因為神先決的旨意是要他悔改信主，他若連這一點也不願意，其他的就不用說了。"},{"label":"附篇一 · 要重生得救","text":"如果一旦未重生得救的人想要明白神的旨意，他的用心也不過是要利用神，想要藉閉祝知道一些未來的事，像一般人想要藉占卜看相的或求問偶像，希望知道一些未來的事，從而選凶就吉。"},{"label":"附篇一 · 要重生得救","text":"但我們身為神的兒女要明白神的旨意目的就不同了。如果我們明白神的旨意要我們遭遇災難，我們也要順服，因為我們知道神能叫萬事都彑相效力，叫愛神的人得盆處。我們希望明白神的旨意並不為利用神達成自己的要求，乃是順服神以達成神的要求，因為有了這個大分别，所以未重生得救的人不願意以順服神的旨意和達成神的旨意為目的，這樣，自然他們就不明白神的旨意了。"},{"label":"附篇一 · 要重生得救","text":"况且，未重生得救的人無從明白神的旨意，因為他們心中沒有神的靈，牛命不同類，自然不能明白，好像我們人可以明白人的事，但人不可以明白昆蟲動物的事，因為我們與昆蟲動物的言語不通，思相習慣不通。同樣，如果我們沒有神的靈，我們不能通往神那裏，我們與神之間的「言語」不通，但有神的靈的人，就相通了。重生得救的人明白何謂新稿「通」了，明白何謂讀經得到亮光，明白何謂神的感動，因為有神的靈在名"},{"label":"附篇一 · 不效法這個世界","text":"不效法這個世界\n\n第二個明白神的旨意的原則或條件是羅馬書十二章一至二節。「所以弟兄們，我以神的慈悲勸你們，將身體獻上，當作活祭，是聖潔的，是神所喜悅的，你們如此事奉乃是理所當然的，不要效法這個世界，只要心意更新而變化，叫你們察驗何為神的善歷，總全可喜悅的旨意。」請注意保羅勸我們獻身作活祭，意思是要我們一為主活一，一為主死」，因為祭牲可以活一段時間，但終於都是被殺才成祭的。"},{"label":"附篇一 · 不效法這個世界","text":"這個祭牲一定要是潔淨的種類，即「聖潔的」，也要是無殘無疾的，即「神所喜悅的」。實際一點來說，甚麼是一聖潔的」呢？就是「不效法這個世界的」。甚麼是「神所喜悅的」呢？就是「察驗神善長，純全，可喜悅的旨意的」。中文聖經譯這句話有點含糊，如果意譯的話可作「察驗神的旨意，這旨章是好的(eg)，完全的(oaoor)，得人吉悅的(已o～—。"},{"label":"附篇一 · 不效法這個世界","text":"總括來說，這兩節經文告訴我們:如果我們決心為主活為主死，並且不效法這個世界，不沾染世俗澆算，我們就一定能明白神的旨意。神的旨意對我們這些獻身的人來說一定是好的，是完全的，我們也一定喜愛的。"},{"label":"附篇一 · 不效法這個世界","text":"獻身為主，不效法這個世界是一個非常重要的原則，因仿祝的旨意絕對不會要我們效法與生坊瑞的世俗的(雅各書四章四節，這裏「世俗」一詞在原文與羅馬書十二章二節的「世界」是相同的，並且也與約翰壹書二章十五至十七節所說「世界」相同，或問世界是甚麼？是指這個風景美麗的地球嗎？是指世界上的人嗎？"},{"label":"附篇一 · 不效法這個世界","text":"不，將輸壹書二章十五至十七節清楚指出:「不要愛世界和世界上的事，人若愛世界，愛父的心就不在他裏面了。\n\n因為凡世界上的事，就像肉體的情慾，眼目的情慾，並今生的驕傲，都不是從父來的，乃是從世界來的。這世界和其上的情慾都要過去，惟獨遵行神旨意的，是永遠常存。」龐活瑟最後一句，很明顯的指出，神的旨意與世界是對立的，是不能並存的。看拜偶像的人，求籤問卜的人，他們豈不也是想要明白他們的神的旨意嗎？"},{"label":"附篇一 · 不效法這個世界","text":"但他們想要明白的是怎樣可以賺得世界，怎樣可以過安舒的生活，怎樣可以逢凶化吉，他們絕沒有自潔分別才聖，為獻身事奉神而求問神的旨意。\n\n所以這樣的求問，並不能通到賞神那裏，只能通到魔鬼撒但那裏，因為魔鬼撒但是這世界的王。我們屬神的人不要效法他們，我們求問神的旨意目的不是為自己，乃是為主自己，不是為世界，乃是為神的國。因我們信主的人不再是自己的人，乃是主用重價買來的，所以我們獻身為主而活為主而死是理所當然的。基督徒不持定這個目標態度，焉想能明白神的旨意。"},{"label":"附篇一 · 不效法這個世界","text":"舉例來說，某教會有一位長老想要多娶一個妻子，他於是禱告求問神說:「神阿！如果不是你的旨意要我多娶一個妻子，求你讓我三天之內死去；如果是你的則更，求你讓我三天之內不會死去。」何等可笑的禱告:既目的不正又用要脅的態度去强逼禮，禮理會他誠怪呢！有人為股票，彩票，買賣求問神的旨意。有人為報仇雪恨，對付異己求問神的旨意；有人為娛樂享受，名譽地位求問神的旨意。"},{"label":"附篇一 · 不效法這個世界","text":"這種種世俗化的祈求，簡直是利用神，以為神是他們的僕役，替他們消災解難，那知神旣是神，我們才是祂的僕役，我們求問祂的旨意，應該像一個僕人求問主人的旨意一般說:「主人啊，你喜歡我替你做甚麼？」讀者可能讀到這裏會問，不知這位「主人」對待我這個「僕人」的態度怎樣呢？"},{"label":"附篇一 · 不效法這個世界","text":"萬一祂的旨意是要害我，萬一祂要我替祂做事沒有顧及我的安危，或者袍強逼我做一些我不喜歡做的事，那麼我還要求問祂嗎？對於這些問題，保羅的答覆是:你旣是獻身為主的人，主的旨意一定是好的～08完全的～品ec二，二定算你所喜歡的nenseagqC。"},{"label":"附篇一 · 不效法這個世界","text":"如果你認為不好，不完全，不喜歡，那一定就是你沒有獻身為主而活為主而死，你的活與死都是為己為世界。所以，我們總括這一點說:只要我們一心為主，不為世俗情慾，我們就一定能明白神的旨意了。"},{"label":"附篇一 · 屬靈的智慧和悟性","text":"屬靈的智慧和悟性\n\n明白神旨意的第三個步驟記載在歌羅西書一章九至十一節—！一願你們在一切屬靈的智慧悟性上，滿心知道神的旨意。好叫你們行事為人對得起主，凡事蒙祂喜悅，在一切善事上結果子，漸漸的多知道神。照祂榮耀的權能得以力上加力，好叫你們凡事歡歡喜喜的忍耐寬容。」"},{"label":"附篇一 · 屬靈的智慧和悟性","text":"請注意第十和第十一節，由「好叫你們行事::」直到乛忍耐寬容」這段話，再一次强調了上文第二點所說的，尋求神的旨意不是為世俗為自己，乃是為對得起主，蒙祂喜悅，訪袍緒善果，多知道祂，在事奉上得力，在逼迫苦難中忍耐寬容。"},{"label":"附篇一 · 屬靈的智慧和悟性","text":"但這一切的果效，都是由於「滿心』知道神的旨意，滿心知道的意思是淸清楚楚的知道。我們怎能清清楚楚的知道呢？上文所提及屬靈的「智慧」和「悟性」就是緊要的秘訣了。甚麼是屬靈的智慧和悟性呢？屬靈的「智慧」就是指將聖經真理融濫綱通，變成自己的思想原則。正如詩篇一百一十九篇九十七至九十九節說:「我何等愛慕你的律法，終日不住的思想，你的命令常存在我心裏，使我比仇敵有智慧。"},{"label":"附篇一 · 屬靈的智慧和悟性","text":"我比我的師傅更通達，因我思想你的法度」。或問，為甚麼聖經不明言在「神的話語上」滿心知道神的旨意？卻好像轉一個彎說在「屬靈的智慧上」滿心知道神的旨意？原因是許多人熟讀神的話，甚至熟背神的話，但他們仍不能明白神的旨意，因為他們沒有把神的話融濫綱通，憂成自己的思想原則，變成自己的智慧。"},{"label":"附篇一 · 屬靈的智慧和悟性","text":"看古時的文士，他們十分熟悉聖經，甚至用錐將一皮爺聖經由外面第出坐弟二層刺穿到裏面的捲軸去，他們都能說出，每一層所穿過的那幾個字是甚麼字。但他們卻不明白耶穌是基督，不知道神的旨意是要基督先受苦才進入榮耀。所以，要明白神的旨意，必須先將神的話變成自己的智慧。那麼，屬靈的「悟性」又是甚麼呢？屬靈的「悟性」是指將屬靈的智慧應用在所求問的事情上，從而領悟到這件事情是否合乎神的旨意。"},{"label":"附篇一 · 屬靈的智慧和悟性","text":"「悟性」這個詞在聖經的用途上不是指一種神秘不可言喻的領悟力，好像有人說他禱告到了一個地步，突然很神奇的明白了神的旨意。乃是指一種理性的運用，常理的覺悟，正如保羅在哥林多前書十四章十五節那裏，將神奇的與常理的禱告歌唱分開說:「我要用靈禱告，也要用悟性禱告。"},{"label":"附篇一 · 屬靈的智慧和悟性","text":"我要用靈歌唱，也要用悟性歌唱」，用「靈」來幬告分明是說一種不能表達得明白的禱告，“用「悟性一禱告分明是指一種表達得明白的禱告。\n\n所以這裏的「悟性」就是理性領悟的意思。這樣，運用屬靈的悟性去滿心明白神的旨意，就是以理性運用屬靈的智慧—神的話—去鑑别所求問的事情是否合乎神的旨意。不過，在運用的過程裏，禱告是不可“缺少的。"},{"label":"附篇一 · 屬靈的智慧和悟性","text":"我們把有關的事情在禱告中帶到神的面前，然後用悟性去運用屬靈的智慧來鑑，别那件事是否合神的旨意，因為在禱告中，我們比較專心面對神，於是我們就容易不效'法這個世界，容易運用悟性，即容易想起神的話，容易明白那件事在不效法世界的原則下，是否脗合聖經教訓的原則，尤其是我們的禱告是在一聖靈裏禱告」，即讓孕震完全自由引帶自己禱告時的思想，這樣我們在禱告中所思想的，就是用悟性所明白的，就是聖靈引帶的。"},{"label":"附篇一 · 屬靈的智慧和悟性","text":"羅馬書八章二十六至二十七節說:「我們的軟弱有聖靈幫助，我們本不曉得當怎樣禱告，只是聖靈用說不出來的歎息替我們禱告，鑒察人心的，曉得聖靈銜意思，因為聖靈照着神的旨意替聖徒祈求。"},{"label":"附篇一 · 屬靈的智慧和悟性","text":"」又有約翰福音十四章二十六節說:「保慰師就是父因我的名所要差來的聖靈，祂要將一切的事指教你們，並且叫你們想起我對你們所說的一切話。」還有約翰壹書二章二十七節說:「你們從主所受的恩膏～聖靈～常存在你們心裏，並不用人教訓你們，自有主的恩膏在凡事上教訓你們。」這就是以賽亞書三十章二十一節所說的:「你或向左，或向右，你必聽見後邊有馨香說:這是正路，要行在其中。"},{"label":"附篇一 · 屬靈的智慧和悟性","text":"」當然這「後邊的聲音一和「恩膏的教導」，就是指聖靈叫我們「要趨主一而說的。這樣，在聖靈裏禱告，就是在禱告中運用悟性去想起主的話，從而鑑别這是否「正路」，是否合乎神的旨意了。"},{"label":"附篇一 · 屬靈的智慧和悟性","text":"換言之，讀經與禱告是明白神的旨意的人不可少的，有了神的話為指南針，有了聖靈引導自己的悟性，我們一定能滿心知道神的旨意，一切含有世俗情慾的事，一定不是神的旨意，一切不含聖經教訓的事，一定不是神的旨意。"},{"label":"附篇一 · 屬靈的智慧和悟性","text":"即使那事多順利，多奇妙，且有「神蹟」印證，甚至有「天使」出現印，有靈有聲音印，都不一定是神的旨意，正如保羅說:「無論是我們，是天上來的使者，若傳福音一包括任何信息一給你們，與我們所傳給你們的(即聖經所記的～不同，他就應當被咒詛。～加一8)又說:-「我勸你們，無論有靈，有言語，有冒我名的書信，說主的日子現在到了(與聖經不符)不要輕易動心心。"},{"label":"附篇一 · 屬靈的智慧和悟性","text":"～帖後一只有聖經是我們信仰最高的權威，是我們分辦頁偏的唯一準則，而且要明白聖經，應用聖經，就只有靠着聖靈引帶我們的悟性，因為若不是祂開了我們的眼睛，我們絕不能看見神話語中的奇妙～詩一+Q。"},{"label":"附篇一 · 一些錯誤的例子","text":"一些錯誤的例子\n\n'有人以為只要「目的正確」，那就是神的旨意。有一次我在一問鑽會帶領一個研討會，出席的都是教會的領袖。我提出一個問題說:「如果目的純正，為了救人一命，我們可以撒一個說嗎？」使我感到希奇的，就是竟然全體都認為可以。我立刻指出這是錯誤的，如果這也是真理，那麼主耶穌所說的:「信子的人有永生」這句話豈不也可能是假的？因為冗的目的也是純正，也是為了要我們棄惡行善。"},{"label":"附篇一 · 一些錯誤的例子","text":"不！不但目的純正不能說謊，就是連自己的生命也要失去都不能說謊，看主耶穌受審時，只要祂肯說一句謊話就可以免死了，但袍寢可死也不說謊，因為祂知道，是就說是，不是就說不是，若再多說，就是出於那惡者了。所以，我們應用「不效法這個世界」的原HJ④」，立刻清楚的鑑定，任何含有說謊的事，都不是神的旨意。有人以為，如果是神的旨意，一定十分順利的。"},{"label":"附篇一 · 一些錯誤的例子","text":"如果不是神的旨意，一定諸多困難。NH但我要指出，許多走私販毒也是十分順利的，那是神的旨意嗎？許多蒙召奉獻自己作全時間傳道的，多是困難重重，為甚麼結果又被神重用？所以，順利與不順利不是一個原則，不能鑑定那就是神的旨意。"},{"label":"附篇一 · 一些錯誤的例子","text":"正如保羅寫信給羅馬的弟兄姊妹說：一禱告之間常常的狠求刁或心，終能得平坦的道路往你們那裏去。羅10～結果怎樣呢？絡果神的旨意真的要他到羅馬去，但神的旨意没有讓他得平坦的道路，反而是多災多難的道路:首先他補猴太人控告下錨，首且險些被殺，然後帶着鎖鏈被押上船到羅馬去，途中遭遇風淚沉船，蒙神保守免死，到了羅馬仍然帶着鎖鏈不得自由，但畢胸，禮要他去羅馬傳道的旨意達到了。"},{"label":"附篇一 · 一些錯誤的例子","text":"有人以為如果事情有神蹟奇事印証，那就是神的旨意了。這也不一定，如果神蹟奇事的出現不合聖經真理，那只不過是撒但的圈套，想要藉欺騙人的法術迷惑人。事實上每一個宗教都有十分靈驗的神蹟奇事，連在基督教的圈子之內，也有不少邪靈假扮光明天使施行的神蹟奇事，那麼我們怎能分辨出來呢？聖經告訴我們；「凡靈認耶穌基督是成了肉身來的，就是出於神，從此你們可以認出神的靈來。"},{"label":"附篇一 · 一些錯誤的例子","text":"凡靈不認耶穌，就不是出於神，這是那敵基督者的。(約壹西2二這樣我們看見聖經的話是最高的鑑别。最普遍的意見是，如果是神的旨意，到了適當的時候，必定有好像很巧合的事發生的•例如有人在十分窮困時，人的方法沒有了，突然在他出門的時候，拾到了一個錢包，這正是神供給的。又例如，失業時，突然有人請他做某某香烟公司的營業代表，薪金十分優厚，這麼巧合的事，必定是神的旨意了。"},{"label":"附篇一 · 一些錯誤的例子","text":"不！請註疙，拾遺不報是罪，做香因公司的營業代表等於勸人吸煙，害人身體，這都是違背聖經的真理，因此，無論事情多巧合，不合聖經真理就不是神的旨意。還有許多别的例子，不過，我們要强調的是，真正清楚鑑定是否合神旨意的原則只有聖經，其他的一切只能拿來當作一種助証或參考。或者有人會問，當我們遇見一些事連聖經的原則都不能使我們有所決定的時候，我們應當怎樣？"},{"label":"附篇一 · 一些錯誤的例子","text":"例如有幾個選擇都是符合聖經教訓原則的，那麼，我們怎能知道那一個決擇才是神的旨意？是的，要回答這問題，我們就需要下一個步驟了1！\n\n1立志事行事，保羅在腓立比書二章十三節那裏說:「因為你們"},{"label":"附篇一 · 立志行事","text":"立志行事\n\n，都是禮在你們心裏運行，為要成就祂的美意。」這是說，只要我們的心意念以聖經的真理教訓為原則，那麼我們自己立志怎樣行，那就是神的旨意了。或許你以為，立志分明是我自己立的，那怎可能是神的旨意呢？問題就在這裏了。"},{"label":"附篇一 · 立志行事","text":"我們常感到神則瑟難尋求的原因，是因為我們存着一個心理，以為神的旨意一定是一種超自然的啟示，祂或藉異夢，異象啟示我們，不然完了會賜我們一種神奇的感覺力，使我們領悟尋常人所不能領悟的啟示，又或者祂藉着甚巧妙奇蹟的安排來引導我們在祂的旨意中，無論如何，神的旨意一定是一種超自然的啟示。"},{"label":"附篇一 · 立志行事","text":"不！神不一定這樣行•當然袖可以這樣行，但祂只會在超常的時候才用超自然的方法•如果在平常的時候，祂總喜歡用平常自然的方法。我們為甚麼一定要强逼神用超自然的方法才順服呢？為甚廢不相信神的大能是大到甚至在平常自然的情况下，仍然可以引導我們行在融的旨意裏面呢？"},{"label":"附篇一 · 立志行事","text":"當神創道天地時，秘看着所造的一切都「甚好」，這一切甚好的是包括自然界一切的定律，也包括了我們生活在自然的狀况下。\n\n所以，神看自然的啟示方法也是甚好的。話說回來，立志不錯是我們自己定的。但聖經明說，我們之所以這樣立志都是神大能的運行在我們裏面，叫我們這樣立志，神的大能大到一個地步，在我們裏面運行影響我們立志，我們一點也不會發覺，或說我們甚麼感受也没有。不但我們立志不會感覺到神在我們裏面運行，就是連聖經作者在寫聖經的時候，他們也不一定有任何感覺的。"},{"label":"附篇一 · 立志行事","text":"當我們的思想意念以聖經的真理教訓為原則之時，神就能以運行在我們裏面，叫我們作出一個決定，一個很自然的決定，去行在神的旨意裏面了。所以，簡單說一句，神的旨意非常容易明白，沒有甚麼神秘感，只要我們的思想以聖經的真理為原則，我們自己喜歡甚麼，那就是神的旨意了。在聖經原則之內，神樂意讓我們有一個自由的揀選或決定"},{"label":"附篇一 · 一些正確的例子","text":"一些正確的例子\n\n“舉一個常遇見的例:許多人常為自己畢業中學升大學的事傷腦筋，有五個選擇:到美國讀書呢？還是到英國呢？還是到加拿大呢？還是留在本港呢？又或者是出來做事呢？首先，我將這些問題在禱告中帶到神面前，放下自己的私見{心尋求神的旨馬只要是出於神的旨瑟，無論怎樣也願意接受，因為我已經立定主意照羅馬書第十二章所說的，獻上自己作「活祭」—為主活為主死。"},{"label":"附篇一 · 一些正確的例子","text":"好！有了這一個準確的態度之後，我就專心禱告，在禱告之中，運用屬靈的智慧去思想這些問題是否符合聖經的教訓原則，這時候，聖靈已經運行在我們裏面作工，我們就開始領悟～這屬靈的悟性～；噢！不能到加拿大去讀書，因為申請到那裏讀書必須向加拿大領事館說煞，不然就得不到批準～這只是一個假設不是例子～，我不能去效法這個世界去騙人。然後在禱告思想:噢！"},{"label":"附篇一 · 一些正確的例子","text":"我不能到美國讀書，因為收我入學的那一間大學是天主教的或反對基督教的，我恐怕我站立不住，失去自己的信仰，神不喜歡的我也不喜歡。現在剩下三個選擇了，在英國讀書，在本港讀書，在本港做事，這三條路都沒有不合聖經的教訓原則，怎麼辨呢？好！這是我自己立志的時候了，照我個人的喜好，我總喜愛出國多見識一點好，所以我揀選到英國讀書，這個揀選就是神的旨意了。"},{"label":"附篇一 · 一些正確的例子","text":"或許上述的例子太嚴重了，為了要表明神的旨意是非常容易尋找明白的，我再舉一個例:吃飯時，滿桌子都是美味的）神的旨意要我先吃那一樣呢？那一味是棘的，不！我不能吃，因為我有胃病.雖然我喜歡吃，但聖經教訓我要愛惜自己的身體，因為這身體是神的殿，所以神的旨意一定不要我吃那〞1味䤪o另一味餸是狗肉，基督徒也可以吃狗肉，但在香港的法律下，吃狗肉是犯法的，所以我也不吃。"},{"label":"附篇一 · 一些正確的例子","text":"還有一味我十分喜歡吃，但可能我吃會中別人跌倒，我寧願不吃，剩下其他的餸都合聖經教訓了，可是我怎知神的旨意要我先吃那一味呢？讀者，請問你以為有那一個基督徒在這個時候會感到猜疑，會逼母尋戋神超自然的啟示，戰戰表說的不知怎樣作一個選擇好呢？不！"},{"label":"附篇一 · 一些正確的例子","text":"我相信沒有人會這樣做，任何人在這時候都會很自然的，喜歡先吃甚麼就先吃甚麼，心想神不會連這麼小事也管的，祂必定給我一個自由揀選權。\n\n神給人自由揀選權是對的，但說神管不着這麼小的事就不對了，我們用甚麼標準來衡量事情的大與小呢？不如說，神的旨意就是我們在聖經原則下所立志去做的事，這誤清楚明白得多了。恐怕說到這裏仍有人担心說:會不會有可能自己立的志不是神的旨意呢？倘若我們立志錯了，所喜歡做的事錯了那怎麼辨？為了解答這個問題，我們又再進一步討論下一點，作為以上所論的補充"},{"label":"附篇一 · 超自然的引導","text":"超自然的引導\n\n首先我要指出，在普通的情况下，依照上述的幾個原則行事，就不會抵骨宙的旨意了。\n\n倘若遇有不平常的事，即是上述原則不能涉及的事，我們就是決定錯了，神知道不能條責我們，因為我們無從明白錯在那裏。所以，這一類不平常的事神必自己負責，無\"論如何祂不會眼巴巴看着我們走錯路而不理的。科或阻憎我們，或藉異象異夢啟示我們，或用神蹟奇事引導我們走另一條路，使我們終能成就祂的旨意為止。"},{"label":"附篇一 · 超自然的引導","text":"但這種超自然的引I導，一定是在神認為可以用自然的方法來引導我們的話，祂總喜歡用自然的方法，所以，我們不能鮑強禮一定要用超1自然的方法。\n\n另一方面我們也不要認為神一定不會用超自然的方法，我們總得把主權交IU給神，神喜歡怎樣行就怎樣行好了。因為策用甚麼方法來引導我們，那是我們管不着的，我們的責任就是照聖經的教訓行女們照聖經的儿訓行，就是行錯了也是神的責任，不是我們的責任。"},{"label":"附篇一 · 超自然的引導","text":"而且，為了防避邪靈假冒聖靈用超自然的方法來引導我們，我們還得用聖經的真理去辨别，出自聖靈我們才順服，出自邪靈的，無論那引導多奇妙，我們也要奉主耶穌基督的名拒斥之，千萬不要因為經驗到超自然的引導，就歡喜得連聖靈邪靈也不去分辨，這是非常危險的。"},{"label":"附篇一 · 超自然的引導","text":"舉一個例子說，使徒行傳十六章六至十節告訴我們，保羅和他的同工在路司得和以哥念傳完了道之後，他們就隨自己的立志，或隨自己的喜歡，想要到亞西亞傳福音。"},{"label":"附篇一 · 超自然的引導","text":"我們要注意，到亞西亞傳福音並沒有抵觸聖經的教訓，也沒有任何私慾罪惡的目的，我的意思是說，保羅運用上述普通尋求神則瑟的原則也不能發覺有何不對的地方，當然他祝千過了，聖經的原則也對照過了，屬靈的智慧和悟性也運用過了，他於是決定去亞西亞便芒百。"},{"label":"附篇一 · 超自然的引導","text":"誰知聖經告訴我們，聖靈禁止他們下去，聖靈用甚麼方法禁止他們，這一點我們不知道，我們只知道這一次的禁止是屬於一種超自然的方法。還有我們不要以為聖靈禁止他就是怪責他，不，聖靈絕沒有半硅怪責的含寢，因為聖靈明白保羅走錯路是不自知的，保羅一生都是這樣隨自己喜歡立志去傳福百一生都沒有走錯，這一次聖靈禁止，只不過是一生之中的一兩次經驗吧了。"},{"label":"附篇一 · 超自然的引導","text":"這不是失敗的經驗，而是用平常原則行不通時，神用超常的方法引導他的經騐，以後他也没有故意去尋找這一種經驗了他在以後和路程，還是照以往所慣用的平常原則來行事，可見他並不覺得平常原則有甚麼缸黑我再說，用平常原則行事是我們的責任，用超常的方法引導我們是神的責任，旣然如此，保羅雖然發現聖靈禁止他到亞西亞去傳福特，他還是用平常的原則再立悉到别的地方去傳往悍。"},{"label":"附篇一 · 超自然的引導","text":"這一次，他立志到庇推尼去傳福音，請注意，他立志到庇推尼去傳福音還是沒有抵觸聖經的真理教訓，當然他也曾把這立志在禱告中帶到神的面前，用屬靈的智慧和悟性去鑑别過，但他仍不能發現有甚麼不對之處，於是他就打算下庇推尼去了，誰知這-次耶穌的靈叉不許，究竟耶穌的靈用甚麼方法使他知道不可去庇推尼，這一點我們不知道，但我們知道這一次的啟示也是屬於一種超自然的方法。"},{"label":"附篇一 · 超自然的引導","text":"這是第二次，但保羅這一生沒有許多次這樣的經騐，以後他還是用平常的原則行事。神用超自然的方法阻攔他之後，神知道無論如何保羅用平常的原則是不可能明白祂的計劃的。於是神就必須用超自然的引導了，神在夜間使保羅作了一個異夢，看見一個馬其頓人站在他面前對他說:「請過來幫助我們。」保羅就領悟可能神要他到馬其頓傳福音了。"},{"label":"附篇一 · 超自然的引導","text":"或問，保羅怎麼知那夢就是異夢？怎知那異夢有神的啟示在其中？我們的答案是：/【/這夢沒有與聖經的真理教訓相抵觸，聖經還是最高的原則。（2）神要啓示那一個人，那一個人一定清楚知道是異夢，因為神能他清楚知道。"},{"label":"附篇一 · 超自然的引導","text":"我們不能根據經驗指出異夢一定是在夜間甚麼時間作的，一定是有甚麼顏色的，一定有甚麼感覺的，一定是在日間生活中未見過的，或未想過的::，這一切都不是鑑定異夢的原則，因為聖經沒有這樣說明，而且聖經中作異夢的任何人，在作異夢之前也沒有任何經驗，沒有任何鑑别異夢的原則，似乎只有作異夢的人本身清楚明白這是異夢，因為神使他清楚了，（3）保羅得到異夢之後，根據異夢的內容，他仍不能作最後的決定，認定這是神的旨意要他下馬其頓去傳福音。"},{"label":"附篇一 · 超自然的引導","text":"只是：憑聖經原則來說，下馬其頓去並沒有犯罪，沒有抵觸員理，於是他決定不妨下去看看，所以經文這樣說:「保羅旣看見這異象，我們隨即想要往馬其頓去，『以為『神召我們傳往香給那裏的人聽。」請注意一以為」兩個字，意思是說心中認為為有這個可能性，但要得到最後印証才能斷定。果然，他們來到馬其頓的第一個城腓立比，在這裏建立了一個新約中可以算為最好的教會。"},{"label":"附篇一 · 超自然的引導","text":"但是，這樣的超自然引導就只有這一次，以後保羅仍然用平常的原則去行事，因為他知道在這平常的原則之下行事已經足夠行在神的旨意中，如果真有不夠，這也不是我們的責任，是神的責任了。"},{"label":"附篇一 · 結論","text":"結論\n\n如果讀者明白我在這一章所詳論的，你會領會到，尋求神的旨意不外三個步驟：（1）要運用屬靈的智慧悟性去鑑別所做的事，是否合乎聖經的真理癥誤。"},{"label":"附篇一 · 結論","text":"（2在聖經真理教訓的鑑别之下如果仍不能得到最後的決定，那就可以隨意立志行事（3）如果隨意立志行事神以為是行錯了，神會阻攔或用超自然的方法加以引導，但這不是我們的責任，是神的責任。請問，這麼簡單的三步困難嗎？不！只有那些把神的旨意弄至奥秘莫測的人才感到困難，只有那些不注重真理，只圖追求超自然引導的人才感到困難。"},{"label":"附篇一 · 結論","text":"在他們看來，天父好像常常捉弄他們，要他們行在祂的旨意中但又不讓他們容易明白祂的旨馬仿何。但明白聖經真理的人，知道聖經真理就是神旨意的原則，在這些原則之內，天父願意他的兒女有自由選擇權，正如人間的父母一樣，絕不會事事規定，叫兒女活在家中「步步為營」，失去幸福喜樂。"}]},{"short":"全時間事奉的呼召","terms":["呼召"],"cards":[{"label":"先抓住一個重點","title":"蒙召要清楚","lines":["作者觀察：香港每年有很多神學畢業生，教會卻仍缺傳道人。","他指出有幾個「漏洞」，令傳道人流失。","所以他認為清楚蒙召非常重要。"],"takeaway":"不清楚的呼召，容易半途而廢。"},{"label":"把意思拆開","title":"呼召的反應與原則","lines":["人對呼召有不同反應：有的漸進，有的需要更多印證。","作者列出必有的原則，例如看重人的靈魂比一切寶貴。","另有一些可作「助證」的經歷，但不是每人都必有。"],"takeaway":"先看必有的，再看助證。"},{"label":"讀之前想一想","title":"幾點提醒","lines":["奉獻傳道不等於進入更高的屬靈境界。","作者也為神學院辯護：它是教會的一部分，幫助裝備工人。","這篇較適合正考慮全時間事奉的讀者。"],"takeaway":"事奉是順服，不是身份。"}],"quiz":{"question":"作者認為奉獻做傳道代表甚麼？","options":["是順服呼召，並不等於靈性更高","代表靈性比其他信徒高","是每個信徒都必須走的路"],"answer":0,"hint":"看「幾件鑑戒的事」。","explanation":"作者特別提醒，不要把奉獻傳道看成更高的屬靈階級。"},"key":"ap2","id":11,"no":"附篇二","title":"怎樣清楚蒙召傳道","bookTitle":"怎樣清楚蒙召傳道","part":4,"partName":"專題","partTitle":"第四站　專題","idx":2,"original":[{"label":"附篇二","text":"近年香港平均每年都有百多人神學畢業，但香港的教會和基督教機構每年的增長並沒有全部吸收這百多個傳道人，照理傳道人大有供過於求的現象。可是，奇怪得很，這麼多年以來，許多教會和基督教機構一直在叫喊找不到傳道人來幫助他們，那麼，每年畢業的傳道人到底跑到那裏去呢？"},{"label":"附篇二 · 四個漏洞","text":"四個漏洞\n\n仔細研究之下，我們發現有以下四個「漏」走傳道人的一洞-—-一有一些傳道人以到外國深造為名，但以移民定居外國仿實，每年跑到外國的傳道人多極了。但歐美加一帶的華人教會仍喊叫沒有傳道人。因為許多移民出國的傳道人都轉了行業，聽說單在美國東部就有超過一千名中國傳道牧師在餐館中替人洗碗洗碟，或做其他霉世的工作。"},{"label":"附篇二 · 四個漏洞","text":"我個人以為，就讓他們繼續做一洗碗碟一的工作好了，因為如果讓他們都返回教會做牧養工作，我想教會都變成「餐館」了。\n\n2有許多女傳道結了婚，尤其是與做其他行業的弟兄結了婚，結果婚後被許多家務兒女往累，無法再參與事奉，最少無法再做全時間的女傳道工作～與男傳道結婚的女傳道還可以有機會事奉～。這一種情形非常普遍，因為奉獻做傳道的，姊妹比弟兄多，而且.許多男傳道為了經濟問題，多喜愛與薪金較高的職業女性結婚。與女傳道結婚者，-來薪金低，二來許多教會不肯付「牧師娘」薪金的，只肯稍微加些生活津貼。"},{"label":"附篇二 · 四個漏洞","text":"這一來，女傳道就吃虧了，與男傳道結婚呢！機會少，薪金低；與其他職業弟兄結婚呢！傳道事奉工作沒有了。不結婚呢！未必得人讚賞，有時反而遭人批評為「老處女」，在這許多壓力之下，許多女傳道寧可選一放棄事奉」的途徑了。一3另外還有一個因素是教會要求高，不肯信任剛剛神學畢業出來的傳道人，於是有許多神學畢業出來的傳道人，就只得轉業或出國「謀出路」了。"},{"label":"附篇二 · 四個漏洞","text":"最容易被這一類傳道人接受的職業是教師，因為可以一面傳福音，一面教書賺錢維持生活，但也有不少轉到别的與福音工作毫不相關的行業去。我以為這一點，教會應該負部份的責任。.4最不應該的是那些被邀請到教會事奉的傳道人，他們因人坊遇到了各種答樣的難處，變得心灰意冷，退去不再參與事奉，甚至不信。這樣的傳道人也不少。不錯，有許多教會的難處是絆倒人的。"},{"label":"附篇二 · 四個漏洞","text":"但旣然奉獻為主，就不應該在離開二個工作崗位時。連主也離開了，大可以再找别的事奉崗位。以上四個「洞」漏走了不知多少傳道人，真叫人感到可借。可借不但因為失去了這許多傳道人，同時因為他們從前決定走上這一條奉獻為主的路時，他們所放下的，犧牲的，都白費了。"},{"label":"附篇二 · 四個漏洞","text":"白費了自己多年神學造就的時光，白費了教會和許多愛主的弟兄姊妹對神學院的代禱和經費支持，白費了神學院老師們多年來的心血，白費了神的恩典呼召，阻礙了多少聖工，絆跌了多少靈魂::所以，一個奉獻為主而走不上的傳道人，實在是累已簿人，倘若每一個奉獻為主的傳道人都真的一生為主，今天教會的光景實在得到大大的復興了。"},{"label":"附篇二 · 四個漏洞","text":"當然我這樣說好像給那些決心奉獻的人一撥冷水」，但我以為真正清楚蒙召的人，是一定經得起「冷水品”而肖，這也不單是冷水的問題，同時也是應該切實考慮的問題，只有這樣切實考慮的人才是清楚蒙召的人。不然，將來教會只多了一個害人比救人更多的壞人。我以為要就是不奉獻，如果奉獻了，就一定要淸楚，一生不後悔，一生全心全意為主，一生沒有别二樣的事，只以「新太傳道為事」。然而，我們怎樣才能清楚明白"},{"label":"附篇二 · 人對神呼召的三種反應","text":"人對神呼召的三種反應\n\n神向人發出呼召，但許多時候不同的人有不同的反應。有的立即順服，有的要求更多的証據才肯順服，像基甸一樣，但一般來說，神呼召人和人對呼召的反應有三種：一漸進的這即是由部份時間事奉泗泗變為全時間事奉，當自己在教會或福音工作中參與事奉時，發現自己越來越被神使用，自己也感到越來越有負担，恩賜也越操練越成熟，適合更多更重的事奉，而且需要自己放上的時間也越來越多等等，這許多的因素尊環形成，於是呼召的聲音也弓泗響起來。"},{"label":"附篇二 · 人對神呼召的三種反應","text":"初時可能只抽十分一時間出來事奉，後來變成十分二，進而十分三至十分十奉獻為主，每一個基督徒都當為主而活，都當參與事奉，但並不是每一位基督徒都有負担有能力去作全時間的事奉，所以當一個基督徒要衡量自己應該抽多少時間來參與事奉時，他自然會全面考慮各種因素～即稍後我們將要列出的種種因素～，這些因素也就是神呼召人的因素，問題是他考慮這些因素需要多少時間和證據，"},{"label":"附篇二 · 人對神呼召的三種反應","text":"才能作出清楚蒙召的決定，所以循這一條途徑決定自己清楚蒙召的人，有優點，也有缺點:A、長時間考慮，不會誤把情緒作用當作神的感動，所以十分冷靜，決定得十分清楚。B、漸漸更多參與事奉，對工作有把握，有與超，有成功感。C、在未決定全時間奉獻之前，已經對全時間傳道的生涯有了深入的探索和了解，結果日後不會容易後海。"},{"label":"附篇二 · 人對神呼召的三種反應","text":"A、因為由部份時間事奉變為全時間事奉所需的時間很長，許多時候，等到自己感到需要全時間奉獻時，自己的年紀已經有了相當，失去讀神學的機會，或提不起勁去自修追求，加上家庭經濟的問題，結果走不上，因此不能將自己青年最好的時光獻與主，只能將次好的，或表到的時光獻與主。"},{"label":"附篇二 · 人對神呼召的三種反應","text":"B、因為長時間的考慮，養成事事要求自己認為最有把握才肯作出決定的習慣，結果學不會毅然決定的信心功課，工作因而推展慢，果敢繳蔚的精神也弱，這種態度比較難應付危機急事，也不容易担負重大的工作。"},{"label":"附篇二 · 人對神呼召的三種反應","text":"C、可能教會的事奉機會不多，而參與事奉的人也不少，結果使自己由部份時間轉變為全時間事奉的機會也少，所以由這樣途徑清楚蒙召的人也少，或者可以說神比較少用這種方法來呼召人，因為在「莊稼多，作工的人少一煦情形下，禮實在不可能慢漫等那些人由部分時間事奉轉變為全時間事奉了。2突進的「—即在一時間得到特殊的感動或異象而毅然獻身全時間為主的。如上文所指，神為了工場的急需，許多時候會用這種突進的呼召方法來呼召人。"},{"label":"附篇二 · 人對神呼召的三種反應","text":"例如在夏令會或其他的聚會中，神藉一個信息，一個貝”，一個事實等使人有突然的感動，這樣的感動可以分為兩種，一種是自然的，另一種是超自然的。超自然的是看見神蹟異象，如保羅在大馬色路上的經歷，又如中國的席勝魔(參看席勝魔傳～，印度的孫大信～參看印度聖徒孫大信一書～等。"},{"label":"附篇二 · 人對神呼召的三種反應","text":"可是，得這種超自然感動的人萬中無一，只有神認為在特珠環境，特需要，特人物，特使命之下，神才會揉玫這樣的呼召方法，所以我們不應强求神賜給我們這一類的感動。"},{"label":"附篇二 · 人對神呼召的三種反應","text":"强求的人多是出於不信，不順服，不信不順服的人神不會使用的。但另一種自然的感動稱為廣義的異象～一種由感動變成的思想景象～，就是我們應該有的。這種感動異象我們稍後再討論。但在這裏我也要澄淸一點，從這條突進途徑清楚神的呼召的人，也有優點和缺點，要明白這些優點和缺點，只要把上文論漸進的一途徑的優點和缺點反轉過思想來就清楚了，所以我不再在此詳論。"},{"label":"附篇二 · 人對神呼召的三種反應","text":"_3漸進而突進—我以為最有把握的途徑是初時部份時間參與事奉，到轉為更多時圓參與事奉時，即由十分“時間轉到十分三四或五時間事奉時，突然受感動立刻進入全時間事奉。這即是說，將上述兩條途徑合併為一條途徑，取兩者之長，而捨兩者之短，這就理想了。不過，我雖然這樣說，但我並没有表示依從上述兩種途徑清楚蒙召的人有甚麼不對的地方。神喜歡用甚麼方法來呼召人，這是神自己決定的，我們沒有資格批評。"},{"label":"附篇二 · 人對神呼召的三種反應","text":"我們在這裏所指出的，只是在人考慮的方面。如果人認為他需要漸進的明白神的呼召，他也應當明白，他這樣認為會有上述的優點和缺圖，加果人認為他是突進的明白神的呼召，他也應當知道，他這樣的認為也有上述反面的優點和鍋黑。但如果人認焦禮呼召他是漸進而突進的，他這樣的考慮會是比較更有把握清楚是神的呼召，免去上述的缺點或危機。\n\n所以，通常來說，循這條途徑淸楚神的呼召的人比較多。"},{"label":"附篇二 · 清楚蒙召必有的幾點","text":"清楚蒙召必有的幾點\n\n無論你認為自己淸楚蒙召是屬於上述那一種也好，清楚蒙召的原則還是相同的，首先讓我列出幾點必有的原則供讀者參考，如果讀者發現自己缺少了其中的任何一個原則的話，那就是說，你一定不是蒙神呼召作全時間傳道的。1人的靈魂比地上一切的都寶貴—傳道人若不是傳救人需魂的，盐不是傳道人。"},{"label":"附篇二 · 清楚蒙召必有的幾點","text":"傳道人若不了解主耶穌愛人靈魂的心腸，甚至補願意放下天上的榮耀，降世擒命，他根本就未了解差他去傳道的是誰。加果了解的話，既然差他的主也認為人的靈魂寶貴到一個地步，甚至冗可以捨命來拯救，那麼受差的人怎能不看重人的靈魂，反看面世界？了解主的心腸，事奉才有熱心了解人靈魂的價值，工作才有準確的對象。了解主入人捨命，自己才會將生命獻上。"},{"label":"附篇二 · 清楚蒙召必有的幾點","text":"我們在上閻指出許多傳道人漏走了，原因就是他們不以人的靈魂比地上一切的都寶貴。不是他們不仆人的靈魂，只是他們愛地上其他的比及人的靈魂多一點，於是就漏走到世界去，像底馬一樣。我再說，不錯，傳道人在教會中遇到叫人灰心的事實在太多了，有時中感到十分同情漏走的人。"},{"label":"附篇二 · 清楚蒙召必有的幾點","text":"但如果他們熱心到一個地步，愛人的靈魂勝過仿自己的生命，像主愛人靈現一樣，他們就必勝過和教會任何的困難，像主勝過一切困難仍然不退去一樣。\n\n今天衝會不是缺乏傳道人，而是缺乏有熱心，肯吸禾一切為主，有屬圳能力的傳道人。所以我勸勉那些還未考慮清楚，還未認為人的靈魂頁的比地上一切都寶貴，比自己地上的生命都寶貴的人，不要走這一條全時間的路。但相反，我歡鮑那些真認識人的靈魂比地上一切都寶貴的人，棄然你已經尋到最寶貴的，就應該感到快樂，應該欣然放下一切奉獻給主。"},{"label":"附篇二 · 清楚蒙召必有的幾點","text":"一個頁蒙召的人，他可以了解到走上這條路需要付許多代價，必會遇見許多困難，甚至需要捨命，這一切他都考慮清楚，但他發現有一個莫大的力量，莫大的寶貝，莫大的好處吸引著他，這個吸引，大大勝過所有地上的吸引力，勝過一切難處的阻力，使他毅然前進，這個吸引力，就是人靈魂的寶貴價值和主耶穌自己。"},{"label":"附篇二 · 清楚蒙召必有的幾點","text":"所以，我在前文說，真清楚蒙召的人不怕一撥冷水」，因為他愛主愛人靈魂的心實在太熱了。這熱是由於聖靈的火在內焚燒，地上一切的「冷水」休想可以、2傳道是我人生之大任—神要每一個基督徒都傳福音，但神並不是要每個基督徒都全時間傳福音。"},{"label":"附篇二 · 清楚蒙召必有的幾點","text":"每一個基督徒都當以傳篇理為正業，其他的職業為副業。但有感動奉獻全時間傳道的人，他再沒有副業，在他來說，一生只有一個任務，就是傳主的福音牧養教會，或其他與福音有關的工作。當然有人會提到保羅也有織帳棚的職業，於是就認為傳道人也可以有副業。"},{"label":"附篇二 · 清楚蒙召必有的幾點","text":"但是要知道，保羅織帳棚是在他沒有得到經濟支持的時候，而且又在不影響福音工作的情况下才織帳棚的，甚麼時候得到供應，甚麼時候他受感動要到別處傳福特；織帳楓的工作就立刻放下來了。"},{"label":"附篇二 · 清楚蒙召必有的幾點","text":"可是今天許多傳道人有副業並不如此，他們為求經濟更富裕，甚至為副業而放下傳道的正業，這些人不是蒙召傳道的。傳道人旣然清楚神的呼召，就該以傳道為自己一生的大任，任何事物不能分自己的心。只有這樣專心的人才能將自己全部的精力，時間、心思，感情，生命獻上為主，傳道事工才能成功。"},{"label":"附篇二 · 清楚蒙召必有的幾點","text":"所以，考慮自己是否清楚蒙召的人，要衡量自己是否能夠以傳道工作作為自己一生的任務，若不是主的意思，若不是必要如此，一生不轉業，將自己一切的力量投上去為傳道。當然，立這樣志願的人，並不單是為「不這樣行就有禍」，同時也是為一這樣行就有賞賜」。不是逼自己以傳道為專業，而是為屬天的一切好處而歡喜以傳道為專業。"},{"label":"附篇二 · 清楚蒙召必有的幾點","text":"不是苦着口面的說:「神捉我來傳道」，而是十分羨慕的對主說:「主啊！我在這裏，請差遣我。」我樂意以傳道為我一生的大任，因為這是最尊貴，最上算，最有價值，最榮耀的任務。"},{"label":"附篇二 · 清楚蒙召必有的幾點","text":"，靈魂體的決定「—對神呼召的真清楚，應是「全人」的清楚。就是靈，魂，體的清楚，在靈更清來，是因為得到真理異象的感勒。這異象有分超自然的異象，和自然的，即因受真理感動而在腦海中浮現出來的異象兩種，這兩種都是靈的感受。"},{"label":"附篇二 · 清楚蒙召必有的幾點","text":"前文說過超自然的異象並不是每一個人都有，但自然的，因受真理感動而浮現出來的異象就應該是每一個清楚蒙耕的人都有，例如有一次主耶穌退到曠野去歇息，但祂看見許多來就祂的人，如同羊沒有牧人一般，於是就開口教訓他們許多道理。"},{"label":"附篇二 · 清楚蒙召必有的幾點","text":"請注意，主看見的是人，但他卻想像出是羊沒有牧人，這就是自然的異象。又一次主對門徒說，一擧目向田觀看，要收的莊稼多，作工的人少:::」主所指的田是世界，莊稼是人的靈魂，所以主要門徒看的也是一個自然的異象。"},{"label":"附篇二 · 清楚蒙召必有的幾點","text":"有人煮飯，看見火爐像地獄，因而掀起搶救人靈魂的熱心；印度的亞力山大打夫，想到萬王之王招慕軍兵去印度救人的異象，有人讀以賽亞書第六章，好像聽見主直接對他說:「我可以差遣誰呢？"},{"label":"附篇二 · 清楚蒙召必有的幾點","text":"誰肯為我們去呢？」，他就回答說:我在這裏，請差貴我。」有人在街上看見許多人走路，就想到他們都是瞎眼的，向死亡的陷坑走去而不自知。總之，蒙召的人必有異象，或是人靈魂的異象，或是神榮美的異象，或是天上的異象，或是地獄的異象，如果他真的愛人的靈魂，真的愛主，真的明白所傳的是天國救人的福特，這些真理在他裏面感動他到一個決定奉獻的地步，是不可能不產生自然的異象的。"},{"label":"附篇二 · 清楚蒙召必有的幾點","text":"這些異象在他心中很難磨滅，一直感動他，因為感動他的真理在異象中具體化了，感動就越大，直到他決定奉獻為止。魂的決定就是感情意志的決定。為了人寶貴的靈魂，為了可愛的主，決定放下一切走上這條奉獻的道路，這樣的決定真是人生之中最大的決定，任何人在作出這樣重大的决定之前，他一定在意志上衡量清楚，也一定產生情緒波動。"},{"label":"附篇二 · 清楚蒙召必有的幾點","text":"他不可能單在意志上衡量化算不化算，而無喜怒哀樂的情緒產生，他也不可能只有情緒的激動，而無意志方面的衡量。兩種情况都是不可靠的，太理智的人根本就未會愛人的靈魂，也未愛主，那裏有愛是純理智而沒有感情的呢丝只有情緒激動而沒有用理智想清楚自己為何要這樣做的人，也是胡塗人，他怎能傳講說服人的道理呢？"},{"label":"附篇二 · 清楚蒙召必有的幾點","text":"青年人多偏向理智而排斥情緒作用，這是錯的，因為情緒是神賜給人的，情緒的產生是感情自然的流露，流露出情緒的理智決定才是真誠的決定，一員一是理智，「誠」是情緒，所以，真正清楚神的呼召是有理智有情穎的。"},{"label":"附篇二 · 清楚蒙召必有的幾點","text":"體的決定就是行動的決定，一個清楚蒙召的人就是有行動表現的人，既然清楚蒙召’他必定生活像傳道人，衣飾像傳道人，起居飲食像傳道人，動作禮貌像傳道人，靈修讀經像傳道人，傳福音像傳道人，即使他仍在中學或大學裏讀書，他也是坊著要做傳道而讀書，當然，他的一切表現不可能立刻就百分之百像一個忠心事主的傳道人，但無論如何他一定會常常鼓勵自己，朝着做傳道人的方向去充實自己，裝備自己。"},{"label":"附篇二 · 清楚蒙召必有的幾點","text":"不少人誤會了蒙召做傳道人是神學畢業出來在教會裏工作才算是做傳道人，不，那只不過是受過訓練的傳道人，如果你還在學校裏讀書，你就是帶學業的傳道人，如果你仍在社會工作，等候神學院開學才進去就讀，這樣你就是帶職業的傳道人，在神學院裏受訓是正在受訓的傳道人，我們在甚麼時候開始清楚蒙召，就在甚麼時候開始作傳道人，旣然清楚了，旣然開始了，就應該有實際行動表現，等到我們真的有行動表現之時，我們才是真正淸楚之時"},{"label":"附篇二 · 清楚蒙召的幾點助證","text":"清楚蒙召的幾點助證\n\n以上的幾點是清楚蒙召必有的原則，但除了那幾點必有的原則之外，還有幾點可能不是每一個人必有的，但是這幾點也可以作為助證。"},{"label":"附篇二 · 清楚蒙召的幾點助證","text":"1有適合傳道的恩賜—通常來說，神呼召我們傳道之前，已經賜給我們一些適合做傳道的恩賜，使我們可以明白神真的喜歡用我們。這些恩賜可能是我們的口才，領袖才，學間，理解力，音樂技能等等。"},{"label":"附篇二 · 清楚蒙召的幾點助證","text":"恩賜不一定是突然出奇地有的，恩賜通常都是潤計操練出來的，我們不能勉强神一定要用突然出奇的方法賜我們恩賜，我們也應該相信神可以喝我們能力泗泗的操練出各樣的恩賜來，正如我們信嗎哪是神所賜，但我們也信五穀是神所賜的一樣。"},{"label":"附篇二 · 清楚蒙召的幾點助證","text":"所以，我們是否淸楚是神的呼召，有時也可以看看自己有没有適合做傳道的恩賜，作為一個助證，不錯，有不少傳道人在奉獻之前沒有口才，等到奉獻之後，神賜他口才，但我們要注意，他未奉獻之前也有其他方面適合做傳道的恩賜，即使沒有，也有操練恩賜的潛力和可能性，完全没有可能性和潛力的例子很少很少，所謂可能性和潛力，可能就是他的堅强信心，信得過神會用他，給他恩賜，而且自己也願意付任何代價去操練，再加上他的天資聰明，他的毅力，他的年齡和身體健康等等。\n\n他也可以決定自己將來會適合做一個傳道人。"},{"label":"附篇二 · 清楚蒙召的幾點助證","text":"，2寶習時有印證—在考慮全時間事奉的人，最好多一些實習事奉，一方面看看自己的恩賜是否適合，二方面看看神有沒有賜下印證，如果神賜下印證，實習的人一定會發現自己越來越有感動負担，傳道的崗位也越來越需要自己，事奉也越來越快樂，人生觀也新翊轉向主，轉向屬天的事，有時成功感也可以作為一種助證，有時發現神特别賜福給自己所負責的型工，有時發現自己的生活人事環境泗謂改變，使自己更適合做傳道，有時發現自己身體的健康好轉，家庭經濟好轉等等。"},{"label":"附篇二 · 清楚蒙召的幾點助證","text":"不過，這一切只可以作為助證。因為許多時候我們未必有這些，一方面是因為魔鬼要攻擊我們，一方面是因為我們仍未有好好的訓練，所以事奉未必有成功感等等。但無論事情或順或逆，在研究其原因之後，最低限度這一點也可以拿來作為助證。"},{"label":"附篇二 · 清楚蒙召的幾點助證","text":"3肯獨立追求—許多奉獻自己作全時間傳道的，尤其是在夏令會的獻心會中奉獻的，常被人認為是出於一種軍眾心理作用所驅使，不是真正的聽到神的呼召，為此，在一些比較注重理性的青年基督徒中，他們表示極之反對這種獻心會，或呼召人奉獻作傳道的聚會。"},{"label":"附篇二 · 清楚蒙召的幾點助證","text":"我個人認為這是兩個極端的問題:一方面，我們確實應該防避人為的踢眾心理作用，以免與神的呼召相視消；另一方面，我們也不要過份排氛蛋眾心理作用，以免我們跑到另一極端，以為聖靈不可能在聚會的熱烈氣氛中感動人，其實任何心理作用，包括玲眾心理作用，如果出自自然的反應流露，那是寶貴的，正如主耶穌在拉撒路的壩墓前，看見猶太人哭，祂就哭了。"},{"label":"附篇二 · 清楚蒙召的幾點助證","text":"這是一種自然流露出來的心理反應，是十分寶貴的，結果猶太人就說:「你看祂愛這人是何等懇切。一八約十一36~如果主耶穌是只注重理性，不注重感情的話，祂必不會哭，同時也會吩咐猶太人和馬利亞不要哭，因坊冗知道等一會兒拉撒路要復活了。我們要防避的不是出於自然反應的心理作用，我們要防避的只是人為的右人企圖利用心理作用以達成某種目的。"},{"label":"附篇二 · 清楚蒙召的幾點助證","text":"例加一些教會在聚會時大喊大，大力拍掌，吹號打鼓，跳舞輥動，造成一種激動的場面氣氛，他們就說是聖靈充滿，其實只是人為的心理作用，叫人感受到興奮，熱烈，激動，誤以為是愛主的熱誠，喜樂，一個人如果在這樣的氣氛之下決定奉獻作傳道，就危險了，但以我為，一般夏令會的獻心會並不至這樣，如果分明有一個信息，一個真理，進入自己心中叫自己產生感動的話，那感動就是真的感動了。"},{"label":"附篇二 · 清楚蒙召的幾點助證","text":"但是，有人以為真感動是有的，只是在夏令會的獻心會之中，分不出真感動的成份高，還是因氣氛而產生的心理作用的成份高。對於這一個問題，倒不難解決，一個得到苴感動而清楚蒙召作傳道的人，他不但在聚會中樂意奉獻，樂意傳往百。他也一定在單獨一個人時，嫩粉館水，樂意追求，樂疙傳喜。"},{"label":"附篇二 · 清楚蒙召的幾點助證","text":"如果他說清楚蒙，又在整體下鄉佈道的工作中～或類似集體性的福音工作中～熱心參與，這還不明顯他是淸楚蒙召，他還須要看看自己在單獨與人相處時，是否仍然有傳福音的熱誠，才能證明細對佈的呼召，因為能單獨傳往理的，就擺脫了任何下眾心理的影響了。"},{"label":"附篇二 · 清楚蒙召的幾點助證","text":"不但這樣，真正清楚蒙召傳道的人，不但在教會的聚會中顯出他追求的熱誠，同時也在家中，學校中，個人獨處的時候顯出追求的熱誠，這就是說，他一定有好的靈修生活。十分喜愛讀屬靈書籍和聖經，甚至他留心到生活裏每一件細節都是為裝備自己做一個好傳道，這樣喜愛獨立追求的生活，是蒙召傳道者一個很好的助證。"},{"label":"附篇二 · 清楚蒙召的幾點助證","text":"當然助證還有許多，例如經濟方面的，健康方面的，父母家庭方面的，心靈感受方面的，異夢神蹟方面的(一般來說這些很少有，即使有，也多在助證方面有用，不能作為主要的證明～，職業前途方面的，教會需要方面等等。但較常有的助證，我想就是以上這三樣了。"},{"label":"附篇二 · 幾件鑑戒的事","text":"幾件鑑戒的事\n\n”清楚神呼召的原則並助證我們已經說過了，但我以為有幾點作為鑑戒的事值得在這裏提醒一下的，就是—一奉獻做傳道並不是進入靈性更高的境界：某：心會中，常見有三種獻心，第一種是清楚得救，第二種是為主而活，第三種是奉獻傳道。"},{"label":"附篇二 · 幾件鑑戒的事","text":"當然第一種清楚得救是靈性的最初步，是最基本膚淺的；第二種為主而活是靈性較高的境界，因為表示願意無論是生是死，都叫基督在自己身上照常顯大；可是第三種奉獻傳道就並不表示自己進入更高的靈性境界，因為這不是每一個人所能做到的，只是神自己特別揀選誰，誰才需要奉獻傳道，靈性最高的境界在為主而活的階段中已經達到了，問題就是你是否完全為主而活，越多或越完全為主而活，靈性就越高，靈性越高的人，神未必要他做傳道人。"},{"label":"附篇二 · 幾件鑑戒的事","text":"相反，做傳道人的也未必是靈性高超的人。如果有人誤會了這一點，在夏令會的獻心會中，以為自己去年已經奉獻為主而活，今年應該要進一步奉獻傳道，這就錯了。"},{"label":"附篇二 · 幾件鑑戒的事","text":"又如果日子久，靈歷深的弟兄姊妹，看見日子較自己淺，靈歷也較自己淺的弟兄姊妹奉獻作傳道，因而感到自己不及他們，他們後來的「居上」了，這也是錯的，不可為勉勵自己靈性進深而勉强自己奉獻作全時間的傳道人，奉獻傳道固然要有好靈性，但奉獻傳道與靈性更進深是毫無關係的。"},{"label":"附篇二 · 幾件鑑戒的事","text":"2不要以為神揀選一個人做傳道，他怎麼也逃避不了的:許多人有了這一個思想，就放心逃避神，甚至利用逃避來找一個助證，看看神是否終於把他一捉一回來。如果神真的把他捉回來，那就真的是神呼召他了，如果神不捉他回來，那麼，逃避倒是對的。但那些認為神終於把他捉回來，逼他走上奉獻傳道的人，就苦着臉說:「我原不想做傳道的，只是神把我捉來做傳道吧了。"},{"label":"附篇二 · 幾件鑑戒的事","text":"」這種人到頭來還是做不成傳道，因為他不看重這職份，也可能誤會了祝「提」他的手段。另一方面，那些放心逃避的人，就因此失去了神呼召他用他的福份。要知道，神揀選人做傳道，這是恩典，是大福，因為我們的職份比世上的君王還高！"},{"label":"附篇二 · 幾件鑑戒的事","text":"事實上，神呼召一個人，若他不肯，神會不用他，不再呼召他的，或許我們聽過一些見證故事，說某某人年輕時神呼召他，他一直逃避，十分痛苦，後來再受神責備管教，終於就乖乖的奉獻了。請注悶，這樣的例證只是說神會這樣做過，但沒有說神對待每一個人都是這樣做，換言之，這只是一個特的例證，決不是一個「規例」。正如神呼召約拿傳道是一個特殊的例子，除約拿之外，再沒有這樣的例子了。"},{"label":"附篇二 · 幾件鑑戒的事","text":"神喜歡用你，但禮不能強要用你，決定的自由永遠是屬你的，不用你的自由也永遠是屬神的，我們豈不是看見許多被神丢在一旁用不着的傳道人嗎？\n\n神用我們，許多時候就是因為我們喜歡被使用，如果我們存着一個歡喜破禮使用的心，又專心尋求神的旨意，神一定會用得着我們，縱使不是用我們作全時間的傳道人，也會用我們在某一方面，叫我們的生命過得更有意義和價值。"},{"label":"附篇二 · 幾件鑑戒的事","text":"3如果後來及時發現自己的蒙召是會錯意的話，不要為「收回」奉獻而感到自丫:主然蒙召傳道是照神的旨意奉獻，照樣發現對神的呼召會錯意，並因而收回奉獻也一樣是神的旨意。"},{"label":"附篇二 · 幾件鑑戒的事","text":"能勇於行神的旨意是對的，是神所喜悅的。不是自己不願意奉獻，而是在神的計劃中，神不要自己作全時間的傳道人。旣然這樣，責任不在我們，是在神，如果感到收回奉獻是羞恥的話，那極其量亦只是當初誤會了的董也，決不是變節或不順服神的羞恥。"},{"label":"附篇二 · 幾件鑑戒的事","text":"可是，我見過不少人在夏令會奉獻傳道，後來雖然發現自己是弄錯了，他還是不敢收回，結果產生兩種可悲的後果，一是勉强走上去，痛苦一生；二是退去了，連聚會也停止了，因為無面目見教會的弟兄姊妹，甚至有的因此而離開主，多可憐。\n\n其實淸楚蒙召而走上去，與清楚自己弄錯而收回，兩者都是行在神的旨意中"},{"label":"附篇二 · 神學造就","text":"神學造就\n\n有些人反對入神學院受造就，理由是:接真理，應該是教會產生工人，不是神學院產生工人。我們的答案是:神學院就是教會的一部份，所以神學院產生工人也就等於教會產生工人。正如聖經印刷，按真理應該由教會負責，不應由任何出版社負責，但我相信沒有任何地方教會可能有力量或有需要自己印製聖經。"},{"label":"附篇二 · 神學造就","text":"=r延，倘若我們承認真教會只有一個，就是全世界各地真正信主的基督徒，這樣，不單神學院，屬靈書籍的出版社，甚至許多基督教的其他工作機構，都是屬於教會的。况且，大而强的教會可能有力量自己造就工人起來全時間事奉，小而弱的教會就不能了。"},{"label":"附篇二 · 神學造就","text":"在神的計劃齊，禮學院的存在是替許多不能自己產生工人的教會預備工人，這一點是不能抹煞的事實，即使是那些有能力自己產生工人的教會，有時為了專心受造就，為了全面受造就，為了得到更多神僕人的教導，為了避免偏激狗容，他們也發現讓有心志的弟兄姊妹進入神學院受造就是最適宜不過的。"},{"label":"附篇二 · 神學造就","text":"只有一些年紀太大，有家庭負果，在學歷和其他各方面都不適宜進神學院受訓的人，才應該留在教會中學習配搭事奉，從而慢慢長進成為全時間的傳道人。但那些清楚神的呼召，又有機會入神學院受造就的，如果不入神學院受造就，反而引一些帶職業事奉的，或一些不入神學院而自己追求成功的傳道人為例，故意走帶職事奉，或自己獨立追求的路，這就錯了。"},{"label":"附篇二 · 神學造就","text":"錯是錯在他對讀神學的誤解，甚至許多時候是因為他想要為自己保留一條通往世界的路，美其名是帶職事奉，其實他自己明白是愛屬世的職業多過或許有人認為，他不肯入神學院的原因是因為找不到一間適合他的神學院。"},{"label":"附篇二 · 神學造就","text":"我想，如果這真是他心底裏的理由的話，這倒是一個很好的理由。是的，找不到一間適合自己的神學院，就不要入好了。因為已經有不少人誤入了一些不信神的學院，結果自己也變或不信。有人指出讀神學的第一年是熱的，第二年暖，第三年冷，第四年就死了。因為他入錯了「神學」的院，沒有找到「神的」學院。所以，清楚蒙召的弟兄姊妹不可不注意，你還該求問神應該選那一間神學院受造就？"},{"label":"附篇二 · 神學造就","text":"有的禮學院有十分濃厚宗派的色彩，你若不是蒙召去事奉那一個宗派，尤其是連你自己也不屬那一個宗派，那你就應該不入那一間神學院。\n\n有的神學院十分注重學術研究，以訓練護士，或專門學者為目標，如果你蒙召是為開荒佈道，或為一般傳道牧養工作，你就不該入那一間神學院。有的神學院十分注重神醫方面等靈恩，如果你沒有這方面的恩賜，那你就不應該進那一間神學院，免得你接受了不認識的靈。總而言之，你蒙召的時候是為那一方面的需要，你才進入那一類的祝學院。"},{"label":"附篇二 · 神學造就","text":"倘若你還不清楚神將來會特别用你在那一方面事奉祂的話，這也不要緊，因為許多時候神要在你操練得到某一方面的恩賜之後，才指示你特别的工作崗位。不過，你還不能不思想淸楚這世代的教會特别缺少甚麼，自己對那一方面特别有負担？"},{"label":"附篇二 · 神學造就","text":"依我個人的觀察，今世代的教會並不缺少有學術研究的傳道人(不是不需要，只是不缺少～，不缺少神學博士，不缺少行政策劃的人才，不缺少原文學者，不缺少宗派領導人。"},{"label":"附篇二 · 神學造就","text":"今世代所缺少的是有豐盛生命能力的傳道人；缺少犧牲為主熱心人救靈魂的傳道人，缺少會講純粹聖經真道，有靈命供應的傳道人；缺少真正走信心路線，靠神多過靠人的傳道人；缺少注重靈修生活，不沾世俗的傳道人。今天，許多有志奉獻傳道的弟兄姊妹應當以這些為追求的目標，留心神賜福那一間神學院受訓出來的傳道人{這樣才能找到適合的禮學院，偽神合用的工人。"}]},{"short":"作者對方言運動的研究","terms":["聖靈充滿","方言","靈恩派"],"cards":[{"label":"先抓住一個重點","title":"這是全書最長、最具爭議的一篇","lines":["作者回應當時盛行的方言運動。","他列出新約所有提到方言的經文，逐段研究。","這是作者的神學立場；不同教會可能有不同看法。"],"takeaway":"先理解作者的論證，再自己判斷。"},{"label":"把意思拆開","title":"聖靈與聖靈充滿","lines":["作者說：每個真信主的人都有聖靈內住。","聖靈充滿不在乎特別現象，而是被真理充滿、遵行真理。","只要除去罪、真心愛主事奉主，聖靈就會充滿。"],"takeaway":"看真理和生命，不看現象。"},{"label":"把意思拆開","title":"作者對方言的看法","lines":["他認為使徒行傳的方言多是給不信的猶太人作憑據。","從林前十二至十四章，他看方言只是眾多恩賜之一，愛最重要。","他列出十個條件，認為今天的方言大多不符合。"],"takeaway":"讀時分清：經文、作者解釋、你自己的看法。"}],"quiz":{"question":"作者怎樣理解「被聖靈充滿」？","options":["被真理充滿，明白並遵行真理","一定要說方言","一定要有激動的感受"],"answer":0,"hint":"看「自稱聖靈充滿是謙卑」那一節的開頭。","explanation":"作者說最要緊的是真理，其他現象有無也不要緊。"},"key":"ap4","id":12,"no":"附篇四","title":"聖靈與「方言」","bookTitle":"聖靈與「方言」","part":4,"partName":"專題","partTitle":"第四站　專題","idx":3,"original":[{"label":"附篇四","text":"今天世界上許多地方，連歐美也包括在內，十分盛行「方言」運動。甚至有不少純正信仰的神的僕人也有說方言的經騐。可能正因為這些同磁祖重用的神的僕人們也有方言的經騐，所以千千萬萬基督徒也就放心去接受方言的靈了。或問，為甚麼苯祖的僕人們也會接受方言的靈呢？我以為有幾個明顯的理由促成—一聖經時代的確有方言這回事。\n\n二很難找到確實的理由說今天一定沒有真正的方言恩賜。"},{"label":"附篇四","text":"三大家都怕太過極端，因為排斥方言的緣故，結果可能雁瀆了聖靈。四不少提倡方言的教會實在有復興的現象。五方言恩賜和其他異能恩賜是最有力排斥新神學思想的明証。六有方言恩賜的人十分强調他們與神有甜蜜的交通，差不多對樣樣聖工都有禪盆，叫靈性低沉的人十分羨慕。面對這些問題，差不多任何不存偏見的人都會傾向方言。就我自己思想這些問題來說，我承認會經在我心靈問插起了很大的傾向。"},{"label":"附篇四","text":"只是當我認定聖靈是稱為二真理」的聖靈，只有憑真理才能分辦出今天的方言是否出自聖靈，不能憑「現象」或「經驗」來分辨時，我發現我總無法接受今天的方言。本來有關方言的辨别不太適宜在這本書內舌論，但因為今天的基督徒實在缺乏美好的靈修生使而方言運動差不多把真正美好的靈修完全歸在用方言禱告的經騐上，所以我實在不能不在此糾正一下"},{"label":"附篇四 · 六點回答","text":"六點回答\n\n在撩誕的開始，自然我們不能不先對上述所提出六大點作一個正面的回答，因為那正是困擾不少信徒心靈的問題。\n\n上我們也承認聖經時代的確有方言這回事。但聖經時代有的事，不一定每一個時代都有。例如聖經時代有使徒的職份恩賜，現今卻沒有；聖經時代有神的靈啓示人寫聖經，現今也沒有。仔細研究聖經的歷史，我們發現由亞當至以色列人入埃及，都沒有普遍出現神蹟的現象，因為神造天地時，看一切所造的都甚好，這表示神的原本計劃是喜歡人在自然律之下生活的。"},{"label":"附篇四 · 六點回答","text":"到了以色列人出埃及時，因為一個新的時代開始了，又因為以色列人早已忘記他們祖先的神了，所以神要藉摩西在埃及和在曠野期間，普遍施行神蹟奇事，要叫埃及人和以色列人認識神。但到了入迦南的時候，神蹟就沁湳減少了。初時攻打耶利哥城還有大神蹟幫助他們，但以後涌詞的再沒有神蹟，沒有嗎哪，沒有雲柱火柱。這是因為神喜歡以色列人潤詞返回自然律之下生活，超自然的神蹟只有超常的時期才需要應用。"},{"label":"附篇四 · 六點回答","text":"然後一直到了以利亞和以利沙的時代，神又再一次藉這兩位先知普遍地施行神蹟，一則因為以色列人都轉向巴力～只剩七千暗地裏信仰神的以色列人未向巴力屈膝～；二則因為先知時代開始了，所有的先知書都是以利亞之後寫成的。但神在這時代的開始只藉以利亞和以利沙兩位先知大行神蹟，以後神卻喜歡返回自然律之下，藉衆先知用真理勸勉警戒他們，不太多用神蹟來引導他們。"},{"label":"附篇四 · 六點回答","text":"這樣又一直來到主耶穌的時代，以色列人長時期生活在自然律之下。主耶穌來了，新約時代開始了，所以神又再藉主耶穌和衆使徒大行神蹟奇事。但這種情形維持不久，即使在使徒行傳之內，我們也清楚的看見神蹟一連同方言在內～漸漸減少，因為有真理聖經代替了。"},{"label":"附篇四 · 六點回答","text":"研究教會歷史的人都看見，從初期教會以後一直到如今，神都是以真理來引導人，來造就人，神蹟減少到幾近零的地步，因為聖靈是真理的聖袁，禮始終喜歡人生活在自然律之下。從前一些傳道人喜歡指出，彼得之所以會用神蹟醫病，因為「金銀他都沒有一一徒三6～，今天的傳道人和教會之所以不能用神蹟醫病，是因為有了「金和銀」，這句話顯然是錯誤的。"},{"label":"附篇四 · 六點回答","text":"當日保羅也因病才到加拉太教會傳道，他也勸勉有胃病的提摩太可以稍微用點酒，而且保羅王生有路加醫生跟著他，但保羅並沒有用神蹟自醫和醫提摩太，也沒有勸路加轉業或指責他做醫生不對。很明顯的，聖經並沒半句說明，神蹟和方言是永遠常存的。反之，歷史証明了神喜歡我們生活在自然律之下。"},{"label":"附篇四 · 六點回答","text":"2不錯，我們不能找到確實的理由說今天一定沒有真正的方言恩賜，但我們要反過來問，我們又何嘗試找到確實的理由說今天一定有真正的方言恩賜？看歷史我們知道這運動是起於一九〇六年。"},{"label":"附篇四 · 六點回答","text":"(本來一九〇一年已開始了，但到了一九〇六年在美國洛棚礙那裏掀起巨潮一這運動之前，我們看不見方言在歷史上有-正常」的出現。但以後，我們就看見普遍的出現。初期的靈恩派大叫大嗷，趣地拍掌，又哭又笑，完全沒有秩序，簡直認損得像地獄，那時許多人都看見這運動違背了聖經，大加攻擊反對。"},{"label":"附篇四 · 六點回答","text":"後來產生新靈恩運動出來就比較安靜，而且不像以前的激烈，思想也較有接近聖經原則，於是以前反對的人就轉過來加以支持了。但我們要指出，方言恩賜的流行始終出自早期的靈恩運動，那運動旣是錯謬的，那-靈」豈會是真的？贊成方言的人喜歡指出，從前司布員，慕迪，宋從節等神的僕人都是零金委靈恩」的人。請留意他們的用詞。「靈恩」未必包括方言。"},{"label":"附篇四 · 六點回答","text":"不錯這些神的僕人們都會被聖靈充滿，但他們卻沒有[方言」的恩賜。如果按上一點所提出的原則來看，神在一個特殊的時代開始之時會施行神蹟奇事。\n\n請問，今天方言的流行又是甚麼特殊時代的開始？如果說是主快要再來之前的時代開始，那是不對的。因為主再來的日子沒有人能明確的指出一個開始，任何清楚劃出主再來的日子的理論都是錯的。我們可以說主的日子很近，但不可以說現在就是，或說現在就是一個真正的開始。再返回來說，既然長期以來神都沒有賜下方言恩賜，我們是不必找理由去証明今天沒有真正方言恩賜的。"},{"label":"附篇四 · 六點回答","text":"只有當方言運動出現時，我們才有責任去找理由証明那是，3因指斥方言運動可能出自邪靈而產生「犯了藜瀆聖靈的罪」的惡帆感，這是一個非常利害牢籠人心的關鍵，叫接受了方言的人，不能去試騐那靈，不敢去懷疑，不敢去作反的思想，我自己有二個時期思想這一類的問題時，心裏被這種恐懼感纏得十分苦。"},{"label":"附篇四 · 六點回答","text":"在真理上我不接受它，但在感情上，我卻像被控制着想要去接受它，尤其是每每提醒白己會否想錯時，更叫自己的惡卍加強。\n\n不過我始終抓緊真理不放，終於真理使我得到自由。後來有機會與一位屬靈的長輩交通，他給我指出—如果說方言可能出於”邪靈就是雁漬聖靈，那麼如果方言真的出於邪靈，而你卻說是出於聖靈，這豈不也是褻凟聖靈嗎？真的，在未清楚方言的來源之前，懷疑它可能是出於邪靈是絕對不算坊膺汪聖靈的。"},{"label":"附篇四 · 六點回答","text":"况且有許許多多會講方言的人，後來真的被發現是被鬼附所致，尤其是當奉主耶穌基督的名趕出那鬼之後，就更得到証實了。\n\n這一圖困不少靈恩派的人也知道。甚至我認議一些有經騐的人指茁，百分之九十說方言的人都是破鬼附的。旣然污鬼也有叫人說方言的能力，我們在鑑别方言的時候，試騐他，懷疑他，這絕不應該與故意褻瀆聖靈相題並論。我們知道，撒但自古至今都經常使用恐嚇的手段，只有在真理的亮光底下，撒但的恐嚇就無所作為了。4不錯，不少提倡方言的教會實在有復興的現象。"},{"label":"附篇四 · 六點回答","text":"但這只是一種現象，憑現象不能証實員偏的。正加眾所週知的，摩門教，耶和華見人會，共產主義，甚至撒但會等在近幾十年來也有興盛的現象，我們怎可以說這些也是出於聖靈的呢？况且，我們看一件事不能單看一面，為甚麼不看看今天仍有更多沒有方言的教會也有復興的現象呢？為甚麼不看有不少說方言的教會也有衰退的現象呢？再者，一些贊助方言的教會，他們復興的緣故豈是純因為方言呢？"},{"label":"附篇四 · 六點回答","text":"為甚麼不說禱告，講道，熱心，奉獻，文字工作，神學教育等等是復興的主因呢？把教會復興與方言拉在一起來說，明顯是强調了方言過於它應有的地位。我敢說我所牧養的教會也是復興的教會，我所教的神學院也是得神十分賜福的神學院。許多次我聽見會講方言的人對我說，聽我講道很得幫助，我心裏立即說，如果他們復興起來可能又强調是方言的緣故，為何不說最少有一部份是因為聽我講道呢？"},{"label":"附篇四 · 六點回答","text":"-過去基督教實在受到太利害的理性衝激，以致个少致會走向無神主義，不信主義。所以，當方言運動興起的時候，這種超自然的經歷，不錯確實叫不少信徒感到這是排斥新神學思想的最好証據。"},{"label":"附篇四 · 六點回答","text":"尤其在懷疑邊緣掙扎的基督徒，一旦得着方言的經騐，真是寶貴。誰知這可能有從一個理性極端，進到另一個靈性極端的危險。我要指出，排斥新砷學派的根本辦法不是超目然的經騐，因為對方的經騐總無法說服别人的理性，根本的辦法仍然是真理的分辨。新神學派的攻擊是在真理，我們不用真理回擊，卻用經歷來回擊，這豈不是對敵人說，我們的真理站不住了嗎？不！聖靈是真理的聖靈，祂要用真理來保護教會。"},{"label":"附篇四 · 六點回答","text":"唯有真理存在，經歷是暫時的，是個人的，是不能拿來作為準的。、0有方言恩賜的人强調他們與神有甜蜜的交通，靈性低沉的人就羨慕去追求方言，這一點我在前面第一章已經說過，這樣羨慕去追求、不是追求神，而是追求「甜蜜」的感受。如果一個人真知道主的寶貴，真看見主的美麗可愛，他當然會產生甜蜜的感受。"},{"label":"附篇四 · 六點回答","text":"但如果未看見主有任何美麗可愛的地方，而只在一種超自然的狀態中—在講方言之中1—不知為甚麼的，感到「甜蜜」，這就是情緒上的甜蜜，不是真與主交通的甜蜜。"},{"label":"附篇四 · 六點回答","text":"如果真看見主可愛美麗的地方，那就是出於員理的啓發，出於主自己，這才合理。靈恩派的人强調了方言是唯一「靈交」的途徑，這是錯的，我們不講方言，但我們也會靈交，而且我們的靈交也是甜蜜的。但我們靈交不為甜蜜的緣故，乃為主自己的緣故。與主有了相通的靈交，即使在情緒上沒有甚麼特别感受，這也是不要緊的一參第一章"},{"label":"附篇四 · 主耶穌所介紹的聖靈","text":"主耶穌所介紹的聖靈\n\n我們回答了上述六個問題之後，現在我們可以開始研究聖經有關方言的問題了。我們將會把新約聖經中論及方言的所有經文都列出來研究，以免斷章取義。此外，因為方言是聖靈所分派的。靈恩派之錯謬大部份是因為對聖靈有了錯誤的見解，所以我們在正式研究有關方言的經文之先，我們還應思想清楚聖靈的問題:當然，我們這一本書並不是專論聖靈與方言，所以我們不打算作全面性的研究。"},{"label":"附篇四 · 主耶穌所介紹的聖靈","text":"但我們也不希望對這問題馬虎了事。為了得到一個準確的看法，先準確地認議型靈是應該的。聖靈是主耶穌介紹來的，我相信沒有一個人不同更，耶穌基督的介紹必然是最清楚，最準確的。例如我介紹一個人給你認識說:「明天你到火車站某地方，你會看見一個人，這人最愛吃甜東西的，他為人誠實，但有點胃病，如果你見到一個這樣的人，你就知道他是李先生了。」"},{"label":"附篇四 · 主耶穌所介紹的聖靈","text":"你聽見我這樣介紹一定會說:「火車站有許多人，我怎知道謊仿吃甜東西？誰為人老實？誰有胃病？這樣的介紹簡直是糊塗，不清楚，葡辦認。你應該將李先生最容易看出來的特徵講明白，例加穿甚麼顏色的胡服，手拿聖經沒有，年組怎樣品眼鏡有甚麼特別，面部有甚麼特徵等，這才清楚準確！」是的，我們用以上的情形來思想主耶穌介紹聖靈來就清楚準確了，請問主耶穌說聖靈來有何特徵沒有？我們憑甚麼認出是祂？"},{"label":"附篇四 · 主耶穌所介紹的聖靈","text":"回答這一個問題，相信任何研究過型絕的人都同意，主耶穌詳細介紹聖靈來的經文就只有約翰福音十四和十冰草。"},{"label":"附篇四 · 稱號與內住","text":"稱號與內住\n\n十四章十六至十七節記載主耶穌的話說:「我要求父，父就另外賜給你們一位保惠-師，叫祂永遠與你們同在，就是真理的聖靈，乃世人不能接受的，因為不見祂，也不認_議冗，你們卻認議冗，因祂常與你們同在，也要在你們裏面。"},{"label":"附篇四 · 稱號與內住","text":"」請注意，主耶穌介紹聖靈為一真理」的聖靈，意思就是憑真理就可以認出祂。以賽亞書十一章二節的介紹是:「耶和華的靈必住在祂身上，就是使他有智慧和聰明的靈，-謀略和能力的靈，知識和敬畏耶和華的靈。」這種種稱呼全部都與真理有關，即使是「能力的靈」這稱呼，雖然意味着神蹟奇事，但並不完全指神蹟奇事。傳講真理也帶有能力的。"},{"label":"附篇四 · 稱號與內住","text":"所以，這些介紹全部集中在一員理」，只有真理是自古以來不停傳講的，神蹟奇事方言只是一個時期有，不能長久有的，要認出聖靈就不可能單憑神蹟奇事，但可以單色公頁理。而且當神蹟奇事與真理相反之時，神蹟奇事就不是出自聖靈。還有，神蹟奇事'如果不是為証明真理或帶出真理，這也不是出自聖靈。主耶穌和衆使徒從來沒有行過一～\"件神蹟奇事不為真理或不帶真理的。因此，我要指出，我們絕不能憑方言認出聖靈來，聖靈不是稱為方言的靈。"},{"label":"附篇四 · 稱號與內住","text":"而且今天的方言帶不出真理，也証明不出是真理(這一點，稍後論及方言的作用時再詳論～；甚至許多人說方言到了一個地步以之為得救的條件，又不按次序說，又沒有翻出來，亂叫亂喊，這簡直是違背真理。再者，主耶穌說，世人不能接受聖靈，因為不見祂，也不認議冗。意思是說世人認識是憑眼見，能見得到才肯接受，見不到就不肯接受。"},{"label":"附篇四 · 稱號與內住","text":"因為世人是屬肉體的，根本不明白甚麼是靈。而且憑肉體一眼見」才認識這句話，廣闊一點來說，也表示世人要憑肉體的五官感覺來認識。即凡視覺、聽覺、味覺、觸魯、嗅覺所感覺得到的，世人才肯接受。我們大家都曉得，聖靈旣是靈，不是物質，怎能憑五官感覺認議完呢？只有邪靈常用物質和感覺來欺騙人。"},{"label":"附篇四 · 稱號與內住","text":"靈恩派的人之所以强調方言，並不是為方言能使他們更明白賞理，只為方言能使他們有所感覺，而且有不少靈恩派的人說聖靈充滿他們的時候，有電波漫過身的感魯，有熱力的感魯，有震動的感覺，有興奮的感覺，有心中莫名的甜蜜感覺，有所謂見「異象」(帶不出真理來的幻象～的感覺，甚至有的看見自己的身體在地上輥動，自己站在旁邊觀看的感覺，這一切都是憑肉體的感覺說議聖靈，照世人的樣子行，怎能有準確的說議？"},{"label":"附篇四 · 稱號與內住","text":"看主耶穌怎樣說:-「你們卻認議冗，因祂常與你們同在，也要在你們裏面。一請問主說我們認識聖靈是因為感覺麼？不，全因為聖靈的「同在」，和-「內住」。聖靈是-另一位保惠師」。第一位是耶穌自己，聖靈是「另」一位。"},{"label":"附篇四 · 稱號與內住","text":"保惠師這詞意即有一位站在你旁邊，保護你，照顧你，安愈你品呂装主耶穌三年來向門徒做這工作，現仿生要離開」，但祂差聖靈來做同樣的工作，憑聖吉之樣的工作，我們就認議富了。"},{"label":"附篇四 · 稱號與內住","text":"而且祂一住」在我們「裏面」，也不是為要叫我們有所感覺，聖靈旣是靈而沒有物質的身體，祂進入我們裏面，自然不會叫我們產生一定的感覺。但可能有人這樣問，如果不泡成售和學，先到底有沒有進入我們裏面，我們怎知道呢？好，這是一個非常重要的問題，我們怎能確實的知道聖靈住在我們裏面呢？讓我們再來看主耶穌介紹聖靈的話就可以淸楚明白了"},{"label":"附篇四 · 聖靈的工作","text":"聖靈的工作\n\n約翰十四章廿六節記着說:「但保惠師，就是父因我的名所要差來的聖靈，祂要將-切的事指教你們，並且要叫你們想起我對你們所說的一切話。」十六章七至十四節記着說:「然而我將真情告訴你們，我去是與你們有益的，我若不去，保惠師就不到你們這裏來，我若去，就差祂來。袍既來了，就要叫世人為罪，為義，為審判自己責備自己。為罪是因他們不信我。為義是因我往父那裏去，你們就不再見我。"},{"label":"附篇四 · 聖靈的工作","text":"為審判是因這世界的王受了審判。我還有好些事要告訴你們，但你們現在担當不了。然意悬迷照業舉等，祂要引導你們明白一切的真理，因為祂不是憑自己說的，乃是把祂所聽見的都說出來，並要把將來的事告訴你們。"},{"label":"附篇四 · 聖靈的工作","text":"祂要榮耀我，因信完要將受於我的告訴你們。」請注意我在上述經文齊所用的黑體字:指鞏，想起，自責，明占，預告共五個動詞。這五個動詞就是聖靈住在我們裏面的工作。主耶穌的意思分明是指出，要認出聖靈來，只要憑聖靈在我們裏面這五樣工作就可以了。他指教甚麼？"},{"label":"附篇四 · 聖靈的工作","text":"是真理；宙趾我想起主所說的話，也是真理；祂叫我們自責，原因也是為真理；祂引導我們明白一切的員理；祂把將來的事(即日後聖靈啓示使徒寫在新約聖經裏的末世預言一預告我們知道，也是屬於真理。"},{"label":"附篇四 · 聖靈的工作","text":"我再說:聖靈是真理的聖靈，只有憑真理才可以認出祂。請記住，主耶穌介紹聖靈的話就是這些了，如果在其他福音書有介紹聖靈的話，也不外是這些，也不外是真理，主耶穌從來沒有說聖靈來叫你們說方言。說到這裏，可能有人指出兩段經文來反駁。第一段是使徒行傳第一章八節:-但聖靈降臨在你們身上，你們就必得着能力，並要在耶路撒冷，狠太全地，和撒瑪利亞，直到地極作我的見証。」"},{"label":"附篇四 · 聖靈的工作","text":"這豈不也是主耶穌介紹聖靈的話麼？這裏豈不是說憑-得着能力」可以知道聖靈降臨在我們身上麼？是的，但得着能力是指甚麼能力呢？不一定是指說方言的能力，也不一定是指行神蹟奇事的能力，因為方言和神蹟奇事是暫時，正如我在前文指出的，使徒行傳的後半部份漸漸少神蹟方言，難道那時候聖靈也泗汐減少作工嗎？不！聖靈來是「永遠」與我們同住的。"},{"label":"附篇四 · 聖靈的工作","text":"請仔細看上述所引的經文，主耶穌所說的能力是指「為祂作見証的能力」。這能力不單初期教會有，而且從那時開始一直到現在也有。為主作見証的能力是為甚麼？也是為真理。還有一段靈恩派的人士喜歡拿來反駁的經文，就是馬可十六章十七至十八節—一信的人必有神蹟隨着他們，就是奉我的名趕鬼，說新方言，手能拿蛇，若喝了甚麼毒物也必不受害，手按病人，病人就必好了。"},{"label":"附篇四 · 聖靈的工作","text":"」這裏所說的豈不是贊成靈恩運動的一切思想行為嗎？這豈不也是主耶穌的話嗎？回答這一個問題並不難，首先我希望讀者要正視一個事實，就是有兩部最古的手抄本聖經～西乃古卷和梵諦岡古卷～沒有記載第九節至結尾這一段的話。而且其他的古卷亦只記載了一部份，有的還有不同的記載。"},{"label":"附篇四 · 聖靈的工作","text":"雖然有不少解經家維護這一段經文而發表不少十分有力的意見，例如有不少古代教父也引用過這一段經文等等，但所有解經家無不認為應該保留一個可能性，就是十二至二十節這一段話文可能不是出自主耶穌親口說的話，是日後加上去的。"},{"label":"附篇四 · 聖靈的工作","text":"退-步來說，即使聖經原著真有這一段稻妳，這段經文本身也沒有說明其中的神蹟是永久性的，它只不過是一種預言，指出日後會有這一類的事出現。事實上，這些神蹟就只在最早期的教會裏有過，而且也不是常有。如果把這一段經文拿來支持靈恩派，那就出現許多不合理的地方。"},{"label":"附篇四 · 聖靈的工作","text":"除以上所指的之外，我們還可指出:手拿蛇，喝毒物，這些神蹟分明就不是常有的，就是靈恩派的人也不敢說他們能常常這樣行，和人人能這樣行。\n\n旣然這些不是常有的，不是人人有的，為何一定要說-方言」是常有的和人人有的呢？再者，這裏所說的「新方言」可以指普通外國語文來說的，不一定指一没有人能聽出來」的那一種。更重要的一點，就是這一段經文根本不是介紹聖靈的經文。我們rr不可以憑手拿蛇，喝毒物不死等來認出聖靈。同樣的，我們也不能憑「說新方言」來認出聖靈來。"},{"label":"附篇四 · 聖靈的工作","text":"總而言之，一個清楚而不能推翻的事實，主耶穌介紹聖靈來，完全而且單單强調只憑一真理」，就可以認出聖靈來。正如保羅所說:-無論有靈，有言語，有冒我名的書信說，主的日子現在到了，不要輕易動心(因為說主的日子現在到了這句話與真理不符合)」(帖後二2～。又說:-「無論是我們，是天上來的使者，若傳福音給你們，與我們所傳給你們的不同，他就應該被咒詛。"},{"label":"附篇四 · 聖靈的工作","text":"我們已經說了，現在又說，若有人傳福音給你們，與我們所領受的不同，他就應該被咒詛～因為與真理不符合～一二期9～。\n\n主耶穌介紹聖靈來的話，不但可以給我們準確的認出聖靈住在我們裏面。而且還可以給我們一個準確的鑑别，明白甚麼是被聖靈充滿。"},{"label":"附篇四 · 信的人都有聖靈","text":"信的人都有聖靈\n\n首先我們認定一點，就是彼得在使徒行傳第-和聞被聖靈充滿双說起別國的話來的時候，他對那些願意悔改接受救恩的人說:「你們各人要悔改，奉主耶穌基督的名受浸，叫你們的罪得赦，就必領受所賜的聖靂，因為這應許是給你們，和你們的兒女，並一切在遠方的人，就是主為我們1神所召1/1工的「H~—~14-侂—～～3839～，這是指每一個真心信主的人都有聖靈。"},{"label":"附篇四 · 信的人都有聖靈","text":"「敘麗」和「奉主耶穌基督的名受浸一這兩樣不外表示「上中心」信，表示內心悔改改變，外表也藉浸禮見証自己的改變。可是激烈的靈恩派拿鄉輸壹書五章六至八節—[「這藉着水和血～即浸禮和十字架的捨命～而來的耶穌基督，不是單用水，乃是用水又用血，並且有聖靈作見証，因為聖靈就是真理，作見証的原來有三，就是聖靈，水，與血，這三樣也都歸於一。"},{"label":"附篇四 · 信的人都有聖靈","text":"二—指出單信主受浸不能得救，還要加上一靈」，是三樣，不是兩樣。他們把聖靈分了出來，指信主的人沒有聖靈，要有方言才表示有聖靈，這是錯的。約翰所說的不是這樣，乃是說聖靈見証我們的濕禮和信靠主寶血的信”\"心。換言之，移輸是說，當我們悔改受浸真心信主時，聖靈就立刻自動進到我們裏面，見証我們的信心。"},{"label":"附篇四 · 信的人都有聖靈","text":"聖靈旣然在我們真心信主之時就進到我們裏面，而且我們單肥員理(上掂五樣工作)就可以認出祂來，那麼我們祈求聖靈充滿就不應該以為聖靈從上面，外面，下面進來充滿我們。"},{"label":"附篇四 · 信的人都有聖靈","text":"祂要充滿我們應該就是在我們裏面充滿我們，是內在的擴充，不是外在的進入，好像有另外一位進來似的。當日我們信主時，聖靈既進來，就是整位進來，不是一部份進來，也不可能分開兩位以不同的時間進來。只不過聖靈進來了，基督徒未必完全順服祂，未必完全讓祂一佔有」整個人的意羔；感情，思想，行動，喜好等，所以未有「充滿」。"},{"label":"附篇四 · 信的人都有聖靈","text":"如果我們肯讓祂完全管理我們，肯完全順服祂的引導，祂就立刻自動的充滿我們。可是靈恩派的人不是這樣說，他們說主耶穌復活之後向門徒吹一口氣說:「你們受聖靈吧！」那時門徒已經受了聖靈。但主耶穌仍要門徒等候五旬節聖靈從上面降臨，可見是分開兩次的。"},{"label":"附篇四 · 信的人都有聖靈","text":"這見解不對，因為那是過渡時期，主耶穌向門徒吹一口氣之時，是聖靈未普遍降臨之時～有解經家認為那只是預指五旬節聖靈降臨的一種表記)那時的情形仍像舊約的情形一樣，聖靈只一時住在人心，不久即離去。"},{"label":"附篇四 · 信的人都有聖靈","text":"但到了五旬節普遍降臨在人身上之後，祂就像主耶穌所說的永遠與我們同在，又在我們裏面，不再離開了。所以當時門徒的情形，不可能拿來當作恆久不變的原則"},{"label":"附篇四 · 聖靈充滿的現象","text":"聖靈充滿的現象\n\n我們每一個真信主的人都有聖靈住在我們裏面，這一點我們已經確定了。否定這一點的就是異端，因為改變了救恩真理。我們雖然確定有聖靈住在我們裏面，但我們怎知道甚麼時候和怎樣才算是被聖靈充滿呢？被聖靈充滿有甚麼必有的現象呢？有人說:被聖靈充滿必火像舌頭顯現出來，因為五旬節聖靈降臨時是有這現象的。"},{"label":"附篇四 · 聖靈充滿的現象","text":"有時會有大風吹過的現象，因仿風也是聖靈的表記，有時會有彷彿像鴿子的落下來，正如主耶穌受浸之後，聖靈降在祂身上的時候所表現出來的一樣。有時有大聲音，有時有地震，有時有異象，總而言之，聖靈充滿一定有超自然的，可見的現象。我們反對這種講法。不錯上述的種種情形都是聖經所記載的一些例子。"},{"label":"附篇四 · 聖靈充滿的現象","text":"但聖經並沒有說這些超自然的現象是「必」有的，最低限度我們看見使徒行傳第四章八節，記載彼得被聖靈充滿，回答審問他的官府和長老時，完至沒有超自然的現象。"},{"label":"附篇四 · 聖靈充滿的現象","text":"施洗納眾從母腹裏就被聖靈充滿～路一15～，但他一生都沒有遇過超自然的現象。有與沒有超自然的現象是聖靈自己決定的，祂以為需要有才有。如果我們硬性規定要有，恐怕我們所得的不是「內在聖經的充滿」，而是「外在的邪靈加入」，因為我們已經確定聖靈充滿是內裏的「擴充」，不是外在的「加入」。"},{"label":"附篇四 · 聖靈充滿的現象","text":"有的說:以弗所書五章十八節—「一不要醉酒，酒能使人放蕩，乃要被聖靈充滿一—作者將一醉酒」的現象與「聖靈充滿」的現象作一個比較，可見聖靈充滿的現象與醉酒的現象感受差不多。諸如喜樂、能力，做事有衝勁，興奮，勇敢，甚至多言，胡言，散髮，輥地，跳躍等也算在內。我們也反對這一個講法。首先以弗所書五章十八節指出不可醉酒的原因就是「上放蕩」。"},{"label":"附篇四 · 聖靈充滿的現象","text":"而聖靈充滿是與此相反的，是自約的，又「不可醉酒:::乃要被聖靈充滿」這句話是說出兩種充滿，不是着意指出其表現狀態，或現象感受。保羅勸人不要隨私慾而行以致醉酒，被酒充滿。應該隨聖靈而行，以致破型靈充滿才對。再者，聖經並沒有告訴我們聖靈充滿有一定的現象感受，以致我們可以憑某種現象感受來鑑别是否聖靈充滿。"},{"label":"附篇四 · 聖靈充滿的現象","text":"不錯，聖靈充滿一個人可能會使他有喜樂能力衝勁等表現，但並不是每一次每一個人補蟻靈充滿都是如此，最低限度主耶穌自己不是這樣，聖經裏面有許多被聖靈充滿的人也不是這樣。"},{"label":"附篇四 · 聖靈充滿的現象","text":"有的說:聖靈充滿一定有方言，異能，醫病，預言，翻方言等恩賜，因為聖靈要配搭我們成為基督的身體，每一個肢體都有功用，所以每一個被聖靈充滿的人都有恩賜。我們也不同意這個意見。不錯恩賜是聖靈分賜給我們的，不錯，有許多被聖靈充滿的人(尤其是初期教會的時代～都有方言等恩賜。但得恩賜的人不一定是被聖靈充滿的人。"},{"label":"附篇四 · 聖靈充滿的現象","text":"正如哥林多教會的信徒，多有分爭結黨，淫亂污自，聚會混亂等等罪惡問題，怎可能是被聖靈充滿？但他們卻會講方言，而且講到出了亂子，他們也十分有恩賜，正如保羅所指一你們在恩賜上沒有一樣不及人的一～林前一7～。主耶穌也明指，有一些將來被主拒絕進天國的人也有「行異能，趕鬼」的恩賜～太七22～。為甚麼今天靈恩派的人士一定要以為教會有了各樣的異能恩賜才是被聖靈充滿的教會呢？"},{"label":"附篇四 · 聖靈充滿的現象","text":"再者，為甚膨一定要有超自然的賜才算是被聖靈充滿呢？聖靈充滿一個人不可以賜他講道，安慰，辦事等自然的恩賜嗎？可見這一種意見一定是錯的。\n\n最低限度我們找不到聖經支持，被聖靈充滿一定有某種恩賜的表現。"},{"label":"附篇四 · 聖靈充滿的準則","text":"聖靈充滿的準則\n\n或問，既然被聖靈充滿不一定有上述種種的現象，那麼我們憑甚麼得知道被聖靈充滿呢？研究這一個問題，我們就要查出，到底聖靈來最主要的是甚廢工作？祂經常不閒斷做的是甚麼工作？我們在前文已經指出，神蹟奇事並不是聖靈經常做的主要工作，所以我們不能憑神蹟奇事的現象來鑑别聖靈充滿。\n\nJ風」，「火」，「地震」等現象也不是聖靈經常帶來的現象，所以我們不能憑這些現象來鑑别聖靈充滿。"},{"label":"附篇四 · 聖靈充滿的準則","text":"聖靈經常做的双是最主要的工作，是「指教」我們認識真理；叫我們在適當的時候「想起」真理；當我們違背員理時，戰我們「自責」；當我們讀聖經的時候，引導我們「明白一員理；並且接著員理把將來必要成的事「預告」給我們知道；而且在我們傳揚真理時賜我們作見証”的「能力」，以上這六點我們在前文已經詳論過了，不過我在這裏指出，既然這六點是一聖靈經常做的最主要工作，那麼，我們就可以憑這六點知道何謂聖靈充滿了。"},{"label":"附篇四 · 聖靈充滿的準則","text":"聖靈被稱焦頁理的聖靈，祂充滿我們的時候，就一定叫我們充滿真理，我們可以有神蹟奇事的現象，可以有恩賜受感的現象～我再說未必有的～，但這一切都不外是要傳揚真理，這一切都必須合員理。"},{"label":"附篇四 · 聖靈充滿的準則","text":"事實上，當真理的聖靈在我們裏進行指教，趾我們想起，明白，自責，預知一切有關主耶穌的事的時候，我們若能完全順服聖靈，依從聖靈、體貼聖靈的話，我們就是被聖靈充滿了。至於現象方面，這要看聖靈自己認為我們需要甚麼現象，甚麼現象對我們最有幫助，祂才賜下甚麼現象。但無論聖靈賜甚麼現象給我們也不要緊，最要緊的是員理。"},{"label":"附篇四 · 聖靈充滿的準則","text":"例如當我們「想起」主耶穌的話而得到很大的安慰，於是心中哲起一陣喜樂的感受來。請問這喜樂的感受重要呢？還是想起主的話重要呢？當然是想起主的話。例如聖靈叫我仿罪自責叫我難過起來，請H.問難過的感受重要呢？還是為罪自責重要呢！當然是為罪自責重要。又例如聖靈賜哥尼流一家人方言為要給不信的猶太人証明神已經悅納外邦人了。"},{"label":"附篇四 · 聖靈充滿的準則","text":"請問方言本身重要呢？還是証明神悅納外邦人重要呢？所以，如果一定要找一個必有的「現象」來指出這就是被聖靈充滿的話，這個必有的現象就是真理補翊顯出來的現象。其他的都不是準確的，最低限度不是長久有效的鑑别準則。"},{"label":"附篇四 · 聖靈充滿的準則","text":"如果有人反駁說:「你說沒有經文支持方言，神蹟奇事，現象感受等為衡量準則，難道你也可以找出經文來支持你的說法—「真理一定是準確的衡量準則嗎？」迷然可以，請看約翰壹書四章一至三節教我們怎樣分辨聖靈邪靈，經文豈不是說:「贍靈認耶穌基督•是成了肉身來的，就是出於神的::凡靈不認耶穌就不是出於神。請注意，一耶穌基督成了肉身來」就是一個最大的真理。"},{"label":"附篇四 · 聖靈充滿的準則","text":"問題是，為甚麼聖經教導我們用真理來辨別聖靈與邪靈，而不用「神蹟奇事」的大小現象等來分辦？答案很簡單，因為聖靈是真理的聖靈。"},{"label":"附篇四 · 自稱聖靈充滿是謙卑","text":"自稱聖靈充滿是謙卑\n\n有了以上的答案，我們明白被聖靈充滿就是被真理充滿，即不單明白真理，又行真理，售頁理，以真理為樂，為寶，訪具望，為生命。其他的現象有無也不要緊，如果有現象，那現象是甚麼也不要緊，最要緊是真理。"},{"label":"附篇四 · 自稱聖靈充滿是謙卑","text":"這麼一來，我要再進一步指出的，就是有許多基督徒曾經有過被聖靈充滿的經歷，只可惜他們不知道那就是被聖靈充滿，也不敢隨便說自己是破阻靈充滿，恐怕别人說他們驕傲。結果-被聖靈充滿」這詞就被一些强調特經歷的人壟斷了。其實聖經用「被聖靈充滿」這詞的原意來說，那是謙卑的說法，不是矣例的說法。"},{"label":"附篇四 · 自稱聖靈充滿是謙卑","text":"意思是說，那人之所以有這樣的能力，有這樣的成就，有這樣的喜樂，有這樣的見証，有這樣真理洞察力，完全是因為聖靈充滿他之原故，不是他自己的本事，所以將榮耀歸給神。"},{"label":"附篇四 · 自稱聖靈充滿是謙卑","text":"因此，當我明白真理，有喜樂，有能力，有見等時，我稱自己仿磁聖靈充滿，我絕不是在自誇，反之，我是謙卑，承認這一切不是出於我自己，是聖靈的作為。可惜，在今天一般的基督徒和傳道人的心理上，自稱被聖靈充滿被視為一種過做，結果我們十分少聽見有人被聖靈充滿，結果，强調特殊經歷的人就獨佔了這一被聖靈充滿」的權利了。.其實，許多仿主的人都有過，並且是多次有過補聖靈充滿的經歷。"},{"label":"附篇四 · 自稱聖靈充滿是謙卑","text":"你回想一下'你以往在聽道，唱詩，靈修，默想，讀經等，因為被真理感動的緣故，毅然順服聖靈，愛主，事奉主，對付罪惡，以致滿心充滿喜樂，生活滿有能力等的經歷，那就是被聖靈充滿了。只不過大器皿有大充滿，小器皿有小充滿。你的被聖靈充滿經歷不及宋尚節等偉大信徒被聖靈充滿的經歷，是因為他們是大器皿，你是小器皿。"},{"label":"附篇四 · 自稱聖靈充滿是謙卑","text":"倘若我們在生活事奉上多多操練自己，在真理上多多造就自己，我們的器皿就會變大，這時候，我們所經歷的被聖靈充滿，就有更大的，更明顯的表現了"},{"label":"附篇四 · 聖靈充滿的條件","text":"聖靈充滿的條件\n\n聖靈的「居衷」每個基督徒都有。聖靈充滿的機會也是每個基督徒都有的。我們只要真心信耶穌就有聖靈居衷，同樣，只要我們除去一切的罪惡污自，頁心愛主事奉主，聖靈就自動會充滿我們。因為聖靈是主所差來的。"},{"label":"附篇四 · 聖靈充滿的條件","text":"而且祂來又是為要一榮耀」主一約十六14～，祂不憑自己說話，乃是把祂所聽見的說出來，將受於主的告訴我們(約十六13214～，如果祂責備我們，也完全是仿主的原故(繳十太有11冖™，換言之，聖靈一切的工作就是引導我們信主，更愛主，事奉主，像主。那麼，當我們對準主，竭力追求認識主，愛主，事奉主，我們就是被聖靈充滿了。"},{"label":"附篇四 · 聖靈充滿的條件","text":"保羅在歌羅西書告訴我們—一父喜歡叫一切的豐盛～包括聖靈充滿，和聖靈充滿所帶來的一切好處～，在祂～基督～裏面居住～一19～：一所積蓄的一切智慧知識～包括真理的聖靈所引導我們明白的一勒頁理～，都在祂～基督～裏面藏着～二3～；一神本性一切的豐盛～包括聖靈一切的本性能力～，都有形有體的居住在基督裏面，你們在祂裏面也得了豐盛「～二910～。"},{"label":"附篇四 · 聖靈充滿的條件","text":"我之所以這樣指主，因為靈恩派和許多無知的基督徒，都以為我們單對付罪惡，信主，愛主，事奉主，順服主，像主，榮耀主是不夠的，換言之，單靠主耶穌基督是不夠的，除了照上述的去行之外，我們還須要切切的去追求聖靈充滿。「切切」的求，有時也包括捶胸大明的求，按手禱告和重複背誦一句話的求，暫時不向主，改為專心向聖靈求。"},{"label":"附篇四 · 聖靈充滿的條件","text":"不然，我們就得不到聖靈充滿的特殊經歷。我不是說向聖靈禱告是錯的，聖靈是有位格的禾，當然可以向補碟告，但是我要清楚的指出，上述那樣的追求聖靈充滿是錯誤的，不單錯在以為聖靈還在自己內心以外(其實祂已在我們信主時進入我們裏面了～，錯在追求一種特殊經歷，以之為聖靈充滿的必有現象；最大的錯誤和最危險的錯誤還是在於分裂聖靈與基督的關係。"},{"label":"附篇四 · 聖靈充滿的條件","text":"聖經清楚的指出~^聖靈來是為要榮耀主，正如我在上文所詳細指出的，我們怎麼以為單愛主，順服主，事奉主不夠，還須要「另外」去求聖靈，好像以為聖靈是另一位很會妒忌的神。祂看見我一們單愛主，順服主，事奉主，但忽略了袍，袍就有點生氣，不肯充滿我們，除非我們在-愛主，事奉主，順服主以外，也同樣的愛聖靈，事奉聖靈，順服聖靈。不！我們之所以愛主，完全是聖靈的工作！"},{"label":"附篇四 · 聖靈充滿的條件","text":"我們之所以事奉主，順服主，也完全是聖靈的工作，換言之，我們完全的愛主，事奉主，順服主的時候，正是聖靈充滿我們的時候，將這兩件事分開就是間接的分裂聖靈與主耶穌的關係"},{"label":"附篇四 · 求聖靈充滿的錯誤根據","text":"求聖靈充滿的錯誤根據\n\n讓我進一步的指出，聖經裏面找不出一個在追求愛主事奉主之外，還另外追求聖靈充滿的例子，也找不出一節勸人特别追求聖靈充滿的經文。聖經一貫的教訓都是要我們信主，認識主，愛主，事奉主，這樣，聖靈就會自動充滿我們，因為充滿我們是祂的責任，是祂樂疙偽的，問題是我們肯不肯讓祂充滿，如果我們肯，和就隨時隨刻充滿我們，不需要我們求祂。"},{"label":"附篇四 · 求聖靈充滿的錯誤根據","text":"因為聖靈充滿我們是祂作主動的，不是被動的。我知道，主張追求聖靈充滿的人必定會提出兩處經文來反駁我的說法。第一處是以弗所書五章十八節—「不要醉酒::乃要被聖靈充滿。」第二處是路加十一章十一至十三節—一你們中間作父親的，誰有兒子求餅，反給他石頭呢？求魚，反拿蛇當魚給他呢？求從看，反給他蠍子呢？"},{"label":"附篇四 · 求聖靈充滿的錯誤根據","text":"你們雖然不好，尚且知道拿好東西給兒女，何况天父，豈不更將聖靈給求他的人麼？一讓我先解釋前一處經文。請注意保羅十分小心地用了一個一被一字。「要被聖靈充滿」的意思分明是說，聖靈會探取主動來充滿我們，問題是我們肯不肯讓祂充滿，所以保羅勸我們一要」「被」聖靈充滿。前面的「要」字是勸告詞，目的是勸我們肯接受聖靈的充滿，後面的-被」字是强調詞，目的指出主動在聖靈。"},{"label":"附篇四 · 求聖靈充滿的錯誤根據","text":"如果這節經文是勸我們追求聖靈充滿的話，保羅為何不說「要「求聖靈充滿」呢？可見，保羅十分明白，聖靈充滿是不用求的。因為聖靈會自動而又主動的充滿我們，問題是我們肯不肯讓祂充滿。一切攔阻我們被聖靈充滿的只有罪，此外再沒有攔阻的。如果我們肯徹底的對付自己的罪，除去一切偶像汚穢，我們就是肯被聖靈充滿了。好像自來水管一樣，只要我們把塞佳水管的東西除去，水就自動的流出來，不必另外再去求的。"},{"label":"附篇四 · 求聖靈充滿的錯誤根據","text":"或問，為甚麼有許多神的僕人見証他們會經有過祈求聖靈充滿的經歷，後來果真被聖靈充滿呢？是的，有許多神的僕入寫傳記或講道都這樣說，我推測可能他們所謂的追求被聖靈充滿，只是追求聖潔，對付罪惡污穢，生活更像主，更愛主，不過後來他們在作見証時，-來為了簡化所講的見証，二來是為了歸榮耀給神，三來是為了不便將自己對付罪惡的詳細過程說出，於是就說是追求被聖靈充滿。"},{"label":"附篇四 · 求聖靈充滿的錯誤根據","text":"再者[追求」這兩個字若只用作形容自己徹底除去障礙，議聖靈充滿自己，這也是無可厚非的。但決不是在自己已經符合被聖靈充滿的條件之後，還好像未得到一樣拚命去求。也不是不理會自己是否除去汚穢障碍，只拚命捶胸的求。現在我們思想路加十一章十一至十三節那段經文。請注意，那一段經文不單沒有勸我們去追求聖靈充滿，而且還清楚的指出，聖靈是不用求就可以得到的。"},{"label":"附篇四 · 求聖靈充滿的錯誤根據","text":"經文說:「你們雖然不好，尚且知道拿好東西給兒女，何況天父，周不更將聖靈給求祂的人麼？一請注意:第一聖經並沒有說那「求祂的人」是求聖靈。第二，天父「更」將聖靈給他，這個更字表明聖靈是額外賜給他，或超過他所想所求的。第三，根據馬太七章七至十一節所記載同一個內容的經文指出之你們雖然不好，尚且知道拿好東西給兒女，何况你們在天上的父，豈不更把好東西給求祂的人麼？」"},{"label":"附篇四 · 求聖靈充滿的錯誤根據","text":"(第十一節)這裏是說不是說「聖靈」，可見那「求祂的人」所求的，只是好東西，他根本不曉得求聖靈，正如我們在信主時，我們只曉得求神赦免我們的罪，賜我們永生平安等等，絕沒有一個人在決志信主之時就曉得求聖靈，因為他根本未認識聖靈，也不知道聖靈的好處。"},{"label":"附篇四 · 求聖靈充滿的錯誤根據","text":"但是，我們每一個人在決心信主之時就立刻得到聖靈居住在我們裏面。這是天父超過我們所想所求的賞賜。所以，路加十一章十一至十三節這段經文只能應用在信主得聖靈的情况裏，決不能應用在信後追求聖靈充滿的事上。"},{"label":"附篇四 · 求聖靈充滿的錯誤根據","text":"靈恩派的人士喜愛利用這段經文勸别人放心去追求聖靈，他們說，天父絕對不會拿石頭當餅賜給我們，拿蛇當魚賜給我們。照樣，天父必不會議懂靈充滿我們當作讓聖靈充滿我們。是的，天父當然不會這樣，但魔鬼卻會這樣。問題是你求的對象是施？加果我們在真理之外，在無知盲目的狀態下追求聖靈充滿，魔鬼大可以裝作光明的天使來基騙我們，結果使我們落在邪靈的控制之下"},{"label":"附篇四 · 使徒行傳的方言","text":"使徒行傳的方言\n\n既然主耶穌介紹聖靈來而沒有說明聖靈一定會賜方言的恩賜給每一個信主的人，那慶，為甚麼在初期教會的時代，聖靈要賜下方言呢？賜下方言的目的何在？聖靈賜下方言的目的只有一個，那就是哥林多前書十四章二十一至二十二節所指出的—「律法上訊著:『主說，我要用外邦人的舌頭和外邦人的咀唇，向這百姓說話。雖然如此，他們還是不聽從我。"},{"label":"附篇四 · 使徒行傳的方言","text":"』這樣看來，說方言不是為信的人作証據，乃是為不信保羅這樣引用「律法上」的話，分明是要指出，外邦人的舌頭和咀唇所說的外邦話就是方言。而一為不信的人作証據」分明就是指「這百姓」—猶太人。我們用這一個真理作信鑣匙，就可以解釋使徒行傳裏面所有說方言的事例了。"},{"label":"附篇四 · 五旬節的方言","text":"五旬節的方言\n\n五旬節聖靈像火舌般降臨在門徒身上，他們就「說起别國的話來」(徒二4～。聖靈降臨在主身上像鴿子，表明聖靈使主有鴿子的馴，和平，聖潔。主復活以後向門徒吹一口氣說「你們受聖靈吧」，那口氣表明聖靈是主差來的，帶有看不見的能力。主說信祂的人有活水江河從他腹中流出，是表明聖靈要解決人一切的乾渴。"},{"label":"附篇四 · 五旬節的方言","text":"如今聖靈降臨在門徒身上像火舌，當然是聖靈賜他們方言的恩賜和作見証的能力。請注意，聖靈以甚麼形式降臨是接袍的旨意和按我們的需要的，不能强說聖靈降臨就一定有方言。況且，聖靈為甚麼在五旬節時賜下方言的恩賜呢？因為主耶穌基督是磋獅太人所殺，他們之所以殺主，是因為不信主，如果要猶太人信主，就非要有神蹟顯現不可。"},{"label":"附篇四 · 五旬節的方言","text":"因為正如保羅所指出的一猶太人是要神蹟，希利尼人是求智慧」(林前一22～。或問，猶太人要求神蹟，聖靈可以賜下醫病趕鬼的神蹟豈不是夠了嗎？為何要賜方言恩賜呢？聖靈賜方言為証據的原因有二，第一是因為主耶穌也會行過許多神蹟醫病趕鬼，但猶太人仍然不肯信，如今非要有一種人人看得出來，而主耶穌也沒有行過的神蹟，猶太人就不肯信，所以需要方言的恩賜。"},{"label":"附篇四 · 五旬節的方言","text":"第二是因為方言的恩賜正應驗約珥先先知的預言，正如彼得站起來所見証的—一神說，在末後的日子，我要將我的靈澆灌凡有血氣的，你們的兒女要說預言，你們的少年人要見異象，老年人要作異夢，在那些日子，我要將我的靈澆灌我的僕人和使女，他們就要說預言，在天上我要顯出奇事，在地下我要顯出神蹟。有血，有火，有煙霧，日頭要變為黑暗，月亮要變為血，這都在主大而明顯的日子未到以前。到那時候，凡求告主名的，就必得救。」(徒二1721～至於預言怎樣應騐方面，我們稍後再詳細討論。"},{"label":"附篇四 · 五旬節的方言","text":"這裏先指出聖靈賜下方言的原因就是應騐先知的預言。當那些不信的猶太人聽見彼得和其餘的使徒講一種話，叫他們十八種不同鄉談的猶太人都聽明白，又聽見彼得指出這是應騐先知預言的，即合聖經真理的，他們就承認這種神蹟是出於神，又承認使徒們所講論的耶穌是出於神的，於是紛紛要求信主受浸。這樣，我們清楚的看見方言是為一不信的猶太人作証據一而有的"},{"label":"附篇四 · 撒瑪利亞人受聖靈","text":"撒瑪利亞人受聖靈\n\n請注意，根據使徒行傳記載，自從五旬節聖靈降臨叫使徒們說方言之後，一直到彼得向哥尼流一家傳福音時才再有方言～十46～。即使彼得講道叫他們虱收那三千和五千人，也沒有說方言。到四章八節彼得被聖靈充滿反駁審問他的大祭司等人時，也沒有說方言。"},{"label":"附篇四 · 撒瑪利亞人受聖靈","text":"彼得釋放後回到聚會的地方，衆門徒和他一同禱告讚美神，他們就被聖靈充滿，連地也震動，但他們還是沒有說方言，只放胆講論神的道～四31～。\n\n到揀選七個管理飯食的人時，所提出的條件只是被聖靈充滿，沒有提及說方言(六3、5～。又來到司提反被殺時，他也再一次被聖靈充滿，也是沒有方言(七55～。到了第八章撒瑪利亞人信主的事，他們在按手時受了聖靈，但沒有說方言(八17～。同章記載埃提阿伯太監信主有令漫的事，太監也沒有說方言～八39～。"},{"label":"附篇四 · 撒瑪利亞人受聖靈","text":"再來到掃羅歸主的故事，亞拿尼亞明明的對他=旦脱上主耶穌打發我來，叫你能看見，又褲聖靈充滿二！可是掃羅眼睛看見了，又受浸歸主了，也沒有說方言。"},{"label":"附篇四 · 撒瑪利亞人受聖靈","text":"這樣我們來到第十章哥尼流一家歸主的故事，才正式的再看見方言出現。或問，為何上述許多聖靈充滿的事蹟都沒有方言呢？答案很簡單，因為聖靈認為沒有這個需要，方言只為給不信的人作証據。"},{"label":"附篇四 · 撒瑪利亞人受聖靈","text":"可是靈恩派的人士一定會指出，撒瑪利亞人信主後按手才有聖靈的故事一公1424y一定有方言，只是聖經沒有明顯記載吧了，因為他們奉了主耶穌的名受浸仍沒有聖靈降在他們身上，及至按手在他們頭上之後，他們就受了聖靈。"},{"label":"附篇四 · 撒瑪利亞人受聖靈","text":"他們受聖靈與否是可以看見的，因信困那個行邪術的西門也看見了，所以他才出錢向使徒買這按手叫人受聖靈的恩賜。可見，想要得方言是需要按手，而且一個見得到的受聖靈現象必是說方言的現象。這種解釋是錯誤的。首先我們要注意，使徒行傳只是歷史的記載，一切發生的事作者並沒有責任去解釋，因為他的目標不是傳講教義真理，他的目標只是將所發生的一切事原原本本的記載下來。"},{"label":"附篇四 · 撒瑪利亞人受聖靈","text":"所以，我們萬萬不能只按使徒行傳本身來解釋使徒行傳。要解釋使徒行傳所記的一切事蹟就必須憑真理—！即憑書信，四福音中所記主的話，和其他經文所記能代表神發表的話。這樣，撒瑪利亞人按手受聖靈的事例不能看為真理原則。因為其他人受聖靈沒有按手，哥尼流一家人受聖靈，說方言也沒有按手。聖經並沒有說受聖靈一定要按手的。然則為甚麼撒瑪利亞人須要按手才能受聖靈呢？"},{"label":"附篇四 · 撒瑪利亞人受聖靈","text":"為何他們受聖靈是可以看得見的呢？回答這個問題並不困難。請注意，這些人是撒瑪利亞人，撒瑪利亞人與猶太人是不相往來的。\n\n撒瑪利亞人看自己也是亞伯拉罕的後裔，因為他們原是補遞時餘下的猶太人，只是他們與外族通婚和混居(參王下十七24～，以致後來忘記了自己的族譜，所以隊猴太人看他們為不潔，不能進聖殿敬拜神。他們見自己不能進耶路撒冷聖殿，於是在撒瑪利亞山上敬拜神，這一來更使猶太人恨他們，自此，兩方面一直沒有相交。"},{"label":"附篇四 · 撒瑪利亞人受聖靈","text":"主耶穌升天之前吩咐門徒傳福音也將猶太人和撒瑪利亞人分開來說:「並要在耶路撒冷地，猶太全地和撒瑪利亞，直到地極，作我的見証。\n\n「～徒一8～。所以使徒們出來傳福音的時候，只向猶太人講，不向外邦人講，因為他們還不認識外邦人可以和他們同蒙應許，同為後嗣，這奧秘原是隱藏的，直到後來才被保羅發現出，米一弗二17)。"},{"label":"附篇四 · 撒瑪利亞人受聖靈","text":"如今在耶路撒冷的使徒門聽見腓利竟然下到撒瑪利亞去傳禮特，壟且有不少男女都信了主，受了浸，連那個行邪術的西門也信了主，受了浸，於是他們大大驚奇，打發彼—II一得和約翰往撒瑪利亞去看個究竟。請注意彼得和約翰是當時最大的領袖，由他們代表全—教會去研究這個問題作個最後的決定是應當的。"},{"label":"附篇四 · 撒瑪利亞人受聖靈","text":"及至彼得和約翰到了撒瑪利亞之後，他—一們發現那些撒瑪利亞人的信心並沒有甚麼虛假的地方，並且腓利也實在在他們中間行了*\"許多神蹟，醫好了他們許多病人。本來這已經足夠叫他們相信神悅納和拯救了這些撒瑪利亞人，事實上，主也會向撒瑪利亞城的人傳講過福音。"},{"label":"附篇四 · 撒瑪利亞人受聖靈","text":"可是，彼得和絢輸仍以為証據不夠，可能他們認為最低限度難以向其他猶太人交代，於是問這些撒瑪利亞人受了聖靈沒有。這些撒瑪利亞人也實在未受聖靈，因為神知道撒瑪利亞人和猶太人的不長關係，特要等待彼得和約翰來替他們按手禱告才讓聖靈降在他們身上，好讓後得和絢夫看見，日後向其他猶太人作見証，証明禮末自悅納了這些撒瑪利亞人。"},{"label":"附篇四 · 撒瑪利亞人受聖靈","text":"於是彼得和約眾接手在他們頭上，為他們禱告，聖靈就立刻降到他們身上了。這按手的禮只是一種新禧習慣，尤其是為一個人祈求神醫病或賜福之時，猶太人都習慣按手在那一個人的頭上。按手禮本身並不是傳授聖靈的必需媒介，因為有許多其他人受聖靈並沒有接受按手禮的。而且彼得和約翰之所以按手在這些撒瑪利亞人的頭上，是因為他們已經受了浸，再沒有别的禮需要行了。"},{"label":"附篇四 · 撒瑪利亞人受聖靈","text":"聖靈降在他們身上的情形磁後得和絢輸看見了，這可以看得見的聖靈降臨，或許是像火舌的降臨，或許是像鴿子的降臨，或許是集體說預言，或許是方言，也或許是其他的形式。總而言之，聖經並沒有說明，我們不能硬說一定是說方言的現象。即使是說方言的現象，這也是為了給「不信」的猶太人！彼得和納輸作了其他猶太人的代表，他們不信神悅納了這些「半外邦人一—作証據(林前十四22～。"},{"label":"附篇四 · 撒瑪利亞人受聖靈","text":"所以到了使徒行傳入章廿五節那裏，聖經記着說:「使徒既明主道，而且傳講，就回耶路撒冷去，一路在撒瑪利亞好些村莊傳揚福音。\n\n」所以，按手叫撒瑪利亞人受聖靈的事，是一件特的事，正如五旬節聖靈降臨在門徒身上是一件特的事一樣。這旣然是一件劃時代的特事件，我們就不可能拿來作為常例的原則，正如我們不能拿五旬節聖靈降臨的現象作為經常性的原則一樣。"},{"label":"附篇四 · 哥尼流一家說方言","text":"哥尼流一家說方言\n\n叮我們經已用林前十四章廿二節這鑣是開了兩個門誥學為感則坚音張护含燒时猶太人作証明五名節的一方言一也是給不信的猶太人作証據，並且兩者都是劃時代的特事件，誰明福音降臨到猶太人，繼而臨到「半猶太人」的撒瑪利亞人。"},{"label":"附篇四 · 哥尼流一家說方言","text":"現在我們來到思想哥尼流這一家外邦人了。～他是一位歡曠禾的外邦人，換言之是一位比較接近猶太人的外邦人～。請注意，這個次序正正對照主耶穌的使命—」並要在耶路撒冷，猶太全地，撒瑪利亞(以後接着到該撒利亞「十二1一，叙利亞的安提阿」＋1^等地)直到地極(所有外邦人)，作我的見証◎請細讀使徒行傳第十章全章。"},{"label":"附篇四 · 哥尼流一家說方言","text":"彼得三次拒絕天上來的馨香，不肯吃在異象中所看見的那塊大布裏面的不潔之物，而這些不潔之物正是猶太人看為外邦人的代表。可見猶太人和彼得歧視外邦人之深。結果當哥尼流所差的人到來尋訪彼得時，聖靈就直接的吩咐彼得與這些人同去，不要猜疑。彼得不能不順服了。"},{"label":"附篇四 · 哥尼流一家說方言","text":"於是他第二天就和那些人回哥尼流的家去。可是當他一進哥尼流的家，看見已經有許多人聚集，等候要聽他講道，他第一句話就說:「你們知道猶太人和别國的人親近來往，本是不合例的，但神已經指示我們，無論甚麼人都不可看作俗而不潔的。」及至彼得聽見哥尼流解釋，說有一位天使在異象中吩咐請他來之後，彼得又再進一步得到神的指示要傳福音給他們聽，於是彼得開講。"},{"label":"附篇四 · 哥尼流一家說方言","text":"但是，當彼得剛講完福音的精義，還要繼續講下去的時候，聖靈忽然降臨在一切聽道的人身上，叫他們說方言，甚至「那些季制禮和彼得同來的信徒見聖靈的恩賜也澆在外邦人身上，就都希奇。」「於是彼得說，這些人旣受了聖靈與我們一樣，誰能禁止用水給他們施浸呢？就吩咐奉耶穌基督的名給他們施浸。"},{"label":"附篇四 · 哥尼流一家說方言","text":"一～45，47節～聖經的字據是何等的清幣說明這一次聖靈降臨在這些外邦人身上，趾他們說方言，完全是為了給不信的猶太人作證據，證明神親自悅納外邦人，外邦人可以同蒙應許，同坊後嗣，這一點真是猶太人驚天動地的大發現，其轟動的程度由十一章彼得回耶和撒冷之後，立刻有奉割禮的門徒起來與他大大爭辯的事可以見到，再由日後猶太人為這事常常逼迫擾亂保羅事件可見到，"},{"label":"附篇四 · 哥尼流一家說方言","text":"因為這奧秘正正式式由保羅發表出來，而且，保羅發表了這個奧秘啟示，不但引起了未信主的猶太人的憤恨，同時也非常艱難才能使其他的門徒～十五2)同意他的「看法—～其實這是主直接的啟示，不是保羅自己發明出來的。"},{"label":"附篇四 · 哥尼流一家說方言","text":"～但感謝神，當使徒們聚集在耶路撒冷開第一次大議會(徒十五章～，要討論外邦人信主及應否守律法的事之時，聖經說，一辯論已經多了～7節～，可見猶太人十分難以相信神會悅納外邦人的。後來這辯論怎樣結束呢？是彼得起來把哥尼流一家信主受聖靈的事說出來，作為一個有力的證據，證明神親自悅納外邦人。於是一衆人就默默無聲」再聽保羅和巴拿巴的印證～12節)。"},{"label":"附篇四 · 哥尼流一家說方言","text":"從這個會議看來，神早就知道猶太人不信的硬心，所以才特别的感動彼得去傳往理綸哥尼流一家人，神特别揀選彼得，因為他是最有影響力的領袖，但這最有影響力的領袖，再加上保羅這個偉大的使徒，並加上保羅從主耶穌直接得來的秘奧，仍然無法改變猶太人的態度，因為使徒行傳給我們看到，猶太人的不信越來越利害，教會內的猶太主義—外邦基督徒必須受割禮—也越來越勢力大。\n\n明白這一切背景的人，就必定明白當時神賜「方言」的作用為何了。"},{"label":"附篇四 · 十二個人說方言","text":"十二個人說方言\n\n-請注意，由第十章一直到第十八章末了，都再沒有例證指出在信主之時有說方言的事件，只有到了第十九章，保羅在以弗所遇見十二個受了絢輸漫禮的門徒，因為他們還未領受聖靈，保羅就向他們講解身輸的浸是悔改的浸，應當「相信耶穌—才對，於是奉主耶穌的名再給他們施浸，然後按手在他們頭上，聖靈便降在他們身上，使他們說起方言和預言來(十九17～。"},{"label":"附篇四 · 十二個人說方言","text":"這一個事例當然比較前面的幾個更容易明白了，因為聖靈不是絢輸差來的，而且單悔改而不信耶穌仍是不能得救。可是，當這十二個人信了耶穌，又奉主耶穌的名受了浸之後，一禱告，聖靈就立刻降在他們身上使他們講方言，聖靈這一次賜下方言，目的也是要給這十二個剛信主的門徒一個證明，當然也給其他可能在垃歡禮的不信的猶太人一個證明，證明聖靈是主耶穌差來的，主耶穌比逢輸還大，並且這件事也可以說是一個特别的事例，為要劃分納輸與主耶穌的關係，因為從前受過綱輸漫禮而仍未認識主耶穌的人還多着呢。"},{"label":"附篇四 · 十二個人說方言","text":"再請注意，由第十九章一直到二十八章再沒有方言的記載了。一方面由於這十多章經文主要是記載保羅上耶路撒冷和上訴該撒的事，另一方面也因為福音已經在外邦人當中傳開了，所以用方言向猶太人作證的功用也逐漸消失，於是方言是潤泗減少的，神蹟奇事也漸漸減少。因為聖經漸漸寫成，真理渭渭取代方言與神蹟，真理的聖靈喜歡用真理來作證據，多過喜歡用方言入蹟來作證據。"},{"label":"附篇四 · 十二個人說方言","text":"神的計劃不會長久用超自然的力量來推動篇特，因為冗看一切所造的都其好，當然也看一切在自然律之下推進的方式為甚好。如果要說神喜歡用超自然的方法來推進生的一切工作，那麼，神是無所不能的，信甚麼生不用最大的神能—說一句話，使全人類突然全部信了主，像和說一句話創造天地一樣呢？不！"},{"label":"附篇四 · 十二個人說方言","text":"神喜歡用自然的方法，科喜歡用真理說最人，讓人有自由的選擇，和不喜歡用「沒有人能聽出來」的方言來吸引人，冗在歷史上會經用過方言，也是因為冗以仿一個特殊的情形，特殊的時代，需要特殊的方法。"},{"label":"附篇四 · 十二個人說方言","text":"一旦特殊的情形過去了，自然的方法就會恢復使用了。正如以色列人入操南，初時神用祝蹟奇事幫助他們，但後來禮就泗潤要他們憑自然的作戰方法，努力去得那些未得之地了。"},{"label":"附篇四 · 末世天國降臨與方言","text":"末世天國降臨與方言\n\n研究為甚麼使徒行傳後期和教會歷史漸尊減少方言與神蹟奇事這個問題，還有一個十分重要的真理必須明和白。根據聖經研究一書的作者巴斯德的疙見，他指出:方言與入蹟減少的問題，是與末世壟天國降臨的時間有關的。"},{"label":"附篇四 · 末世天國降臨與方言","text":"讓我們再來思想一下使徒行傳第二章，當時使徒們說起別國的話來，筱得起來引遞納即先知的話說:「神說，在末後的日子，我要將我的靈澆灌凡有血氣的，你們的兒女要說預言，你們的少年人要見異象，老年人要作異夢。在那些日子，我要將我的靈澆灌我的僕人和使女，他們吉要說預言。在天上我要顯出奇事，在地下我要顯出神蹟，有血、有火、有煙霧。日頭要變為黑暗，月亮要變為血，這都在主大而明顯的日子未到以前。到那時候，凡求告主名的，就必得救。」"},{"label":"附篇四 · 末世天國降臨與方言","text":"請註疙，第得引據這一段話，表示他以為那時候就是「末後的日子」，他以為不久之後「在天上便會有奇事，在地下便會顯出神蹟」，而且環境也改變了，甚至「有血，有火，有煙霧(大戰的情形～，日頭變黑，月亮變血紅」可是，事實上，我們從歷史看見，這一切都未出現過，只有方言和神蹟出現，但也漸漸減少，到了今天，已經過了差不多二千年了，一末後的日子」還未出現，為甚麼呢？由這事使我們聯想到其他的經文—為甚麼綱輸出來傳道說天國近了，但仍然不見天國來臨？"},{"label":"附篇四 · 末世天國降臨與方言","text":"為甚麼主耶穌和衆使徒出來傳福音也是傳天國的福音？而到了今天還未見天國出現？為甚麼衆使徒都說，「如今是末時了」，「主必快來了」，「還有一點點的時候，那要來的就來了」，但事實上，現在已經過了差不多二千年了，主還沒有再來，到底是甚麼緣故呢？當然，「主看一日如千年，千年如一日一～彼後三8—9～，所以過了二千年也算不了甚麼。"},{"label":"附篇四 · 末世天國降臨與方言","text":"但到底不能抹煞一個事實，就是新約越早寫成的書信和福音書，就越强調主快再來，越遲寫成的福音當就越將主再來的事放得更遠。例如重視主再來的帖撒羅尼迦前後書就是保羅最早期的作品，但監總書信這些後期的作品就較少提及主再來的事了，而且，照初期教會的進展來看，五句節聖靈降臨的一切神蹟方言，只有減少而沒有增加這是為甚麼緣故呢？"},{"label":"附篇四 · 末世天國降臨與方言","text":"巴斯德很明白的給我們一個答案，他說，本來天國降臨只為猶太人，往香只篇狠太人，應許和諸約都是他們的，所以主耶穌和使徒們初時不向外邦人傳道，只向猶太人傳消号這是一個非常明顯的事實可是，猶太人拒絕丫約翰，殺死了耶穌，逼迫了衆使徒，換言之，他們越來越堅決拒絕天國的降臨。"},{"label":"附篇四 · 末世天國降臨與方言","text":"他們只圖謀推翻地上的羅馬帝國，建立地上的國，他們不肯悔改，不肯承認耶穌是舊約應許要來拯救他們的彌賽亞，逼使彌賽亞不能實現「天國降臨」的計劃，這棵無花果樹—一以色列國的代表—在主耶穌傳道的三年之中不肯結果～路十三69)，主耶穌容忍它，沒看把它砍下來，反給它週圍挖開士，加上開，瑟思是再差使徒四處傳福音，行更多的神蹟，希望他們相信悔改，"},{"label":"附篇四 · 末世天國降臨與方言","text":"可是他們在使徒行傳的三十幾年之中，不但不肯悔改，而且變本加厲的逼害衆使徒，堅決拒絕福音，結果，主後七十年時，羅馬人來了，放火燒了耶路撒冷，拆毁了聖殿，殺了一百多萬猶太人，於是這無花果樹被及訊死了～太二十一1819～。"},{"label":"附篇四 · 末世天國降臨與方言","text":"約翰和主耶穌並衆使徒向他們所傳的天國降臨的機會被收回了(太二十六43，轉而賜給外邦人，使外邦人這「野品檻校子」，可以有機會被接在好欖橄樹上，在那一被折下來的枝子」的位置上，妓下神救恩的肥汁(羅十一0)。倘若猶太人真的肯及時悔改信主的話。"},{"label":"附篇四 · 末世天國降臨與方言","text":"不但他們的耶路撒冷城和聖殿不至被拆毀，而且主耶穌在升天之後，也會非常快的「—可能七年之內—駕着天上的雲回來，復興以色列國，坐在大衞的寶座上，統治全世界，以耶路撒冷為首都，換言之，千禧年提早實現，天國正式降臨，主耶穌和約翰所傳的「天國近了」的信息也實現了。"},{"label":"附篇四 · 末世天國降臨與方言","text":"仿閉要給這些「要求神蹟」的猶太人(林前一22一更多天國近了的証據，使他們可1哈所以主耶穌和衆使徒在出來傳福音時，都行了許多神蹟，而且在聖靈降臨的初期，也普遍出現方言的現象，好讓彼得站起來傳福音的時候，能有力的引摔逢豆先知的話來証明「天國近了」。"},{"label":"附篇四 · 末世天國降臨與方言","text":"雖然我們在前文指出納豆先知的話還有許多未應驗的地方，但是，如果猶太人真的越來越多人肯悔改信主，以致天國真的能在當時降臨的話，這些仍未應驗的部份也必接續應驗了。"},{"label":"附篇四 · 末世天國降臨與方言","text":"可是，事情不是這樣，猶太人越來越堅決拒絕，相對的，方言神蹟也越來越減少，因為福理泗潮的轉向外邦人去了。如果按徂以理所得的「七十個七」的毛示來徂九21⑦冖，七十個七的奧秘指明是單為以色列人和聖城而定的，七十個七就是七士個七牛，我們在此無法詳細講論其中的含意，但有一點非常明顯必須在這裏指出的，就是過了六十九個七之後「那受膏者」被剪除，受膏者在原文就是彌賽亞，果然，從亞達薛西王最後一個命令下來，幫助以色列人重建聖殿那一年開始計算，到了主耶穌磋匈十字架那一年，就剛剛滿了六十九乘七，即四百八十三年，預言應驗了。"},{"label":"附篇四 · 末世天國降臨與方言","text":"但是有一點相當難明白的，就是第七十個七，即是最後那七年為甚麼不立刻接在主釘死那一年之後？而要加插一段無限期的時間在內—教會時代，亦即但以理書九章廿六節所形容的「必有一王的民來毀減這城和聖所，至終必如洪水冲沒，必有爭戰，一直到底，荒涼的事已經定了」的可怕時代，使最後那一個七年變成我們今天常常懼怕要臨到我們的七年大災難？"},{"label":"附篇四 · 末世天國降臨與方言","text":"原來答案很簡單，如果猶太人真的肯在初期教會時信主，那最後的七年就立即接在主破匈的那一年之後，即主耶穌將要在升天之後七年回來•可惜猶太人不肯悔改信主，天國被收回，插入教會時代，末後的七年就遷移到將來，主再來的日子也航捆二千多年了。\n\n這樣的解釋我以為非常圓滿，合真理。"},{"label":"附篇四 · 末世天國降臨與方言","text":"所以，我們應當明白，為甚麼初期教會的方1'言神蹟蘭翊減少，為甚麼這時代神不普遍賜下方言神蹟，因為沒有這個需要，因為我們—I、不是猶太人，因為主再來的日子還未確實的知道，但是到了教會被提，七年大災難開始1、了，猶太人在大災難的末期，將要照着保羅的預言全家悔改得救(現今猶太人肯信主的W～非常少，最近聽說，如果有人向猶太人傳往香，會被罰二千五百美元～，那時候，"},{"label":"附篇四 · 末世天國降臨與方言","text":"約珥1、書的預言也應驗了，方言，預言，神蹟，日頭變黑，月亮變血紅等等也普遍出現了，跟M着應驗的，就是納豆先知所指的「那大而明顯的日子」來到，即主耶穌駕着天上的雲降—臨，衆目都要看見祂，地上的萬族都要哀哭的日子來到。"},{"label":"附篇四 · 林前十二至十四章的方言","text":"林前十二至十四章的方言\n\n身眾福音所介紹的聖靈說過了，使徒行傳的方言也研究完了，現在我們應該來到最直接論及方言的經文林前十二至十四章。請記得，新約再沒有别的書信論方言。而這所論的，任何人都明白作者並不在提倡方言，或高舉方言”小4十甲：金器譜坚只或强調方言；反之，作者乃是在運用許多真理去平息因方言而引起的混亂，並指出，在不與真理相合的情形之下，不要說方言"},{"label":"附篇四 · 肢體不同的功用——十二章","text":"肢體不同的功用——十二章\n\n我們並沒有時間解釋全章聖經，我們的目的只是從這章經文看方言的地位是怎樣的，首先我要指出的，作者將神所賜給教會的許多種不同的恩賜，比喩基督身體上各個不同功用的肢體，這一個比喻帶給我們以下各點的真理—.上由四，十，革九節看來—一恩賜原有分别：：功用也有分别：：這人蒙聖靈賜:.那人蒙聖靈賜:::又有一人:::又叫一人:::又叫一人:::豈都是使徒麼？豈都是先知麼？:::豈都是說方言的麼？"},{"label":"附篇四 · 肢體不同的功用——十二章","text":"一—可見保羅淸清楚楚的指出，各人的恩賜不同，不能都有一樣的恩章，不能人人都說方言，因為基督身體上的許多肢體不是一樣的，為此，很明白的，靈恩派主張人人都應該說方言是錯誤，因為不合真理，不是出於聖靈的配搭。"},{"label":"附篇四 · 肢體不同的功用——十二章","text":"如果在十恩派的教會詩人人都講方言，又不是出於聖靈的配搭，那慶一個不能繩夠的結論，就是出於那靈的配搭，事實上，有許多說方言的人，科一些入的僕人們奉主耶穌的名從他們身上趕出邢靈來，因為除了聖靈和邪靈之外，再沒有第三種趾人議方言的靈了。"},{"label":"附篇四 · 肢體不同的功用——十二章","text":"激烈的靈圍派之所以變成異端，不但是因訪出於那靈的配搭，同時也因為他們認為沒有方言就沒有聖靈，沒有聖靈就是未得救的，這樣他們強調了方言成為得救必需的條件，這就是更敵了「因信稱義」的真理，贍更改了因信稱義的真理的，他們才是不能得救折，不能稱為弟兄的，所以就是異端。其實十五至十太節清楚的說出，不能因仿別人沒有某一種的恩喝，就定他為「不屬乎身子」的。"},{"label":"附篇四 · 肢體不同的功用——十二章","text":"恩賜的作用不是用來鑑別那人是否屬主，恩章的作用只是用來配搭成為主的身體，讓主(元首)隋更使用，作成救時的工作e_2由四至十一節看來—「聖靈卻是一位::聖靈賜他::聖靈賜他::聖靈賜他:，這一切都是這位聖靈所運行，隨己瑟分鑰名人的。」"},{"label":"附篇四 · 肢體不同的功用——十二章","text":"得甚麼恩賜，不是照我們自己的喜好計劃，乃是聖靈自己認伺施可以有甚麼恩章才喝雁他，因為我們不哇得如何配拱基督的身體，只有聖靈才曉得。\n\n為此，我雖然可以求聖靈賜給我們各樣的恩賜，但我們不能組求，不能照自己的喜好求。僻求方言的人求一次得不到，兩次得不到，有的五太次都得不到，最後他自己定意，無論怎樣，無論付甚麼代價，或藉手，或藉大聲咱，手而，急速的講哈利路亞等句語，都要得着方言。這種態度就是强求。"},{"label":"附篇四 · 肢體不同的功用——十二章","text":"凡不明白為何自一己需要方言，又不明白為何神在自己第一次求時不賜下方言，而不惜用任何其他方法去求的都是强求。凡因别人有了方言，或因誤以為方言會使自己被聖靈充滿，而祈求神賜下方言的，都是照自己的喜好求，因仿不合聖經頁理。"},{"label":"附篇四 · 肢體不同的功用——十二章","text":"如果是照聖靈的意思求，一定就是「接」上真理求，「仿」員理求。，3由廿八至卅一節看來「神在教會所設立的，第一是使徒，第二是先知，第三是教師，其次是行異能的，再次是得恩賜醫病的，幫助人的，治理事的，說方言的。貴都是使徒麼？:::先知麼？:::教師麼？:::行異能的麼？：：得恩賜醫病的麼？：：說方言的麼？：：繙方言的麼？你們要切切的求那更大的恩賜。"},{"label":"附篇四 · 肢體不同的功用——十二章","text":"」—可見方言恩賜是最小的恩賜，而且保羅勸勉我們，與其求方言這最小的恩賜，不如求更大的恩賜。或許有人不明白這段經文那裏指出方言是最小的恩賜。"},{"label":"附篇四 · 肢體不同的功用——十二章","text":"讓我指出，經文明說「第一是::第二是::第三是::其次:::再次:::」這些字句分明表示這些恩賜是有大小先後次序的，而且最後一句勸我們要切切求那「更大」的恩賜，就更清楚的表明，上文的次序，就是恩賜大小的次序，再按事實來看，使徒當然比先知大，先知當然比教師大，教師當然比以下的各種恩賜大，所以，保羅勸我們求更大的恩賜，分明是說若要求方言恩賜，不如求「作先知講道的恩賜一～參十四1—一其中更要羨慕的，是作先知講道～，因為方言若不翻出來，不能造就人，先知講道才能造就人。"},{"label":"附篇四 · 肢體不同的功用——十二章","text":"即使方言翻出來，已經多了一重手續，花費了更多時間，而且，自古至今，從來沒有VH一扁感人的講道記錄，或寫作，是由方言翻過來寫成的。許多人說出「方言」，被翻出來之後，發現並不是甚麼奧秘，只是平平凡凡的一些話，甚至有不少是無疙議的話。"},{"label":"附篇四 · 肢體不同的功用——十二章","text":"還有一點是這段經文玥達出來的，就是第一第二第三這三種大恩賜都與「員理」有關，以後較小的恩賜之所以較小，分明就是因為比較難帶出真理，可見真理的聖靈總是以真理為重，為目標。.坐再由上述廿八至卅一節經文來著，我們可以肯定的指出，地方教會不一定需要方言唱治病等恩賜才算配搭完全。"},{"label":"附篇四 · 肢體不同的功用——十二章","text":"如果有人以為聖經既說明，「神在教會所設立的上這一切恩賜，所以一個配搭完全的教會，必定有着這許多種不同的恩賜，今天的教會缺乏這許多種恩賜的其中一種，就不完全。"},{"label":"附篇四 · 肢體不同的功用——十二章","text":"我要清楚的指出，這種思想是錯的，因為這裏所說的不是地方教會，而是普世古今所有得救的基督徒合起來而成的屬靈教會，地方教•會有許多，屬靈的，稱為基督身體的教會只有一個，因為基督只可能有一個身體～弗四4～，不可能有許多身體，而這段經文所說的許多不同恩賜，就是配搭成基督身體的肢體。如果我們認為教會必須要有方言，為甚麼我們不以為教會必須要有「使徒」呢？"},{"label":"附篇四 · 肢體不同的功用——十二章","text":"但我們知道，只有初期教會見過主面，被主差派的那些人才能稱為使徒，我們今天的教會是不再有使徒這種恩賜的，在神的配搭計劃中，教會是破建造在「使徒和先知的根基上」，和根基立穩了，就不用再立，初期教會使徒和先知建立了教會，首寫完聖經了，就不再需生要使徒和先知，即使我們現今作先知講道，也不是講新預言，乃是講古時先知寫在聖經裏的預言。"},{"label":"附篇四 · 肢體不同的功用——十二章","text":"所以，今天的教會是否配搭完全，不是看這些恩賜。若要看，應該看以韻所書四章十一至十三節—「祁所竟的有使徙，有先知，有傳福百的，有牧師和教師，為要成全型徒，各盡其職，建立基督的身體，直等到我們眾人在員道上同歸於一，認議神的兒子，得以長大成人，滿有基督長成的身量」—請注意黑體的字全各指頁理作為教會配搭的藍圖"},{"label":"附篇四 · 方言何時停止——十三章","text":"方言何時停止——十三章\n\n現在我們來到最著名的第十三章，這一章的中心是論人愛，保羅在這一章論俯最妙的地方(十二3)是愛加在恩賜上便使恩賜有意義有價值。反之，如果沒有了人愛，一切恩賜都算不得甚麼。這是為要針對當時哥林多教會為恩賜的緣故(尤其為方言的緣故)產生分門別類，互相攻擊的現象。不過我們在這裏閃不打算詳細講論人愛，我們要注疙的一圖，就是保羅在這裏提及方言何時停止的問題。"},{"label":"附篇四 · 方言何時停止——十三章","text":"到了第八節，保羅指出「雙是永不上息」之後，跟者他提出三種恩賜作仿例證，表明恩賜是有停止的一天，永不止息的只有愛。第八節提出這三種恩賜的次序如下:先知講道之能，終必歸於無有；折說方言之能，終必停止；包知議也終必歸於無有。好，這些恩賜會停止，歸於無有，這一點是清楚而確定的了。問題是到底這三種恩賜何時停上呢？"},{"label":"附篇四 · 方言何時停止——十三章","text":"主張說方言的人會這樣籠統地回答說一直看下去，最清楚的時間表明出來就是「到那時就要面對面了，我如今所知道的有限，到那時就全知道，如同主知道我一樣」，這樣很明顯的，一切恩賜，連同方言在崔，要到主再來我們與主面對面之時就停止了。"},{"label":"附篇四 · 方言何時停止——十三章","text":"這樣的答案是錯的，因為不仔細研究，籠籠統統的將三件事渴為一談，請注意經六的次序，三種恩賜的次序我們在前面說過了。三個答案的次序又怎樣呢？請看聖經1關於先知講道何時歸無有的答案，第九和第十節說:「我們現在所知道的有限，先知所講的也有限，等那完全的來到，這有限的必歸於無有了。」這是說，「那完全的來到」，先知講道(即預言)就要停止了。"},{"label":"附篇四 · 方言何時停止——十三章","text":"2關於方言何時停上的答案，第十一節說:「我作孩子的時候，話語像孩子，心思像孩子，疙念像和孩子，既成了人，就把孩子的事篤棄了。」這裏所說的話語像孩子，就是指方言，理由是第十四章廿至廿二節清楚說明說方言等於在心志上作小孩-弟兄們，在心志上不要跟小孩子，然而在惡事上要作嬰孩，在心志上總要作大人(即要有追求更大恩賜，追求認識主的心志，理由容後詳解)。"},{"label":"附篇四 · 方言何時停止——十三章","text":"律法上記着：一主說，我要用外邦人的舌頭，和外邦人的咀唇(即方言>向這百姓說話，雖然加此，他們還是不聽從我」這樣看來，說方言不是為信的人作証據，乃是為不信的人作証據，—[前文不要在心志上作小孩，後文接續論及方言的問題，很容易看出來，在心志上作小孩就是指說方言，意即指他們靈性幼小，在真理上少有認識，要用小孩般的方言來給他們作證據，但他們還是不信。"},{"label":"附篇四 · 方言何時停止——十三章","text":"如果有人反對這段經文的解釋，說「作小孩」不是指「方言」，那麼我要請問他，第二十節「弟兄們，不要在心志上作小孩，然而要在惡事上作嬰孩，在心志上總要作大人」這幾句話，插在前後文都是論及方言的問題中，有何用意呢？任何人都會看到如果那不是指着方言說的，這一整節經文就完全沒有意思了。"},{"label":"附篇四 · 方言何時停止——十三章","text":"再者，方言說起來，在屬靈的意義上，真的像小孩子說話一般，因為沒有人聽明白是甚麼，他所領會的也是十分膚淺的事，正如我在前文所指出的，自古至今，從來沒有一篇有價值的文章或書本是從方言翻出來的，在說方言的聚會之中，也從沒有聽見過翻方言的，翻出一篇有份量的道理來，卻是一些平凡的話吧了。"},{"label":"附篇四 · 方言何時停止——十三章","text":"還有，按照第八節至第十二節所列出來恩賜的次序來說，第九第十節旣說明了第一種先知講道的恩賜停止的時間，第十一節就很順序的說明了第一種方言恩賜停上的時間，第十二節說明了第三種知識恩賜的停止時間三樣，第二種恩賜對照了第十一節，明顯的指出，孩子的話語就是指方言了。好，話說回來，究竟方言何時停止，經文說？到成了人之後，孩子的話—方言就停止了。"},{"label":"附篇四 · 方言何時停止——十三章","text":"，3關於知識何時停止的答案，順序的，明顯的，第十二節這樣說:「我們如今彷彿對着鏡子觀看，模糊不清，到那時就要面對面了，我如今所知道的有限，到那時就全知道，如同主知道我一樣。"},{"label":"附篇四 · 方言何時停止——十三章","text":"」這是說:一切知識，到了主再來面對面之時就停止，歸於無這樣我們看見，三種恩賜有三種不同停止的時間。第一，先知講道之能～按原文即指預言～，要到「那完全的來到」就停止了。那「完全的」當然是指完全的預言：元全的預言是指甚麼呢？豈不是指寫完啟示錄之後的聖經麼？保羅寫哥林多前書之時聖經還未完成，所以當然他說要等那完全的來到。"},{"label":"附篇四 · 方言何時停止——十三章","text":"事實上，聖經寫成之後，我們在整個教會歷史裏面再看不見先知的出現，也再沒有可靠的新預言發表過。第二，說方言之能要到「成了人」之後就停止了。成了人是指着甚麼說的呢？我們不能亂猜，一定要以經解經才準確，這樣，黑經指一個人的靈性長大成人，最清楚，最準確就是以弗所書第四章十一至十四節！"},{"label":"附篇四 · 方言何時停止——十三章","text":"「」祂所賜的有使徒先知，有傳往百的名月牧師和教師，為要成全聖徒，各盡其職，建立基督的身體，直等到我們的衆人在真道上同歸於一，認識神的兒子，得以長大成人，滿有基督長成的身量，使我們不再作小孩子，中了人的詭計，和欺騙的法術，磋一切異教之風搖動，桔來柚去，就隨從各樣的異端。」請注意黑體字的內容，長大成人，就是在真道上，即真理上成熟，亦即是在認識主的真理上成熟。"},{"label":"附篇四 · 方言何時停止——十三章","text":"方言只是未在真理上成熟，未夠深入認識主的小孩子說的。况且，這段徑文還指出，小孩子十分容易中計，搖動，因為小孩子不明理，好奇心重，凡是超自然的法術都可能會吸引他的，這正好說明靈恩派的人沉迷方言的原因。"},{"label":"附篇四 · 方言何時停止——十三章","text":"話說回來，今天有真正的方言恩賜嗎？方言恩賜已經停止了嗎？如果按照長大成人的理論來說，到了聖經寫成之後，我們已經有足夠的啟示去認識基督，得以長大成人了，所以照理聖經寫成之後，方言就停止了。"},{"label":"附篇四 · 方言何時停止——十三章","text":"但是，可能(我只能說可能～在某一些基督徒來說，他對真理的認識不夠深，認識主耶穌不多，而聖靈也認為要用他向一些不信的人(尤基是猶太人作證據，於是在一種合聖經真理的途徑之下(稍後再詳論這一畔聖靈會賜方言論他也未可料。"},{"label":"附篇四 · 方言何時停止——十三章","text":"但我要指出，即使聖靈賜他真的方言，這不過表示他在真理的認識上是小孩吧了。如果他在真理的認識上成了人，聖靈就絕不會賜他方言作証據，因為他已經能夠用真理作証據了，為此，假如今天仍有真的方言，那也不值我們羨慕它過於羡慕真理，如果今天仍有真的方言，那也一定不是靈恩運動提倡那一種。"},{"label":"附篇四 · 方言何時停止——十三章","text":"我想，今天極可能沒有真的方言，尤其是有許多被邪靈附身的人也說方言，聖靈不會在這種情形之下賜下真方言，叫神的兒女分不出真假來，而且我們也找不出需要賜下真方言的理由來。第三，知識的恩賜要到主再來之時就停止了，這一點不用解釋。一說就明白了。但林前十三章還有一節經文証明方言不可能「常存」的，那就是第十三節—「一如今常存的有信，有望，有愛，其中最大的是愛。"},{"label":"附篇四 · 方言何時停止——十三章","text":"一—請問二字是指甚麼時候呢？接前交一熱，那能“全都知道」的話看來，「如今」二字一定是指由現今至主再來之前的時代無疑。\n\n而且事實上，信闡肪三樣確是在「如今」不能少，不能停止的，而「其中最大的是愛」，因為「信」和一望一到了主再來之時也停止了～因為那時旣看見了，旣到達了，就無須再信，再望～，唯有「仿」這一樣，即使到了主再來之時，還是需要，而且那時正是愛達到最高峯的時候，因為一愛是永不止息」的，所以愛最大。好！"},{"label":"附篇四 · 方言何時停止——十三章","text":"旣然「如今」常存的只有信望愛三樣，明顯的表示出，所有恩賜都(包括方言二个會在一如今」常存，都會在「如今」之中某一個階段的時候停止的。\n\n至於知識的恩賜，如果不是與信望愛有關的，也都要停止，與信望愛有關的知識不能停止。不然，信疹仿本身也就停止了。"},{"label":"附篇四 · 方言的功能——十四章","text":"方言的功能——十四章\n\n我們談論完方言停止的問題之後，這一章就易明白得多了。而且我在前文和在本書之前幾章中，也有不少論及這一章所論及的。所以，我不打算在此詳細解釋這一章，我以為留下最重要而未解釋的，就只是方言的功用這個問題。"},{"label":"附篇四 · 方言的功能——十四章","text":"論到方言的功用，這一章給我們知道有四個：（1）心靈裏講說各樣的奧秘(第二節)；仿造就自己(第四節)；g用靈禱告，用靈歌唱(第十四至十六節～；1AN作証據(第二十二節～。第三個功用我們在「靈修的程序」那一章已經說過了。第四個功用我們在前文也說過了，剩下的只是第一和第二個功用。"},{"label":"附篇四 · 方言的功能——十四章","text":"而且詳細的研究一下，我們還發現第一和第二個“功用原是一個，現在讓我分析出來—「心靈裏講說各樣的奧秘」這句話是說，說方言的人感受到靈界的奧秘，不能用悟性表達出來。但聖靈叉感動他要說，為的是要給不信的人作証據，於是他就說出沒有人能聽懂的方言來。"},{"label":"附篇四 · 方言的功能——十四章","text":"但當聖經寫成之後，亦即是所有人能明白和應該明白的奧秘都啟示出來之後，方言的用涂就沒有了，因為聖靈旣然可以感動入看聖經，直接明白那些奧秘，使他們能造就人又能造就自己，這何需方言來表達呢？"},{"label":"附篇四 · 方言的功能——十四章","text":"尤其是聖經寫完之時，猶太人不信的立場已經固定了，聖靈亦認為不必再給他們方言為証據，所以方言的恩賜就到消了，如果說方言的人以為這種說話太武斷，我們大可以反問他們，今天的方言所說出的奧秘是聖經所記載的奧秘呢？還是聖經以外的奧秘呢？若是聖經本身的奧秘，真理的聖靈何不感動人直接用人聽明白的話說出來—即用講道方式講出來，以省翻譯方言的麻煩呢？"},{"label":"附篇四 · 方言的功能——十四章","text":"如果說是聖經以外的奧秘，我們立贅就否定，聖經以外根本就再沒有奧秘了。如果聖經以外還有奧秘，豈不是說聖經仍不完全？為甚麼靈恩派的人不把方言所說出來的奧秘，經過翻方言的人翻出來後，加寫在聖經裏面呢！如果這樣，主耶穌就會將聖經裏面的災亡加在他們身上了(和氮二十二M)。事實上，他們把方言中所謂的奧秘翻出來之後發現完全不是奧秘，只是平平凡凡的話吧了。"},{"label":"附篇四 · 方言的功能——十四章","text":"自古至今從來沒有一篇有價值的信息或女章或書本，是從方言翻出來的，所以，退一萬步來說，如果今天有方言的話，今天的方啟亦不能講出甚麼奧秘來。至於「說方言是仿造就自己」這一點，那是因仿既不能造就別人(若不翻出來)，只是自己心靈間感受到各樣靈界的奧秘，所以這些奧秘只能造就自己。但「造就」這兩個字完全是為「奧秘」而寫的，若沒有奧秘，根本就沒有造就可言。"},{"label":"附篇四 · 方言的功能——十四章","text":"如今，說方言的人既然說出來的都是平平凡凡的話(經翻出來可以證實；怎能在心靈裏有所造就呢？明顯的，今天說方言的人之所謂「造就」，首不焦明白其中的奧秘，只為追求說方言時的特殊感受吧了。我遇見過一個說方言的人，他在我旁邊用方言芒告說:_-(生生太信條評語之三放丰生人品品生生人品品店人衝衝人品人人ooc再oo」這樣把這一句方言重複幾十逼。"},{"label":"附篇四 · 方言的功能——十四章","text":"我問他為甚麼重複只講一句相同的話呢？這豈不是用重複話富告嗎？這豈不是主耶穌所禁止的嗎？他說他心靈裏講說各樣的奧秘，我立刻指出，如果現在有一個能翻方言的人在這裏，他把你的方言翻出來，豈能從一句方言翻出各樣的奧秘來呢？他說他可以用重複說話讚美神。我文立刻指出。舊約詩篇從來沒有一個例子是將一句說話重複幾十次的。"},{"label":"附篇四 · 方言的功能——十四章","text":"最後他又說，他心裏感到多快樂多甜蜜“我亦不肯上記過的指出，他所追求的不是主，不是奧秘，而是感受，撒但可以用各樣的感受欺騙人。\n\n又有另外一個贊成方言的人，我問他說:「方言加增了你甚麼呢？加增你的知識嗎？靈性份量嗎？」他回答說不是，乃是加增他在禱告中的喜樂。我立刻又指出:「主耶穌在約翰福音十五章十一節那裏說:-這些事我已經對你們說了，是要叫我的喜樂存在你們心裏，並叫你們的喜樂可以滿足#這既是“滿買的喜樂，還有可以增加的嗎？而且主耶穌所說這滿足的喜樂並沒有包括方言的感受。"},{"label":"附篇四 · 方言的功能——十四章","text":"」這樣，我們清楚的看見，方言在今天並沒有甚麼功用，既沒有功用，也就不需要有了。如果有，我不能不懷疑它的真實性和可靠性。"},{"label":"附篇四 · 如果真有方言的話","text":"如果真有方言的話\n\n我以為今天說方言的人雖然不少，但無說方言的人仍然佔着絕大部份。只可惜，傳道人和一般弟兄姊妹通常都自以為不可偏激，於是當他們還未弄淸楚方言運動之真偽之前，就持着一不偏激」的態度，認為今天很有可能會有真的方言存在。誰知這種所謂「不偏激」和「很有可能」的說法，正正鼓勵了不少基督徒去尋求方言。同時也助長了方言運動的趨勢。"},{"label":"附篇四 · 如果真有方言的話","text":"他們根本沒有考慮一個鐵一般的事實，就是真的有許多說方言的人是証實被邪靈所附，而且也有不少從前說方言現在不再說的人也見証這一。\n\n或者有人這樣說:「吳主光先生，難道不可能你的見解會有錯嗎？為甚麼不考慮一下，這世代可能有真正的方言呢？」好，我樂言接受任何指出我的見解有錯誤的意見，問題只要他能根據聖經真理，不根據個人經驗和感受，或許多人的經驗感受～許多人誤以這些為正確根據的～，給我指出錯處來，我就佩服他了。我並不是不肯考慮一下，今世代可能有真方言的問題。"},{"label":"附篇四 · 如果真有方言的話","text":"容我退一萬步來說，假若今天有真方言存在的話，在下列的條件之內，我會接受方言的「—上不求而得的方言—五旬節聖靈降臨之前，眾門徒根本就不知道方言是甚麼，所以他們根本就沒有求得方言的恩賜。其他使徒行傳還有許多這樣的例証。w4不按手而得的方言「1聖靈賜人方言不一定假手於人的方法或禮儀的。"},{"label":"附篇四 · 如果真有方言的話","text":"我常對震史派的人挑戰說，如果他們認為真有方言，又認為人人都應該有方言的話，那麼他們可以為我和許多其他的基督徒禱告，求神普遍地賜下方言給我們。"},{"label":"附篇四 · 如果真有方言的話","text":"如果他們認為要藉按手之禮才有，那麼我要問，為甚麼哥尼流一家的人不求，也公用按手就得到方言的恩賜呢？3不學而會的方言—1靈恩派的人不單要人求，要藉按手，許多時候還要跟他們「學」，他們會勸你不斷的說「哈利路亞讚美主」之類的話，而且要越說越快，快到一個地步舌頭捲不過來了，方言就出來了。這種「學」的方法完全不符合聖經。4不重複-句的方言丫—這一點我在上交已經說過了2靈一定不合聖經的。"},{"label":"附篇四 · 如果真有方言的話","text":"但說的人不能自主，不能隨自己的意思說一别國的話」，或「天使的話」，或重複一句的，或多句不同的，靈要他講甚麼，他就講甚麼。•受過試驗的方言—聖經教訓我們要奉主耶穌基督的名間那叫人說方言的靈，認不認耶穌基督是成了肉身來的(約壹四2～，並要他說出「耶穌基督是主」這一句話(林前十二3)，如果那靈不認，或不出聲，或用別的字句回答，不照足聖經的字句回答，那就是邪靈。"},{"label":"附篇四 · 如果真有方言的話","text":"所以，在接受方言之前，一定要先問清楚，不肯接受試驗的方言，我們不、0主張人人都應說的方言—如果自己得方言的恩賜是因為接受了人人都說方言的思想，或從主張人人都應說方言的人中得到方言，這都是危險的。真理旣然錯了，來源就錯，尤其是來自以方言為得救憑據的人，更是百分之百的錯。"},{"label":"附篇四 · 如果真有方言的話","text":"•必需知道神為何賜自己有方言—如果有了方言而不明白為何有，這就是沒有功用的方言是多餘的，是不值得羨慕的，是錯誤的。在配搭基督的身體來說，一個肢體不知自己在全甚麼，和為甚麼而做，那怎能配搭成仿正常的身體呢？"},{"label":"附篇四 · 如果真有方言的話","text":"8沒有翻出來就不公開說—這是聖經明顯的教訓(林前十四%x即使在公祝的時候也不能用方言祝告，因為別人不能和你一同說阿們(林前十四6》*如果今天真有方言只在私祝中說，不在公福中，和聚會中說，那方言運動就根本不成運動了。"},{"label":"附篇四 · 如果真有方言的話","text":"9翻出來要成為員奧秘的方言—我在前文說過，沒有奧秘，既不能造就別人，也不能造就自己，這怎算是午正的方言呢？0能自制的方言說方言的人，有的到了-個深的程度是不能自帛的，不能不說，直到靈叫他停他才能停，甚至有的到了個地步好像自己儿在旁邊看見自己的身體在地上打四，而不能自制，這一定是那靈作則，因為聖經說，先知的靈原是順服先知的(林前十四&)我相信，如果接以上這十黑從今天世上說方言的人中選出及格的人來，不知道會不會有一個即使會，而且不只一個，但我知道一定不會有吉恩派這許多個，不然的話，聖經真理就出現矛盾的現象了。"}]}];
